(window.CLAVE_TODO=window.CLAVE_TODO||{})[6]=[{"a":"Artículo 23 — Órganos competentes para la instrucción EXOF EX ✱ R25","q":[{"i":"6-1","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Órganos competentes para la instrucción. ¿De quién depende la Oficina de asilo y refugio?","o":["El Gobierno.","El Ministerio de Igualdad.","La Seguridad Social.","El Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio del Interior</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-24","p":"Ley 12/2009. Órganos competentes para la instrucción. ¿De quién depende la Oficina de asilo y refugio?","o":["El Gobierno.","El Ministerio de Igualdad.","La Seguridad Social.","El Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio del Interior</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-74","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. De la tramitación de las solicitudes. Órganos competentes para la instrucción. ¿Quién compone la Comisión Interministerial de Asilo y Refugio?","o":["Está compuesta por un representante de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo e igualdad.","Está compuesta por dos representantes de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo e igualdad.","Está compuesta por tres representantes de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo e igualdad.","Está compuesta por cuatro representantes de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo y refugio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Está compuesta por un representante de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo e igualdad</mark></span>Según el <span class=\"ref-norma\">art. 23.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"que está compuesto por un representante de cada uno de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida de los solicitantes de asilo e igualdad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-96","p":"¿Quién resolverá los expedientes en materia de protección internacional, previas las propuestas de la CIAR (Comisión Interministerial de Asilo y Refugio)?","o":["El Ministro del Interior.","La Oficina de Asilo y Refugio.","El Consejo de Ministros.","La Comisión Interministerial de Asilo y Refugio (CIAR)."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 20.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias siguientes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-131","p":"(Ley 12/2009) Órgano colegiado adscrito al Ministerio del Interior en materia de asilo.","o":["La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","El Estado.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Comisión Interministerial de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 23.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Comisión Interministerial de Asilo y Refugio es un órgano colegiado adscrito al Ministerio del Interior\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-136","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio Español. El Ministro del Interior podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando no corresponda a España su examen de conformidad con los Convenios Internacionales en que sea Parte, a propuesta de:","o":["ACNUR.","La Dirección General de Relaciones Internacionales.","La Oficina de Asilo y Refugio.","El Ministerio de Asuntos Exteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 20.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias siguientes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-147","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Órganos competentes para la instrucción. ¿Cuál es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan?","o":["La Dirección General de Relaciones Internacionales.","La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","La Dirección General de Política Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-194","p":"Ley 12/2009... ¿Qué órgano podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando no corresponda a España su examen, por el que se establecen los criterios y mecanismos de determinación del Estado miembro responsable del examen de una solicitud de asilo presentada en uno de los Estados miembros por un nacional de un tercer país?","o":["El Ministro del Interior.","El Secretario de Estado de Seguridad.","El Ministro de Asuntos Exteriores.","El Secretario de Estado de Asuntos Exteriores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 20.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias siguientes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-210","p":"Ley 12/2009... ¿Cuál es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan?","o":["La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","El Centro de Internamiento para Extranjeros.","La Administración General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-273","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. No admisión de solicitudes presentadas dentro del territorio Español. El Ministro del Interior podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando no corresponda a España su examen de conformidad con los Convenios Internacionales en que sea Parte, a propuesta de:","o":["ACNUR.","La Dirección General de Relaciones Internacionales.","La Oficina de Asilo y Refugio.","El Ministerio de Asuntos Exteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 20.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias siguientes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-283","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Órganos competentes para la instrucción. ¿Cuál es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan?","o":["La Dirección General de Relaciones Internacionales.","La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","La Dirección General de Política Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-320","p":"Ley 12/2009... ¿Qué órgano podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando no corresponda a España su examen, por el que se establecen los criterios y mecanismos de determinación del Estado miembro responsable del examen de una solicitud de asilo presentada en uno de los Estados miembros por un nacional de un tercer país?","o":["El Ministro del Interior.","El Secretario de Estado de Seguridad.","El Ministro de Asuntos Exteriores.","El Secretario de Estado de Asuntos Exteriores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 20.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias siguientes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-333","p":"Ley 12/2009... ¿Cuál es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan?","o":["La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","El Centro de Internamiento para Extranjeros.","La Administración General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 23.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1421","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos. De acuerdo con sus competencias en materia de orden público, seguridad pública y seguridad nacional, mantendrá un Registro central de extranjeros:","o":["el Ministerio del Interior.","el Ministerio de Trabajo e Inmigración.","el Ministerio de Asuntos Exteriores.","el Instituto Nacional de Estadística."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Ministerio del Interior</mark></span>El <span class=\"ref-norma\">disp. adic. 5.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Ministerio del Interior, de acuerdo con sus competencias en materia de orden público, seguridad pública y seguridad nacional, mantendrá un Registro central de extranjeros\"</span>. El Registro central de extranjeros lo mantiene el Ministerio del Interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1546","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Derechos sociales generales. Los servicios sociales y de acogida específicamente destinados a las personas solicitantes de protección internacional se determinarán:","o":["por las Comunidades Autónomas en sus Estatutos.","por la Comisión Interministerial de Asilo y Refugio.","por la Oficina de Asilo y Refugio mediante instrucción.","reglamentariamente por el Ministerio competente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">reglamentariamente por el Ministerio competente</mark></span>El <span class=\"ref-norma\">art. 30.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los servicios sociales y de acogida específicamente destinados a las personas solicitantes de protección internacional se determinarán reglamentariamente por el Ministerio competente\"</span>. Reglamentariamente por el Ministerio competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1622","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Iniciará, de oficio o a instancia de parte, cuando concurra causa legal suficiente, los procedimientos de cese y revocación de la protección internacional concedida, haciéndoselo saber a los interesados:","o":["La Comisión Interministerial de Asilo y Refugio.","El Ministro del Interior.","El Alto Comisionado de las Naciones Unidas para los Refugiados.","La Oficina de Asilo y Refugio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Oficina de Asilo y Refugio</mark></span>El <span class=\"ref-norma\">art. 45.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio iniciará, de oficio o a instancia de parte, cuando concurra causa legal suficiente, los procedimientos de cese y revocación de la protección internacional concedida\"</span>. Inicia la OAR; propone la CIAR; resuelve el Ministro del Interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1623","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. A la vista de las actuaciones practicadas en la tramitación del expediente de cese o revocación, si no fuesen fundadas las causas inicialmente advertidas:","o":["el Ministro del Interior deberá dictar resolución expresa.","la Comisión Interministerial deberá informar previamente al ACNUR.","la Oficina de Asilo y Refugio podrá archivar el expediente.","el expediente se entenderá caducado a los seis meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Oficina de Asilo y Refugio podrá archivar el expediente</mark></span>El <span class=\"ref-norma\">art. 45.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"A la vista de las actuaciones practicadas en la tramitación del expediente, la Oficina de Asilo y Refugio podrá archivar el expediente, si no fuesen fundadas las causas de cese o revocación inicialmente advertidas\"</span>. La propia OAR puede archivar el expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1634","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Colaboración con las Organizaciones No Gubernamentales. Los poderes públicos promoverán la actividad de las asociaciones no lucrativas legalmente reconocidas entre cuyos objetivos figuren el asesoramiento y ayuda a las personas necesitadas de protección internacional. Sus informes:","o":["tendrán carácter vinculante para la Comisión Interministerial de Asilo y Refugio en la formulación de sus propuestas.","se remitirán al ACNUR para su valoración antes de la resolución de las solicitudes de protección internacional.","serán preceptivos en los procedimientos de tramitación de urgencia y en las solicitudes presentadas en frontera.","se incorporarán a los oportunos expedientes de solicitudes de protección internacional incoados por el Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se incorporarán a los oportunos expedientes de solicitudes de protección internacional incoados por el Ministerio del Interior</mark></span>El <span class=\"ref-norma\">disp. adic. 6.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Sus informes se incorporarán a los oportunos expedientes de solicitudes de protección internacional incoados por el Ministerio del Interior\"</span>. Sus informes se incorporan a los expedientes; no son vinculantes ni preceptivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria","q":[{"i":"6-2","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. El restablecimiento de la unidad familiar de las personas refugiadas y beneficiarias de protección subsidiaria podrá garantizarse mediante la concesión, respectivamente, del derecho de asilo o de la protección subsidiaria por extensión familiar, en los siguientes supuestos:","o":["Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los descendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fuesen menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad</mark></span>Se completa la opción B, a la que le faltaba «que fueran menores de edad». Según el <span class=\"ref-norma\">art. 40.1.a de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.\"</span> (verificado con el texto del temario)."},{"i":"6-6","p":"Ley 12/2009. Solicitudes presentadas en puestos fronterizos. Contra la resolución de inadmisión a trámite o de denegación de la solicitud se podrá, en el plazo de ____________________________ presentar una petición de reexamen que suspenderá los efectos de aquella.","o":["Dos días contados desde su notificación.","Tres días contados desde su notificación.","Cinco días contados desde su notificación.","Siete días contados desde su notificación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos días contados desde su notificación</mark></span>Según el <span class=\"ref-norma\">art. 21.4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Contra la resolución de inadmisión a trámite o de denegación de la solicitud se podrá, en el plazo de dos días contados desde su notificación, presentar una petición de reexamen que suspenderá los efectos de aquélla\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-25","p":"Ley 12/2009. El restablecimiento de la unidad familiar de las personas refugiadas y beneficiarias de protección subsidiaria podrá garantizarse mediante la concesión, respectivamente, del derecho de asilo o de la protección subsidiaria por extensión familiar, en los siguientes supuestos:","o":["Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los descendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fuesen menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad</mark></span>Se completa la opción B, a la que le faltaba «que fueran menores de edad». Según el <span class=\"ref-norma\">art. 40.1.a de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.\"</span> (verificado con el texto del temario)."},{"i":"6-43","p":"Ley 12/2009. El restablecimiento de la unidad familiar de las personas refugiadas y beneficiarias de protección subsidiaria podrá garantizarse mediante la concesión, respectivamente, del derecho de asilo o de la protección subsidiaria por extensión familiar, en los siguientes supuestos:","o":["Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los ascendientes en primer y segundo grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","Los descendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fuesen menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad</mark></span>Se completa la opción B, a la que le faltaba «que fueran menores de edad». Según el <span class=\"ref-norma\">art. 40.1.a de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.\"</span> (verificado con el texto del temario)."},{"i":"6-120","p":"(Ley 12/2009) Tramitación de urgencia. EL MINISTERIO DEL INTERIOR, de oficio o a petición del interesado, acordará la tramitación de urgencia, previa notificación al interesado, en las solicitudes en las que concurra alguna de las siguientes circunstancias: Señale la INCORRECTA.","o":["Que parezcan manifiestamente fundadas.","Que hayan sido formuladas por solicitantes que presenten necesidades específicas, especialmente, por menores no acompañados.","Que planteen exclusivamente cuestiones que no guarden relación con el examen de los requisitos para el reconocimiento de la condición de refugiado o la concesión de la protección subsidiaria.","Que se presuma solicitante procede de un país de origen considerado inseguro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Que se presuma solicitante procede de un país de origen considerado inseguro</mark></span>Según el <span class=\"ref-norma\">art. 25.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"d) que la persona solicitante proceda de un país de origen considerado seguro\"</span>. Es un país de origen considerado SEGURO (Verificado con el texto del temario oficial.)"},{"i":"6-137","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. El procedimiento se inicia con la presentación de la solicitud, que deberá efectuarse mediante comparecencia personal de los interesados que soliciten protección en los lugares que reglamentariamente se establezcan, o en caso de imposibilidad física o legal, mediante persona que lo represente. La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de _________ desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves.","o":["Siete días.","Diez días.","Un mes.","Dos meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 17.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de un mes desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-171","p":"Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes presentadas en puestos fronterizos. Cuando una persona extranjera que no reúna los requisitos necesarios para entrar en territorio español presente una solicitud de protección internacional en un puesto fronterizo, el Ministro del Interior podrá no admitir a trámite la solicitud mediante resolución motivada. En todo caso, esta resolución deberá ser notificada a la persona interesada en el plazo máximo de:","o":["Siete días desde su presentación.","Cuatro días desde su presentación.","Tres días desde su presentación.","Cinco días desde su presentación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuatro días desde su presentación</mark></span>Según el <span class=\"ref-norma\">art. 21.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Asimismo, el Ministro del Interior podrá denegar la solicitud mediante resolución motivada, que deberá notificarse a la persona interesada en el plazo máximo de cuatro días desde su presentación, cuando en dicha solicitud concurra alguno de los siguientes supuestos\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-184","p":"Ley 12/2009... Solicitudes presentadas en puestos fronterizos. Cuando una persona extranjera que no reúna los requisitos necesarios para entrar en territorio español presente una solicitud de protección internacional en un puesto fronterizo, el Ministro del Interior podrá no admitir a trámite la solicitud. La resolución deberá ser notificada a la persona interesada:","o":["En el plazo máximo de cuatro días.","En el plazo máximo de diez días.","En el plazo máximo de quince días.","En el plazo máximo de veinte días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo máximo de cuatro días</mark></span>Según el <span class=\"ref-norma\">art. 21.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En todo caso, la resolución deberá ser notificada a la persona interesada en el plazo máximo de cuatro días desde su presentación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-218","p":"Ley 12/2009... Solicitudes presentadas en puestos fronterizos. Cuando una persona extranjera que no reúna los requisitos necesarios para entrar en territorio español presente una solicitud de protección internacional en un puesto fronterizo, el Ministro del Interior podrá no admitir a trámite la solicitud. En todo caso, esta resolución deberá ser notificada a la persona interesada en el plazo máximo de:","o":["Siete días desde su presentación.","Cuatro días desde su presentación.","Tres días desde su presentación.","Cinco días desde su presentación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuatro días desde su presentación</mark></span>Según el <span class=\"ref-norma\">art. 21.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En todo caso, la resolución deberá ser notificada a la persona interesada en el plazo máximo de cuatro días desde su presentación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-274","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Presentación de la solicitud. El procedimiento se inicia con la presentación de la solicitud, que deberá efectuarse mediante comparecencia personal de los interesados que soliciten protección en los lugares que reglamentariamente se establezcan, o en caso de imposibilidad física o legal, mediante persona que lo represente. La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de _________ desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves.","o":["Siete días.","Diez días.","Un mes.","Dos meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 17.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de un mes desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-301","p":"Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes presentadas en puestos fronterizos. Cuando una persona extranjera que no reúna los requisitos necesarios para entrar en territorio español presente una solicitud de protección internacional en un puesto fronterizo, el Ministro del Interior podrá no admitir a trámite la solicitud mediante resolución motivada. En todo caso, esta resolución deberá ser notificada a la persona interesada en el plazo máximo de:","o":["Siete días desde su presentación.","Cuatro días desde su presentación.","Tres días desde su presentación.","Cinco días desde su presentación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuatro días desde su presentación</mark></span>Según el <span class=\"ref-norma\">art. 21.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Asimismo, el Ministro del Interior podrá denegar la solicitud mediante resolución motivada, que deberá notificarse a la persona interesada en el plazo máximo de cuatro días desde su presentación, cuando en dicha solicitud concurra alguno de los siguientes supuestos\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-312","p":"Ley 12/2009... Solicitudes presentadas en puestos fronterizos. Cuando una persona extranjera que no reúna los requisitos necesarios para entrar en territorio español presente una solicitud de protección internacional en un puesto fronterizo, el Ministro del Interior podrá no admitir a trámite la solicitud. La resolución deberá ser notificada a la persona interesada:","o":["En el plazo máximo de cuatro días.","En el plazo máximo de diez días.","En el plazo máximo de quince días.","En el plazo máximo de veinte días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo máximo de cuatro días</mark></span>Según el <span class=\"ref-norma\">art. 21.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En todo caso, la resolución deberá ser notificada a la persona interesada en el plazo máximo de cuatro días desde su presentación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1443","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Objeto de la ley. La Ley 12/2009 tiene por objeto establecer los términos en que las personas nacionales de países no comunitarios y las apátridas podrán gozar en España de la protección internacional constituida por:","o":["el derecho de asilo, la protección subsidiaria y la protección temporal en caso de afluencia masiva.","el estatuto de refugiado y el estatuto de apátrida, así como el contenido de dicha protección.","el derecho de asilo y la protección subsidiaria, así como el contenido de dicha protección internacional.","el derecho de asilo y la autorización de residencia por razones humanitarias, así como su contenido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el derecho de asilo y la protección subsidiaria, así como el contenido de dicha protección internacional</mark></span>El <span class=\"ref-norma\">art. 1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"tiene por objeto establecer los términos en que las personas nacionales de países no comunitarios y las apátridas podrán gozar en España de la protección internacional constituida por el derecho de asilo y la protección subsidiaria, así como el contenido de dicha protección internacional\"</span>. La protección internacional la constituyen el asilo y la protección subsidiaria; la protección temporal se rige por su reglamento específico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1445","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Derechos garantizados con el asilo y la protección subsidiaria. La protección concedida con el derecho de asilo y la protección subsidiaria consiste en:","o":["la no devolución ni expulsión de las personas a quienes se les haya reconocido, así como en la adopción de las medidas de efectos de la concesión previstas en la Ley.","la concesión de la nacionalidad española a las personas a quienes se les haya reconocido, transcurridos cinco años de residencia legal y continuada en territorio español.","la no devolución ni expulsión, salvo que la persona haya entrado ilegalmente en territorio español o carezca de documentación.","la expedición de una autorización de residencia temporal renovable cada cinco años, sin derecho a trabajar en España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la no devolución ni expulsión de las personas a quienes se les haya reconocido, así como en la adopción de las medidas de efectos de la concesión previstas en la Ley</mark></span>El <span class=\"ref-norma\">art. 5 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La protección concedida con el derecho de asilo y la protección subsidiaria consiste en la no devolución ni expulsión de las personas a quienes se les haya reconocido\"</span>. Consiste en la no devolución ni expulsión y en las medidas del art. 36 (efectos de la concesión). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1447","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. El concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos:","o":["siempre que el solicitante las haya manifestado públicamente en su país de origen antes de abandonarlo.","siempre que el solicitante haya obrado de acuerdo con tales opiniones, ideas o creencias en su país de origen.","independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias.","cuando el solicitante pertenezca a un partido u organización política perseguida en su país de origen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias</mark></span>El <span class=\"ref-norma\">art. 7.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) el concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos, independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias\"</span>. Es indiferente que haya obrado o no conforme a esas opiniones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1449","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución definidos en la Ley deberán estar relacionados:","o":["con los motivos de persecución mencionados en la Ley.","con la actuación de agentes estatales del país de origen.","con hechos ocurridos en los cinco años anteriores a la solicitud.","con la situación general de violencia en el país de origen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con los motivos de persecución mencionados en la Ley</mark></span>El <span class=\"ref-norma\">art. 6.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los actos de persecución definidos en el presente artículo deberán estar relacionados con los motivos mencionados en el artículo siguiente\"</span>. Deben estar relacionados con los motivos de persecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1450","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. Al valorar los motivos de persecución, el concepto de raza comprenderá, en particular:","o":["el color, la lengua o la pertenencia a una determinada nacionalidad.","el origen geográfico, la cultura o la pertenencia a un grupo social.","el color, el origen o las prácticas religiosas del grupo de pertenencia.","el color, el origen o la pertenencia a un determinado grupo étnico."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el color, el origen o la pertenencia a un determinado grupo étnico</mark></span>El <span class=\"ref-norma\">art. 7.1.a) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"a) el concepto de raza comprenderá, en particular, el color, el origen o la pertenencia a un determinado grupo étnico\"</span>. Raza: color, origen o pertenencia a un determinado grupo étnico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1451","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. El concepto de religión comprenderá, en particular, la profesión de creencias:","o":["teístas reconocidas oficialmente, y la participación en cultos formales en público, ya sea individualmente o en comunidad.","religiosas inscritas en el Registro de Entidades Religiosas, y la participación en cultos formales en privado o en público.","teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público.","teístas y no teístas, con exclusión de las ateas, y la participación en cultos formales en privado o en público."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público</mark></span>El <span class=\"ref-norma\">art. 7.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) el concepto de religión comprenderá, en particular, la profesión de creencias teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público\"</span>. Incluye creencias teístas, no teístas y ateas, y también la abstención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1452","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. El concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular:","o":["la pertenencia a un grupo determinado por sus creencias religiosas, sus opiniones políticas o su relación con los agentes de persecución del Estado del que sea nacional el solicitante.","la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado.","la residencia habitual en un determinado territorio, aunque se carezca de la ciudadanía de ningún Estado reconocido.","la pertenencia a una minoría nacional reconocida por los tratados internacionales en los que sea parte España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado</mark></span>El <span class=\"ref-norma\">art. 7.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) el concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular, la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado\"</span>. Nacionalidad: identidad cultural, étnica o lingüística, orígenes geográficos o políticos comunes o relación con la población de otro Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1453","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. En la valoración acerca de si la persona solicitante tiene fundados temores a ser perseguida será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución:","o":["a condición de que el agente de persecución se la atribuya.","siempre que la persona solicitante la invoque expresamente.","a condición de que la persecución proceda del Estado.","siempre que se acredite mediante prueba documental."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a condición de que el agente de persecución se la atribuya</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución, a condición de que el agente de persecución se la atribuya\"</span>. Basta con que el agente de persecución se la atribuya. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1454","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. En función de las circunstancias imperantes en el país de origen, se incluye en el concepto de grupo social determinado un grupo basado en una característica común de orientación sexual o identidad sexual, y, o, edad. No obstante:","o":["estos aspectos por sí solos darán lugar en todo caso a la aplicación del concepto de grupo social determinado, con independencia de las circunstancias del país de origen.","la orientación sexual solo podrá alegarse si la persona solicitante lo acredita mediante informe pericial.","la edad solo será tenida en cuenta cuando la persona solicitante sea menor de dieciocho años.","en ningún caso podrá entenderse como orientación sexual la realización de conductas tipificadas como delito en el ordenamiento jurídico español."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en ningún caso podrá entenderse como orientación sexual la realización de conductas tipificadas como delito en el ordenamiento jurídico español</mark></span>El <span class=\"ref-norma\">art. 7.1.e) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En ningún caso podrá entenderse como orientación sexual, la realización de conductas tipificadas como delito en el ordenamiento jurídico español\"</span>. Estos aspectos por sí solos no bastan, y en ningún caso se entienden como orientación sexual conductas delictivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1510","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Necesidades de protección internacional surgidas «in situ». Los fundados temores de ser perseguido o el riesgo real de sufrir daños graves pueden asimismo basarse en acontecimientos sucedidos o actividades en que haya participado la persona solicitante:","o":["únicamente con anterioridad al abandono del país de origen, si constan acreditados documentalmente.","durante su estancia en España, siempre que no hayan sido provocados por el propio solicitante.","con posterioridad a la presentación de la solicitud, siempre que se comuniquen en el plazo de un mes.","con posterioridad al abandono del país de origen o, en el caso de apátridas, el de residencia habitual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con posterioridad al abandono del país de origen o, en el caso de apátridas, el de residencia habitual</mark></span>El <span class=\"ref-norma\">art. 15.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"pueden asimismo basarse en acontecimientos sucedidos o actividades en que haya participado la persona solicitante con posterioridad al abandono del país de origen o, en el caso de apátridas, el de residencia habitual\"</span>. Necesidades «in situ»: hechos posteriores al abandono del país de origen o de residencia habitual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1511","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Necesidades de protección internacional surgidas «in situ». En los supuestos de necesidades de protección surgidas «in situ», se ponderará, a efectos de no reconocer la condición de refugiado:","o":["el hecho de que la persona solicitante no haya presentado la solicitud en el plazo de un mes desde que se produjeron los acontecimientos.","el hecho de que la persona solicitante haya residido legalmente en un tercer país seguro antes de su llegada a España.","el hecho de que el riesgo de persecución esté basado en circunstancias expresamente creadas por la persona solicitante tras abandonar su país de origen.","el hecho de que los acontecimientos no constituyan la expresión de convicciones mantenidas en el país de origen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el hecho de que el riesgo de persecución esté basado en circunstancias expresamente creadas por la persona solicitante tras abandonar su país de origen</mark></span>El <span class=\"ref-norma\">art. 15.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"se ponderará, a efectos de no reconocer la condición de refugiado, el hecho de que el riesgo de persecución esté basado en circunstancias expresamente creadas por la persona solicitante tras abandonar su país de origen\"</span>. Se pondera que el riesgo derive de circunstancias creadas expresamente por el solicitante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1512","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Derecho a solicitar protección internacional. Para el ejercicio del derecho a solicitar protección internacional, los solicitantes tendrán derecho a asistencia jurídica gratuita, que se extenderá a la formalización de la solicitud y a toda la tramitación del procedimiento. La asistencia jurídica será preceptiva:","o":["en todos los procedimientos, cualquiera que sea el lugar de presentación.","cuando las solicitudes se formalicen en los puestos fronterizos.","cuando se trate de menores no acompañados o personas vulnerables.","cuando la solicitud se tramite por el procedimiento de urgencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando las solicitudes se formalicen en los puestos fronterizos</mark></span>El <span class=\"ref-norma\">art. 16.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La asistencia jurídica referida en el párrafo anterior será preceptiva cuando las solicitudes se formalicen de acuerdo al procedimiento señalado en el artículo 21 de la presente Ley\"</span>. Es preceptiva en el procedimiento de solicitudes en puestos fronterizos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1530","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes presentadas en puestos fronterizos. En un puesto fronterizo, el Ministro del Interior podrá denegar la solicitud mediante resolución motivada cuando la persona solicitante hubiese formulado alegaciones incoherentes, contradictorias, inverosímiles o insuficientes. Dicha resolución deberá notificarse en el plazo máximo de:","o":["dos días desde su presentación.","diez días desde su presentación.","un mes desde su presentación.","cuatro días desde su presentación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuatro días desde su presentación</mark></span>El <span class=\"ref-norma\">art. 21.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"que deberá notificarse a la persona interesada en el plazo máximo de cuatro días desde su presentación\"</span>. También la denegación en frontera se notifica en cuatro días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1532","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes presentadas en puestos fronterizos. La resolución de la petición de reexamen contra la inadmisión a trámite o la denegación en frontera corresponderá al Ministro del Interior y deberá notificarse a la persona interesada en el plazo de:","o":["cuatro días desde el momento en que aquélla hubiese sido presentada.","dos días desde el momento en que aquélla hubiese sido presentada.","diez días desde la notificación de la resolución recurrida.","dos días desde la notificación de la resolución recurrida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos días desde el momento en que aquélla hubiese sido presentada</mark></span>El <span class=\"ref-norma\">art. 21.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La resolución de dicha petición, que corresponderá al Ministro del Interior, deberá notificarse a la persona interesada en el plazo de dos días desde el momento en que aquélla hubiese sido presentada\"</span>. Reexamen: dos días para pedirlo y dos días para resolverlo desde su presentación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1537","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Tramitación de urgencia. Cuando la solicitud de protección internacional se hubiera presentado en un Centro de Internamiento para Extranjeros:","o":["su tramitación deberá adecuarse a lo dispuesto para las solicitudes en frontera, y las admitidas a trámite seguirán la tramitación de urgencia.","su tramitación seguirá el procedimiento ordinario y el solicitante será puesto en libertad de forma inmediata por la autoridad que lo tenga a su cargo.","su tramitación seguirá el procedimiento de urgencia desde su presentación, sin fase de admisión a trámite.","su tramitación se suspenderá hasta que finalice el internamiento acordado por el Juez de Instrucción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su tramitación deberá adecuarse a lo dispuesto para las solicitudes en frontera, y las admitidas a trámite seguirán la tramitación de urgencia</mark></span>El <span class=\"ref-norma\">art. 25.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"su tramitación deberá adecuarse a lo dispuesto en el artículo 21 de esta Ley para las solicitudes en frontera. En todo caso, presentadas las solicitudes en estos términos, aquéllas que fuesen admitidas a trámite se ajustarán a la tramitación de urgencia prevista en el presente artículo\"</span>. En CIE: régimen de frontera para la admisión y, admitidas, tramitación de urgencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1538","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Tramitación de urgencia. Se acordará la tramitación de urgencia en las solicitudes:","o":["que hayan sido presentadas por personas mayores de sesenta y cinco años o con discapacidad, previa solicitud del Ministerio Fiscal.","que hayan sido presentadas en una Embajada o Consulado de España por personas no nacionales del país en que se encuentre la Representación diplomática, siempre que corra peligro su integridad física.","que planteen cuestiones relacionadas con la situación general de violencia en el país de origen de la persona solicitante.","que planteen exclusivamente cuestiones que no guarden relación con el examen de los requisitos para el reconocimiento de la condición de refugiado o la concesión de la protección subsidiaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">que planteen exclusivamente cuestiones que no guarden relación con el examen de los requisitos para el reconocimiento de la condición de refugiado o la concesión de la protección subsidiaria</mark></span>El <span class=\"ref-norma\">art. 25.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) que planteen exclusivamente cuestiones que no guarden relación con el examen de los requisitos para el reconocimiento de la condición de refugiado o la concesión de la protección subsidiaria\"</span>. Una de las causas es plantear exclusivamente cuestiones ajenas a los requisitos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1539","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Tramitación de urgencia. En la tramitación de urgencia de las solicitudes de protección internacional:","o":["la Oficina de Asilo y Refugio resolverá directamente los expedientes y los plazos del procedimiento ordinario se verán reducidos a un tercio.","la Comisión Interministerial de Asilo y Refugio no intervendrá y el Ministro del Interior resolverá en el plazo máximo de un mes.","la Comisión Interministerial de Asilo y Refugio será informada de los expedientes y los plazos del procedimiento ordinario se verán reducidos a la mitad.","el ACNUR será informado de los expedientes y los plazos del procedimiento ordinario se verán reducidos a la mitad, salvo el de resolución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Comisión Interministerial de Asilo y Refugio será informada de los expedientes y los plazos del procedimiento ordinario se verán reducidos a la mitad</mark></span>El <span class=\"ref-norma\">art. 25.3 y 25.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La Comisión Interministerial de Asilo y Refugio será informada de los expedientes que vayan a ser tramitados con carácter de urgencia\"</span>. Se informa a la CIAR y se aplican los plazos del ordinario reducidos a la mitad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1540","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Evaluación de las solicitudes. Para que se resuelva favorablemente la solicitud de protección internacional:","o":["será necesaria la prueba plena de la persecución o de los daños graves sufridos.","bastará que aparezcan indicios suficientes de persecución o de daños graves.","deberá acreditarse documentalmente la persecución mediante informes oficiales.","bastará la declaración de la persona solicitante, aunque no existan indicios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">bastará que aparezcan indicios suficientes de persecución o de daños graves</mark></span>El <span class=\"ref-norma\">art. 26.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Para que se resuelva favorablemente la solicitud bastará que aparezcan indicios suficientes de persecución o de daños graves\"</span>. Basta con indicios suficientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1541","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Archivo de la solicitud. Se podrá presumir que la retirada o desistimiento de la solicitud se ha producido cuando, en el plazo de __________, el solicitante no hubiese respondido a las peticiones de facilitar información esencial para su solicitud, no se hubiese presentado a una audiencia personal a la que hubiera sido convocado, o no compareciera para la renovación de la documentación.","o":["treinta días","quince días","diez días","dos meses"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">treinta días</mark></span>El <span class=\"ref-norma\">art. 27 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En todo caso, se podrá presumir que dicha retirada o desistimiento se ha producido cuando en el plazo de treinta días el solicitante no hubiese respondido a las peticiones de facilitar información esencial para su solicitud\"</span>. Treinta días, salvo que demuestre que se debió a circunstancias ajenas a su voluntad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1547","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Acogida de los solicitantes de protección internacional. En la acción concertada para la prestación de servicios de acogida, se acreditará la propiedad de los centros o el derecho al uso de los inmuebles por un periodo no inferior al de vigencia de la autorización, que podrá alcanzar:","o":["cinco años prorrogables de mutuo acuerdo, por igual periodo.","cuatro años improrrogables, sin perjuicio de una nueva autorización.","cuatro años prorrogables de mutuo acuerdo, por igual periodo.","dos años prorrogables de mutuo acuerdo, por otros dos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuatro años prorrogables de mutuo acuerdo, por igual periodo</mark></span>El <span class=\"ref-norma\">art. 31.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"que podrá alcanzar cuatro años prorrogables de mutuo acuerdo, por igual periodo\"</span>. Hasta cuatro años prorrogables por igual periodo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1552","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Autorización de trabajo a los solicitantes de protección internacional. Las personas solicitantes de protección internacional serán autorizadas para trabajar en España:","o":["transcurridos seis meses desde la presentación de la solicitud.","en los términos que reglamentariamente se establezcan.","desde la admisión a trámite de la solicitud.","una vez concedida la protección subsidiaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los términos que reglamentariamente se establezcan</mark></span>El <span class=\"ref-norma\">art. 32 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Las personas solicitantes de protección internacional serán autorizadas para trabajar en España en los términos que reglamentariamente se establezcan\"</span>. La Ley remite al reglamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1608","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Mantenimiento de la unidad familiar. Cuando, durante la tramitación de una solicitud de protección internacional, los miembros de la familia de la persona interesada se encontrasen también en España, y no hubiesen presentado una solicitud independiente de protección internacional:","o":["se les concederá por extensión familiar la protección internacional con carácter provisional, hasta la resolución de la solicitud.","se les autorizará la residencia en España con carácter provisional, condicionada a la resolución de la solicitud de protección internacional.","deberán presentar una solicitud independiente en el plazo de un mes para poder permanecer en España durante la tramitación.","se les autorizará la estancia en España por un período máximo de tres meses, prorrogable hasta la resolución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se les autorizará la residencia en España con carácter provisional, condicionada a la resolución de la solicitud de protección internacional</mark></span>El <span class=\"ref-norma\">art. 39.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"se les autorizará la residencia en España con carácter provisional, condicionada a la resolución de la solicitud de protección internacional y en los términos que reglamentariamente se determinen\"</span>. Residencia provisional condicionada a la resolución de la solicitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1609","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Extensión familiar del derecho de asilo o de la protección subsidiaria. Podrá garantizarse el restablecimiento de la unidad familiar por extensión familiar respecto de otro adulto que sea responsable del beneficiario de protección internacional, de acuerdo con la legislación española vigente, cuando dicho beneficiario sea:","o":["un menor no casado.","un menor de dieciséis años.","una persona con discapacidad.","un menor no acompañado tutelado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un menor no casado</mark></span>El <span class=\"ref-norma\">art. 40.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) Otro adulto que sea responsable del beneficiario de protección internacional, de acuerdo con la legislación española vigente, cuando dicho beneficiario sea un menor no casado\"</span>. Cuando el beneficiario sea un menor no casado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1611","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Extensión familiar del derecho de asilo o de la protección subsidiaria. En el procedimiento de extensión familiar del derecho de asilo o de la protección subsidiaria:","o":["la Comisión Interministerial de Asilo y Refugio tramitará las solicitudes y, previo informe de la Oficina de Asilo y Refugio, elevará la propuesta de resolución al Consejo de Ministros, quien resolverá.","la Oficina de Asilo y Refugio tramitará y resolverá las solicitudes, previo informe preceptivo del ACNUR y de la Comisión Interministerial.","la Oficina de Asilo y Refugio tramitará las solicitudes y, previo estudio en la Comisión Interministerial de Asilo y Refugio, se elevará la propuesta al Ministro del Interior, quien resolverá.","el Ministerio de Asuntos Exteriores tramitará las solicitudes a través de los consulados y el Ministro del Interior resolverá."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Oficina de Asilo y Refugio tramitará las solicitudes y, previo estudio en la Comisión Interministerial de Asilo y Refugio, se elevará la propuesta al Ministro del Interior, quien resolverá</mark></span>El <span class=\"ref-norma\">art. 40.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La Oficina de Asilo y Refugio tramitará las solicitudes de extensión familiar presentadas. Una vez instruidas se procederá, previo estudio en la Comisión interministerial de Asilo y Refugio, a elevar la propuesta de resolución al Ministro del Interior, quien resolverá\"</span>. Tramita la OAR; estudia la CIAR; resuelve el Ministro del Interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1619","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Revocación. Procederá la revocación del estatuto de refugiado o del estatuto de protección subsidiaria cuando la persona beneficiaria:","o":["haya abandonado el territorio español y fijado su residencia en otro país.","se haya acogido de nuevo, voluntariamente, a la protección del país de su nacionalidad, de forma expresa y reiterada.","haya tergiversado u omitido hechos, incluido el uso de documentos falsos, que fueron decisivos para la concesión del estatuto.","haya adquirido una nueva nacionalidad y disfrute de la protección de dicho país."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">haya tergiversado u omitido hechos, incluido el uso de documentos falsos, que fueron decisivos para la concesión del estatuto</mark></span>El <span class=\"ref-norma\">art. 44.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) la persona beneficiaria haya tergiversado u omitido hechos, incluido el uso de documentos falsos, que fueron decisivos para la concesión del estatuto de refugiado o de protección subsidiaria\"</span>. Las otras tres son causas de CESE, no de revocación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1620","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Revocación. A los efectos de la tramitación del expediente sancionador para la expulsión tras la revocación de la protección internacional, la Oficina de Asilo y Refugio:","o":["incoará directamente el expediente sancionador de expulsión por el procedimiento preferente, con comunicación al ACNUR.","dará traslado inmediato de la revocación al órgano competente para incoar el correspondiente expediente sancionador.","comunicará la revocación al ACNUR en el plazo de diez días antes de su ejecución.","remitirá el expediente al Juez de Instrucción para que autorice la expulsión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dará traslado inmediato de la revocación al órgano competente para incoar el correspondiente expediente sancionador</mark></span>El <span class=\"ref-norma\">art. 44.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"la Oficina de Asilo y Refugio dará traslado inmediato de la revocación al órgano competente para incoar el correspondiente expediente sancionador\"</span>. La OAR da traslado inmediato al órgano competente para incoar el expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1621","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Revocación. Ninguna revocación ni eventual expulsión posterior podrá determinar el envío de los interesados a un país en el que:","o":["exista peligro para su vida o su libertad o estén expuestos a tortura o a tratos inhumanos o degradantes, o carezcan de protección efectiva contra la devolución.","no se haya ratificado la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951, ni su Protocolo suscrito en Nueva York el 31 de enero de 1967.","la persona interesada no haya residido legalmente durante al menos cinco años antes de su llegada a España.","no exista una representación diplomática española que pueda velar por el cumplimiento de sus derechos fundamentales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">exista peligro para su vida o su libertad o estén expuestos a tortura o a tratos inhumanos o degradantes, o carezcan de protección efectiva contra la devolución</mark></span>El <span class=\"ref-norma\">art. 44.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"ninguna revocación ni eventual expulsión posterior podrá determinar el envío de los interesados a un país en el que exista peligro para su vida o su libertad o en el que estén expuestos a tortura o a tratos inhumanos o degradantes\"</span>. Principio de no devolución: peligro para la vida o libertad, tortura o tratos inhumanos, o falta de protección contra la devolución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1626","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Régimen general de protección. Se tendrá en cuenta la situación específica de las personas solicitantes o beneficiarias de protección internacional en situación de vulnerabilidad, tales como: Señale la INCORRECTA.","o":["menores no acompañados;","familias monoparentales con menores de edad;","personas que hayan padecido torturas, violaciones u otras formas graves de violencia psicológica o física o sexual y víctimas de trata de seres humanos;","personas que hayan permanecido en situación irregular en otro Estado miembro;"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">personas que hayan permanecido en situación irregular en otro Estado miembro;</mark></span>El <span class=\"ref-norma\">art. 46.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"tales como menores, menores no acompañados, personas con discapacidad, personas de edad avanzada, mujeres embarazadas, familias monoparentales con menores de edad\"</span>. La situación irregular previa en otro Estado no figura entre las situaciones de vulnerabilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1628","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Menores. Los menores solicitantes de protección internacional que hayan sido víctimas de cualquier forma de abuso, negligencia, explotación, tortura, trato cruel, inhumano, o degradante, o que hayan sido víctimas de conflictos armados recibirán:","o":["la protección subsidiaria con carácter automático, sin necesidad de entrevista personal.","la asistencia sanitaria y psicológica adecuada y la asistencia cualificada que precisen.","la asistencia sanitaria de urgencia y una autorización de residencia de larga duración en España.","la asistencia jurídica gratuita y un tutor designado por el Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la asistencia sanitaria y psicológica adecuada y la asistencia cualificada que precisen</mark></span>El <span class=\"ref-norma\">art. 47 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"recibirán la asistencia sanitaria y psicológica adecuada y la asistencia cualificada que precisen\"</span>. Asistencia sanitaria y psicológica adecuada y asistencia cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1631","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reasentamiento. El marco de protección de la Ley 12/2009 será de aplicación a las personas acogidas en España en virtud de programas de Reasentamiento elaborados por el Gobierno de la Nación, en colaboración con el ACNUR. Los refugiados reasentados en España:","o":["tendrán un estatuto de protección temporal renovable anualmente por el Consejo de Ministros.","tendrán el estatuto de beneficiarios de protección subsidiaria durante los primeros cinco años.","tendrán el mismo estatuto que los refugiados reconocidos en virtud de las disposiciones de la Ley.","tendrán derecho a una autorización de residencia temporal por razones humanitarias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tendrán el mismo estatuto que los refugiados reconocidos en virtud de las disposiciones de la Ley</mark></span>El <span class=\"ref-norma\">disp. adic. 1.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los refugiados reasentados en España tendrán el mismo estatuto que los refugiados reconocidos en virtud de las disposiciones de la presente Ley\"</span>. Mismo estatuto que los refugiados reconocidos conforme a la Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1639","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Incorporación del Derecho de la Unión Europea. Mediante la Ley 12/2009 se incorporan al Derecho español, entre otras, la Directiva 2005/85/CE, del Consejo, de 1 de diciembre, relativa a:","o":["normas mínimas para la acogida de los solicitantes de asilo en los Estados miembros de la Unión Europea.","los requisitos para el reconocimiento y el estatuto de nacionales de terceros países o apátridas como refugiados o personas que necesitan otro tipo de protección.","normas mínimas para los procedimientos que deben aplicar los Estados miembros para conceder o retirar la condición de refugiado.","la concesión de protección temporal en caso de afluencia masiva de personas desplazadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">normas mínimas para los procedimientos que deben aplicar los Estados miembros para conceder o retirar la condición de refugiado</mark></span>El <span class=\"ref-norma\">disp. final 2.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"y la Directiva 2005/85/CE, del Consejo, de 1 de diciembre, sobre normas mínimas para los procedimientos que deben aplicar los Estados miembros para conceder o retirar la condición de refugiado\"</span>. La 2005/85/CE es la de procedimientos; la 2004/83/CE, la de requisitos; también se incorpora la 2003/86/CE de reagrupación familiar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 18 — Derechos y obligaciones de los solicitantes ✱","q":[{"i":"6-3","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Derechos y obligaciones de los solicitantes. Serán obligaciones de los solicitantes de protección internacional las siguientes: Señale la incorrecta.","o":["Presentar, lo antes posible, todos aquellos elementos que, junto a su propia declaración, contribuyan a fundamentar su solicitud.","Informar a las autoridades del país de origen o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud.","Informar sobre su domicilio en España y cualquier cambio que se produzca en él.","Cooperar con las autoridades españolas en el procedimiento para la concesión de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Informar a las autoridades del país de origen o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"e) informar, asimismo, a la autoridad competente o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud\"</span>. Es ante la autoridad competente española, no ante las autoridades del país de origen (Verificado con el texto del temario oficial.)"},{"i":"6-26","p":"Ley 12/2009. Derechos y obligaciones de los solicitantes. Serán obligaciones de los solicitantes de protección internacional las siguientes: Señale la incorrecta.","o":["Presentar, lo antes posible, todos aquellos elementos que, junto a su propia declaración, contribuyan a fundamentar su solicitud.","Informar a las autoridades del país de origen o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud.","Informar sobre su domicilio en España y cualquier cambio que se produzca en él.","Cooperar con las autoridades españolas en el procedimiento para la concesión de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Informar a las autoridades del país de origen o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"e) informar, asimismo, a la autoridad competente o comparecer ante ella, cuando así se les requiera con relación a cualquier circunstancia de su solicitud\"</span>. Es ante la autoridad competente española, no ante las autoridades del país de origen (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1531","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes presentadas en puestos fronterizos. El plazo de cuatro días para notificar la denegación de la solicitud en frontera se ampliará hasta un máximo de diez días por resolución del Ministro del Interior, en los casos en que, por incurrir la persona solicitante en alguno de los supuestos de exclusión o de denegación:","o":["lo solicite la persona interesada o su abogado.","la Oficina de Asilo y Refugio lo estime necesario.","el ACNUR, de manera razonada, así lo solicite.","la Comisión Interministerial así lo proponga."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el ACNUR, de manera razonada, así lo solicite</mark></span>El <span class=\"ref-norma\">art. 21.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El plazo previsto en el apartado anterior se ampliará hasta un máximo de diez días por resolución del Ministro del Interior, en los casos en los que, por concurrir alguna de las circunstancias previstas en la letra f) del apartado primero del artículo 25, el ACNUR, de manera razonada, así lo solicite\"</span>. Ampliación a diez días a petición razonada del ACNUR. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 21 — Derecho al recurso contra los actos administrativos","q":[{"i":"6-4","p":"Ley Orgánica 4/2000. Los procedimientos de expulsión pueden ser:","o":["Preferentes.","Extraordinarios.","Urgentes.","Todos los anteriores son correctos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Preferentes</mark></span>Según el <span class=\"ref-norma\">art. 63.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Incoado el expediente en el que pueda proponerse la expulsión por tratarse de uno de los supuestos contemplados en el artículo 53.1.d), 53.1.f), 54.1.a), 54.1.b), y 57.2, la tramitación del mismo tendrá carácter preferente\"</span>. La Ley regula el procedimiento preferente y el ordinario; no existen procedimientos «extraordinarios» ni «urgentes» de expulsión (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1035","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho al recurso contra los actos administrativos. El régimen de ejecutividad de los actos administrativos dictados en materia de extranjería será el previsto con carácter general en la legislación vigente, salvo lo dispuesto en esta Ley para:","o":["la denegación de entrada en los puestos fronterizos habilitados.","la devolución de los extranjeros que pretendan entrar ilegalmente.","la tramitación de expedientes de expulsión con carácter preferente.","la tramitación de expedientes de expulsión por el procedimiento ordinario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la tramitación de expedientes de expulsión con carácter preferente</mark></span>El <span class=\"ref-norma\">art. 21.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"salvo lo dispuesto en esta Ley para la tramitación de expedientes de expulsión con carácter preferente\"</span>. La excepción al régimen general de ejecutividad es el expediente de expulsión preferente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1636","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Informe Anual. El Gobierno remitirá un informe anual sobre el número de personas que han solicitado asilo o protección subsidiaria, el número de personas a las que les ha sido concedido o denegado tal estatuto, los reasentamientos, la reagrupación familiar, los ceses y revocaciones y la situación específica de menores u otras personas vulnerables:","o":["al Defensor del Pueblo.","a las Cortes Generales.","a la Comisión Europea.","al ACNUR."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a las Cortes Generales</mark></span>El <span class=\"ref-norma\">disp. adic. 8.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El Gobierno remitirá a las Cortes Generales un informe anual sobre el número de personas que han solicitado asilo o protección subsidiaria\"</span>. El informe anual se remite a las Cortes Generales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 13 — Derechos en materia de vivienda ✱","q":[{"i":"6-5","p":"Ley Orgánica 4/2000. De los siguientes derechos, ¿cuál corresponderá únicamente a los extranjeros residentes?","o":["Derecho a acceder a los sistemas públicos de ayudas en materia de vivienda.","Sindicarse libremente o afiliarse a una organización profesional.","Derecho a la huelga.","Derecho a la asistencia sanitaria en los términos previstos en la legislación vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Derecho a acceder a los sistemas públicos de ayudas en materia de vivienda</mark></span>Según el <span class=\"ref-norma\">art. 13 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes tienen derecho a acceder a los sistemas públicos de ayudas en materia de vivienda en los términos que establezcan las leyes y las Administraciones competentes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1019","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos en materia de vivienda. Los extranjeros residentes tienen derecho a acceder a los sistemas públicos de ayudas en materia de vivienda en los términos que establezcan las leyes y las Administraciones competentes. En todo caso, tienen derecho a dichas ayudas en las mismas condiciones que los españoles:","o":["los extranjeros residentes con hijos menores a su cargo.","los extranjeros empadronados con más de un año de residencia.","los extranjeros residentes de larga duración.","los extranjeros residentes temporales con autorización renovada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los extranjeros residentes de larga duración</mark></span>El <span class=\"ref-norma\">art. 13 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, los extranjeros residentes de larga duración tienen derecho a dichas ayudas en las mismas condiciones que los españoles\"</span>. La equiparación plena «en todo caso» es para los residentes de larga duración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1602","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo o de protección subsidiaria. La concesión del derecho de asilo o de la protección subsidiaria implicará el acceso a la educación, a la asistencia sanitaria, a la vivienda, a la asistencia social y servicios sociales, a los derechos reconocidos a las víctimas de violencia de género, en su caso, a la seguridad social y a los programas de integración:","o":["en las mismas condiciones que los residentes de larga duración.","en los términos que establezca cada Comunidad Autónoma.","en las condiciones que fije el Ministerio de Trabajo e Inmigración.","en las mismas condiciones que los españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 36.1.f) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"f) el acceso a la educación, a la asistencia sanitaria, a la vivienda, a la asistencia social y servicios sociales, a los derechos reconocidos por la legislación aplicable a las personas víctimas de violencia de género, en su caso, a la seguridad social y a los programas de integración, en las mismas condiciones que los españoles\"</span>. En las mismas condiciones que los españoles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 20 — No admisión de solicitudes presentadas dentro del territorio español","q":[{"i":"6-7","p":"Ley 12/2009. No admisión de solicitudes presentadas dentro del Territorio Español. La no admisión a trámite prevista en este artículo deberá notificarse en el plazo:","o":["Máximo de cuatro días contado a partir de la presentación de la solicitud.","Máximo de un mes contado a partir del día siguiente a la presentación de la solicitud.","Máximo de dos meses contados a partir del día siguiente a la presentación de la solicitud.","Máximo de un mes contado a partir de la presentación de la solicitud."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Máximo de un mes contado a partir de la presentación de la solicitud</mark></span>Según el <span class=\"ref-norma\">art. 20.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La no admisión a trámite prevista en este artículo deberá notificarse en el plazo máximo de un mes contado a partir de la presentación de la solicitud\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-116","p":"(Ley 12/2009) No admisión de solicitudes presentadas dentro del territorio español. EL MINISTRO DEL INTERIOR, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes cuando concurra alguna de las circunstancias previstas en esta ley. La no admisión a trámite deberá notificarse en el plazo máximo de:","o":["Tres meses contados a partir de la presentación de la solicitud.","Quince días contados a partir de la presentación de la solicitud.","Un mes contado a partir de la presentación de la solicitud.","Diez días contados a partir de la presentación de la solicitud."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un mes contado a partir de la presentación de la solicitud</mark></span>Según el <span class=\"ref-norma\">art. 20.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La no admisión a trámite prevista en este artículo deberá notificarse en el plazo máximo de un mes contado a partir de la presentación de la solicitud\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1524","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. Cuando no corresponda a España el examen de la solicitud de conformidad con los Convenios Internacionales en que sea Parte, en la resolución por la que se acuerde la no admisión a trámite se indicará a la persona solicitante el Estado responsable de examinarla. En este caso:","o":["dicho Estado dispondrá de un plazo de un mes para aceptar su responsabilidad, entendiéndose aceptada si no responde.","dicho Estado habrá aceptado explícitamente su responsabilidad y se obtendrán garantías suficientes de protección para la vida, libertad e integridad física.","la persona solicitante será trasladada a dicho Estado en el plazo de setenta y dos horas, sin necesidad de garantías adicionales de protección para su vida o libertad.","dicho Estado deberá haber ratificado la Convención de Ginebra, sin que sea necesaria su aceptación explícita."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dicho Estado habrá aceptado explícitamente su responsabilidad y se obtendrán garantías suficientes de protección para la vida, libertad e integridad física</mark></span>El <span class=\"ref-norma\">art. 20.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En este caso, dicho Estado habrá aceptado explícitamente su responsabilidad y se obtendrán garantías suficientes de protección para la vida, libertad e integridad física de los interesados\"</span>. Aceptación explícita del Estado responsable y garantías suficientes de protección. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1525","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. Podrá no admitirse a trámite la solicitud cuando la persona solicitante proceda de un tercer país seguro, siempre que el solicitante sea readmitido en ese país y:","o":["existan vínculos por los cuales sería razonable que el solicitante fuera a ese país.","haya residido en ese país durante al menos seis meses antes de su llegada.","ese país figure en la lista de países seguros aprobada por el Gobierno.","el solicitante no haya alegado temor de persecución en ese país."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">existan vínculos por los cuales sería razonable que el solicitante fuera a ese país</mark></span>El <span class=\"ref-norma\">art. 20.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"siempre que el solicitante sea readmitido en ese país y existan vínculos por los cuales sería razonable que el solicitante fuera a ese país\"</span>. Readmisión y vínculos que hagan razonable ir a ese país. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1526","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. Por falta de requisitos podrá no admitirse a trámite la solicitud cuando la persona solicitante se halle reconocida como refugiada y tenga derecho a residir o a obtener protección internacional efectiva en un tercer Estado, siempre que:","o":["haya residido en ese país durante al menos un año y disponga de documentación de viaje válida expedida por sus autoridades, previo informe favorable del ACNUR sobre la situación de dicho país.","ese Estado sea miembro de la Unión Europea o parte en el Convenio Europeo de Derechos Humanos.","lo solicite expresamente el ACNUR, previo informe favorable de la Comisión Interministerial de Asilo y Refugio.","sea readmitida en ese país, no exista peligro para su vida o su libertad, ni esté expuesta a tortura o trato inhumano y tenga protección efectiva contra la devolución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sea readmitida en ese país, no exista peligro para su vida o su libertad, ni esté expuesta a tortura o trato inhumano y tenga protección efectiva contra la devolución</mark></span>El <span class=\"ref-norma\">art. 20.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"siempre que sea readmitida en ese país, no exista peligro para su vida o su libertad, ni esté expuesta a tortura o a trato inhumano o degradante y tenga protección efectiva contra la devolución al país perseguidor\"</span>. Readmisión, sin peligro para la vida o libertad, sin tortura y con protección contra la devolución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1527","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. Podrá no admitirse a trámite la solicitud cuando la persona solicitante hubiese reiterado una solicitud ya denegada en España o presentado una nueva solicitud con otros datos personales:","o":["aunque se planteen nuevas circunstancias relevantes en cuanto a las condiciones particulares o a la situación del país de origen o de residencia habitual.","siempre que la solicitud anterior hubiera sido denegada en los dos años anteriores a la nueva solicitud.","siempre que no se planteen nuevas circunstancias relevantes en cuanto a las condiciones particulares o a la situación del país de origen.","salvo que la nueva solicitud se presente en un puesto fronterizo distinto de aquel en que se presentó la anterior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">siempre que no se planteen nuevas circunstancias relevantes en cuanto a las condiciones particulares o a la situación del país de origen</mark></span>El <span class=\"ref-norma\">art. 20.1.e) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"e) cuando la persona solicitante hubiese reiterado una solicitud ya denegada en España o presentado una nueva solicitud con otros datos personales, siempre que no se planteen nuevas circunstancias relevantes en cuanto a las condiciones particulares o a la situación del país de origen o de residencia habitual de la persona interesada\"</span>. La inadmisión procede si no hay nuevas circunstancias relevantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1528","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. El transcurso del plazo para notificar la no admisión a trámite de una solicitud presentada dentro del territorio español sin que se haya notificado la resolución determinará:","o":["la inadmisión a trámite de la solicitud por silencio administrativo negativo, con los mismos efectos que la denegación.","la admisión a trámite de la solicitud y su permanencia provisional en territorio español, sin perjuicio de la resolución definitiva.","la concesión de la protección subsidiaria con carácter provisional hasta la resolución definitiva del procedimiento.","la tramitación de la solicitud por el procedimiento de urgencia, con plazos reducidos a la mitad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la admisión a trámite de la solicitud y su permanencia provisional en territorio español, sin perjuicio de la resolución definitiva</mark></span>El <span class=\"ref-norma\">art. 20.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El transcurso de dicho plazo sin que se haya notificado la resolución a la persona interesada determinará la admisión a trámite de la solicitud y su permanencia provisional en territorio español\"</span>. El silencio implica admisión a trámite y permanencia provisional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1529","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. No admisión de solicitudes presentadas dentro del territorio español. Sobre los efectos de la no admisión a trámite de solicitudes presentadas dentro del territorio español, señale la INCORRECTA:","o":["La constatación, con posterioridad a la admisión a trámite, de alguna de las circunstancias de inadmisión será causa de revocación de la protección.","La no admisión a trámite conllevará los mismos efectos que la denegación de la solicitud.","La no admisión a trámite deberá notificarse en el plazo máximo de un mes contado a partir de la presentación de la solicitud por la persona interesada.","El transcurso del plazo sin notificación determinará la permanencia provisional del solicitante en territorio español."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La constatación, con posterioridad a la admisión a trámite, de alguna de las circunstancias de inadmisión será causa de revocación de la protección</mark></span>El <span class=\"ref-norma\">art. 20.2 y 20.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La constatación, con posterioridad a la admisión a trámite de la solicitud de protección internacional, de alguna de las circunstancias que hubiesen justificado su no admisión será causa de denegación de aquélla\"</span>. Es causa de DENEGACIÓN, no de revocación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 19 — Efectos de la presentación de la solicitud ✱","q":[{"i":"6-8","p":"Ley 12/2009. Efectos de la presentación de la solicitud. Solicitada la protección, la persona extranjera:","o":["Podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","No podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","No podrá ser objeto de retorno o devolución, pero sí de expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","Podrá ser objeto de retorno y devolución, pero sí de expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida</mark></span>Según el <span class=\"ref-norma\">art. 19.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Solicitada la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-176","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la presentación de la solicitud. Señale la INCORRECTA.","o":["Solicitado la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención.","La solicitud de protección suspenderá, hasta la decisión definitiva, la ejecución del fallo de cualquier proceso de extradición de la persona interesada que se halle pendiente.","La solicitud de protección dará lugar al cómputo del inicio de los plazos previstos para su tramitación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención</mark></span>Según el <span class=\"ref-norma\">art. 19.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"podrá entregarse o extraditarse a una persona solicitante, según proceda, a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención y entrega\"</span>. SÍ podrá entregarse o extraditarse (Verificado con el texto del temario oficial.)"},{"i":"6-185","p":"Ley 12/2009... Efectos de la presentación de la solicitud. Señale la INCORRECTA:","o":["Las personas solicitantes de asilo tienen derecho a entrevistarse con un abogado en las dependencias de los puestos fronterizos y centros de internamiento de extranjeros.","Reglamentariamente, y sin perjuicio de las normas de funcionamiento establecidas para los puestos fronterizos y centros de internamiento de extranjeros, podrán establecerse condiciones para el ejercicio de este derecho derivadas de razones de seguridad, orden público o de su gestión administrativa.","La admisión de la solicitud de protección dará lugar al inicio del cómputo de los plazos previstos para su tramitación.","La resolución que admite a trámite una solicitud de asilo determinará el procedimiento correspondiente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La admisión de la solicitud de protección dará lugar al inicio del cómputo de los plazos previstos para su tramitación</mark></span>La C es la INCORRECTA: el cómputo de plazos lo inicia la SOLICITUD, no su admisión. La D es literal del art. 19.6. Según el <span class=\"ref-norma\">art. 19.5 y 19.6 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"5. La solicitud de protección dará lugar al inicio del cómputo de los plazos previstos para su tramitación. 6. La resolución que admita a trámite una solicitud de asilo determinará el procedimiento correspondiente.\"</span> (verificado con el texto del temario)."},{"i":"6-222","p":"Ley 12/2009... Efectos de la presentación de la solicitud. Señale la INCORRECTA.","o":["Solicitado la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención.","La solicitud de protección suspenderá, hasta la decisión definitiva, la ejecución del fallo de cualquier proceso de extradición de la persona interesada que se halle pendiente.","La solicitud de protección dará lugar al inicio del cómputo de los plazos previstos para su tramitación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención</mark></span>Según el <span class=\"ref-norma\">art. 19.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"podrá entregarse o extraditarse a una persona solicitante, según proceda, a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención y entrega\"</span>. SÍ podrá entregarse o extraditarse (Verificado con el texto del temario oficial.)"},{"i":"6-305","p":"Ley 12/2009... Efectos de la presentación de la solicitud. Señale la INCORRECTA.","o":["Solicitado la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.","No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención.","La solicitud de protección suspenderá, hasta la decisión definitiva, la ejecución del fallo de cualquier proceso de extradición de la persona interesada que se halle pendiente.","La solicitud de protección dará lugar al inicio del cómputo de los plazos previstos para su tramitación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá entregarse o extraditarse a una persona solicitante a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención</mark></span>Según el <span class=\"ref-norma\">art. 19.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"podrá entregarse o extraditarse a una persona solicitante, según proceda, a otro Estado miembro de la Unión Europea en virtud de las obligaciones dimanantes de una orden europea de detención y entrega\"</span>. SÍ podrá entregarse o extraditarse (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1520","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la presentación de la solicitud. Solicitada la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida. No obstante:","o":["por motivos de orden público, la autoridad competente podrá acordar la expulsión antes de que se resuelva la solicitud.","por motivos de salud o seguridad públicas, la autoridad competente podrá adoptar medidas cautelares en aplicación de la normativa de extranjería.","si la solicitud se presenta en un centro de internamiento de extranjeros, podrá ejecutarse la devolución acordada en el plazo de setenta y dos horas.","por motivos de seguridad nacional, el Ministro del Interior podrá acordar el retorno inmediato de la persona solicitante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por motivos de salud o seguridad públicas, la autoridad competente podrá adoptar medidas cautelares en aplicación de la normativa de extranjería</mark></span>El <span class=\"ref-norma\">art. 19.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"No obstante, por motivos de salud o seguridad públicas, la autoridad competente podrá adoptar medidas cautelares en aplicación de la normativa vigente en materia de extranjería e inmigración\"</span>. Por salud o seguridad públicas solo caben medidas cautelares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1521","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la presentación de la solicitud. La solicitud de protección suspenderá, hasta la decisión definitiva, la ejecución del fallo de cualquier proceso de extradición de la persona interesada que se halle pendiente. A tal fin, la solicitud:","o":["será comunicada inmediatamente al órgano judicial o al órgano gubernativo ante el que en ese momento tuviera lugar el correspondiente proceso.","será comunicada al Ministerio de Justicia en el plazo de diez días para que acuerde, en su caso, la suspensión del proceso de extradición pendiente.","deberá ser acompañada de un informe del ACNUR sobre el riesgo de persecución en el Estado requirente.","será comunicada al Estado requirente de la extradición a través de los cauces diplomáticos correspondientes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">será comunicada inmediatamente al órgano judicial o al órgano gubernativo ante el que en ese momento tuviera lugar el correspondiente proceso</mark></span>El <span class=\"ref-norma\">art. 19.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"A tal fin, la solicitud será comunicada inmediatamente al órgano judicial o al órgano gubernativo ante el que en ese momento tuviera lugar el correspondiente proceso\"</span>. Comunicación inmediata al órgano judicial o gubernativo del proceso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1523","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la presentación de la solicitud. En caso de que la tramitación de una solicitud de protección internacional pudiese exceder del plazo previsto para su resolución y notificación, se informará a la persona interesada del motivo de la demora. Ese plazo es de:","o":["tres meses, ampliables de acuerdo con la legislación de procedimiento administrativo.","seis meses, sin posibilidad de ampliación en ningún caso.","seis meses, ampliables de acuerdo con la legislación de procedimiento administrativo.","un año, ampliable por otros seis meses mediante resolución motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis meses, ampliables de acuerdo con la legislación de procedimiento administrativo</mark></span>El <span class=\"ref-norma\">art. 19.7 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En caso de que la tramitación de una solicitud pudiese exceder de seis meses, ampliables de acuerdo con lo previsto en el artículo 49 de la Ley 30/1992\"</span>. Seis meses, ampliables según la legislación de procedimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1554","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Intervención en el procedimiento de solicitud. A efectos de su intervención en el procedimiento, el ACNUR tendrá acceso a las personas solicitantes de protección internacional:","o":["salvo las que se encuentren en centros penitenciarios o de internamiento, en los que se requerirá en todo caso autorización judicial previa.","solo en las dependencias fronterizas, previa autorización del Ministro del Interior.","excepto las que se encuentren en centros de internamiento de extranjeros.","incluidas las que se encuentren en dependencias fronterizas o en centros de internamiento de extranjeros o penitenciarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">incluidas las que se encuentren en dependencias fronterizas o en centros de internamiento de extranjeros o penitenciarios</mark></span>El <span class=\"ref-norma\">art. 34 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"A estos efectos, tendrá acceso a las personas solicitantes, incluidas las que se encuentren en dependencias fronterizas o en centros de internamiento de extranjeros o penitenciarios\"</span>. Incluso en frontera, CIE y centros penitenciarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1635","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Normativa supletoria en materia de procedimiento. En lo no previsto en materia de procedimiento en la Ley 12/2009, será de aplicación con carácter supletorio:","o":["la Ley Orgánica 4/2000, de 11 de enero.","la Ley de Enjuiciamiento Civil.","la Ley 30/1992, de 26 de noviembre.","la Ley 29/1998, de 13 de julio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Ley 30/1992, de 26 de noviembre</mark></span>El <span class=\"ref-norma\">disp. adic. 7.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En lo no previsto en materia de procedimiento en la presente Ley, será de aplicación con carácter supletorio la Ley 30/1992, de 26 de noviembre\"</span>. Supletoriamente, la Ley 30/1992 de procedimiento administrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 60 — Efectos de la denegación de entrada ✱ R18","q":[{"i":"6-9","p":"Ley Orgánica 4/2000. Efectos de la denegación de entrada. ¿Qué les pasaría a los extranjeros a los que en el control de entrada se les deniegue la misma?","o":["Se les incoará un procedimiento sancionador.","Estarán obligados a regresar a su punto de origen.","Serán conducidos a la aduana.","Se les incoará un procedimiento de devolución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Estarán obligados a regresar a su punto de origen</mark></span>Se corrige la opción B, que decía «Serán conducidos a la frontera». Según el <span class=\"ref-norma\">art. 60.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros a los que en frontera se les deniegue la entrada según lo previsto por el artículo 26.2 de esta Ley, estarán obligados a regresar a su punto de origen.\"</span> (verificado con el texto del temario)."},{"i":"6-52","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Efectos de la denegación de entrada. La detención de un extranjero a efectos de proceder al regreso a consecuencia de la denegación de entrada será comunicada:","o":["Al Ministro del Interior y a la embajada o consulado de su país.","Al Gobierno y a la embajada o consulado de su país.","Al Subsecretario de Asuntos Exteriores y a la embajada o consulado de su país.","Al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país</mark></span>Se corrige la opción D: el texto dice «Ministerio», no «Ministro». Según el <span class=\"ref-norma\">art. 60.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La detención de un extranjero a efectos de proceder al regreso a consecuencia de la denegación de entrada será comunicada al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país.\"</span> (verificado con el texto del temario)."},{"i":"6-100","p":"Según la LO 4/2000, el extranjero que no cumpla los requisitos de entrada en España, será objeto de:","o":["Denegación de entrada.","Expulsión.","Devolución.","Readmisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Denegación de entrada</mark></span>Según el <span class=\"ref-norma\">art. 26.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"A los extranjeros que no cumplan los requisitos establecidos para la entrada, les será denegada mediante resolución motivada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-172","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Los extranjeros internados estarán privados:","o":["Únicamente del derecho de circulación.","Únicamente del derecho ambulatorio.","Del derecho a la libertad entre otros.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Únicamente del derecho ambulatorio</mark></span>Según el <span class=\"ref-norma\">art. 60.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros internados estarán privados únicamente del derecho ambulatorio.\"</span> (verificado con el texto del temario)."},{"i":"6-219","p":"Ley Orgánica 4/2000... Los extranjeros internados estarán privados:","o":["Únicamente del derecho de circulación.","Únicamente del derecho ambulatorio.","Del derecho a la libertad entre otros.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Únicamente del derecho ambulatorio</mark></span>Según el <span class=\"ref-norma\">art. 60.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros internados estarán privados únicamente del derecho ambulatorio\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-302","p":"Ley Orgánica 4/2000... Los extranjeros internados estarán privados:","o":["Únicamente del derecho de circulación.","Únicamente del derecho ambulatorio.","Del derecho a la libertad entre otros.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Únicamente del derecho ambulatorio</mark></span>Según el <span class=\"ref-norma\">art. 60.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros internados estarán privados únicamente del derecho ambulatorio\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-399","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la denegación de entrada. El extranjero durante su internamiento se encontrará en todo momento a disposición de:","o":["La autoridad judicial que lo autorizó.","La autoridad gubernativa que acordó el internamiento.","El Director del centro de internamiento de extranjeros.","La Delegación del Gobierno de la provincia del centro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La autoridad judicial que lo autorizó</mark></span>El <span class=\"ref-norma\">art. 60.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. El extranjero durante su internamiento se encontrará en todo momento a disposición de la autoridad judicial que lo autorizó, debiéndose comunicar a ésta por la autoridad gubernativa cualquier circunstancia en relación a la situación de los extranjeros internados.\"</span>"},{"i":"6-ia-1321","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la denegación de entrada. La resolución de la denegación de entrada conllevará la adopción inmediata de las medidas necesarias para que el extranjero regrese en el plazo más breve posible. Cuando el regreso fuera a retrasarse más de setenta y dos horas, la autoridad que hubiera denegado la entrada:","o":["se dirigirá al Juez de Instrucción para que determine el lugar donde hayan de ser internados hasta ese momento.","acordará por sí misma el internamiento del extranjero en un centro de internamiento de extranjeros.","se dirigirá al Ministerio Fiscal para que solicite al Juez de Instrucción la expulsión del extranjero por el procedimiento preferente.","pondrá al extranjero a disposición de la Delegación del Gobierno hasta que se ejecute el regreso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se dirigirá al Juez de Instrucción para que determine el lugar donde hayan de ser internados hasta ese momento</mark></span>El <span class=\"ref-norma\">art. 60.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Cuando el regreso fuera a retrasarse más de setenta y dos horas, la autoridad que hubiera denegado la entrada se dirigirá al Juez de Instrucción para que determine el lugar donde hayan de ser internados hasta ese momento\"</span>. Más de 72 horas: decide el Juez de Instrucción el lugar de internamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1322","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la denegación de entrada. Los lugares de internamiento para extranjeros no tendrán carácter penitenciario, y estarán dotados de servicios:","o":["sociales, sanitarios, educativos y religiosos.","jurídicos, sanitarios, de traducción y de seguridad.","sociales, jurídicos, laborales y sanitarios.","sociales, jurídicos, culturales y sanitarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sociales, jurídicos, culturales y sanitarios</mark></span>El <span class=\"ref-norma\">art. 60.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los lugares de internamiento para extranjeros no tendrán carácter penitenciario, y estarán dotados de servicios sociales, jurídicos, culturales y sanitarios\"</span>. Servicios sociales, jurídicos, culturales y sanitarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1422","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos. En cumplimiento de lo establecido por la normativa comunitaria, la tramitación de procedimientos relativos a visados de tránsito y de estancia se realizará sobre la aplicación informática específicamente creada a los efectos, dependiente:","o":["del Ministerio del Interior, interconectada con el Registro central de extranjeros.","del Ministerio de Trabajo e Inmigración, integrada en la aplicación informática común y en el Registro central de extranjeros.","de la Comisión Europea, a través del Sistema de Información de Visados.","del Ministerio de Asuntos Exteriores y de Cooperación, interconectada con la aplicación informática común."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del Ministerio de Asuntos Exteriores y de Cooperación, interconectada con la aplicación informática común</mark></span>El <span class=\"ref-norma\">disp. adic. 5.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la tramitación de procedimientos relativos a visados de tránsito y de estancia se realizará sobre la aplicación informática específicamente creada a los efectos, dependiente del Ministerio de Asuntos Exteriores y de Cooperación, que estará interconectada con la aplicación informática común\"</span>. Visados de tránsito y estancia: aplicación del Ministerio de Asuntos Exteriores, interconectada con la común. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social","q":[{"i":"6-10","p":"Ley Orgánica 4/2000. De la salida de España. La salida será obligatoria en los siguientes supuestos: señale la incorrecta.","o":["Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario.","Ejecución de una orden judicial por un delito sexual, en los casos previstos en el Código Penal.","Expulsión o devolución acordadas por resolución administrativa en los casos previstos en la presente Ley.","Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ejecución de una orden judicial por un delito sexual, en los casos previstos en el Código Penal</mark></span>Según el <span class=\"ref-norma\">art. 28.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal. b) Expulsión o devolución acordadas por resolución administrativa en los casos previstos en la presente Ley. c) Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España. d) Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario\"</span>. La salida obligatoria por orden judicial es la expulsión en los casos previstos en el Código Penal, no la ejecución de una orden por un delito sexual (se corrigen las opciones A, C y D, que venían alteradas: «transportista», «retorno obligatorio», «desaparición administrativa») (Verificado con el texto del temario oficial.)"},{"i":"6-12","p":"Ley Orgánica 4/2000. Sanciones. Las infracciones graves con multa de _______________________.","o":["501 hasta 10.000 euros.","hasta 500 euros.","500 hasta 10.000 euros.","10.001 hasta 100.000 euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">501 hasta 10.000 euros</mark></span>Según el <span class=\"ref-norma\">art. 55.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Las infracciones graves con multa de 501 hasta 10.000 euros\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-21","p":"Ley Orgánica 4/2000. Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un periodo superior a seis meses, obtendrán la Tarjeta de Identidad de Extranjero, que:","o":["Deberán solicitar personalmente en el plazo de un mes desde su entrada en España o desde que se conceda la autorización, respectivamente.","Estarán exceptuados de dicha obligación los titulares de un visado de residencia y trabajo de temporada.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 4.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"que deberán solicitar personalmente en el plazo de un mes desde su entrada en España o desde que se conceda la autorización, respectivamente. Estarán exceptuados de dicha obligación los titulares de un visado de residencia y trabajo de temporada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-31","p":"Ley Orgánica 4/2000. Residencia de larga duración. Señale la correcta.","o":["Autoriza a únicamente a residir en España indefinidamente, en las mismas condiciones que los españoles.","Tienen derecho a residencia de larga duración los que hayan tenido residencia temporal en España durante diez años de forma continuada.","Los extranjeros residentes de larga duración en otro Estado miembro de la Unión Europea no podrán solicitar y obtener una autorización de residencia de larga duración en España.","Con carácter reglamentario se establecerán criterios para la concesión de otras autorizaciones de residencia de larga duración en supuestos individuales de especial vinculación con España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Con carácter reglamentario se establecerán criterios para la concesión de otras autorizaciones de residencia de larga duración en supuestos individuales de especial vinculación con España</mark></span>La opción B es falsa: son CINCO años de residencia temporal continuada (art. 32.2), no diez. La A falla por «únicamente» (autoriza a residir Y TRABAJAR) y la C contradice el art. 32.3. Según el <span class=\"ref-norma\">art. 32.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Con carácter reglamentario se establecerán criterios para la concesión de otras autorizaciones de residencia de larga duración en supuestos individuales de especial vinculación con España.\"</span> (verificado con el texto del temario)."},{"i":"6-32","p":"Ley Orgánica 4/2000. Régimen jurídico de los extranjeros. De la entrada y salida del territorio español. De la entrada. Señale la correcta.","o":["Excepcionalmente, el Ministro del Interior podrá proponer al Ministro de Asuntos Exteriores que prohíba la salida del territorio español por razones de seguridad nacional o de salud pública.","Excepcionalmente, el Ministro del Interior podrá prohibir la salida del territorio español por razones de seguridad nacional o de salud pública.","Excepcionalmente, el Ministro de Asuntos Exteriores podrá proponer al Ministro del Interior que prohíba la salida del territorio español por razones de seguridad nacional o de salud pública.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Excepcionalmente, el Ministro del Interior podrá prohibir la salida del territorio español por razones de seguridad nacional o de salud pública</mark></span>Según el <span class=\"ref-norma\">art. 28.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Excepcionalmente, el Ministro del Interior podrá prohibir la salida del territorio español por razones de seguridad nacional o de salud pública. La instrucción y resolución de los expedientes de prohibición tendrá siempre carácter individual.\"</span> (verificado con el texto del temario)."},{"i":"6-36","p":"Ley Orgánica 4/2000. Autorización de Residencia y trabajo por cuenta ajena. Para la concesión inicial de la autorización de residencia y trabajo, en el caso de trabajadores por cuenta ajena, se tendrá en cuenta:","o":["La tasa de paro.","La situación nacional de empleo.","La situación europea de empleo.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La situación nacional de empleo</mark></span>Según el <span class=\"ref-norma\">art. 38.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Para la concesión inicial de la autorización de residencia y trabajo, en el caso de trabajadores por cuenta ajena, se tendrá en cuenta la situación nacional de empleo\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-38","p":"Ley Orgánica 4/2000. De las infracciones en materia de extranjería y su régimen sancionador. Para la graduación de las sanciones, el órgano competente en imponerlas se ajustará a criterios de:","o":["Proporcionalidad.","Capacidad económica del infractor.","Daño de la prohibición.","Todos son correctos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Proporcionalidad</mark></span>Según el <span class=\"ref-norma\">art. 55.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Para la graduación de las sanciones, el órgano competente en imponerlas se ajustará a criterios de proporcionalidad\"</span>. La capacidad económica del infractor se tiene en cuenta para la CUANTÍA de la sanción, no para su graduación, y el «daño de la prohibición» no existe (la respuesta «todos» era errónea) (Verificado con el texto del temario oficial.)"},{"i":"6-44","p":"Ley Orgánica 4/2000. De la salida de España. La salida será obligatoria en los siguientes supuestos: señale la incorrecta.","o":["Cumplimiento del plazo en el que un transportista extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario.","Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal.","Expulsión o devolución acordadas por resolución administrativa en los casos previstos en la presente Ley.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cumplimiento del plazo en el que un transportista extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario</mark></span>Según el <span class=\"ref-norma\">art. 28.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal. b) Expulsión o devolución acordadas por resolución administrativa en los casos previstos en la presente Ley. c) Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España. d) Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario\"</span>. Es un trabajador (no un transportista) quien se compromete a regresar en un programa de retorno voluntario (Verificado con el texto del temario oficial.)"},{"i":"6-45","p":"Ley Orgánica 4/2000. Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un periodo superior a seis meses, obtendrán la Tarjeta de Identidad de Extranjero, que:","o":["Deberán solicitar personalmente en el plazo de un mes desde su entrada en España o desde que se conceda la autorización, respectivamente.","Estarán exceptuados de dicha obligación los titulares de un visado de residencia y trabajo de temporada.","A y B son correctas.","Los extranjeros se podrán ver privados de su documentación, salvo en los supuestos y con los requisitos previstos en esta Ley Orgánica, entre otras."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 4.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"que deberán solicitar personalmente en el plazo de un mes desde su entrada en España o desde que se conceda la autorización, respectivamente. Estarán exceptuados de dicha obligación los titulares de un visado de residencia y trabajo de temporada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-48","p":"Ley Orgánica 4/2000. La residencia de larga duración es la situación que autoriza:","o":["A residir y trabajar en España por un periodo de tiempo superior a 10 años.","A residir y trabajar en España indefinidamente, en las mismas condiciones que los españoles.","Solo a trabajar en España indefinidamente, en las mismas condiciones que los españoles.","A residir y trabajar en España por un período de cinco años prorrogable, en las mismas condiciones que los españoles."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A residir y trabajar en España indefinidamente, en las mismas condiciones que los españoles</mark></span>Según el <span class=\"ref-norma\">art. 32.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La residencia de larga duración es la situación que autoriza a residir y trabajar en España indefinidamente, en las mismas condiciones que los españoles\"</span>. La opción marcada antes tenía una errata («residir en trabajar»); la literal es la B (Verificado con el texto del temario oficial.)"},{"i":"6-50","p":"Ley Orgánica 4/2000. ¿En qué casos podrá aplicarse, en atención al principio de proporcionalidad, en lugar de la sanción de multa, la expulsión del territorio español?","o":["Cuando los infractores sean extranjeros y se encuentren trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuenten con autorización de residencia válida.","Por el retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado.","Por permanecer o trabajar en España un extranjero cuya entrada legal haya contado con una invitación expresa del infractor.","Por contraer matrimonio, simular relación afectiva análoga o constituirse en representante legal de un menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando los infractores sean extranjeros y se encuentren trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuenten con autorización de residencia válida</mark></span>Se corrige la opción A para recoger la infracción del art. 53.1.b). La antigua C (promover la permanencia irregular de un invitado) es del art. 53.2.c), que NO permite la expulsión; B es leve y D es del art. 53.2.b). Según el <span class=\"ref-norma\">art. 57.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Cuando los infractores sean extranjeros y realicen conductas de las tipificadas como muy graves, o conductas graves de las previstas en los apartados a), b), c), d) y f) del artículo 53.1 de esta Ley Orgánica, podrá aplicarse, en atención al principio de proporcionalidad, en lugar de la sanción de multa, la expulsión del territorio español...\"</span> (verificado con el texto del temario)."},{"i":"6-54","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. La extinción de la residencia de larga duración se producirá en alguno de los casos siguientes:","o":["Cuando se produzca la ausencia del territorio de la Unión Europea durante 12 meses consecutivos.","Cuando se adquiera la residencia de larga duración en otro Estado miembro.","Cuando, obtenida la autorización por la persona a quien otro Estado miembro reconoció protección internacional, las autoridades de dicho Estado hubieran resuelto el cese o la revocación de la citada protección.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>Según el <span class=\"ref-norma\">art. 32.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Cuando se produzca la ausencia del territorio de la Unión Europea durante 12 meses consecutivos\"</span>. Se corrige C, que venía alterada; las tres son causas de extinción (Verificado con el texto del temario oficial.)"},{"i":"6-55","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. De la salida de España. La salida será obligatoria en los siguientes supuestos:","o":["Ejecución del decreto acordado por orden judicial, en los casos previstos en el Código Civil.","Ejecución de la devolución acordada por resolución judicial en los casos previstos en la presente Ley.","Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España.","Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno obligatorio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España</mark></span>Según el <span class=\"ref-norma\">art. 28.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España\"</span>. La opción correcta venía alterada («desestimación», «permanentemente») (Verificado con el texto del temario oficial.)"},{"i":"6-68","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Ingreso en Centros de Internamiento. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de _______ y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.","o":["45 días.","60 días.","90 días.","30 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60 días</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-69","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de _______ y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.","o":["45 días.","60 días.","90 días.","30 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60 días</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-71","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. La incoación del expediente, las medidas cautelares de detención e internamiento y la resolución final del expediente de expulsión del extranjero serán comunicadas:","o":["Al Ministerio de Asuntos Exteriores, al Ministerio del Interior y a la embajada o consulado de su país.","Al Ministerio del Interior y a la embajada o consulado de su país.","Al Ministro de Asuntos Exteriores y al Ministro del Interior.","Al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país</mark></span>Según el <span class=\"ref-norma\">art. 62.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La incoación del expediente, las medidas cautelares de detención e internamiento y la resolución final del expediente de expulsión del extranjero serán comunicadas al Ministerio de Asuntos Exteriores y a la embajada o consulado de su país\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-81","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. Las infracciones tipificadas en esta ley serán sancionadas en los términos siguientes:","o":["Las infracciones leves con multa de hasta 600 euros.","Las infracciones graves con multa de 501 hasta 10.000 euros.","Las infracciones menos grave con multa desde 10.001 hasta 10.500 euros.","Las infracciones muy grave con multa desde 10.001 hasta 100.001 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las infracciones graves con multa de 501 hasta 10.000 euros</mark></span>Según el <span class=\"ref-norma\">art. 55.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Las infracciones graves con multa de 501 hasta 10.000 euros\"</span>. Leves: hasta 500 euros; muy graves: de 10.001 hasta 100.000 euros (Verificado con el texto del temario oficial.)"},{"i":"6-107","p":"(Ley Orgánica 4/2000) Sanciones. Para la graduación de las sanciones, el órgano competente en imponerlas se ajustará a:","o":["Criterios de proporcionalidad, valorando el grado de culpabilidad.","El daño producido o el riesgo derivado de la infracción y su trascendencia.","Criterios de proporcionalidad.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 55.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"se ajustará a criterios de proporcionalidad, valorando el grado de culpabilidad y, en su caso, el daño producido o el riesgo derivado de la infracción y su trascendencia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-114","p":"(Ley Orgánica 4/2000) Derechos y libertades de los extranjeros. Derecho a la documentación. Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un periodo superior a seis meses, obtendrán, la tarjeta de identidad de extranjero, que deberán solicitar personalmente en el plazo de:","o":["Un mes desde su entrada en España o desde que se conceda la autorización respectivamente.","Dos meses desde su entrada en España o desde que se conceda la autorización, respectivamente.","Tres meses desde su entrada en España o desde que se conceda la autorización, respectivamente.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes desde su entrada en España o desde que se conceda la autorización respectivamente</mark></span>Según el <span class=\"ref-norma\">art. 4.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un período superior a seis meses, obtendrán la tarjeta de identidad de extranjero, que deberán solicitar personalmente en el plazo de un mes desde su entrada en España o desde que se conceda la autorización, respectivamente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-117","p":"(Ley Orgánica 4/2000) Cuantía de las tasas. Los importes de las tasas por tramitación de la solicitud de visado se adecuarán a la revisión que proceda por aplicación del ________. Se acomodarán, asimismo, al importe que pueda establecerse por aplicación del ________.","o":["Derecho Comunitario / Principio de reciprocidad.","Derecho mercantil / Principio de reciprocidad.","Reglamentos de la Unión / Principio de colaboración.","Derechos y decisiones de la Unión / Derecho comunitario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Derecho Comunitario / Principio de reciprocidad</mark></span>Según el <span class=\"ref-norma\">art. 48.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los importes de las tasas por tramitación de la solicitud de visado se adecuarán a la revisión que proceda por aplicación del derecho comunitario. Se acomodarán, asimismo, al importe que pueda establecerse por aplicación del principio de reciprocidad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-126","p":"(Ley Orgánica 4/2000) Señale la opción INCORRECTA sobre la renovación de la Autorización de Residencia y Trabajo por cuenta ajena.","o":["Cuando el extranjero sea beneficiario de una prestación económica asistencial de carácter público destinada a lograr su inserción sociolaboral.","Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo.","Cuando persista o se renueve el contrato de trabajo o se mantenga la relación laboral como víctima de violencia de género.","Cuando concurran otras circunstancias previstas reglamentariamente, en particular, los supuestos de extinción del contrato de trabajo o suspensión de la relación laboral como consecuencia de ser víctima de violencia de género."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando persista o se renueve el contrato de trabajo o se mantenga la relación laboral como víctima de violencia de género</mark></span>Según el <span class=\"ref-norma\">art. 38.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato\"</span>. Se corrige B, que también venía alterada (Verificado con el texto del temario oficial.)"},{"i":"6-134","p":"(Ley Orgánica 4/2000) ¿Qué autoridad podrá prohibir excepcionalmente la salida del territorio español por razones de seguridad nacional o de salud pública?","o":["Presidente del Gobierno.","Ministro de Defensa.","Ministro del Interior.","Ministro de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 28.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Excepcionalmente, el Ministro del Interior podrá prohibir la salida del territorio español por razones de seguridad nacional o de salud pública\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-145","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la documentación. Los extranjeros que se encuentren en territorio español tienen el derecho y el deber de conservar:","o":["La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de destino, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen, así como la que acredite su situación en la Comunidad Autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España</mark></span>Según el <span class=\"ref-norma\">art. 4.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros que se encuentren en territorio español tienen el derecho y el deber de conservar la documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-151","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. De las infracciones en materia de extranjería y su régimen sancionador. En ningún caso podrán imponerse conjuntamente las sanciones de:","o":["Expulsión y multa.","Multa y clausura.","Expulsión y sanción administrativa.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Expulsión y multa</mark></span>Según el <span class=\"ref-norma\">art. 57.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-157","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de:","o":["30 días.","60 días.","90 días.","120 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60 días</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.\"</span> (verificado con el texto del temario)."},{"i":"6-167","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. De las autorizaciones para la realización de actividades lucrativas. Autorización de residencia y trabajo por cuenta ajena. Señale la CORRECTA.","o":["Para la concesión inicial de la autorización de residencia y trabajo, en el caso de trabajadores por cuenta propia, se tendrá en cuenta la situación nacional de empleo.","La situación nacional de empleo será determinada por el Servicio Público de Empleo Estatal con la información proporcionada por el Estado y con aquella derivada de indicadores estadísticos oficiales.","La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación.","A partir de la primera concesión, las autorizaciones se concederán con limitación de ámbito geográfico u ocupación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación</mark></span>Según el <span class=\"ref-norma\">art. 38.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-177","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de Residencia y trabajo por cuenta ajena. El Catálogo de Ocupaciones de Difícil Cobertura será aprobado:","o":["Previa consulta de la Comisión Laboral Tripartita de Inmigración.","Previa consulta de la conferencia sectorial en la materia.","Previa consulta del Ministerio de Migraciones.","Previa consulta del Gobierno y las Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Previa consulta de la Comisión Laboral Tripartita de Inmigración</mark></span>Según el <span class=\"ref-norma\">art. 38.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"será aprobado previa consulta de la Comisión Laboral Tripartita de Inmigración\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-189","p":"Ley Orgánica 4/2000... Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito, será sancionado con:","o":["Multa de 1.001 a 100.000 euros.","Multa de 3.001 a 10.000 euros por cada viajero.","Con un mínimo de 500.000 euros al tanto alzado, con independencia del número de viajeros transportados.","Multa de 10.001 a 100.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Multa de 10.001 a 100.000 euros</mark></span>Según el <span class=\"ref-norma\">art. 55.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Las infracciones muy graves con multa desde 10.001 hasta 100.000 euros\"</span>. Es una infracción muy grave (Verificado con el texto del temario oficial.)"},{"i":"6-192","p":"Ley Orgánica 4/2000... Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el Instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares: señale la opción INCORRECTA.","o":["Presentación periódica ante las autoridades competentes.","Residencia obligatoria en determinado lugar.","Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de las medidas.","Internamiento preventivo, previa autorización gubernativa, en los centros de internamiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Internamiento preventivo, previa autorización gubernativa, en los centros de internamiento</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Internamiento preventivo, previa autorización judicial en los centros de internamiento\"</span>. La autorización es judicial, no gubernativa (Verificado con el texto del temario oficial.)"},{"i":"6-197","p":"Ley Orgánica 4/2000... Autorización de residencia y trabajo por cuenta ajena. La autorización de residencia y trabajo se renovará a su expiración: señale la opción CORRECTA.","o":["Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato.","Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo.","Cuando el extranjero sea beneficiario de una prestación económica asistencial de carácter público destinada a lograr su inserción social o laboral.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 38.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato. b) Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo. c) Cuando el extranjero sea beneficiario de una prestación económica asistencial de carácter público destinada a lograr su inserción social o laboral\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-203","p":"Ley Orgánica 4/2000... La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a:","o":["Cinco años.","Diez años.","Ocho años.","Nueve años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 31.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-209","p":"Ley Orgánica 4/2000... Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el Instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares:","o":["Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida.","Internamiento preventivo, previa autorización judicial en los centros de internamiento.","Cualquier otra medida cautelar que el juez estime adecuada y suficiente.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Presentación periódica ante las autoridades competentes. b) Residencia obligatoria en determinado lugar. c) Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida. d) Detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de 72 horas previas a la solicitud de internamiento. En cualquier otro supuesto de detención, la puesta a disposición judicial se producirá en un plazo no superior a 72 horas. e) Internamiento preventivo, previa autorización judicial en los centros de internamiento. f) Cualquier otra medida cautelar que el juez estime adecuada y suficiente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-220","p":"Ley Orgánica 4/2000... De las autorizaciones para la realización de actividades lucrativas. Autorización de residencia y trabajo por cuenta ajena. Señale la CORRECTA.","o":["Para la concesión inicial de la autorización de residencia y trabajo, en el caso de trabajadores por cuenta propia, se tendrá en cuenta la situación nacional de empleo.","La situación nacional de empleo será determinada por el Servicio Público de Empleo Estatal con la información proporcionada por el Estado y con aquella derivada de indicadores estadísticos oficiales.","La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación.","A partir de la primera concesión, las autorizaciones se concederán con limitación de ámbito geográfico u ocupación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación</mark></span>Según el <span class=\"ref-norma\">art. 38.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación\"</span>. La D era también literal; se reformula como falsa (Verificado con el texto del temario oficial.)"},{"i":"6-223","p":"Ley Orgánica 4/2000... En ningún caso podrán imponerse conjuntamente las sanciones de:","o":["Expulsión y multa.","Multa y pena de cárcel.","Expulsión y sanción administrativa.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Expulsión y multa</mark></span>Según el <span class=\"ref-norma\">art. 57.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa.\"</span> (verificado con el texto del temario)."},{"i":"6-228","p":"Ley Orgánica 4/2000... Ingreso en centros de internamiento. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de:","o":["30 días.","60 días.","90 días.","120 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60 días</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-229","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Procedimiento de expulsión. Indique cuál de las siguientes es una medida cautelar posible:","o":["La suspensión de sus actividades.","Presentación periódica ante las autoridades competentes.","La prestación de fianzas.","La inmovilización del medio de transporte utilizado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Presentación periódica ante las autoridades competentes</mark></span>Según el <span class=\"ref-norma\">art. 5.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Presentación periódica ante las autoridades competentes\"</span>. Las otras son medidas previstas para los expedientes sancionadores de transportistas (Verificado con el texto del temario oficial.)"},{"i":"6-231","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Ingreso y permanencia en Centros de Internamiento de Extranjeros. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de __________ y sin que pueda ___________ en virtud de un mismo expediente.","o":["90 días / prorrogarse.","60 días / acordarse un nuevo internamiento.","90 días / acordarse un nuevo internamiento.","60 días / prorrogarse."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60 días / acordarse un nuevo internamiento</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-237","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Procedimiento de expulsión ordinario. La duración del plazo de cumplimiento voluntario oscilará entre:","o":["Siete y treinta días.","Cinco y treinta días.","Siete y quince días.","Cinco y quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Siete y treinta días</mark></span>Según el <span class=\"ref-norma\">art. 63 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La duración de dicho plazo oscilará entre siete y treinta días\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-240","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. La salida de los extranjeros del territorio español será obligatoria en los siguientes supuestos: señale la INCORRECTA.","o":["Expulsión del territorio español por orden judicial, en los casos previstos en la Ley de Enjuiciamiento Criminal.","Expulsión o devolución acordadas por resolución administrativa en los casos previstos en la Ley Orgánica sobre Derechos y Libertades de los Extranjeros en España y su Integración Social.","Denegación administrativa de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España.","Cumplimiento del plazo en el que un trabajador extranjero se hubiese comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Expulsión del territorio español por orden judicial, en los casos previstos en la Ley de Enjuiciamiento Criminal</mark></span>Según el <span class=\"ref-norma\">art. 28.3.a de la LO 4/2000</span>, la salida será obligatoria en caso de: <span class=\"ref-concepto\">\"Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal.\"</span> La opción A es la incorrecta porque cita la Ley de Enjuiciamiento Criminal en lugar del Código Penal. Las demás recogen supuestos literales del art. 28.3 (b, c y d; esta última, el cumplimiento del plazo de un programa de retorno voluntario) (verificado con el texto del temario)."},{"i":"6-247","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. En el procedimiento de expulsión, cuál de las siguientes es una medida cautelar correcta:","o":["Detención cautelar... por un período máximo de 48 horas...","Cualquier otra medida cautelar que el fiscal general estime adecuada y suficiente.","Presentación anual ante las autoridades competentes.","Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-248","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Cuantía de las tasas. Los importes de las tasas por tramitación de la solicitud de visado se adecuarán a la revisión que proceda por aplicación del derecho comunitario. Se acomodarán, asimismo, al importe que pueda establecerse por aplicación del:","o":["Principio de igualdad de trato.","Principio de reciprocidad.","Principio de solidaridad.","Principio de universalidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Principio de reciprocidad</mark></span>Según el <span class=\"ref-norma\">art. 48.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Se acomodarán, asimismo, al importe que pueda establecerse por aplicación del principio de reciprocidad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-256","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. La duración máxima del internamiento es de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente. Esta última previsión significa que:","o":["Transcurrido un año podrá acordarse un nuevo internamiento en el mismo expediente.","El internamiento podrá prorrogarse por otros 60 días por auto motivado.","No cabe acordar un nuevo internamiento por cualquiera de las causas previstas en el mismo expediente.","Podrá acordarse un nuevo internamiento solo si concurre una causa distinta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No cabe acordar un nuevo internamiento por cualquiera de las causas previstas en el mismo expediente</mark></span>Según el <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente\"</span>. El enunciado original hablaba de un plazo de «un año» que no figura en la Ley (Verificado con el texto del temario oficial.)"},{"i":"6-264","p":"(Ley Orgánica 4/2000) La sanción por una infracción leve se sancionará con multa de hasta:","o":["100 €.","500 €.","1.000 €.","10.000 €."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">500 €</mark></span>Según el <span class=\"ref-norma\">art. 55.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Las infracciones leves con multa de hasta 500 euros\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-266","p":"(Ley Orgánica 4/2000) Situación de residencia. La residencia temporal es la situación que autoriza a permanecer en España por un periodo superior a ___________ e inferior a cinco años.","o":["80 días.","90 días.","65 días.","70 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">90 días</mark></span>Según el <span class=\"ref-norma\">art. 31.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-271","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. De las infracciones en materia de extranjería y su régimen sancionador. En ningún caso podrán imponerse conjuntamente las sanciones de:","o":["Expulsión y multa.","Multa y clausura.","Expulsión y sanción administrativa.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Expulsión y multa</mark></span>Según el <span class=\"ref-norma\">art. 57.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-281","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la documentación. Los extranjeros que se encuentren en territorio español tienen el derecho y el deber de conservar:","o":["La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de destino, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen, así como la que acredite su situación en España.","La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen, así como la que acredite su situación en la Comunidad Autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España</mark></span>Según el <span class=\"ref-norma\">art. 4.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros que se encuentren en territorio español tienen el derecho y el deber de conservar la documentación que acredite su identidad, expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación en España\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-297","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. De las autorizaciones para la realización de actividades lucrativas. Autorización de residencia y trabajo por cuenta ajena. Señale la CORRECTA.","o":["Para la concesión inicial de la autorización de residencia y trabajo, en el caso de trabajadores por cuenta propia, se tendrá en cuenta la situación nacional de empleo.","La situación nacional de empleo será determinada por el Servicio Público de Empleo Estatal con la información proporcionada por el Estado y con aquella derivada de indicadores estadísticos oficiales.","La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación.","A partir de la primera concesión, las autorizaciones se concederán con limitación de ámbito geográfico u ocupación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación</mark></span>Según el <span class=\"ref-norma\">art. 38.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo se limitará, salvo en los casos previstos por la Ley y los Convenios Internacionales firmados por España, a un determinado territorio y ocupación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-306","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de Residencia y trabajo por cuenta ajena. El Catálogo de Ocupaciones de Difícil Cobertura será aprobado:","o":["Previa consulta de la Comisión Laboral Tripartita de Inmigración.","Previa consulta de la conferencia sectorial en la materia.","Previa consulta del Ministerio de Migraciones.","Previa consulta del Gobierno y las Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Previa consulta de la Comisión Laboral Tripartita de Inmigración</mark></span>Según el <span class=\"ref-norma\">art. 38.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"será aprobado previa consulta de la Comisión Laboral Tripartita de Inmigración\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-315","p":"Ley Orgánica 4/2000... Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito, será sancionado con:","o":["Multa de 1.001 a 100.000 euros.","Multa de 3.001 a 10.000 euros por cada viajero.","Con un mínimo de 500.000 euros al tanto alzado, con independencia del número de viajeros transportados.","Multa de 10.001 a 100.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Multa de 10.001 a 100.000 euros</mark></span>Se restauran las cifras de las opciones, que estaban truncadas. Según el <span class=\"ref-norma\">art. 55.1.c de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves con multa desde 10.001 hasta 100.000 euros...\"</span> (verificado con el texto del temario)."},{"i":"6-318","p":"Ley Orgánica 4/2000... Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el Instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares: señale la opción INCORRECTA.","o":["Presentación periódica ante las autoridades competentes.","Residencia obligatoria en determinado lugar.","Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de las medidas.","Internamiento preventivo, previa autorización gubernativa, en los centros de internamiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Internamiento preventivo, previa autorización gubernativa, en los centros de internamiento</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Internamiento preventivo, previa autorización judicial en los centros de internamiento\"</span>. La autorización es judicial, no gubernativa (Verificado con el texto del temario oficial.)"},{"i":"6-321","p":"Ley Orgánica 4/2000... Autorización de residencia y trabajo por cuenta ajena. La autorización de residencia y trabajo se renovará a su expiración: señale la opción CORRECTA.","o":["Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato.","Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo.","Cuando el extranjero sea beneficiario de una prestación económica asistencial de carácter público destinada a lograr su inserción social o laboral.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 38.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato. b) Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo. c) Cuando el extranjero sea beneficiario de una prestación económica asistencial de carácter público destinada a lograr su inserción social o laboral\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-326","p":"Ley Orgánica 4/2000... La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a:","o":["Cinco años.","Diez años.","Ocho años.","Nueve años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 31.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-332","p":"Ley Orgánica 4/2000... Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el Instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares:","o":["Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida.","Internamiento preventivo, previa autorización judicial en los centros de internamiento.","Cualquier otra medida cautelar que el juez estime adecuada y suficiente.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) Presentación periódica ante las autoridades competentes. b) Residencia obligatoria en determinado lugar. c) Retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega al interesado del resguardo acreditativo de tal medida. d) Detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de 72 horas previas a la solicitud de internamiento. En cualquier otro supuesto de detención, la puesta a disposición judicial se producirá en un plazo no superior a 72 horas. e) Internamiento preventivo, previa autorización judicial en los centros de internamiento. f) Cualquier otra medida cautelar que el juez estime adecuada y suficiente\"</span>. Las tres son medidas cautelares (la respuesta estaba mal marcada) (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1002","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exclusión del ámbito de la ley. Quedan excluidos del ámbito de aplicación de esta ley: Señale la INCORRECTA.","o":["Los representantes, delegados y demás miembros de las Misiones permanentes o de las Delegaciones ante los Organismos intergubernamentales con sede en España, así como sus familiares.","Los funcionarios destinados en Organizaciones internacionales o intergubernamentales con sede en España, así como sus familiares, a quienes los Tratados en los que sea parte España eximan de las obligaciones mencionadas.","Los agentes diplomáticos y los funcionarios consulares acreditados en España que, en virtud de las normas del Derecho internacional, estén exentos de la obligación de inscribirse como extranjeros.","Los miembros de las Fuerzas Armadas de otros Estados destinados en España en virtud de acuerdos de cooperación militar, así como sus familiares."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los miembros de las Fuerzas Armadas de otros Estados destinados en España en virtud de acuerdos de cooperación militar, así como sus familiares</mark></span>El <span class=\"ref-norma\">art. 2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Los representantes, delegados y demás miembros de las Misiones permanentes o de las Delegaciones ante los Organismos intergubernamentales con sede en España o en Conferencias internacionales que se celebren en España, así como sus familiares\"</span>. Los militares extranjeros no figuran entre los excluidos; sí los agentes diplomáticos y consulares, los miembros de Misiones permanentes y Delegaciones y los funcionarios de Organizaciones internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1003","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exclusión del ámbito de la ley. Quedan excluidos del ámbito de aplicación de esta ley los agentes diplomáticos y los funcionarios consulares acreditados en España, así como los demás miembros de las misiones diplomáticas permanentes o especiales y de las oficinas consulares y sus familiares que, en virtud de las normas del Derecho internacional, estén exentos de las obligaciones relativas a:","o":["la obtención del visado y de la tarjeta de identidad de extranjero.","su inscripción en el Padrón Municipal y a la obtención de la autorización de trabajo.","su inscripción como extranjeros y a la obtención de la autorización de residencia.","la obtención de la autorización de residencia y al pago de las tasas correspondientes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su inscripción como extranjeros y a la obtención de la autorización de residencia</mark></span>El <span class=\"ref-norma\">art. 2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"estén exentos de las obligaciones relativas a su inscripción como extranjeros y a la obtención de la autorización de residencia\"</span>. La exención se refiere a la inscripción como extranjeros y a la autorización de residencia, no al visado, al padrón ni a las tasas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1017","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho al trabajo y a la Seguridad Social. Los extranjeros podrán acceder al empleo público:","o":["en los términos previstos en la Ley 7/2007, de 12 de abril, del Estatuto Básico del Empleado Público.","en las mismas condiciones que los españoles, siempre que sean residentes de larga duración.","únicamente como personal laboral y en los términos que fijen los convenios colectivos.","cuando lo prevean los tratados internacionales suscritos por España en régimen de reciprocidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en los términos previstos en la Ley 7/2007, de 12 de abril, del Estatuto Básico del Empleado Público</mark></span>El <span class=\"ref-norma\">art. 10.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros podrán acceder al empleo público en los términos previstos en la Ley 7/2007, de 12 de abril, del Estatuto Básico del Empleado Público\"</span>. La Ley se remite al Estatuto Básico del Empleado Público; no exige residencia de larga duración ni reciprocidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1031","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento para la reagrupación familiar. El extranjero que desee ejercer el derecho a la reagrupación familiar deberá solicitar una autorización de residencia por reagrupación familiar a favor de los miembros de su familia que desee reagrupar:","o":["sin que pueda solicitarse la reagrupación mientras esté en trámite la renovación de su autorización de residencia.","debiendo presentarse la solicitud por cada familiar en la misión diplomática de su país de residencia.","pudiendo solicitarse de forma simultánea la renovación de la autorización de residencia y la solicitud de reagrupación familiar.","pudiendo presentarse la solicitud únicamente por el propio familiar reagrupable desde su país."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">pudiendo solicitarse de forma simultánea la renovación de la autorización de residencia y la solicitud de reagrupación familiar</mark></span>El <span class=\"ref-norma\">art. 18 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"pudiendo solicitarse de forma simultánea la renovación de la autorización de residencia y la solicitud de reagrupación familiar\"</span>. La Ley permite simultanear renovación y reagrupación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1032","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento para la reagrupación familiar. En caso de que el derecho a la reagrupación se ejerza por residentes de larga duración en otro Estado miembro de la Unión Europea que residan en España, la solicitud podrá presentarse:","o":["únicamente por el reagrupante, una vez obtenida la autorización de residencia de larga duración en España.","por los familiares reagrupables, aportando prueba de residencia como miembro de la familia del residente de larga duración en el primer Estado miembro.","por los familiares reagrupables, siempre que acrediten haber residido como miembros de la familia en el primer Estado miembro durante al menos cinco años.","por la autoridad competente del primer Estado miembro en representación de los familiares."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por los familiares reagrupables, aportando prueba de residencia como miembro de la familia del residente de larga duración en el primer Estado miembro</mark></span>El <span class=\"ref-norma\">art. 18 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la solicitud podrá presentarse por los familiares reagrupables, aportando prueba de residencia como miembro de la familia del residente de larga duración en el primer Estado miembro\"</span>. Pueden presentarla los propios familiares, con prueba de residencia como familia en el primer Estado miembro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1044","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la entrada en territorio español. Cuando se autorice la entrada en España de extranjeros que no reúnan los requisitos establecidos por existir razones excepcionales de índole humanitaria, interés público o cumplimiento de compromisos adquiridos por España:","o":["se le concederá automáticamente una autorización de residencia temporal por circunstancias excepcionales.","se procederá a hacer entrega al extranjero de la documentación que se establezca reglamentariamente.","se comunicará la entrada al Ministerio de Asuntos Exteriores y al consulado de su país.","se le expedirá un visado en frontera con validez máxima de tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se procederá a hacer entrega al extranjero de la documentación que se establezca reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 25.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En estos casos, se procederá a hacer entrega al extranjero de la documentación que se establezca reglamentariamente\"</span>. La consecuencia es la entrega de la documentación reglamentaria, no una autorización automática. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1049","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. Reglamentariamente se establecerá la normativa específica del procedimiento de concesión y expedición de visados. En dicho procedimiento:","o":["podrá requerirse la comparecencia personal del solicitante.","será siempre obligatoria la comparecencia personal del solicitante.","no podrá requerirse la comparecencia personal del solicitante.","deberá celebrarse una entrevista personal en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrá requerirse la comparecencia personal del solicitante</mark></span>El <span class=\"ref-norma\">art. 27.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En dicho procedimiento podrá requerirse la comparecencia personal del solicitante\"</span>. «Podrá» requerirse: no es obligatoria en todo caso ni está prohibida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1052","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. De la salida de España. Excepcionalmente, el Ministro del Interior podrá prohibir la salida del territorio español por razones de seguridad nacional o de salud pública. La instrucción y resolución de los expedientes de prohibición:","o":["podrá tener carácter colectivo en caso de emergencia.","tendrá siempre carácter individual.","corresponderá al Delegado del Gobierno.","requerirá autorización judicial previa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tendrá siempre carácter individual</mark></span>El <span class=\"ref-norma\">art. 28.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La instrucción y resolución de los expedientes de prohibición tendrá siempre carácter individual\"</span>. Los expedientes de prohibición de salida tienen «siempre carácter individual». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1053","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. De la salida de España. La salida de los extranjeros a los que no les sea de aplicación el régimen comunitario:","o":["podrá ser registrada por las autoridades españolas a los efectos de control de su período de permanencia legal en España.","deberá ser autorizada previamente por las autoridades españolas cuando el extranjero sea residente temporal con autorización vigente.","será registrada en todo caso por las autoridades españolas en el Registro central de extranjeros.","requerirá la presentación del visado de salida expedido por la Oficina de Extranjeros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrá ser registrada por las autoridades españolas a los efectos de control de su período de permanencia legal en España</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La salida de los extranjeros a los que no les sea de aplicación el régimen comunitario, podrá ser registrada por las autoridades españolas a los efectos de control de su período de permanencia legal en España\"</span>. La salida es libre y «podrá ser registrada» para controlar el período de permanencia legal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1109","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal y trabajo de mujeres extranjeras víctimas de violencia de género o de violencias sexuales. Si al denunciarse una situación de violencia de género o de violencia sexual contra una mujer extranjera se pusiera de manifiesto su situación irregular:","o":["no se incoará el expediente administrativo sancionador por estancia irregular y se suspenderá el que se hubiera incoado con anterioridad a la denuncia.","se incoará el expediente sancionador por estancia irregular, pero se suspenderá la ejecución de la orden de expulsión hasta que concluya el procedimiento penal.","se continuará el expediente sancionador ya incoado, sin perjuicio de la concesión de una autorización provisional de residencia.","no se incoará expediente sancionador si la mujer acredita haber solicitado previamente una autorización por arraigo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no se incoará el expediente administrativo sancionador por estancia irregular y se suspenderá el que se hubiera incoado con anterioridad a la denuncia</mark></span>El <span class=\"ref-norma\">art. 31 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"no se incoará el expediente administrativo sancionador por infracción del artículo 53.1.a), y se suspenderá el expediente administrativo sancionador que se hubiera incoado por la comisión de dicha infracción con anterioridad a la denuncia\"</span>. No se incoa expediente por estancia irregular y se suspende el ya incoado (o la ejecución de la expulsión o devolución). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1110","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal y trabajo de mujeres extranjeras víctimas de violencia de género o de violencias sexuales. La mujer extranjera víctima de violencia de género o sexual podrá solicitar una autorización de residencia y trabajo por circunstancias excepcionales a partir del momento en que se hubiera dictado una orden de protección a su favor o, en su defecto, informe del Ministerio Fiscal. Dicha autorización:","o":["se resolverá en el plazo máximo de tres meses.","se concederá en el plazo de diez días desde la solicitud.","se resolverá con la sentencia de primera instancia.","no se resolverá hasta que concluya el procedimiento penal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no se resolverá hasta que concluya el procedimiento penal</mark></span>El <span class=\"ref-norma\">art. 31 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Dicha autorización no se resolverá hasta que concluya el procedimiento penal\"</span>. La autorización definitiva espera a la conclusión del procedimiento penal; entretanto cabe una provisional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1112","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal y trabajo de mujeres extranjeras víctimas de violencia de género o de violencias sexuales. Las autorizaciones provisionales de residencia y trabajo eventualmente concedidas a la mujer extranjera víctima de violencia de género o sexual y a sus hijos:","o":["concluirán en el momento en que se dicte sentencia firme en el procedimiento penal, sea condenatoria o absolutoria.","concluirán en el momento en que se concedan o denieguen definitivamente las autorizaciones por circunstancias excepcionales.","tendrán una vigencia máxima de un año, prorrogable mientras se tramite el procedimiento penal.","se convertirán automáticamente en definitivas transcurridos seis meses desde su concesión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">concluirán en el momento en que se concedan o denieguen definitivamente las autorizaciones por circunstancias excepcionales</mark></span>El <span class=\"ref-norma\">art. 31 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las autorizaciones provisionales eventualmente concedidas concluirán en el momento en que se concedan o denieguen definitivamente las autorizaciones por circunstancias excepcionales\"</span>. Las provisionales concluyen al concederse o denegarse definitivamente las autorizaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1114","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal y trabajo de mujeres extranjeras víctimas de violencia de género o de violencias sexuales. Si del procedimiento penal concluido no pudiera deducirse la situación de violencia de género o sexual:","o":["se archivará definitivamente cualquier expediente sancionador incoado por estancia irregular.","se mantendrá la autorización provisional de residencia y trabajo hasta su caducidad y no se incoará en ningún caso expediente sancionador alguno.","se procederá a la devolución inmediata de la mujer extranjera a su país de origen.","se incoará el expediente administrativo sancionador por estancia irregular o se continuará, si se hubiera suspendido inicialmente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se incoará el expediente administrativo sancionador por estancia irregular o se continuará, si se hubiera suspendido inicialmente</mark></span>El <span class=\"ref-norma\">art. 31 bis.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Si del procedimiento penal concluido no pudiera deducirse la situación de violencia de género o sexual, se incoará el expediente administrativo sancionador por infracción del artículo 53.1.a) o se continuará, en el supuesto de que se hubiera suspendido inicialmente\"</span>. Se incoa o se reanuda el expediente por estancia irregular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1115","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. A los efectos de obtener la residencia de larga duración:","o":["computarán los periodos de estancia por estudios en España, siempre que sean continuados y acreditados.","computarán los periodos de residencia previa en otros Estados miembros con cualquier tipo de autorización de residencia, aunque no hayan sido continuados.","computarán los periodos de residencia previa y continuada en otros Estados miembros, como titular de la tarjeta azul de la UE.","no computarán los periodos de residencia en otros Estados miembros, salvo acuerdo internacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">computarán los periodos de residencia previa y continuada en otros Estados miembros, como titular de la tarjeta azul de la UE</mark></span>El <span class=\"ref-norma\">art. 32.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"A los efectos de obtener la residencia de larga duración computarán los periodos de residencia previa y continuada en otros Estados miembros, como titular de la tarjeta azul de la UE\"</span>. Solo computan los periodos en otros Estados miembros como titular de la tarjeta azul de la UE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1116","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. Tendrán derecho a residencia de larga duración los que hayan tenido residencia temporal en España durante cinco años de forma continuada. Se considerará que la residencia ha sido continuada:","o":["siempre que el extranjero no haya abandonado el territorio nacional por un período superior a seis meses continuados ni a diez meses en total dentro de los cinco años exigidos.","aunque por períodos de vacaciones u otras razones que se establezcan reglamentariamente el extranjero haya abandonado el territorio nacional temporalmente.","aunque el extranjero haya abandonado el territorio nacional, siempre que lo comunique previamente a la Oficina de Extranjeros.","únicamente si el extranjero no ha abandonado en ningún momento el territorio de la Unión Europea durante esos cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">aunque por períodos de vacaciones u otras razones que se establezcan reglamentariamente el extranjero haya abandonado el territorio nacional temporalmente</mark></span>El <span class=\"ref-norma\">art. 32.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se considerará que la residencia ha sido continuada aunque por períodos de vacaciones u otras razones que se establezcan reglamentariamente el extranjero haya abandonado el territorio nacional temporalmente\"</span>. Las ausencias temporales por vacaciones u otras razones reglamentarias no rompen la continuidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1117","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. En el supuesto de que los extranjeros residentes de larga duración en otro Estado miembro de la Unión Europea deseen conservar el estatuto de residente de larga duración adquirido en el primer Estado miembro:","o":["podrán solicitar y obtener una autorización de residencia temporal en España.","deberán solicitar una autorización de residencia de larga duración en España en el plazo de tres meses.","podrán residir en España sin necesidad de autorización alguna.","deberán renunciar al estatuto para residir en España más de tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrán solicitar y obtener una autorización de residencia temporal en España</mark></span>El <span class=\"ref-norma\">art. 32.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"en el supuesto de que los extranjeros residentes de larga duración en otro estado miembro de la Unión Europea deseen conservar el estatuto de residente de larga duración adquirido en el primer estado miembro, podrán solicitar y obtener una autorización de residencia temporal en España\"</span>. Si quieren conservar el estatuto del primer Estado, piden residencia TEMPORAL en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1118","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. No se reconocerá la condición de residente de larga duración en España al beneficiario de protección internacional cuyo estatuto:","o":["hubiese sido concedido por otro Estado miembro de la Unión Europea y no por las autoridades españolas.","hubiese sido concedido hace menos de cinco años en España.","hubiese sido revocado por haber cometido una infracción leve.","hubiese sido revocado, cesado, finalizado, o cuya renovación hubiese sido denegada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">hubiese sido revocado, cesado, finalizado, o cuya renovación hubiese sido denegada</mark></span>El <span class=\"ref-norma\">art. 32.3 bis de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"No se reconocerá la condición de residente de larga duración en España al beneficiario de protección internacional cuyo estatuto hubiese sido revocado, cesado, finalizado, o cuya renovación hubiese sido denegada\"</span>. La protección reconocida por otro Estado miembro también permite pedir la larga duración; lo que lo impide es la revocación, cese, finalización o denegación de la renovación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1119","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. Las personas extranjeras que hayan perdido la condición de residentes de larga duración podrán recuperar dicho estatuto mediante un procedimiento simplificado que se desarrollará reglamentariamente y que se aplicará sobre todo en el caso de personas que hayan residido en otro Estado miembro:","o":["por motivos laborales de temporada.","como beneficiarias de protección internacional.","para la realización de estudios.","por reagrupación familiar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">para la realización de estudios</mark></span>El <span class=\"ref-norma\">art. 32.5 y 32.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Dicho procedimiento se aplicará sobre todo en el caso de personas que hayan residido en otro Estado miembro para la realización de estudios\"</span>. El procedimiento simplificado se piensa sobre todo para quienes residieron en otro Estado miembro por estudios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1133","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. La concesión de una autorización de residencia al menor no acompañado:","o":["no será obstáculo para la ulterior repatriación cuando favorezca el interés superior del menor.","impedirá su ulterior repatriación salvo que lo solicite expresamente el propio menor ante el Ministerio Fiscal.","impedirá su repatriación hasta que alcance la mayoría de edad.","solo permitirá la repatriación por reagrupación familiar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no será obstáculo para la ulterior repatriación cuando favorezca el interés superior del menor</mark></span>El <span class=\"ref-norma\">art. 35.8 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La concesión de una autorización de residencia no será obstáculo para la ulterior repatriación cuando favorezca el interés superior del menor\"</span>. La autorización de residencia no impide la repatriación posterior si favorece el interés superior del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1134","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. Los Cuerpos y Fuerzas de Seguridad del Estado adoptarán las medidas técnicas necesarias para la identificación de los menores extranjeros indocumentados, con el fin de conocer las posibles referencias que sobre ellos pudieran existir en alguna institución pública nacional o extranjera encargada de su protección. Estos datos:","o":["se conservarán en el Registro central de extranjeros durante cinco años.","podrán cederse a las autoridades del país de origen para su repatriación.","serán comunicados al Ministerio Fiscal y a la Comunidad Autónoma de acogida.","no podrán ser usados para una finalidad distinta a la prevista en este apartado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrán ser usados para una finalidad distinta a la prevista en este apartado</mark></span>El <span class=\"ref-norma\">art. 35.10 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Estos datos no podrán ser usados para una finalidad distinta a la prevista en este apartado\"</span>. Los datos de identificación tienen una finalidad tasada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1144","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. Declarada la situación de contingencia migratoria extraordinaria, si se localiza a una persona menor extranjera no acompañada se procederá a realizar su reseña inmediata o a la mayor brevedad posible, y a su inscripción en el Registro de Menores Extranjeros No Acompañados:","o":["dentro de las setenta y dos horas siguientes a su localización por las autoridades.","dentro de las veinticuatro horas siguientes desde que se realice esta reseña.","en el plazo máximo de cinco días naturales desde la reseña.","dentro de las cuarenta y ocho horas siguientes a la determinación de su edad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dentro de las veinticuatro horas siguientes desde que se realice esta reseña</mark></span>El <span class=\"ref-norma\">art. 35 quáter.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"en el Registro de Menores Extranjeros No Acompañados dentro de las veinticuatro horas siguientes desde que se realice esta reseña\"</span>. La inscripción es dentro de las 24 horas siguientes a la reseña, acreditada o no la minoría de edad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1145","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. Mientras se mantenga la situación de contingencia migratoria extraordinaria, la persona extranjera no acompañada, con independencia de que su minoría de edad sea indubitada o no pudiera ser establecida con seguridad, será trasladada a la comunidad o ciudad autónoma de destino en el plazo máximo de:","o":["quince días naturales a contar desde la fecha de inscripción en el Registro de Menores Extranjeros No Acompañados.","diez días hábiles a contar desde la fecha de su localización por las autoridades competentes.","quince días hábiles a contar desde la declaración de la situación de contingencia migratoria.","cinco días naturales a contar desde la fecha de inscripción en el Registro de Menores Extranjeros No Acompañados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quince días naturales a contar desde la fecha de inscripción en el Registro de Menores Extranjeros No Acompañados</mark></span>El <span class=\"ref-norma\">art. 35 quáter.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"será trasladada en el plazo máximo de quince días naturales a contar desde la fecha de inscripción en el Registro de Menores Extranjeros No Acompañados\"</span>. Quince días naturales desde la inscripción en el Registro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1146","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. La resolución de ubicación y traslado a una concreta comunidad o ciudad autónoma será dictada dentro del plazo de quince días naturales desde la inscripción en el Registro, dentro de los cuales:","o":["la comunidad autónoma de origen y la de destino habrán de prestar su conformidad expresa, previo informe del Ministerio Fiscal.","la persona menor afectada habrá de ser oída por el Juez de Instrucción del lugar en que se encuentre.","la comunidad o ciudad autónoma de destino podrá oponerse motivadamente ante la Conferencia Sectorial.","la persona menor afectada y la comunidad o ciudad autónoma de destino habrán de ser oídas, dando conocimiento al Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la persona menor afectada y la comunidad o ciudad autónoma de destino habrán de ser oídas, dando conocimiento al Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 35 quáter.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"dentro de los cuales la persona menor afectada y la comunidad o ciudad autónoma de destino habrán de ser oídas, dando conocimiento al Ministerio Fiscal en garantía del interés superior del menor\"</span>. Se oye al menor y a la comunidad de destino, dando conocimiento al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1147","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. En el supuesto de la persona menor extranjera no acompañada indocumentada cuya minoría de edad no pudiera ser establecida con seguridad, las actuaciones del expediente de determinación de edad se practicarán:","o":["en la comunidad o ciudad autónoma de origen, antes del traslado.","en el lugar que determine el Ministerio Fiscal.","en la comunidad o ciudad autónoma de destino.","en las dependencias de los Cuerpos y Fuerzas de Seguridad del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en la comunidad o ciudad autónoma de destino</mark></span>El <span class=\"ref-norma\">art. 35 quáter.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se practicarán en la comunidad o ciudad autónoma de destino las actuaciones del expediente de determinación de edad\"</span>. En contingencia, la determinación de edad se hace en la comunidad de DESTINO. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1148","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. Se entregará a las personas menores de edad extranjeras no acompañadas si su grado de madurez lo permite, o a sus representantes legales en otro caso:","o":["una copia íntegra del expediente de determinación de la edad y de la resolución de ubicación y traslado dictada por la Administración General del Estado.","una certificación de los datos que consten en el Registro de Menores Extranjeros No Acompañados que les afecten.","una tarjeta de identidad de extranjero provisional válida durante la situación de contingencia.","un documento de viaje que acredite su identidad y la comunidad autónoma de acogida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una certificación de los datos que consten en el Registro de Menores Extranjeros No Acompañados que les afecten</mark></span>El <span class=\"ref-norma\">art. 35 quáter.8 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"una certificación de los datos que consten en el Registro de Menores Extranjeros No Acompañados que les afecten, incluyendo los datos correspondientes a su identidad y la comunidad o ciudad autónoma a la que se encuentren asignados\"</span>. Se entrega una certificación de sus datos del Registro, con su identidad y la comunidad asignada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1151","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Criterios de aplicación del Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. Las personas menores de edad extranjeras no acompañadas que se desplacen, sin autorización, fuera del territorio de la comunidad o ciudad autónoma titular de su guarda o tutela:","o":["quedarán bajo la tutela de la comunidad o ciudad autónoma en la que sean localizadas, previa comunicación al Ministerio Fiscal.","serán puestas a disposición del Juez de Menores del lugar en que sean localizadas.","podrán ser conducidas nuevamente por los servicios competentes, una vez localizadas, a su territorio.","perderán el derecho a la autorización de residencia por un período de un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrán ser conducidas nuevamente por los servicios competentes, una vez localizadas, a su territorio</mark></span>El <span class=\"ref-norma\">art. 35 quinquies.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"podrán ser conducidas nuevamente por los servicios competentes, una vez localizadas, a su territorio\"</span>. Pueden ser conducidas de nuevo a la comunidad titular de su guarda o tutela y, en todo caso, puestas a disposición de la autoridad correspondiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1155","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. En la concesión inicial de la autorización administrativa para trabajar podrán aplicarse criterios especiales para determinadas nacionalidades en función del principio de:","o":["solidaridad.","igualdad de trato.","reciprocidad.","preferencia comunitaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reciprocidad</mark></span>El <span class=\"ref-norma\">art. 36.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En la concesión inicial de la autorización administrativa para trabajar podrán aplicarse criterios especiales para determinadas nacionalidades en función del principio de reciprocidad\"</span>. Los criterios especiales por nacionalidad se basan en la reciprocidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1201","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. La situación nacional de empleo será determinada por el Servicio Público de Empleo Estatal con la información proporcionada por las Comunidades Autónomas y con aquella derivada de indicadores estadísticos oficiales y quedará plasmada en:","o":["el Catálogo de Ocupaciones de Difícil Cobertura.","la previsión anual de ocupaciones aprobada por el Ministerio de Trabajo e Inmigración.","el Registro de Ofertas de Empleo de los Servicios Públicos de Empleo autonómicos.","el informe anual de la Comisión Laboral Tripartita de Inmigración sobre el mercado laboral."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Catálogo de Ocupaciones de Difícil Cobertura</mark></span>El <span class=\"ref-norma\">art. 38.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La situación nacional de empleo será determinada por el Servicio Público de Empleo Estatal con la información proporcionada por las Comunidades Autónomas y con aquella derivada de indicadores estadísticos oficiales y quedará plasmada en el Catálogo de Ocupaciones de Difícil Cobertura\"</span>. La situación nacional de empleo se plasma en el Catálogo de Ocupaciones de Difícil Cobertura; la previsión anual es la de la gestión colectiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1202","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. Se entenderá que la situación nacional de empleo permite la contratación en ocupaciones no catalogadas cuando:","o":["la Comisión Laboral Tripartita de Inmigración informe favorablemente la contratación de forma individual.","el empleador acredite haber publicado la oferta durante un mes sin cubrirla con trabajadores comunitarios.","la Comunidad Autónoma certifique la ausencia de demandantes inscritos en la ocupación durante tres meses.","de la gestión de la oferta se concluya la insuficiencia de demandantes de empleo adecuados y disponibles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de la gestión de la oferta se concluya la insuficiencia de demandantes de empleo adecuados y disponibles</mark></span>El <span class=\"ref-norma\">art. 38.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Igualmente, se entenderá que la situación nacional de empleo permite la contratación en ocupaciones no catalogadas cuando de la gestión de la oferta se concluya la insuficiencia de demandantes de empleo adecuados y disponibles\"</span>. La regla es la insuficiencia de demandantes adecuados y disponibles resultante de la gestión de la oferta; los requisitos mínimos se fijan reglamentariamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1203","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. El procedimiento de concesión de la autorización de residencia y trabajo inicial se basará en la solicitud de cobertura de un puesto vacante, presentada por un empresario o empleador ante la autoridad competente, junto con el contrato de trabajo y el resto de documentación exigible, ofrecido al trabajador extranjero:","o":["que se encuentre en España en situación de estancia.","inscrito como demandante de empleo en España.","residente en un tercer país.","residente en otro Estado miembro de la Unión Europea."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">residente en un tercer país</mark></span>El <span class=\"ref-norma\">art. 38.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se basará en la solicitud de cobertura de un puesto vacante, presentada por un empresario o empleador ante la autoridad competente, junto con el contrato de trabajo y el resto de documentación exigible, ofrecido al trabajador extranjero residente en un tercer país\"</span>. El procedimiento ordinario se refiere al trabajador residente en un tercer país. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1204","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. Verificado el cumplimiento de los requisitos, la autoridad competente expedirá una autorización de residencia y trabajo inicial cuya eficacia estará condicionada a que:","o":["el empleador registre el contrato en los Servicios Públicos de Empleo y comunique el alta del trabajador en el plazo de un mes desde su entrada en España.","el extranjero solicite el correspondiente visado y que, una vez en España, se produzca el alta del trabajador en la Seguridad Social.","el extranjero obtenga la tarjeta de identidad de extranjero en el plazo de un mes desde su entrada en España.","el extranjero entre en España dentro de los tres meses siguientes a la notificación de la autorización."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el extranjero solicite el correspondiente visado y que, una vez en España, se produzca el alta del trabajador en la Seguridad Social</mark></span>El <span class=\"ref-norma\">art. 38.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la autoridad competente expedirá una autorización cuya eficacia estará condicionada a que el extranjero solicite el correspondiente visado y que, una vez en España, se produzca el alta del trabajador en la Seguridad Social\"</span>. Dos condiciones: visado y alta en la Seguridad Social una vez en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1205","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. El empresario o empleador estará obligado a comunicar el desistimiento de la solicitud de autorización si, mientras se resolviera la autorización o el visado:","o":["desapareciera la necesidad de contratación del extranjero o se modificasen las condiciones del contrato de trabajo que sirvió de base a la solicitud.","el extranjero hubiera sido sancionado por una infracción leve o se modificase la situación nacional de empleo en esa ocupación según el Catálogo vigente.","se produjera la caducidad de la oferta de empleo o el trabajador cambiase de nacionalidad durante la tramitación.","desapareciera la necesidad de contratación o el extranjero no hubiera comparecido personalmente ante el consulado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desapareciera la necesidad de contratación del extranjero o se modificasen las condiciones del contrato de trabajo que sirvió de base a la solicitud</mark></span>El <span class=\"ref-norma\">art. 38.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El empresario o empleador estará obligado a comunicar el desistimiento de la solicitud de autorización si, mientras se resolviera la autorización o el visado, desapareciera la necesidad de contratación del extranjero o se modificasen las condiciones del contrato de trabajo que sirvió de base a la solicitud\"</span>. Las causas son la desaparición de la necesidad de contratar o la modificación de las condiciones del contrato. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1208","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Gestión colectiva de contrataciones en origen. La previsión anual de ocupaciones de la gestión colectiva de contrataciones en origen tendrá en cuenta las propuestas que, previa consulta de los agentes sociales en su ámbito correspondiente, sean realizadas por las Comunidades Autónomas, y será adoptada:","o":["previo acuerdo de la Conferencia Sectorial de Inmigración.","previa consulta de la Comisión Laboral Tripartita de Inmigración.","previo informe del Foro para la Integración Social de los Inmigrantes.","previa aprobación del Consejo de Ministros a propuesta de las CCAA."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">previa consulta de la Comisión Laboral Tripartita de Inmigración</mark></span>El <span class=\"ref-norma\">art. 39.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"y será adoptada previa consulta de la Comisión Laboral Tripartita de Inmigración\"</span>. Igual que el Catálogo, se adopta previa consulta de la Comisión Laboral Tripartita de Inmigración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1212","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto de los extranjeros que obtengan la autorización de residencia por circunstancias excepcionales en los supuestos que se determinen reglamentariamente y, en todo caso, cuando se trate de:","o":["víctimas de violencia de género o de delitos de odio y discriminación.","víctimas de violencia de género o de trata de seres humanos.","solicitantes de protección internacional o apátridas.","víctimas de trata o colaboradores con la Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">víctimas de violencia de género o de trata de seres humanos</mark></span>El <span class=\"ref-norma\">art. 40.1.j) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"j) Los extranjeros que obtengan la autorización de residencia por circunstancias excepcionales en los supuestos que se determinen reglamentariamente y, en todo caso, cuando se trate de víctimas de violencia de género o de trata de seres humanos\"</span>. «En todo caso» se citan las víctimas de violencia de género y de trata de seres humanos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1228","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Cuantía de las tasas. Se consideran elementos y criterios esenciales de cuantificación que sólo podrán modificarse mediante norma del mismo rango, entre otros: Señale la INCORRECTA.","o":["En la concesión de autorizaciones para la prórroga de estancia en España, la duración de la prórroga.","En la concesión de autorizaciones de trabajo, la nacionalidad del trabajador y el número de trabajadores de la empresa.","En la concesión de autorizaciones de trabajo, la duración de la misma, su extensión y ámbito, el carácter y las modalidades de la relación por cuenta ajena.","En todo caso, será criterio cuantitativo de las tasas el carácter individual o colectivo de las autorizaciones, prórrogas, modificaciones o renovaciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En la concesión de autorizaciones de trabajo, la nacionalidad del trabajador y el número de trabajadores de la empresa</mark></span>El <span class=\"ref-norma\">art. 48.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) En la concesión de autorizaciones para la prórroga de estancia en España, la duración de la prórroga\"</span>. Para las autorizaciones de trabajo cuentan la duración, extensión y ámbito, el carácter y modalidades de la relación y, en su caso, el salario pactado; no la nacionalidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1244","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. La infracción muy grave consistente en el transporte de extranjeros hasta el territorio español sin comprobar la validez y vigencia de su documentación se sancionará con una multa de:","o":["10.001 a 100.000 euros por cada viajero transportado o con un mínimo de 500.000 euros a tanto alzado, según el número de viajeros.","5.000 a 10.000 euros por cada viajero transportado o con un mínimo de 750.000 euros a tanto alzado, con independencia del número de viajeros.","5.000 a 10.000 euros por cada viaje realizado o con un mínimo de 750.000 euros a tanto alzado, según el número de viajeros transportados.","3.000 a 10.000 euros por cada viajero transportado o con un mínimo de 1.000.000 de euros a tanto alzado, con independencia del número de viajeros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">5.000 a 10.000 euros por cada viajero transportado o con un mínimo de 750.000 euros a tanto alzado, con independencia del número de viajeros</mark></span>El <span class=\"ref-norma\">art. 55.1.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"excepto la prevista en el artículo 54.2.b), que lo será con una multa de 5.000 a 10.000 euros por cada viajero transportado o con un mínimo de 750.000 euros a tanto alzado, con independencia del número de viajeros transportados\"</span>. 5.000 a 10.000 € por viajero o mínimo de 750.000 € a tanto alzado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1245","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. El incumplimiento por el transportista de la obligación de remitir la información relativa a los pasajeros será sancionado con una multa de 10.001 hasta 100.000 euros:","o":["por cada viaje realizado sin haber comunicado los datos de las personas transportadas o habiéndolos comunicado incorrectamente.","por cada pasajero cuyos datos no se hubieran comunicado o se hubieran comunicado incorrectamente a las autoridades.","a tanto alzado, con independencia del número de viajes realizados sin comunicar los datos de los pasajeros.","por cada viaje realizado, salvo que el transportista acredite haber borrado los datos en el plazo de veinticuatro horas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por cada viaje realizado sin haber comunicado los datos de las personas transportadas o habiéndolos comunicado incorrectamente</mark></span>El <span class=\"ref-norma\">art. 55.1.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"lo será con una multa de 10.001 hasta 100.000 euros por cada viaje realizado sin haber comunicado los datos de las personas transportadas o habiéndolos comunicado incorrectamente\"</span>. Aquí la unidad es el viaje, no el viajero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1246","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. La imposición de sanciones por las infracciones administrativas establecidas en la Ley Orgánica corresponderá, con carácter general:","o":["al Delegado del Gobierno en todas las Comunidades Autónomas.","al Ministro del Interior o al Secretario de Estado de Seguridad.","al Director General de la Policía o a los Jefes Superiores de Policía de la Comunidad Autónoma correspondiente.","al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales</mark></span>El <span class=\"ref-norma\">art. 55.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La imposición de sanciones por las infracciones administrativas establecidas en la presente Ley Orgánica corresponderá al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales\"</span>. Regla general: Subdelegado del Gobierno (o Delegado en las uniprovinciales). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1247","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. En los supuestos de participación en actividades contrarias a la seguridad nacional o que pueden perjudicar las relaciones de España con otros países, la competencia sancionadora corresponderá:","o":["al Ministro del Interior, en todo caso.","al Delegado del Gobierno.","al Secretario de Estado de Seguridad.","al Consejo de Ministros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Secretario de Estado de Seguridad</mark></span>El <span class=\"ref-norma\">art. 55.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la competencia sancionadora corresponderá al Secretario de Estado de Seguridad\"</span>. Para la seguridad nacional, el Secretario de Estado de Seguridad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1249","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. En el supuesto de la infracción muy grave de contratación de trabajadores extranjeros sin autorización, la autoridad gubernativa podrá adoptar, sin perjuicio de la sanción que corresponda, la clausura del establecimiento o local:","o":["desde seis meses a cinco años.","desde tres meses a dos años.","desde un año a cinco años.","desde seis meses a tres años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desde seis meses a cinco años</mark></span>El <span class=\"ref-norma\">art. 55.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la autoridad gubernativa podrá adoptar, sin perjuicio de la sanción que corresponda, la clausura del establecimiento o local desde seis meses a cinco años\"</span>. Clausura de seis meses a cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1250","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. Si el sancionado por emplear a extranjeros sin la correspondiente autorización fuera subcontratista de otra empresa, el contratista principal y todos los subcontratistas intermedios que conocieran que la empresa sancionada empleaba a extranjeros sin autorización:","o":["responderán subsidiariamente, en todo caso y sin excepción.","responderán mancomunadamente de la sanción económica impuesta a la empresa subcontratista.","no responderán en ningún caso de las sanciones económicas.","responderán solidariamente, salvo que hubieran respetado la diligencia debida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">responderán solidariamente, salvo que hubieran respetado la diligencia debida</mark></span>El <span class=\"ref-norma\">art. 55.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"responderán, solidariamente, tanto de las sanciones económicas derivadas de las sanciones, como de las demás responsabilidades derivadas de tales hechos\"</span>. Responden solidariamente; quedan exonerados si respetaron la diligencia debida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1251","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. A no ser que pertenezcan a un tercero no responsable de la infracción, en el supuesto de la infracción muy grave de inducir o facilitar con ánimo de lucro la inmigración clandestina:","o":["serán objeto de inmovilización temporal los vehículos y embarcaciones utilizados, durante la tramitación del expediente sancionador.","se procederá a la clausura del establecimiento o local desde seis meses a cinco años, sin perjuicio de la multa.","serán objeto de decomiso los vehículos, embarcaciones, aeronaves, y cuantos bienes hayan servido de instrumento para la comisión de la infracción.","se impondrá además la suspensión de la autorización de explotación del medio de transporte por un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">serán objeto de decomiso los vehículos, embarcaciones, aeronaves, y cuantos bienes hayan servido de instrumento para la comisión de la infracción</mark></span>El <span class=\"ref-norma\">art. 55.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"serán objeto de decomiso los vehículos, embarcaciones, aeronaves, y cuantos bienes muebles o inmuebles, de cualquier naturaleza que sean, hayan servido de instrumento para la comisión de la citada infracción\"</span>. Procede el decomiso de los bienes que sirvieron de instrumento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1252","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Constituirá causa de expulsión, previa tramitación del correspondiente expediente, que el extranjero haya sido condenado, dentro o fuera de España, por una conducta dolosa que constituya en nuestro país delito sancionado con pena privativa de libertad superior a:","o":["dos años, salvo que los antecedentes penales hubieran sido cancelados.","un año, salvo que los antecedentes penales hubieran sido cancelados.","un año, aunque los antecedentes penales hubieran sido cancelados.","seis meses, salvo que la pena hubiera sido suspendida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un año, salvo que los antecedentes penales hubieran sido cancelados</mark></span>El <span class=\"ref-norma\">art. 57.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"que constituya en nuestro país delito sancionado con pena privativa de libertad superior a un año, salvo que los antecedentes penales hubieran sido cancelados\"</span>. Pena superior a un año y antecedentes no cancelados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1253","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. En el caso de estancia irregular o de trabajo sin autorización, salvo que concurran razones de orden público o de seguridad nacional, si el extranjero fuese titular de una autorización de residencia válida expedida por otro Estado miembro:","o":["se le advertirá, mediante diligencia en el pasaporte, de la obligación de dirigirse de inmediato al territorio de dicho Estado.","se procederá a su devolución inmediata al Estado miembro que expidió la autorización, sin necesidad de expediente previo de expulsión.","se tramitará el expediente de expulsión por el procedimiento preferente, con comunicación a dicho Estado.","se le concederá un plazo de cumplimiento voluntario de quince días para abandonar el territorio español."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se le advertirá, mediante diligencia en el pasaporte, de la obligación de dirigirse de inmediato al territorio de dicho Estado</mark></span>El <span class=\"ref-norma\">art. 57.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se le advertirá, mediante diligencia en el pasaporte, de la obligación de dirigirse de inmediato al territorio de dicho Estado\"</span>. Primero se le advierte mediante diligencia en el pasaporte; si no cumple, se tramita la expulsión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1254","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. La sanción de expulsión no podrá ser impuesta, salvo determinadas excepciones, a los extranjeros que se encuentren en los siguientes supuestos: Señale la INCORRECTA.","o":["Los residentes de larga duración.","Los que hayan sido españoles de origen y hubieran perdido la nacionalidad española.","Los que perciban una prestación contributiva por desempleo.","Los nacidos en España que hayan residido legalmente en los últimos tres años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los nacidos en España que hayan residido legalmente en los últimos tres años</mark></span>El <span class=\"ref-norma\">art. 57.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Los nacidos en España que hayan residido legalmente en los últimos cinco años\"</span>. Para los nacidos en España se exige residencia legal en los últimos CINCO años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1255","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Tampoco se podrá imponer o, en su caso, ejecutar la sanción de expulsión al cónyuge del extranjero que se encuentre en alguna de las situaciones protegidas y que haya residido legalmente en España durante más de:","o":["un año.","tres años.","dos años.","cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos años</mark></span>El <span class=\"ref-norma\">art. 57.5.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"al cónyuge del extranjero que se encuentre en alguna de las situaciones señaladas anteriormente y que haya residido legalmente en España durante más de dos años\"</span>. El cónyuge queda protegido si ha residido legalmente más de dos años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1301","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Cuando el extranjero se encuentre procesado o imputado en un procedimiento judicial por delito o falta para el que la Ley prevea una pena privativa de libertad inferior a seis años o una pena de distinta naturaleza, y conste este hecho acreditado en el expediente administrativo de expulsión, el Juez, previa audiencia del Ministerio Fiscal, autorizará la expulsión:","o":["en el plazo más breve posible y en todo caso no superior a tres días, salvo que, de forma motivada, aprecie circunstancias que justifiquen su denegación.","en el plazo máximo de setenta y dos horas, salvo que el extranjero se oponga de forma expresa y motivada a la expulsión acordada por la autoridad gubernativa competente.","en el plazo más breve posible y en todo caso no superior a cinco días, salvo que el delito esté castigado con pena de prisión.","en el plazo de diez días, previa audiencia del interesado, salvo que aprecie riesgo para la investigación penal en curso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el plazo más breve posible y en todo caso no superior a tres días, salvo que, de forma motivada, aprecie circunstancias que justifiquen su denegación</mark></span>El <span class=\"ref-norma\">art. 57.7.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"en el plazo más breve posible y en todo caso no superior a tres días, el Juez, previa audiencia del Ministerio Fiscal, la autorizará salvo que, de forma motivada, aprecie la existencia de circunstancias que justifiquen su denegación\"</span>. Plazo no superior a tres días; el Juez autoriza salvo circunstancias que de forma motivada justifiquen denegarla. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1303","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Cuando los extranjeros, residentes o no, hayan sido condenados por conductas tipificadas como delitos contra los derechos de los trabajadores o de tráfico ilegal de personas previstos en la ley, la expulsión se llevará a efecto:","o":["de forma inmediata, sustituyendo a la pena.","cuando hayan cumplido la mitad de la condena.","una vez cumplida la pena privativa de libertad.","antes del cumplimiento, previo informe fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una vez cumplida la pena privativa de libertad</mark></span>El <span class=\"ref-norma\">art. 57.8 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la expulsión se llevará a efecto una vez cumplida la pena privativa de libertad\"</span>. En esos delitos la expulsión se ejecuta una vez cumplida la pena privativa de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1304","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. En el supuesto de expulsión de un residente de larga duración de otro Estado miembro de la Unión Europea que se encuentre en España, si no se reúnen los requisitos para que la expulsión se realice fuera del territorio de la Unión:","o":["la misma se efectuará al país de origen del extranjero, previa consulta al Estado miembro afectado.","la misma se efectuará al Estado miembro en el que se reconoció la residencia de larga duración.","se archivará el expediente de expulsión y se impondrá en su lugar la sanción de multa correspondiente.","se suspenderá la expulsión hasta que el Estado miembro afectado revoque la residencia de larga duración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la misma se efectuará al Estado miembro en el que se reconoció la residencia de larga duración</mark></span>El <span class=\"ref-norma\">art. 57.10 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En caso de no reunirse estos requisitos para que la expulsión se realice fuera del territorio de la Unión, la misma se efectuará al Estado miembro en el que se reconoció la residencia de larga duración\"</span>. Si no se cumplen los requisitos para expulsar fuera de la Unión, se expulsa al Estado miembro que reconoció la larga duración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1305","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Cuando España decida expulsar a un residente de larga duración que sea beneficiario de protección internacional reconocida por otro Estado miembro, solicitará a dicho Estado información sobre si esa condición continúa vigente. Dicha solicitud deberá ser respondida en el plazo de:","o":["un mes, entendiéndose, en caso contrario, que la protección internacional sigue vigente.","un mes, entendiéndose, en caso contrario, que la protección internacional ha cesado.","diez días, entendiéndose, en caso contrario, que la protección internacional sigue vigente.","tres meses, entendiéndose, en caso contrario, que la protección internacional sigue vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un mes, entendiéndose, en caso contrario, que la protección internacional sigue vigente</mark></span>El <span class=\"ref-norma\">art. 57.11 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Dicha solicitud deberá ser respondida en el plazo de un mes, entendiéndose, en caso contrario, que la protección internacional sigue vigente\"</span>. Un mes; el silencio se entiende como protección vigente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1307","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. La autoridad competente revocará la prohibición de entrada impuesta por estancia irregular o trabajo sin autorización cuando el extranjero:","o":["acreditara haber solicitado una autorización de residencia temporal por arraigo antes de la resolución.","abandonara el territorio nacional dentro de los seis meses siguientes a la notificación de la expulsión.","abandonara el territorio nacional en el plazo de cumplimiento voluntario previsto en la orden de expulsión.","abonara la multa que le hubiera correspondido por la infracción cometida en el plazo voluntario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">abandonara el territorio nacional en el plazo de cumplimiento voluntario previsto en la orden de expulsión</mark></span>El <span class=\"ref-norma\">art. 58.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"o revocará la prohibición de entrada impuesta por las mismas causas, cuando el extranjero abandonara el territorio nacional en el plazo de cumplimiento voluntario previsto en la orden de expulsión\"</span>. Se revoca si sale en el plazo de cumplimiento voluntario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1323","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. Entre las medidas cautelares figura la detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de 72 horas previas a la solicitud de internamiento. En cualquier otro supuesto de detención:","o":["la puesta a disposición judicial se producirá en un plazo no superior a 24 horas.","la puesta a disposición judicial se producirá en un plazo no superior a 48 horas.","la puesta a disposición judicial se producirá en un plazo no superior a 72 horas.","la puesta a disposición judicial podrá demorarse hasta la resolución del expediente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la puesta a disposición judicial se producirá en un plazo no superior a 72 horas</mark></span>El <span class=\"ref-norma\">art. 61.1.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En cualquier otro supuesto de detención, la puesta a disposición judicial se producirá en un plazo no superior a 72 horas\"</span>. En cualquier otro supuesto también rige el límite de 72 horas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1324","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, podrá adoptar alguna de las medidas cautelares previstas en la Ley, a fin de asegurar la resolución final que pudiera recaer:","o":["el Juez de Instrucción.","el instructor.","el Subdelegado del Gobierno.","el Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el instructor</mark></span>El <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares\"</span>. Las adopta el instructor (el internamiento, previa autorización judicial). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1325","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. Incoado el expediente de expulsión, el instructor podrá solicitar al Juez de Instrucción competente que disponga el ingreso del extranjero en un centro de internamiento. El Juez resolverá mediante auto motivado:","o":["previa audiencia del interesado y del Ministerio Fiscal.","previa audiencia del instructor del expediente y del propio interesado.","previo informe de la autoridad gubernativa.","sin audiencia, dada la urgencia de la medida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">previa audiencia del interesado y del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 62.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Juez, previa audiencia del interesado y del Ministerio Fiscal, resolverá mediante auto motivado\"</span>. Audiencia del interesado y del Ministerio Fiscal; resuelve por auto motivado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1326","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. Para acordar el internamiento, el Juez, de acuerdo con el principio de proporcionalidad, tomará en consideración las circunstancias concurrentes y, en especial: Señale la INCORRECTA.","o":["el riesgo de incomparecencia por carecer de domicilio o de documentación identificativa.","las actuaciones del extranjero tendentes a dificultar o evitar la expulsión.","la existencia de condena o sanciones administrativas previas y de otros procesos penales o procedimientos administrativos sancionadores pendientes.","la nacionalidad del extranjero y la existencia de acuerdos de readmisión con su país."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la nacionalidad del extranjero y la existencia de acuerdos de readmisión con su país</mark></span>El <span class=\"ref-norma\">art. 62.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"tomará en consideración las circunstancias concurrentes y, en especial, el riesgo de incomparecencia por carecer de domicilio o de documentación identificativa, las actuaciones del extranjero tendentes a dificultar o evitar la expulsión, así como la existencia de condena o sanciones administrativas previas\"</span>. La nacionalidad y los acuerdos de readmisión no figuran entre las circunstancias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1327","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. En caso de enfermedad grave del extranjero cuyo internamiento se solicita, el juez:","o":["denegará en todo caso el internamiento y acordará otra medida cautelar menos gravosa.","acordará el internamiento en un centro hospitalario penitenciario hasta su curación.","valorará el riesgo del internamiento para la salud pública o la salud del propio extranjero.","solicitará informe médico forense antes de resolver en el plazo de setenta y dos horas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">valorará el riesgo del internamiento para la salud pública o la salud del propio extranjero</mark></span>El <span class=\"ref-norma\">art. 62.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Asimismo, en caso de enfermedad grave del extranjero, el juez valorará el riesgo del internamiento para la salud pública o la salud del propio extranjero\"</span>. El juez valora el riesgo para la salud pública o del propio extranjero; no hay denegación automática. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1329","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. El Juez competente para el control de la estancia de los extranjeros en los Centros de Internamiento y en las Salas de Inadmisión de fronteras será:","o":["el Juez de Instrucción del lugar donde estén ubicados.","el Juez de Instrucción del lugar donde se practique la detención.","el Juez de lo Contencioso-Administrativo de la provincia.","el Juez de Vigilancia Penitenciaria del lugar del centro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Juez de Instrucción del lugar donde estén ubicados</mark></span>El <span class=\"ref-norma\">art. 62.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Juez competente para el control de la estancia de los extranjeros en los Centros de Internamiento y en las Salas de Inadmisión de fronteras, será el Juez de Instrucción del lugar donde estén ubicados\"</span>. Autorizar el internamiento: Juez de Instrucción del lugar de la detención; controlar la estancia: el del lugar donde esté ubicado el centro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1336","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Información y reclamaciones. Los extranjeros recibirán a su ingreso en el centro de internamiento información escrita sobre sus derechos y obligaciones, las cuestiones de organización general, las normas de funcionamiento, las normas disciplinarias y los medios para formular peticiones o quejas. La información se les facilitará:","o":["en castellano y en inglés.","en un idioma que entiendan.","en la lengua oficial del país de origen.","verbalmente, con asistencia de intérprete."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en un idioma que entiendan</mark></span>El <span class=\"ref-norma\">art. 62 quáter.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La información se les facilitará en un idioma que entiendan\"</span>. En un idioma que entiendan. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1339","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas de seguridad. El director del centro de internamiento deberá comunicar lo antes posible la adopción y cese de los medios de contención física personal, con expresión detallada de los hechos que hubieren dado lugar a dicha utilización:","o":["al Ministerio Fiscal de la provincia en que se ubique el centro.","a la Dirección General de la Policía.","a la autoridad judicial que autorizó el internamiento.","al Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a la autoridad judicial que autorizó el internamiento</mark></span>El <span class=\"ref-norma\">art. 62 quinquies.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El director deberá comunicar lo antes posible a la autoridad judicial que autorizó el internamiento la adopción y cese de los medios de contención física personal\"</span>. Se comunica a la autoridad judicial que autorizó el internamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1344","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento ordinario. El plazo de cumplimiento voluntario de la orden de expulsión tramitada por el procedimiento ordinario podrá prorrogarse durante un tiempo prudencial en atención a las circunstancias que concurran en cada caso concreto, como pueden ser:","o":["la nacionalidad del extranjero, la carencia de medios económicos o la existencia de una oferta de trabajo en España.","la duración de la estancia, estar a cargo de niños escolarizados o la existencia de otros vínculos familiares y sociales.","la duración de la estancia, la existencia de un contrato de trabajo o la solicitud de protección internacional en trámite.","la edad del extranjero, su estado de salud o la falta de acuerdos de readmisión con su país de origen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la duración de la estancia, estar a cargo de niños escolarizados o la existencia de otros vínculos familiares y sociales</mark></span>El <span class=\"ref-norma\">art. 63 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El plazo de cumplimiento voluntario de la orden de expulsión podrá prorrogarse durante un tiempo prudencial en atención a las circunstancias que concurran en cada caso concreto, como pueden ser, la duración de la estancia, estar a cargo de niños escolarizados o la existencia de otros vínculos familiares y sociales\"</span>. La Ley cita la duración de la estancia, tener a cargo niños escolarizados y otros vínculos familiares y sociales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1345","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento ordinario. Tanto en la fase de tramitación del procedimiento ordinario como durante el plazo de cumplimiento voluntario, podrá adoptarse alguna o algunas de las medidas cautelares establecidas en la Ley:","o":["excepto la de internamiento.","excepto la de detención cautelar.","incluido el internamiento hasta 60 días.","excepto la retirada del pasaporte."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">excepto la de internamiento</mark></span>El <span class=\"ref-norma\">art. 63 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Tanto en la fase de tramitación del procedimiento como durante el plazo de cumplimiento voluntario, podrá adoptarse alguna o algunas de las medidas cautelares establecidas en el artículo 61, excepto la de internamiento prevista en la letra e)\"</span>. En el procedimiento ordinario cabe cualquier medida cautelar salvo el internamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1347","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. Tanto en los supuestos de prórroga del plazo de cumplimiento voluntario como de aplazamiento o suspensión de la ejecución de la expulsión, se tendrá en cuenta la garantía para el extranjero afectado de: Señale la INCORRECTA.","o":["El mantenimiento de la unidad familiar con los miembros que se hallen en territorio español.","La prestación de atención sanitaria de urgencia y tratamiento básico de enfermedades.","La obtención de una autorización provisional de residencia y trabajo.","Las necesidades especiales de personas vulnerables."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La obtención de una autorización provisional de residencia y trabajo</mark></span>El <span class=\"ref-norma\">art. 64.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) El mantenimiento de la unidad familiar con los miembros que se hallen en territorio español. b) La prestación de atención sanitaria de urgencia y tratamiento básico de enfermedades\"</span>. La autorización provisional de residencia y trabajo no es una de las garantías. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1351","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Carácter recurrible de las resoluciones sobre extranjeros. En todo caso, cuando el extranjero no se encuentre en España, podrá cursar los recursos procedentes, tanto en vía administrativa como jurisdiccional:","o":["directamente ante el órgano que dictó la resolución, por medios electrónicos y sin necesidad de representante.","a través del Ministerio de Asuntos Exteriores, que los remitirá al órgano judicial competente en el plazo de diez días.","a través de las representaciones diplomáticas o consulares correspondientes, quienes los remitirán al organismo competente.","únicamente por medio de abogado colegiado en España, designado de oficio si careciera de recursos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a través de las representaciones diplomáticas o consulares correspondientes, quienes los remitirán al organismo competente</mark></span>El <span class=\"ref-norma\">art. 65.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"cuando el extranjero no se encuentre en España, podrá cursar los recursos procedentes, tanto en vía administrativa como jurisdiccional, a través de las representaciones diplomáticas o consulares correspondientes, quienes los remitirán al organismo competente\"</span>. A través de las representaciones diplomáticas o consulares, que los remiten al organismo competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1352","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Obligaciones de los transportistas. Las autoridades encargadas del control de entrada guardarán los datos de los pasajeros remitidos por los transportistas en un fichero temporal, borrándolos tras la entrada y en un plazo de:","o":["cuarenta y ocho horas desde su comunicación, salvo necesidades en el ejercicio de sus funciones.","veinticuatro horas desde su comunicación, salvo necesidades en el ejercicio de sus funciones.","setenta y dos horas desde la llegada del transporte, salvo autorización judicial en contrario.","veinticuatro horas desde la entrada, sin excepción alguna en ningún caso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">veinticuatro horas desde su comunicación, salvo necesidades en el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 66.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las autoridades encargadas del control de entrada guardarán los datos en un fichero temporal, borrándolos tras la entrada y en un plazo de veinticuatro horas desde su comunicación, salvo necesidades en el ejercicio de sus funciones\"</span>. Veinticuatro horas desde su comunicación, salvo necesidades en el ejercicio de sus funciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1353","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Obligaciones de los transportistas. Toda compañía, empresa de transporte o transportista estará obligada a enviar a las autoridades encargadas del control de entrada la información comprensiva del número de billetes de vuelta no utilizados por los pasajeros que previamente hubiesen transportado a España, desde rutas procedentes de fuera del Espacio Schengen. Esta información deberá enviarse en un plazo no superior a:","o":["48 horas desde la fecha de caducidad del billete.","24 horas desde la fecha prevista de vuelta.","72 horas desde la fecha de caducidad del billete.","48 horas desde la fecha de llegada a España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">48 horas desde la fecha de caducidad del billete</mark></span>El <span class=\"ref-norma\">art. 66.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La información señalada en el presente apartado deberá enviarse en un plazo no superior a 48 horas desde la fecha de caducidad del billete\"</span>. 48 horas desde la caducidad del billete (los datos de pasajeros se borran a las 24 horas). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1354","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Obligaciones de los transportistas. Toda compañía de transporte estará obligada a transportar a los extranjeros a los que se hubiera denegado la entrada hasta el Estado a partir del cual le haya transportado, hasta el Estado que haya expedido el documento de viaje, o bien a cualquier otro Estado que garantice:","o":["su admisión y la tramitación de su solicitud de asilo.","su admisión, previa autorización del Ministerio del Interior.","la protección internacional del extranjero transportado.","su admisión y un trato compatible con los derechos humanos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su admisión y un trato compatible con los derechos humanos</mark></span>El <span class=\"ref-norma\">art. 66.3.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"o bien a cualquier otro Estado que garantice su admisión y un trato compatible con los derechos humanos\"</span>. Debe garantizar su admisión y un trato compatible con los derechos humanos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1355","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Obligaciones de los transportistas. Las obligaciones de los transportistas se entienden también para el caso en que el transporte aéreo o marítimo se realice:","o":["desde Canarias hasta cualquier otro punto del territorio español.","entre Estados miembros del Espacio Schengen con destino final en España.","desde Ceuta o Melilla hasta cualquier otro punto del territorio español.","desde las Islas Baleares hasta la península, en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desde Ceuta o Melilla hasta cualquier otro punto del territorio español</mark></span>El <span class=\"ref-norma\">art. 66.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Lo establecido en este artículo se entiende también para el caso en que el transporte aéreo o marítimo se realice desde Ceuta o Melilla hasta cualquier otro punto del territorio español\"</span>. Se extiende al transporte desde Ceuta o Melilla al resto del territorio español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1402","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de las Administraciones Públicas. El informe sobre la integración social del extranjero previo a la concesión de autorizaciones por arraigo tendrá en cuenta, en todo caso: Señale la INCORRECTA.","o":["el periodo de permanencia.","los vínculos con familiares residentes en España.","los esfuerzos de integración a través del seguimiento de programas de inserción sociolaborales y culturales.","la carencia de antecedentes penales en España y en su país de origen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la carencia de antecedentes penales en España y en su país de origen</mark></span>El <span class=\"ref-norma\">art. 68.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, el informe tendrá en cuenta el periodo de permanencia, la posibilidad de contar con vivienda y medios de vida, los vínculos con familiares residentes en España, y los esfuerzos de integración a través del seguimiento de programas de inserción sociolaborales y culturales\"</span>. Los antecedentes penales no figuran entre los contenidos del informe de integración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1407","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plazo máximo para resolución de expedientes. El plazo general máximo para notificar las resoluciones de las solicitudes de autorizaciones es de tres meses, sin perjuicio del plazo máximo establecido por la normativa comunitaria en relación con procedimientos de solicitud de visado de tránsito o estancia, que es de:","o":["15 días hábiles.","10 días naturales.","15 días naturales.","30 días naturales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">15 días naturales</mark></span>El <span class=\"ref-norma\">disp. adic. 1.ª.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio del plazo máximo de 15 días naturales establecido por la normativa comunitaria en relación con procedimientos de solicitud de visado de tránsito o estancia\"</span>. Quince días naturales para los visados de tránsito o estancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1431","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas. Para dotar en el año 2025 el Fondo para compensar a las comunidades y ciudades autónomas por los costes ocasionados por la sobreocupación por menores extranjeros no acompañados trasladados se concede un crédito extraordinario por un importe de:","o":["10.000.000 de euros.","50.000.000 de euros.","100.000.000 de euros.","1.000.000.000 de euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">100.000.000 de euros</mark></span>El <span class=\"ref-norma\">disp. adic. 11.ª.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"por un importe de 100.000.000 de euros\"</span>. Cien millones de euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1437","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Modificación del artículo 312 del Código Penal. Conforme a la modificación del Código Penal introducida por la Ley Orgánica 4/2000, serán castigados los que trafiquen de manera ilegal con mano de obra con las penas de:","o":["prisión de dos a cinco años y multa de seis a doce meses.","prisión de uno a tres años y multa de doce a veinticuatro meses.","prisión de dos a cuatro años y multa de seis a doce meses.","prisión de seis meses a tres años y multa de seis a doce meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">prisión de dos a cinco años y multa de seis a doce meses</mark></span>El <span class=\"ref-norma\">disp. final 1.ª de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Serán castigados con las penas de prisión de dos a cinco años y multa de seis a doce meses, los que trafiquen de manera ilegal con mano de obra\"</span>. Prisión de dos a cinco años y multa de seis a doce meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1438","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Preceptos no orgánicos. Según la disposición sobre preceptos no orgánicos de la Ley Orgánica 4/2000, NO tienen naturaleza orgánica:","o":["los preceptos sobre infracciones muy graves y el régimen de sanciones pecuniarias aplicable.","los preceptos sobre los derechos de reunión, asociación y sindicación.","los preceptos sobre la expulsión del territorio y sus efectos.","los preceptos sobre tasas por autorizaciones administrativas y solicitudes de visado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los preceptos sobre tasas por autorizaciones administrativas y solicitudes de visado</mark></span>El <span class=\"ref-norma\">disp. final 4.ª de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los preceptos no incluidos en el apartado anterior no tienen naturaleza orgánica\"</span>. Los artículos 44 a 49 (tasas) no figuran en la lista de preceptos orgánicos; sí los de derechos, infracciones (53 a 55) y expulsión (57 y 58). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25 bis — Tipos de visado EX ✱","q":[{"i":"6-11","p":"Ley Orgánica 4/2000. Tipos de visado. El visado de residencia y trabajo de temporada habilita:","o":["Para trabajar por cuenta propia durante seis meses en un periodo de doce meses consecutivos.","Para trabajar por cuenta ajena hasta nueve meses en un periodo de doce meses consecutivos.","Para trabajar por cuenta ajena hasta nueve meses en un periodo de dieciséis meses consecutivos.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Para trabajar por cuenta ajena hasta nueve meses en un periodo de doce meses consecutivos</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Visado de residencia y trabajo de temporada, que habilita para trabajar por cuenta ajena hasta nueve meses en un período de doce meses consecutivos\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-33","p":"Ley Orgánica 4/2000. Tipos de visado. ¿Cuál de las siguientes clases de visado NO existe?","o":["Visado de tránsito.","Visado de estancia.","Visado de permanencia.","Visado de estudios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Visado de permanencia</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los visados a que se refiere el apartado anterior serán de una de las clases siguientes\"</span>. Las clases son: tránsito, estancia, residencia, residencia y trabajo, residencia y trabajo de temporada, estudios e investigación; no existe el «visado de permanencia» (Verificado con el texto del temario oficial.)"},{"i":"6-35","p":"Ley Orgánica 4/2000. Tipos de visado. Indique la proposición correcta.","o":["Reglamentariamente, se desarrollarán los diferentes tipos de visados.","El visado de estancia habilita para residir sin ejercer actividad laboral o profesional.","El visado de turista tendrá una validez de 3 meses.","El visado de residencia y trabajo de temporada habilita para trabajar por cuenta ajena hasta seis meses en un periodo de doce meses consecutivos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reglamentariamente, se desarrollarán los diferentes tipos de visados</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Reglamentariamente, se desarrollarán los diferentes tipos de visados\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-70","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipo de visados. El visado de residencia y trabajo de temporada habilita:","o":["Para trabajar por cuenta propia hasta nueve meses en un periodo de doce meses consecutivos.","Para trabajar por cuenta ajena hasta nueve meses en un periodo de doce meses consecutivos.","Para trabajar por cuenta propia hasta seis meses en un periodo de nueve meses consecutivos.","Para trabajar por cuenta ajena hasta seis meses en un periodo de nueve meses consecutivos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Para trabajar por cuenta ajena hasta nueve meses en un periodo de doce meses consecutivos</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Visado de residencia y trabajo de temporada, que habilita para trabajar por cuenta ajena hasta nueve meses en un período de doce meses consecutivos\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-90","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. Habilita para residir sin ejercer actividad laboral o profesional:","o":["Visado de residencia.","Visado de estudios.","Visado de estancia.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Visado de residencia</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Visado de residencia, que habilita para residir sin ejercer actividad laboral o profesional\"</span>. El enunciado pedía «la incorrecta» y había dos; se reformula (Verificado con el texto del temario oficial.)"},{"i":"6-200","p":"Ley Orgánica 4/2000... Visados. El visado de residencia habilita a:","o":["Habilita para trabajar por cuenta ajena hasta nueve meses en un período de doce meses consecutivos.","Habilita a permanecer en España para la realización de cursos, estudios, trabajos de investigación o formación.","Habilita para residir sin ejercer actividad laboral o profesional.","Ninguna opción es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Habilita para residir sin ejercer actividad laboral o profesional</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Visado de residencia, que habilita para residir sin ejercer actividad laboral o profesional\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-323","p":"Ley Orgánica 4/2000... Visados. El visado de residencia habilita a:","o":["Habilita para trabajar por cuenta ajena hasta nueve meses en un período de doce meses consecutivos.","Habilita a permanecer en España para la realización de cursos, estudios, trabajos de investigación o formación.","Habilita para residir sin ejercer actividad laboral o profesional.","Ninguna opción es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Habilita para residir sin ejercer actividad laboral o profesional</mark></span>Según el <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Visado de residencia, que habilita para residir sin ejercer actividad laboral o profesional\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-413","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. El visado de estancia habilita para una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de:","o":["Tres meses por semestre a partir de la fecha de la primera entrada.","Tres meses por año a partir de la fecha de la primera entrada.","Seis meses por año a partir de la fecha de la primera entrada.","Noventa días por trimestre a partir de la fecha de la primera entrada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses por semestre a partir de la fecha de la primera entrada</mark></span>El <span class=\"ref-norma\">art. 25 bis.2.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Visado de estancia, que habilita para una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de tres meses por semestre a partir de la fecha de la primera entrada.\"</span>"},{"i":"6-414","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. El visado de residencia y trabajo de temporada habilita para trabajar por cuenta ajena:","o":["Hasta seis meses en un período de doce meses consecutivos.","Hasta nueve meses en un período de dieciocho meses consecutivos.","Hasta doce meses en un período de veinticuatro meses consecutivos.","Hasta nueve meses en un período de doce meses consecutivos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Hasta nueve meses en un período de doce meses consecutivos</mark></span>El <span class=\"ref-norma\">art. 25 bis.2.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Visado de residencia y trabajo de temporada, que habilita para trabajar por cuenta ajena hasta nueve meses en un período de doce meses consecutivos.\"</span>"},{"i":"6-ia-1046","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. El visado de estancia habilita para una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de __________ a partir de la fecha de la primera entrada.","o":["seis meses por año","noventa días por año natural","tres meses por año","tres meses por semestre"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres meses por semestre</mark></span>El <span class=\"ref-norma\">art. 25 bis.2.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Visado de estancia, que habilita para una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de tres meses por semestre a partir de la fecha de la primera entrada\"</span>. La medida es «tres meses por semestre» desde la primera entrada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1047","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. El visado de residencia y trabajo habilita para la entrada y estancia por un período máximo de tres meses y para el comienzo, en ese plazo, de la actividad para la que hubiera sido previamente autorizado. En este tiempo deberá producirse el alta del trabajador en la Seguridad Social y, si transcurrido el plazo no se hubiera producido el alta:","o":["la autorización se prorrogará de oficio por un nuevo período de tres meses.","el empleador quedará obligado a solicitar una nueva autorización de residencia y trabajo en el plazo de un mes desde la caducidad.","el extranjero quedará obligado a salir del territorio nacional, incurriendo, en caso contrario, en infracción.","el visado se transformará en visado de estancia por el tiempo restante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el extranjero quedará obligado a salir del territorio nacional, incurriendo, en caso contrario, en infracción</mark></span>El <span class=\"ref-norma\">art. 25 bis.2.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Si transcurrido el plazo no se hubiera producido el alta, el extranjero quedará obligado a salir del territorio nacional, incurriendo, en caso contrario, en la infracción contemplada en el artículo 53.1.a) de esta Ley\"</span>. Sin alta en plazo, nace la obligación de salir; si no sale, incurre en infracción (grave, estancia irregular). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 20 — Derecho a la tutela judicial efectiva ✱","q":[{"i":"6-13","p":"Ley Orgánica 4/2000. Derechos y libertades de los extranjeros. Derecho a la Tutela judicial efectiva. Los procedimientos administrativos que se establezcan en materia de extranjería respetarán en todo caso las garantías previstas en la legislación general sobre procedimiento administrativo, especialmente en lo relativo a:","o":["Publicidad de las normas.","Contradicción.","Audiencia del interesado.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 20.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"especialmente en lo relativo a publicidad de las normas, contradicción, audiencia del interesado y motivación de las resoluciones\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-29","p":"Ley Orgánica 4/2000. Garantías jurídicas. Los procedimientos administrativos que se establezcan en materia de extranjería respetarán en todo caso las garantías previstas en la legislación general sobre procedimiento administrativo, especialmente en lo relativo a: Indique la INCORRECTA.","o":["Publicidad de las normas.","Contradicción.","Audiencia del interesado.","Defensa y motivación de las resoluciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Defensa y motivación de las resoluciones</mark></span>Según el <span class=\"ref-norma\">art. 20.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"especialmente en lo relativo a publicidad de las normas, contradicción, audiencia del interesado y motivación de las resoluciones\"</span>. La «defensa» no figura entre esas garantías; la publicidad de las normas sí (la respuesta estaba invertida) (Verificado con el texto del temario oficial.)"},{"i":"6-179","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Garantías jurídicas. Los procedimientos administrativos que se establezcan en materia de extranjería respetarán en todo caso las garantías previstas en la legislación general sobre procedimiento administrativo, especialmente en lo relativo a:","o":["Publicidad de las normas y contradicción.","Audiencia del interesado.","Motivación de las resoluciones.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 20.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"especialmente en lo relativo a publicidad de las normas, contradicción, audiencia del interesado y motivación de las resoluciones\"</span>. Es materia de la LO 4/2000; se corrige A («contestación» por contradicción) (Verificado con el texto del temario oficial.)"},{"i":"6-258","p":"(Ley Orgánica 4/2000) Garantías jurídicas: señala la INCORRECTA.","o":["Los extranjeros tienen derecho a la tutela judicial efectiva.","Los procedimientos administrativos que se establezcan en materia de extranjería respetarán en todo caso las garantías previstas en la legislación general sobre procedimiento administrativo.","En los procedimientos administrativos estarán legitimadas para intervenir como interesadas las organizaciones constituidas legalmente en España para la defensa de los inmigrantes, expresamente designadas por éstos.","En los procesos contencioso-administrativos en materia de extranjería no estarán legitimadas para intervenir las entidades que resulten afectadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En los procesos contencioso-administrativos en materia de extranjería no estarán legitimadas para intervenir las entidades que resulten afectadas</mark></span>Según el <span class=\"ref-norma\">art. 20.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los procesos contencioso-administrativos en materia de extranjería estarán legitimadas para intervenir las entidades que resulten afectadas\"</span>. La marcada era en realidad correcta; se reescriben B, C y D (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1034","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la tutela judicial efectiva. En los procedimientos administrativos estarán legitimadas para intervenir como interesadas las organizaciones constituidas legalmente en España para la defensa de los inmigrantes:","o":["inscritas en el registro del Ministerio del Interior.","declaradas de utilidad pública.","que acrediten un interés legítimo directo.","expresamente designadas por éstos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">expresamente designadas por éstos</mark></span>El <span class=\"ref-norma\">art. 20.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En los procedimientos administrativos estarán legitimadas para intervenir como interesadas las organizaciones constituidas legalmente en España para la defensa de los inmigrantes, expresamente designadas por éstos\"</span>. La legitimación en vía administrativa exige la designación expresa por los inmigrantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25 — Requisitos para la entrada en territorio español EXOF EX ✱","q":[{"i":"6-14","p":"Ley Orgánica 4/2000. Régimen de visado. Podrán establecerse excepciones al régimen de visados en relación con:","o":["Nacionales de países con los que se hayan suscrito acuerdos internacionales.","Residentes de países con los que se hayan suscrito acuerdos internacionales.","Nacionales de países que mantengan relaciones diplomáticas estables con España.","Los extranjeros que demuestren que los flujos migratorios tienen una especial incidencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Nacionales de países con los que se hayan suscrito acuerdos internacionales</mark></span>Según el <span class=\"ref-norma\">art. 25.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Salvo en los casos en que se establezca lo contrario en los convenios internacionales suscritos por España o en la normativa de la Unión Europea, será preciso, además, un visado\"</span>. Las excepciones al visado derivan de los convenios internacionales suscritos por España (o de la normativa de la Unión Europea) (Verificado con el texto del temario oficial.)"},{"i":"6-34","p":"Ley Orgánica 4/2000. Requisitos para la entrada en territorio español. Indique la INCORRECTA.","o":["El extranjero que pretenda entrar en España deberá hacerlo por los puestos habilitados al efecto.","Será exigible el visado aun cuando el extranjero se encuentre provisto de la tarjeta de identidad de extranjeros.","Se podrá autorizar la entrada en España de los extranjeros que no reúnan los requisitos establecidos cuando existan razones excepcionales de índole humanitaria.","Lo dispuesto en la presente Ley Orgánica no será de aplicación a los extranjeros que soliciten acogerse al derecho de asilo en el momento de su entrada en España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Será exigible el visado aun cuando el extranjero se encuentre provisto de la tarjeta de identidad de extranjeros</mark></span>La B es la INCORRECTA. La D recoge (casi literal) el art. 25.3 sobre los solicitantes de asilo. Según el <span class=\"ref-norma\">art. 25.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"No será exigible el visado cuando el extranjero se encuentre provisto de la tarjeta de identidad de extranjero o, excepcionalmente, de una autorización de regreso.\"</span> (verificado con el texto del temario)."},{"i":"6-125","p":"(Ley Orgánica 4/2000) Se podrá autorizar la entrada en España de extranjeros que no reúnan los requisitos establecidos cuando existan razones excepcionales de:","o":["El cumplimiento de compromisos adquiridos por España.","Razones excepcionales de índole humanitaria.","Interés público.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 25.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"cuando existan razones excepcionales de índole humanitaria, interés público o cumplimiento de compromisos adquiridos por España\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-350","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la entrada. El extranjero que pretenda entrar en España deberá hacerlo por los puestos habilitados al efecto, hallarse provisto del pasaporte o documento de viaje que acredite su identidad y no estar:","o":["Incluido en el registro de extranjeros en situación irregular.","Sujeto a procedimiento de expulsión en trámite.","Sujeto a prohibiciones expresas.","Sujeto a prohibiciones expresas o a medidas cautelares de la autoridad gubernativa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sujeto a prohibiciones expresas</mark></span>El <span class=\"ref-norma\">art. 25.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. El extranjero que pretenda entrar en España deberá hacerlo por los puestos habilitados al efecto, hallarse provisto del pasaporte o documento de viaje que acredite su identidad, que se considere válido para tal fin en virtud de convenios internacionales suscritos por España y no estar sujeto a prohibiciones expresas.\"</span>"},{"i":"6-351","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la entrada. No será exigible el visado cuando el extranjero se encuentre provisto de:","o":["La tarjeta de identidad de extranjero o de un permiso de conducir internacional, salvo que el órgano competente acuerde otra cosa de forma motivada.","La tarjeta de identidad de extranjero o, excepcionalmente, de una autorización de regreso.","Un contrato de trabajo en vigor o de una autorización de residencia en trámite.","Un pasaporte con validez superior a seis meses o de una autorización de regreso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La tarjeta de identidad de extranjero o, excepcionalmente, de una autorización de regreso</mark></span>El <span class=\"ref-norma\">art. 25.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Salvo en los casos en que se establezca lo contrario en los convenios internacionales suscritos por España o en la normativa de la Unión Europea, será preciso, además, un visado. No será exigible el visado cuando el extranjero se encuentre provisto de la tarjeta de identidad de extranjero o, excepcionalmente, de una autorización de regreso.\"</span>"},{"i":"6-ia-1043","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la entrada en territorio español. El extranjero que pretenda entrar en España deberá presentar los documentos que se determinen reglamentariamente que justifiquen el objeto y condiciones de estancia, y acreditar:","o":["medios de vida suficientes para un período mínimo de tres meses, o una carta de invitación de un residente en España.","un seguro médico con cobertura en todo el territorio nacional y medios económicos suficientes para el regreso a su país de origen.","medios de vida suficientes para el tiempo que pretenda permanecer en España, o estar en condiciones de obtener legalmente dichos medios.","medios de vida suficientes para el tiempo de estancia, sin que pueda suplirse con la posibilidad de obtenerlos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">medios de vida suficientes para el tiempo que pretenda permanecer en España, o estar en condiciones de obtener legalmente dichos medios</mark></span>El <span class=\"ref-norma\">art. 25.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"y acreditar medios de vida suficientes para el tiempo que pretenda permanecer en España, o estar en condiciones de obtener legalmente dichos medios\"</span>. Los medios se refieren al tiempo que pretenda permanecer, y cabe estar en condiciones de obtenerlos legalmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 ter — Integración de los inmigrantes ✱","q":[{"i":"6-15","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Integración de los inmigrantes. Promoverán la plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley:","o":["Los poderes públicos.","El Ministro de la Presidencia.","El Congreso de los Diputados.","Todas las opciones son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los poderes públicos</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los poderes públicos promoverán la plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley\"</span>. Se corrige el enunciado: la Ley atribuye esta promoción a los poderes públicos (el «Estado» garantiza el principio de solidaridad) (Verificado con el texto del temario oficial.)"},{"i":"6-19","p":"Ley Orgánica 4/2000. ¿Qué programas se acordarán en la Conferencia Sectorial de Inmigración para reforzar la integración social de los inmigrantes?","o":["Programas plurianuales.","Programas de acción bienales.","Programas estratégicos plurianuales.","Ninguna opción es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Programas de acción bienales</mark></span>Son programas de acción BIENALES; lo plurianual es el plan estratégico del art. 2 ter.3. Según el <span class=\"ref-norma\">art. 2 ter.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"...el Gobierno y las Comunidades autónomas acordarán en la Conferencia Sectorial de Inmigración programas de acción bienales para reforzar la integración social de los inmigrantes.\"</span> (verificado con el texto del temario)."},{"i":"6-47","p":"Ley Orgánica 4/2000. Integración de los inmigrantes. Las Administraciones Públicas, como factores esenciales de integración:","o":["Garantizarán el acceso al empleo.","Garantizarán en todo caso la escolarización obligatoria.","Sensibilizarán el aprendizaje del conjunto de lenguas oficiales.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Garantizarán en todo caso la escolarización obligatoria</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"garantizando en todo caso la escolarización en la edad obligatoria\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-82","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Disposiciones generales. El Gobierno y las Comunidades Autónomas acordarán en la Conferencia Sectorial de Inmigración programas de acción bienales para reforzar la integración social de los inmigrantes, de conformidad con:","o":["Los criterios y prioridades del Plan Estratégico de Inmigración.","Las bases y prioridades del Plan Europeo de Integración.","Los criterios y prioridades del Plan Estratégico de Trabajo e Inmigración.","Los criterios y prioridades del Plan Estratégico Sectorial de Trabajo e Inmigración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los criterios y prioridades del Plan Estratégico de Inmigración</mark></span>Se corrige el texto de la opción A, que decía «Plan Estratégico de Integración». Según el <span class=\"ref-norma\">art. 2 ter.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"De conformidad con los criterios y prioridades del Plan Estratégico de Inmigración, el Gobierno y las Comunidades autónomas acordarán en la Conferencia Sectorial de Inmigración programas de acción bienales...\"</span> (verificado con el texto del temario)."},{"i":"6-113","p":"(Ley Orgánica 4/2000) Integración de los inmigrantes. Los poderes públicos promoverán:","o":["La plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley.","La plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y los tratados internacionales.","La plena integración de los extranjeros en las comunidades, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley.","La plena socialización de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los poderes públicos promoverán la plena integración de los extranjeros en la sociedad española, en un marco de convivencia de identidades y culturas diversas sin más límite que el respeto a la Constitución y la ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-122","p":"(Ley Orgánica 4/2000) Indique los organismos que colaboran en los planes de Inmigración, Ciudadanía e Integración.","o":["La Administración General del Estado.","Las Comunidades Autónomas.","Los Ayuntamientos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"la Administración General del Estado, las Comunidades Autónomas y los Ayuntamientos colaborarán y coordinarán sus acciones en este ámbito tomando como referencia sus respectivos planes de integración\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1007","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Integración de los inmigrantes. Las Administraciones Públicas incorporarán el objetivo de la integración entre inmigrantes y sociedad receptora, __________, promoviendo la participación económica, social, cultural y política de las personas inmigrantes.","o":["con carácter prioritario en las políticas de empleo y vivienda","con carácter subsidiario respecto de las políticas autonómicas","con carácter transversal a todas las políticas y servicios públicos","con carácter específico en los servicios sociales municipales"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con carácter transversal a todas las políticas y servicios públicos</mark></span>El <span class=\"ref-norma\">art. 2 ter.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las Administraciones Públicas incorporarán el objetivo de la integración entre inmigrantes y sociedad receptora, con carácter transversal a todas las políticas y servicios públicos\"</span>. El carácter es «transversal a todas las políticas y servicios públicos». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1008","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Integración de los inmigrantes. La Administración General del Estado cooperará con las Comunidades Autónomas, las Ciudades de Ceuta y Melilla y los Ayuntamientos para la consecución de las finalidades de integración, en el marco de un plan estratégico plurianual que incluirá entre sus objetivos atender a la integración de:","o":["las mujeres extranjeras víctimas de violencia de género.","los menores extranjeros no acompañados.","los trabajadores extranjeros de temporada.","los solicitantes de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los menores extranjeros no acompañados</mark></span>El <span class=\"ref-norma\">art. 2 ter.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"en el marco de un plan estratégico plurianual que incluirá entre sus objetivos atender a la integración de los menores extranjeros no acompañados\"</span>. El plan estratégico plurianual incluye expresamente la integración de los menores extranjeros no acompañados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 33 — Reducción o retirada de las condiciones de acogida ✱","q":[{"i":"6-16","p":"Ley 12/2009. Reducción o retirada de las condiciones de acogida. El Ministerio competente en el ejercicio de las competencias sobre servicios, ayudas y prestaciones de los diferentes programas de acogida, podrá reducir o retirar alguno o la totalidad de los servicios de acogida en los siguientes casos: Señale la incorrecta.","o":["Cuando la persona solicitante abandone el lugar de residencia asignado sin informar a la autoridad competente, o en caso de haberlo solicitado, sin permiso.","Cuando la persona solicitante accediese a recursos económicos y pudiese hacer frente a la totalidad o parte de los costes de las condiciones de acogida o cuando hubiere ocultado sus recursos económicos, y, por tanto, se beneficie indebidamente de las prestaciones de acogida establecidas.","Cuando haya finalizado el periodo del programa o prestación autorizado.","Cuando se niegue, sin causa justificada, a cooperar con la autoridad competente o con la organización que le preste la asistencia, en el cumplimiento de los fines del programa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se niegue, sin causa justificada, a cooperar con la autoridad competente o con la organización que le preste la asistencia, en el cumplimiento de los fines del programa</mark></span>Según el <span class=\"ref-norma\">art. 33.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) cuando se haya dictado resolución de la solicitud de protección internacional, y se haya notificado al interesado, salvo lo dispuesto en el apartado tercero del artículo 36 de esta Ley; d) cuando por acción u omisión se vulneren los derechos de otros residentes o del personal encargado de los centros donde estén acogidos o se dificulte gravemente la convivencia en ellos, de conformidad con lo establecido en las normas internas de los mismos; e) cuando haya finalizado el periodo del programa o prestación autorizado\"</span>. Negarse a cooperar no figura entre los supuestos de reducción o retirada (se corrigen B y C, que venían alteradas) (Verificado con el texto del temario oficial.)"},{"i":"6-51","p":"Ley 12/2009. Reducción o retirada de las condiciones de acogida. El Ministerio competente en el ejercicio de las competencias sobre servicios, ayudas y prestaciones de los diferentes programas de acogida, podrá reducir o retirar alguno o la totalidad de los servicios de acogida en los siguientes casos, entre otros. Señale la CORRECTA.","o":["Cuando por acción u omisión se vulneren los derechos de otros residentes o del personal encargado de los centros donde sean acogidos o se dificulte, tratando de manera leve, la convivencia en ellos, en conformidad con lo establecido en las normas internas de los mismos.","Cuando la persona solicitante abandone el lugar de residencia asignado sin informar a la autoridad competente o, en caso de haberlo solicitado, sin permiso.","Cuando la persona solicitante acredite o recursos económicos y pudiese hacer frente a la totalidad o parte de los costes de las condiciones de acogida o cuando hubiese ocultado sus recursos económicos o, por tener rentas, se le denegase o retirase prestaciones de las situaciones de acogida establecidas.","Cuando haya transcurrido un año desde la presentación de la solicitud."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando la persona solicitante abandone el lugar de residencia asignado sin informar a la autoridad competente o, en caso de haberlo solicitado, sin permiso</mark></span>La antigua opción D era literal de la letra e) y daba dos respuestas correctas; se sustituye por un supuesto que no está en la Ley. Según el <span class=\"ref-norma\">art. 33.1.a de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) cuando la persona solicitante abandone el lugar de residencia asignado sin informar a la autoridad competente o, en caso de haberlo solicitado, sin permiso;\"</span> (verificado con el texto del temario)."},{"i":"6-119","p":"(Ley 12/2009) De las condiciones de acogida de los solicitantes de protección internacional. Reducción o retirada de las condiciones de acogida. A los efectos de este título, el sistema de faltas y sanciones a aplicar en los centros de acogida será el que de forma reglamentaria establezca:","o":["el Ministro del Interior.","el Ministro de Asuntos Exteriores.","El Ministerio competente, de forma reglamentaria.","el Ministro de Asuntos Sociales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio competente, de forma reglamentaria</mark></span>Se corrige la opción C (decía «La Administración General del Estado»). Según el <span class=\"ref-norma\">art. 33.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"A los efectos del apartado anterior, el sistema de faltas y sanciones a aplicar en los centros de acogida será el que de forma reglamentaria establezca el Ministerio competente.\"</span> (verificado con el texto del temario)."},{"i":"6-446","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reducción o retirada de las condiciones de acogida. Podrán reducirse o retirarse las condiciones de acogida, entre otros supuestos:","o":["Cuando el solicitante haya obtenido autorización de residencia por otro motivo.","Cuando el solicitante haya presentado la solicitud fuera del plazo previsto.","Cuando haya finalizado el periodo del programa o prestación autorizado.","Cuando el solicitante abandone el centro por un período superior a siete días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando haya finalizado el periodo del programa o prestación autorizado</mark></span>El <span class=\"ref-norma\">art. 33.2.e) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"e) cuando haya finalizado el periodo del programa o prestación autorizado.\"</span>"}]},{"a":"Artículo 18 — Requisitos para la reagrupación familiar ✱ R5","q":[{"i":"6-18","p":"Ley Orgánica 4/2000. Requisitos para la reagrupación familiar. ¿Quién informarán sobre la adecuación de la vivienda a los efectos de reagrupación familiar?","o":["Las Comunidades Autónomas.","En su caso, los Ayuntamientos.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Comunidades Autónomas o, en su caso, los Ayuntamientos informarán sobre la adecuación de la vivienda a los efectos de reagrupación familiar\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-162","p":"Ley Orgánica 4/2000 sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos de la reagrupación familiar. El reagrupante deberá acreditar, en los términos que se establezcan reglamentariamente, que dispone, una vez reagrupada:","o":["De una vivienda de su propiedad.","De medios económicos suficientes para cubrir sus necesidades exclusivamente.","De medios económicos suficientes para cubrir sus necesidades y los de su familia, una vez reagrupada.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De medios económicos suficientes para cubrir sus necesidades y los de su familia, una vez reagrupada</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El reagrupante deberá acreditar, en los términos que se establezcan reglamentariamente, que dispone de vivienda adecuada y de medios económicos suficientes para cubrir sus necesidades y las de su familia, una vez reagrupada\"</span>. Se corrige A, que era también literal (Verificado con el texto del temario oficial.)"},{"i":"6-178","p":"Ley Orgánica 4/2000... Requisitos para la reagrupación familiar. ¿Quiénes promoverán la participación de los reagrupados en programas de integración socio-cultural y de carácter lingüístico?","o":["Las Comunidades Autónomas.","Los Ayuntamientos.","Las Administraciones Públicas.","El Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Administraciones Públicas</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Administraciones Públicas promoverán la participación de los reagrupados en programas de integración socio-cultural y de carácter lingüístico\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-269","p":"Ley Orgánica 4/2000. Reagrupación familiar. Cuando los familiares a reagrupar sean menores en edad de escolarización obligatoria, quien deberá comunicar a las autoridades educativas competentes una previsión sobre los procedimientos iniciados de reagrupación familiar, a los efectos de habilitar las plazas necesarias en los centros escolares correspondientes.","o":["El Ayuntamiento.","El Ministerio de Trabajo, migraciónes y seguridad social.","La consejería en materia de integración de la respectiva Comunidad Autónoma.","La administración receptora de la solicitud de reagrupación familiar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La administración receptora de la solicitud de reagrupación familiar</mark></span>Según el <span class=\"ref-norma\">art. 18.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"la Administración receptora de las solicitudes deberá comunicar a las autoridades educativas competentes una previsión sobre los procedimientos iniciados de reagrupación familiar\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-292","p":"Ley Orgánica 4/2000 sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos de la reagrupación familiar. El reagrupante deberá acreditar, en los términos que se establezcan reglamentariamente, que dispone, una vez reagrupada:","o":["De una vivienda de su propiedad.","De medios económicos suficientes para cubrir sus necesidades exclusivamente.","De medios económicos suficientes para cubrir sus necesidades y los de su familia, una vez reagrupada.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De medios económicos suficientes para cubrir sus necesidades y los de su familia, una vez reagrupada</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El reagrupante deberá acreditar, en los términos que se establezcan reglamentariamente, que dispone de vivienda adecuada y de medios económicos suficientes para cubrir sus necesidades y las de su familia, una vez reagrupada\"</span>. Se corrige A, que era también literal (Verificado con el texto del temario oficial.)"},{"i":"6-307","p":"Ley Orgánica 4/2000... Requisitos para la reagrupación familiar. ¿Quiénes promoverán la participación de los reagrupados en programas de integración socio-cultural y de carácter lingüístico?","o":["Las Comunidades Autónomas.","Los Ayuntamientos.","Las Administraciones Públicas.","El Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Administraciones Públicas</mark></span>Según el <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Administraciones Públicas promoverán la participación de los reagrupados en programas de integración socio-cultural y de carácter lingüístico\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-348","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos de la reagrupación familiar. Los extranjeros podrán ejercer el derecho a la reagrupación familiar cuando hayan obtenido:","o":["La renovación de su autorización de residencia inicial.","La autorización de residencia de larga duración.","La residencia temporal inicial, transcurrido un año.","La renovación de su autorización de residencia inicial y la nacionalidad española."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La renovación de su autorización de residencia inicial</mark></span>El <span class=\"ref-norma\">art. 18.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Los extranjeros podrán ejercer el derecho a la reagrupación familiar cuando hayan obtenido la renovación de su autorización de residencia inicial\"</span>"},{"i":"6-ia-1028","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la reagrupación familiar. Los extranjeros podrán ejercer el derecho a la reagrupación familiar cuando hayan obtenido la renovación de su autorización de residencia inicial, con excepción de la reagrupación de los ascendientes, que solamente podrán ser reagrupados:","o":["cuando el reagrupante acredite cinco años de residencia legal y continuada.","a partir del momento en que el reagrupante adquiera la residencia de larga duración.","a partir de la segunda renovación de la autorización de residencia temporal.","cuando el reagrupante obtenga autorización de residencia y trabajo por cuenta ajena."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a partir del momento en que el reagrupante adquiera la residencia de larga duración</mark></span>El <span class=\"ref-norma\">art. 18.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"que solamente podrán ser reagrupados a partir del momento en que el reagrupante adquiera la residencia de larga duración\"</span>. Para los ascendientes se exige la residencia de larga duración del reagrupante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1029","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la reagrupación familiar. La reagrupación de los familiares de residentes de larga duración, de los trabajadores titulares de la tarjeta azul de la U.E. y de los beneficiarios del régimen especial de investigadores:","o":["podrá solicitarse y concederse, simultáneamente, con la solicitud de residencia del reagrupante.","solo podrá solicitarse una vez renovada la autorización de residencia del reagrupante.","deberá solicitarse en el plazo de un mes desde la concesión de la residencia del reagrupante.","podrá solicitarse únicamente desde el Estado de la Unión Europea donde tuvieran su residencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrá solicitarse y concederse, simultáneamente, con la solicitud de residencia del reagrupante</mark></span>El <span class=\"ref-norma\">art. 18.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La reagrupación de los familiares de residentes de larga duración, de los trabajadores titulares de la tarjeta azul de la U.E. y de los beneficiarios del régimen especial de investigadores, podrá solicitarse y concederse, simultáneamente, con la solicitud de residencia del reagrupante\"</span>. Para estos colectivos la reagrupación es simultánea a la solicitud de residencia del reagrupante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1030","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Requisitos para la reagrupación familiar. En la valoración de los ingresos a efectos de la reagrupación:","o":["computarán los provenientes del sistema de asistencia social, pero no se tendrán en cuenta los ingresos aportados por el cónyuge que resida en España y conviva con el reagrupante.","solo computarán los ingresos del reagrupante procedentes de una actividad laboral por cuenta ajena.","no computarán los provenientes del sistema de asistencia social ni tampoco los ingresos aportados por el cónyuge que resida en España, aunque conviva con el reagrupante.","no computarán los provenientes del sistema de asistencia social, pero se tendrán en cuenta otros ingresos aportados por el cónyuge que resida en España y conviva con el reagrupante."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no computarán los provenientes del sistema de asistencia social, pero se tendrán en cuenta otros ingresos aportados por el cónyuge que resida en España y conviva con el reagrupante</mark></span>El <span class=\"ref-norma\">art. 18.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En la valoración de los ingresos a efectos de la reagrupación, no computarán aquellos provenientes del sistema de asistencia social, pero se tendrán en cuenta otros ingresos aportados por el cónyuge que resida en España y conviva con el reagrupante\"</span>. No cuentan los ingresos de asistencia social; sí los del cónyuge residente que conviva con el reagrupante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1518","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Derechos y obligaciones de los solicitantes. El solicitante de asilo, presentada la solicitud, tiene, entre otros, los siguientes derechos: Señale la INCORRECTA.","o":["a ser documentado como solicitante de protección internacional;","a la suspensión de cualquier proceso de devolución, expulsión o extradición que pudiera afectar al solicitante;","a conocer el contenido del expediente en cualquier momento;","a obtener una autorización de residencia y trabajo desde la presentación de la solicitud;"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a obtener una autorización de residencia y trabajo desde la presentación de la solicitud;</mark></span>El <span class=\"ref-norma\">art. 18.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"a) a ser documentado como solicitante de protección internacional\"</span>. La autorización para trabajar se rige por lo que se establezca reglamentariamente; no es un derecho desde la presentación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 16 — Derecho a la intimidad familiar ✱","q":[{"i":"6-20","p":"Ley Orgánica 4/2000. Reagrupación familiar. Indique la proposición más CORRECTA:","o":["Los extranjeros residentes tienen derecho a la vida en familia y a la intimidad familiar en la forma prevista en esta Ley Orgánica.","Los extranjeros en España tienen derecho a reagrupar con ellos a sus familiares.","El cónyuge que hubiera adquirido la residencia en España por causa familiar y sus familiares son el reagrupante conservando la residencia del cónyuge que se ha reagrupado.","Todas las opciones son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los extranjeros residentes tienen derecho a la vida en familia y a la intimidad familiar en la forma prevista en esta Ley Orgánica</mark></span>Según el <span class=\"ref-norma\">art. 16.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes tienen derecho a la vida en familia y a la intimidad familiar en la forma prevista en esta Ley Orgánica\"</span>. El derecho es de los extranjeros RESIDENTES (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1023","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la intimidad familiar. El cónyuge que hubiera adquirido la residencia en España por causa familiar y sus familiares con él agrupados conservarán la residencia aunque se rompa el vínculo matrimonial que dio lugar a la adquisición. En estos supuestos:","o":["deberán acreditar un tiempo previo de convivencia en España de al menos dos años.","la conservación de la residencia exigirá disponer de medios económicos suficientes para cubrir sus propias necesidades.","reglamentariamente se podrá determinar el tiempo previo de convivencia en España que se tenga que acreditar.","la residencia se conservará solo hasta la siguiente renovación de la autorización."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reglamentariamente se podrá determinar el tiempo previo de convivencia en España que se tenga que acreditar</mark></span>El <span class=\"ref-norma\">art. 16.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Reglamentariamente se podrá determinar el tiempo previo de convivencia en España que se tenga que acreditar en estos supuestos\"</span>. La Ley no fija el tiempo de convivencia: lo remite al reglamento («se podrá determinar»). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 36 — Autorización de residencia y trabajo EX ✱","q":[{"i":"6-22","p":"Ley Orgánica 4/2000. Autorización de Residencia y trabajo para la contratación de un extranjero (Señale la correcta).","o":["Para la contratación de un extranjero, el empleador deberá solicitar la autorización administrativa previa para residir y trabajar que en todo caso deberá ir acompañada del contrato de trabajo que garantice una actividad continuada durante el periodo de vigencia de la autorización.","La eficacia de la autorización de residencia y trabajo inicial se condicionará al alta del trabajador en la Seguridad Social.","Cuando el extranjero se propusiera trabajar por cuenta propia o ajena, ejerciendo una profesión para la que se exija una titulación especial, la concesión de la autorización se condicionará a la tenencia y, en su caso, homologación del título correspondiente y, si las leyes así lo exigiesen, a la colegiación.","Todas las anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 36.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La eficacia de la autorización de residencia y trabajo inicial se condicionará al alta del trabajador en la Seguridad Social\"</span>. Se corrige C, que venía alterada («no se exija») (Verificado con el texto del temario oficial.)"},{"i":"6-67","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Efectos de la concesión del derecho de asilo. Señale la opción incorrecta en esta materia:","o":["La protección contra la devolución en los términos establecidos en los tratados internacionales firmados por España.","El acceso a la información sobre los derechos y obligaciones relacionados con el contenido de la protección internacional concedida, en una lengua que le sea comprensible a la persona beneficiaria de dicha protección.","La autorización de residencia y trabajo temporal.","El acceso a los servicios públicos de empleo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La autorización de residencia y trabajo temporal</mark></span>Según el <span class=\"ref-norma\">art. 36.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) la autorización de residencia y trabajo permanente\"</span>. Es permanente, no temporal (Verificado con el texto del temario oficial.)"},{"i":"6-141","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de Residencia y trabajo. Señale la INCORRECTA:","o":["No se concederá autorización para residir y realizar una actividad lucrativa, laboral o profesional, a los extranjeros que, en el marco de un programa de retorno voluntario a su país de origen, se hubieran comprometido a no retornar a España durante un plazo determinado y no hubiese transcurrido dicho plazo.","Salvo en los casos legalmente previstos, el reconocimiento de una prestación modificará la situación administrativa del extranjero.","Salvo en los casos legalmente previstos, el reconocimiento de una prestación no modificará la situación administrativa del extranjero.","La autorización de trabajo se concederá conjuntamente con la de residencia, salvo en los supuestos de penados extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Salvo en los casos legalmente previstos, el reconocimiento de una prestación modificará la situación administrativa del extranjero</mark></span>Según el <span class=\"ref-norma\">art. 36.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Salvo en los casos legalmente previstos, el reconocimiento de una prestación no modificará la situación administrativa del extranjero\"</span>. Se corrige D, que también venía alterada («parados» por penados) (Verificado con el texto del temario oficial.)"},{"i":"6-267","p":"(Ley Orgánica 4/2000) Autorización de residencia y trabajo: señala la CORRECTA.","o":["Los extranjeros mayores de catorce años precisan, para ejercer cualquier actividad lucrativa, laboral o profesional, de la correspondiente autorización administrativa previa para residir y trabajar.","La autorización de trabajo se concederá conjuntamente con la de residencia, salvo en los supuestos de períodos de extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen legalmente.","La eficacia de la autorización de residencia y trabajo inicial se condicionará al alta del trabajador en la Seguridad Social.","Cuando el extranjero se proponga trabajar por cuenta propia o ajena, ejerciendo una profesión para la que se le exija una titulación especial, la concesión de la autorización se condicionará a la colegiación, si las leyes así lo exigieran a la tenencia y, en su caso, homologación del título."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La eficacia de la autorización de residencia y trabajo inicial se condicionará al alta del trabajador en la Seguridad Social</mark></span>Según el <span class=\"ref-norma\">art. 36.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La eficacia de la autorización de residencia y trabajo inicial se condicionará al alta del trabajador en la Seguridad Social\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-277","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de Residencia y trabajo. Señale la INCORRECTA:","o":["No se concederá autorización para residir y realizar una actividad lucrativa, laboral o profesional, a los extranjeros que, en el marco de un programa de retorno voluntario a su país de origen, se hubieran comprometido a no retornar a España durante un plazo determinado y no hubiese transcurrido dicho plazo.","Salvo en los casos legalmente previstos, el reconocimiento de una prestación modificará la situación administrativa del extranjero.","Salvo en los casos legalmente previstos, el reconocimiento de una prestación no modificará la situación administrativa del extranjero.","La autorización de trabajo se concederá conjuntamente con la de residencia, salvo en los supuestos de penados extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Salvo en los casos legalmente previstos, el reconocimiento de una prestación modificará la situación administrativa del extranjero</mark></span>Según el <span class=\"ref-norma\">art. 36.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Salvo en los casos legalmente previstos, el reconocimiento de una prestación no modificará la situación administrativa del extranjero\"</span>. Se corrige D, que también venía alterada («parados» por penados) (Verificado con el texto del temario oficial.)"},{"i":"6-366","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. Para la contratación de un extranjero, el empleador deberá solicitar la autorización, que en todo caso deberá acompañarse del contrato de trabajo que garantice:","o":["Una retribución igual o superior al salario mínimo interprofesional, conforme al procedimiento que reglamentariamente se establezca.","Una actividad continuada durante el periodo de vigencia de la autorización.","Una duración mínima de un año desde la fecha de la solicitud.","La afiliación y el alta en la Seguridad Social desde el primer día."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una actividad continuada durante el periodo de vigencia de la autorización</mark></span>El <span class=\"ref-norma\">art. 36.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"4. Para la contratación de un extranjero, el empleador deberá solicitar la autorización a que se refiere el apartado 1 del presente artículo, que en todo caso deberá acompañarse del contrato de trabajo que garantice una actividad continuada durante el periodo de vigencia de la autorización.\"</span>"},{"i":"6-466","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. Cuando el extranjero se propusiera trabajar por cuenta propia o ajena, ejerciendo una profesión para la que se exija una titulación especial, la concesión de la autorización se condicionará:","o":["a la tenencia y, en su caso, homologación del título correspondiente y, si las leyes así lo exigiesen, a la colegiación.","a la homologación previa del título correspondiente por el Ministerio competente y, en todo caso, a la colegiación del interesado.","a la tenencia del título correspondiente, sin que pueda exigirse su homologación ni la colegiación hasta la primera renovación.","a la tenencia del título correspondiente y a la acreditación de experiencia profesional mínima de un año en el país de origen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la tenencia y, en su caso, homologación del título correspondiente y, si las leyes así lo exigiesen, a la colegiación</mark></span>El <span class=\"ref-norma\">art. 36.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Cuando el extranjero se propusiera trabajar por cuenta propia o ajena, ejerciendo una profesión para la que se exija una titulación especial, la concesión de la autorización se condicionará a la tenencia y, en su caso, homologación del título correspondiente y, si las leyes así lo exigiesen, a la colegiación\"</span> Título (y homologación, en su caso) y colegiación solo si las leyes lo exigen."},{"i":"6-ia-1108","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia temporal. Para la renovación de las autorizaciones de residencia temporal se valorará también el incumplimiento de las obligaciones del extranjero en materia:","o":["laboral y de escolarización de los menores.","tributaria y de seguridad social.","tributaria y de empadronamiento.","de seguridad social y de vivienda."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tributaria y de seguridad social</mark></span>El <span class=\"ref-norma\">art. 31.7.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) El incumplimiento de las obligaciones del extranjero en materia tributaria y de seguridad social\"</span>. La letra b) se refiere a obligaciones tributarias y de seguridad social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1111","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal y trabajo de mujeres extranjeras víctimas de violencia de género o de violencias sexuales. La mujer extranjera víctima podrá solicitar también, a favor de sus hijos que se encuentren en España en el momento de la denuncia, una autorización de residencia y trabajo en caso de que fueran mayores de:","o":["catorce años.","dieciocho años.","dieciséis años.","doce años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dieciséis años</mark></span>El <span class=\"ref-norma\">art. 31 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"o una autorización de residencia y trabajo en caso de que fueran mayores de dieciséis años y se encuentren en España en el momento de la denuncia\"</span>. Para los hijos mayores de dieciséis años la autorización es de residencia y trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1154","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. La carencia de la autorización de residencia y trabajo, sin perjuicio de las responsabilidades del empresario a que dé lugar, no invalidará el contrato de trabajo respecto a los derechos del trabajador extranjero. En todo caso:","o":["el trabajador que carezca de autorización podrá obtener prestaciones por desempleo si hubiera cotizado.","el contrato se considerará nulo a efectos de la Seguridad Social y de las prestaciones.","el reconocimiento de una prestación modificará la situación administrativa del extranjero.","el trabajador que carezca de autorización de residencia y trabajo no podrá obtener prestaciones por desempleo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el trabajador que carezca de autorización de residencia y trabajo no podrá obtener prestaciones por desempleo</mark></span>El <span class=\"ref-norma\">art. 36.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, el trabajador que carezca de autorización de residencia y trabajo no podrá obtener prestaciones por desempleo\"</span>. Sin autorización no hay prestación por desempleo; y el reconocimiento de una prestación no modifica la situación administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1156","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. No se concederá autorización para residir y realizar una actividad lucrativa, laboral o profesional, a los extranjeros que, en el marco de un programa de retorno voluntario a su país de origen, se hubieran comprometido a no retornar a España durante un plazo determinado:","o":["hasta que hubieran transcurrido tres años.","en tanto no hubiera transcurrido dicho plazo.","salvo que reintegren la ayuda recibida.","durante un plazo máximo de cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en tanto no hubiera transcurrido dicho plazo</mark></span>El <span class=\"ref-norma\">art. 36.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se hubieran comprometido a no retornar a España durante un plazo determinado en tanto no hubiera transcurrido dicho plazo\"</span>. La Ley no fija un plazo: es el comprometido en el programa de retorno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1248","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. En determinados supuestos de infracciones laborales (leves, graves y muy graves relativas al trabajo de extranjeros), el procedimiento sancionador se iniciará:","o":["por denuncia de los Cuerpos y Fuerzas de Seguridad.","por acta de la Inspección de Trabajo y Seguridad Social.","de oficio por la Oficina de Extranjeros provincial.","a instancia de la Tesorería General de la Seguridad Social."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por acta de la Inspección de Trabajo y Seguridad Social</mark></span>El <span class=\"ref-norma\">art. 55.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"el procedimiento sancionador se iniciará por acta de la Inspección de Trabajo y Seguridad Social, de acuerdo con lo establecido en el procedimiento sancionador por infracciones del orden social\"</span>. Se inician por acta de la Inspección de Trabajo y Seguridad Social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 bis — La política inmigratoria ✱ R1","q":[{"i":"6-23","p":"Ley Orgánica 4/2000. Los extranjeros tienen derecho a transferir sus ingresos y ahorros obtenidos en España a su país, o a cualquier otro, conforme a los procedimientos establecidos en la legislación española y de conformidad con los acuerdos internacionales aplicables. ¿Quién adoptará las medidas necesarias para facilitar dichas transferencias?","o":["El Delegado provincial.","El Presidente de la Comunidad Autónoma.","El Gobierno.","Todas las opciones son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Gobierno</mark></span>Según el <span class=\"ref-norma\">art. 15.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Gobierno adoptará las medidas necesarias para facilitar dichas transferencias\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-150","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. El Estado garantizará _________ consagrado en la Constitución, atendiendo a las especiales circunstancias de aquellos territorios en los que los flujos migratorios tengan una especial incidencia.","o":["El principio de reciprocidad.","El principio de legalidad.","El principio de solidaridad.","El principio de gratuidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El principio de solidaridad</mark></span>Según el <span class=\"ref-norma\">art. 2 bis.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Estado garantizará el principio de solidaridad, consagrado en la Constitución, atendiendo a las especiales circunstancias de aquellos territorios en los que los flujos migratorios tengan una especial incidencia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-205","p":"Ley Orgánica 4/2000... Llevará a cabo una observación permanente de las magnitudes y características más significativas del fenómeno inmigratorio con objeto de analizar su impacto en la sociedad española y facilitar una información objetiva y contrastada que evite o dificulte la aparición de corrientes xenófobas o racistas:","o":["El Gobierno.","La Conferencia Sectorial de Inmigración.","Las Fuerzas y Cuerpos de Seguridad del Estado.","El Delegado del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Gobierno</mark></span>Según el <span class=\"ref-norma\">art. 67.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Gobierno llevará a cabo una observación permanente de las magnitudes y características más significativas del fenómeno inmigratorio con objeto de analizar su impacto en la sociedad española y facilitar una información objetiva y contrastada que evite o dificulte la aparición de corrientes xenófobas o racistas.\"</span> (verificado con el texto del temario)."},{"i":"6-289","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. El Estado garantizará _________ consagrado en la Constitución, atendiendo a las especiales circunstancias de aquellos territorios en los que los flujos migratorios tengan una especial incidencia.","o":["El principio de reciprocidad.","El principio de legalidad.","El principio de solidaridad.","El principio de gratuidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El principio de solidaridad</mark></span>Según el <span class=\"ref-norma\">art. 2 bis.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Estado garantizará el principio de solidaridad, consagrado en la Constitución, atendiendo a las especiales circunstancias de aquellos territorios en los que los flujos migratorios tengan una especial incidencia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-328","p":"Ley Orgánica 4/2000... Llevará a cabo una observación permanente de las magnitudes y características más significativas del fenómeno inmigratorio con objeto de analizar su impacto en la sociedad española y facilitar una información objetiva y contrastada que evite o dificulte la aparición de corrientes xenófobas o racistas:","o":["El Gobierno.","La Conferencia Sectorial de Inmigración.","Las Fuerzas y Cuerpos de Seguridad del Estado.","El Delegado del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Gobierno</mark></span>Según el <span class=\"ref-norma\">art. 67.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Gobierno llevará a cabo una observación permanente de las magnitudes y características más significativas del fenómeno inmigratorio con objeto de analizar su impacto en la sociedad española y facilitar una información objetiva y contrastada que evite o dificulte la aparición de corrientes xenófobas o racistas.\"</span> (verificado con el texto del temario)."},{"i":"6-410","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. Las Administraciones Públicas basarán el ejercicio de sus competencias vinculadas con la inmigración en determinados principios, entre ellos:","o":["El reconocimiento de iguales derechos políticos para todos los residentes en España.","La efectividad del principio de reciprocidad en el reconocimiento de derechos a los extranjeros, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","La preferencia de los trabajadores nacionales en el acceso al empleo.","La efectividad del principio de no discriminación y el reconocimiento de iguales derechos y obligaciones para todos aquellos que vivan o trabajen legalmente en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La efectividad del principio de no discriminación y el reconocimiento de iguales derechos y obligaciones para todos aquellos que vivan o trabajen legalmente en España</mark></span>El <span class=\"ref-norma\">art. 2 bis.2.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) la efectividad del principio de no discriminación y, consecuentemente, el reconocimiento de iguales derechos y obligaciones para todos aquellos que vivan o trabajen legalmente en España, en los términos previstos en la Ley;\"</span>"},{"i":"6-411","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. Entre los principios de la política inmigratoria se encuentra la promoción del diálogo y la colaboración con los países de origen y tránsito de inmigración, mediante:","o":["Convenios bilaterales dirigidos a facilitar la repatriación de los inmigrantes en situación irregular, en los términos que determine la ley orgánica correspondiente, salvo que el órgano competente acuerde otra cosa de forma motivada.","Acuerdos marco dirigidos a fijar cupos anuales de trabajadores por países de origen.","Acuerdos marco dirigidos a ordenar de manera efectiva los flujos migratorios, así como a fomentar y coordinar las iniciativas de cooperación al desarrollo y codesarrollo.","Tratados internacionales dirigidos a armonizar las legislaciones nacionales de extranjería."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Acuerdos marco dirigidos a ordenar de manera efectiva los flujos migratorios, así como a fomentar y coordinar las iniciativas de cooperación al desarrollo y codesarrollo</mark></span>El <span class=\"ref-norma\">art. 2 bis.2.j) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"j) la promoción del diálogo y la colaboración con los países de origen y tránsito de inmigración, mediante acuerdos marco dirigidos a ordenar de manera efectiva los flujos migratorios, así como a fomentar y coordinar las iniciativas de cooperación al desarrollo y codesarrollo.\"</span>"},{"i":"6-ia-1004","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. Corresponde al Gobierno, de conformidad con lo previsto en la Constitución, la definición, planificación, regulación y desarrollo de la política de inmigración, sin perjuicio de las competencias que puedan ser asumidas por:","o":["las Comunidades Autónomas, exclusivamente en materia de integración.","las Comunidades Autónomas y por las Entidades Locales.","la Unión Europea y por las Comunidades Autónomas.","las Delegaciones del Gobierno y por las Entidades Locales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Comunidades Autónomas y por las Entidades Locales</mark></span>El <span class=\"ref-norma\">art. 2 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Corresponde al Gobierno, de conformidad con lo previsto en el artículo 149.1.2.ª de la Constitución, la definición, planificación, regulación y desarrollo de la política de inmigración, sin perjuicio de las competencias que puedan ser asumidas por las Comunidades Autónomas y por las Entidades Locales\"</span>. La salvedad es a favor de las Comunidades Autónomas y de las Entidades Locales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1005","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. Todas las Administraciones Públicas basarán el ejercicio de sus competencias vinculadas con la inmigración en el respeto a los siguientes principios: Señale la INCORRECTA.","o":["la ordenación de los flujos migratorios laborales, de acuerdo con las necesidades del mercado de trabajo de la Unión Europea;","la integración social de los inmigrantes mediante políticas transversales dirigidas a toda la ciudadanía;","la lucha contra la inmigración irregular y la persecución del tráfico ilícito de personas;","la efectividad del principio de no discriminación y, consecuentemente, el reconocimiento de iguales derechos y obligaciones para todos aquellos que vivan o trabajen legalmente en España;"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la ordenación de los flujos migratorios laborales, de acuerdo con las necesidades del mercado de trabajo de la Unión Europea;</mark></span>El <span class=\"ref-norma\">art. 2 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) la ordenación de los flujos migratorios laborales, de acuerdo con las necesidades de la situación nacional del empleo\"</span>. La ordenación de los flujos laborales se hace de acuerdo con las necesidades de la situación NACIONAL del empleo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1006","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La política inmigratoria. Entre los principios de la política inmigratoria figura la promoción del diálogo y la colaboración con los países de origen y tránsito de inmigración, mediante __________ dirigidos a ordenar de manera efectiva los flujos migratorios, así como a fomentar y coordinar las iniciativas de cooperación al desarrollo y codesarrollo.","o":["convenios bilaterales de readmisión","planes plurianuales de cooperación","tratados internacionales de colaboración","acuerdos marco"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">acuerdos marco</mark></span>El <span class=\"ref-norma\">art. 2 bis.2.j) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"j) la promoción del diálogo y la colaboración con los países de origen y tránsito de inmigración, mediante acuerdos marco dirigidos a ordenar de manera efectiva los flujos migratorios\"</span>. La Ley habla de «acuerdos marco»; los acuerdos de readmisión aparecen en otra disposición. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 — El derecho de asilo ✱","q":[{"i":"6-27","p":"Ley 12/2009. ¿Cómo se conoce a la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado?","o":["Condición de refugiado.","Protección subsidiaria.","Protección internacional.","Derecho de Asilo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Derecho de Asilo</mark></span>La condición de refugiado es el REQUISITO; la PROTECCIÓN que se dispensa es el derecho de asilo. Según el <span class=\"ref-norma\">art. 2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El derecho de asilo es la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado en los términos definidos en el artículo 3 de esta Ley...\"</span> (verificado con el texto del temario)."}]},{"a":"Artículo 58 — Efectos de la expulsión y devolución ✱","q":[{"i":"6-28","p":"Ley Orgánica 4/2000. Régimen sancionador. La expulsión llevará consigo la prohibición de entrada en territorio español. La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá, de manera general, de:","o":["Cinco años.","Diez años.","Tres años.","Seis años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-133","p":"(Ley Orgánica 4/2000) ¿Cuál es la duración de la prohibición de entrada en territorio español tras una expulsión?","o":["Dos años.","Tres años.","Cuatro años.","Cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-242","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. La prohibición de entrada en territorio español que conlleva la expulsión tendrá una duración cuya vigencia, con carácter general, no excederá de:","o":["Tres años.","Cinco años.","Siete años.","Diez años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-243","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Efectos de la expulsión y devolución. Señale la CORRECTA:","o":["La expulsión llevará consigo la prohibición de entrada en territorio español... y su vigencia no excederá de siete años.","Excepcionalmente, cuando el extranjero suponga una amenaza grave... podrá imponerse un período de prohibición de entrada de hasta doce años.","Cuando la devolución no se pudiere ejecutar en el plazo de 48 horas, se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión.","La devolución será acordada por la autoridad gubernativa competente para la expulsión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La devolución será acordada por la autoridad gubernativa competente para la expulsión</mark></span>Según el <span class=\"ref-norma\">art. 58.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La devolución será acordada por la autoridad gubernativa competente para la expulsión\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-246","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión, cuando la devolución no se pudiera ejecutar en el plazo de:","o":["24 horas.","96 horas.","48 horas.","72 horas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">72 horas</mark></span>Según el <span class=\"ref-norma\">art. 58.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas, se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-260","p":"(Ley Orgánica 4/2000) La prohibición de entrada en territorio español que conlleva la expulsión, por regla general, no excederá de:","o":["Un año.","Tres años.","Cinco años.","Diez años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-396","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. La expulsión llevará consigo la prohibición de entrada en territorio español. La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de:","o":["Tres años.","Diez años.","Siete años, salvo que el órgano competente acuerde otra cosa de forma motivada.","Cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 58.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. La expulsión llevará consigo la prohibición de entrada en territorio español. La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años.\"</span>"},{"i":"6-397","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. No será preciso expediente de expulsión para la devolución de los extranjeros en los siguientes supuestos:","o":["Los que hayan sido sancionados por una infracción grave y los que pretendan entrar ilegalmente en el país, conforme al procedimiento que reglamentariamente se establezca.","Los que carezcan de autorización de residencia y los que contravengan la prohibición de entrada.","Los que habiendo sido expulsados contravengan la prohibición de entrada en España y los que pretendan entrar ilegalmente en el país.","Los que habiendo sido expulsados regresen a España y los que presenten documentación falsa en frontera."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los que habiendo sido expulsados contravengan la prohibición de entrada en España y los que pretendan entrar ilegalmente en el país</mark></span>El <span class=\"ref-norma\">art. 58.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. No será preciso expediente de expulsión para la devolución de los extranjeros en los siguientes supuestos: a) Los que habiendo sido expulsados contravengan la prohibición de entrada en España. b) Los que pretendan entrar ilegalmente en el país.\"</span>"},{"i":"6-398","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas, se solicitará de la autoridad judicial:","o":["La prórroga de la detención cautelar por otras 72 horas.","La medida de internamiento prevista para los expedientes de expulsión.","La medida de presentación periódica ante las autoridades competentes, sin perjuicio de lo que establezcan los tratados internacionales.","La medida de residencia obligatoria en determinado lugar."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La medida de internamiento prevista para los expedientes de expulsión</mark></span>El <span class=\"ref-norma\">art. 58.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"6. Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas, se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión.\"</span>"},{"i":"6-ia-1308","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. En el supuesto de que se formalice una solicitud de protección internacional por personas que se encuentren en alguno de los supuestos de devolución:","o":["podrá llevarse a cabo la devolución si la solicitud se formaliza fuera del puesto fronterizo habilitado.","no podrá llevarse a cabo la devolución hasta que se haya decidido la inadmisión a trámite de la petición.","no podrá llevarse a cabo la devolución hasta que se haya resuelto definitivamente sobre la concesión.","se suspenderá la devolución durante un plazo máximo de setenta y dos horas para examinar la solicitud."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no podrá llevarse a cabo la devolución hasta que se haya decidido la inadmisión a trámite de la petición</mark></span>El <span class=\"ref-norma\">art. 58.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"no podrá llevarse a cabo la devolución hasta que se haya decidido la inadmisión a trámite de la petición, de conformidad con la normativa de protección internacional\"</span>. La devolución espera a que se decida la inadmisión a trámite. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1309","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. Toda devolución acordada respecto de los que pretendan entrar ilegalmente en el país llevará consigo la prohibición de entrada en territorio español por un plazo máximo de:","o":["tres años.","cinco años.","dos años.","diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tres años</mark></span>El <span class=\"ref-norma\">art. 58.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"toda devolución acordada en aplicación del párrafo b) del mismo apartado de este artículo llevará consigo la prohibición de entrada en territorio español por un plazo máximo de tres años\"</span>. Devolución por entrada ilegal: prohibición de entrada de hasta tres años (expulsión: hasta cinco, excepcionalmente diez). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1310","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. La devolución acordada respecto de los que, habiendo sido expulsados, contravengan la prohibición de entrada en España:","o":["conllevará una nueva prohibición de entrada de diez años, con independencia de la acordada en la resolución de expulsión quebrantada.","conllevará la suspensión del cómputo del plazo de prohibición de entrada hasta que se ejecute efectivamente la devolución acordada.","no conllevará efecto alguno sobre la prohibición de entrada, que continuará computándose desde la resolución de expulsión.","conllevará la reiniciación del cómputo del plazo de prohibición de entrada que hubiese acordado la resolución de expulsión quebrantada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">conllevará la reiniciación del cómputo del plazo de prohibición de entrada que hubiese acordado la resolución de expulsión quebrantada</mark></span>El <span class=\"ref-norma\">art. 58.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La devolución acordada en el párrafo a) del apartado 3 de este artículo conllevará la reiniciación del cómputo del plazo de prohibición de entrada que hubiese acordado la resolución de expulsión quebrantada\"</span>. Se reinicia el cómputo del plazo de prohibición de entrada de la expulsión quebrantada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41 — Excepciones a la autorización de trabajo EXOF ✱","q":[{"i":"6-30","p":"Ley Orgánica 4/2000. No será necesaria la obtención de autorización de trabajo para el ejercicio de las actividades siguientes: Señale la INCORRECTA.","o":["Los artistas de reconocido prestigio.","Los profesores extranjeros invitados o contratados por una universidad española.","Los corresponsales de medios de comunicación social extranjeros, debidamente acreditados, para el ejercicio de la actividad informativa.","Los miembros de misiones científicas internacionales que realicen trabajos o investigaciones en España, autorizados por el Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los artistas de reconocido prestigio</mark></span>Según el <span class=\"ref-norma\">art. 41.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"g) Los artistas que vengan a España a realizar actuaciones concretas que no supongan una actividad continuada\"</span>. Los «artistas de reconocido prestigio» son un supuesto de exención de la situación nacional de empleo, no de excepción a la autorización de trabajo (Verificado con el texto del temario oficial.)"},{"i":"6-61","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para el ejercicio de alguna de las actividades siguientes:","o":["Los profesores e investigadores invitados o contratados por una empresa privada española.","Los artistas que vengan a España a realizar actuaciones concretas que no supongan una actividad continuada.","Los extranjeros que formen parte de los órganos de representación, gobierno y administración de las asociaciones homologadas internacionalmente, siempre que limiten su actividad a funciones propias de la asociación.","Los ministros, religiosos o representantes de las diferentes iglesias y confesiones, aunque no estén inscritas en el Registro de Entidades Religiosas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los artistas que vengan a España a realizar actuaciones concretas que no supongan una actividad continuada</mark></span>Según el <span class=\"ref-norma\">art. 41.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"g) Los artistas que vengan a España a realizar actuaciones concretas que no supongan una actividad continuada\"</span>. La opción correcta decía «que supongan» (es «que NO supongan»); se reescriben A y D, que también eran correctas (Verificado con el texto del temario oficial.)"},{"i":"6-372","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para el ejercicio de determinadas actividades, como la de:","o":["Los trabajadores de temporada contratados por empresas agrícolas.","Los extranjeros contratados por cuenta ajena en el sector turístico.","Los empleados del hogar contratados por familias residentes en España, en los términos que determine la ley orgánica correspondiente.","Los profesores extranjeros invitados o contratados por una universidad española."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los profesores extranjeros invitados o contratados por una universidad española</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Los profesores extranjeros invitados o contratados por una universidad española.\"</span>"},{"i":"6-373","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para el ejercicio de la actividad informativa de:","o":["Los periodistas freelance extranjeros que colaboren habitualmente con medios españoles, salvo que el órgano competente acuerde otra cosa de forma motivada.","Los corresponsales de medios extranjeros, con independencia de su acreditación.","Los corresponsales de medios de comunicación social extranjeros, debidamente acreditados.","Los colaboradores de agencias de prensa nacionales con residencia temporal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los corresponsales de medios de comunicación social extranjeros, debidamente acreditados</mark></span>El <span class=\"ref-norma\">art. 41.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Los corresponsales de medios de comunicación social extranjeros, debidamente acreditados, para el ejercicio de la actividad informativa.\"</span>"},{"i":"6-374","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los miembros de misiones científicas internacionales que realicen trabajos e investigaciones en España:","o":["Autorizados por las Comunidades Autónomas.","Autorizados por el Estado.","Financiados con fondos públicos europeos.","Con una duración inferior a tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Autorizados por el Estado</mark></span>El <span class=\"ref-norma\">art. 41.1.f) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"f) Los miembros de misiones científicas internacionales que realicen trabajos e investigaciones en España, autorizados por el Estado.\"</span>"},{"i":"6-375","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los artistas que vengan a España a realizar:","o":["Actuaciones concretas que no supongan una actividad continuada.","Actuaciones en espectáculos públicos durante un máximo de un año.","Actuaciones concretas, aunque supongan una actividad continuada.","Giras de duración superior a tres meses con contrato de trabajo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Actuaciones concretas que no supongan una actividad continuada</mark></span>El <span class=\"ref-norma\">art. 41.1.g) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"g) Los artistas que vengan a España a realizar actuaciones concretas que no supongan una actividad continuada.\"</span>"},{"i":"6-376","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los ministros, religiosos o representantes de las diferentes iglesias y confesiones, debidamente inscritas en el Registro de Entidades Religiosas:","o":["Siempre que su estancia no supere los seis meses en España.","En tanto limiten su actividad a funciones religiosas y de asistencia social.","Siempre que sean enviados por una confesión con acuerdos de cooperación.","En tanto limiten su actividad a funciones estrictamente religiosas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En tanto limiten su actividad a funciones estrictamente religiosas</mark></span>El <span class=\"ref-norma\">art. 41.1.h) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"h) Los ministros, religiosos o representantes de las diferentes iglesias y confesiones, debidamente inscritas en el Registro de Entidades Religiosas, en tanto limiten su actividad a funciones estrictamente religiosas.\"</span>"},{"i":"6-377","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los extranjeros que formen parte de los órganos de representación, gobierno y administración de los sindicatos homologados internacionalmente, siempre que:","o":["Limiten su actividad a funciones sindicales y de formación profesional.","Tengan residencia legal en España durante al menos un año.","Limiten su actividad a funciones estrictamente sindicales.","Representen a sindicatos con implantación en la Unión Europea."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Limiten su actividad a funciones estrictamente sindicales</mark></span>El <span class=\"ref-norma\">art. 41.1.i) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"i) Los extranjeros que formen parte de los órganos de representación, gobierno y administración de los sindicatos homologados internacionalmente, siempre que limiten su actividad a funciones estrictamente sindicales.\"</span>"},{"i":"6-378","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los menores extranjeros en edad laboral tutelados por la entidad de protección de menores competente, para aquellas actividades que, a propuesta de la mencionada entidad:","o":["Mientras permanezcan en esa situación, faciliten su formación profesional.","Mientras permanezcan en esa situación, favorezcan su integración social.","Hasta que cumplan la mayoría de edad, favorezcan su autonomía económica.","Una vez obtenida la autorización de residencia, favorezcan su arraigo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mientras permanezcan en esa situación, favorezcan su integración social</mark></span>El <span class=\"ref-norma\">art. 41.1.j) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"j) Los menores extranjeros en edad laboral tutelados por la entidad de protección de menores competente, para aquellas actividades que, a propuesta de la mencionada entidad, mientras permanezcan en esa situación, favorezcan su integración social.\"</span>"},{"i":"6-459","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para el ejercicio de las actividades siguientes, entre otras:","o":["Los ministros, religiosos o representantes de las diferentes iglesias y confesiones inscritas, en tanto limiten su actividad a funciones estrictamente religiosas.","Los trabajadores de temporada que presten servicios durante un máximo de tres meses.","Los trabajadores transfronterizos que residan en un Estado limítrofe de España.","Los empleados del servicio doméstico contratados por embajadas acreditadas en España, en los términos que determine la ley orgánica correspondiente, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los ministros, religiosos o representantes de las diferentes iglesias y confesiones inscritas, en tanto limiten su actividad a funciones estrictamente religiosas</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. No será necesaria la obtención de autorización de trabajo para el ejercicio de las actividades siguientes:\"</span>"},{"i":"6-ia-1215","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para el personal directivo y el profesorado extranjeros, de instituciones culturales y docentes dependientes de otros Estados, o privadas, de acreditado prestigio, oficialmente reconocidas por España, que desarrollen en nuestro país programas culturales y docentes de sus países respectivos:","o":["durante un período máximo de un año prorrogable por otro.","siempre que sean nacionales del Estado del que dependa la institución.","en tanto limiten su actividad a la ejecución de tales programas.","en tanto mantengan su residencia habitual en el país de origen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en tanto limiten su actividad a la ejecución de tales programas</mark></span>El <span class=\"ref-norma\">art. 41.1.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"que desarrollen en nuestro país programas culturales y docentes de sus países respectivos, en tanto limiten su actividad a la ejecución de tales programas\"</span>. La excepción se condiciona a limitar su actividad a la ejecución de tales programas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 56 — Prescripción de las infracciones y de las sanciones ✱","q":[{"i":"6-37","p":"Ley Orgánica 4/2000. Prescripción de las infracciones. Indique la CORRECTA:","o":["Muy graves a los 3 años, graves a los 2 años y leves a los 6 meses.","Muy graves a los 5 años, graves a los 3 años y leves a los 6 meses.","Muy graves a los 4 años, graves a los 3 años y leves a los 9 meses.","Muy graves a los 5 años, graves a los 2 años y leves al año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Muy graves a los 3 años, graves a los 2 años y leves a los 6 meses</mark></span>Se corrige la opción A (decía «leves al año»). La D recoge los plazos de prescripción de las SANCIONES (art. 56.2: 5 años / 2 años / 1 año), no de las infracciones. Según el <span class=\"ref-norma\">art. 56.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses.\"</span> (verificado con el texto del temario)."},{"i":"6-59","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Prescripción de las infracciones y de las sanciones: Las infracciones prescribirán:","o":["Las muy graves a los 5 años, las graves a los 3 años y las leves al año.","Las muy graves a los 3 años, las graves a los 2 años y las leves a los 6 meses.","Las muy graves a los 3 años, las graves a los 2 años y las leves al año.","Las muy graves a los 5 años, las graves a los 2 años y las leves al año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las muy graves a los 3 años, las graves a los 2 años y las leves a los 6 meses</mark></span>Según el <span class=\"ref-norma\">art. 56.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-109","p":"(Ley Orgánica 4/2000) De las Infracciones en materia de extranjería y su régimen sancionador. Las sanciones impuestas por infracciones muy graves prescribirán:","o":["A los cinco años.","A los tres años.","A los dos años.","Al año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los cinco años</mark></span>Según el <span class=\"ref-norma\">art. 56.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años, las graves a los dos años y las impuestas por infracciones leves al año\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-115","p":"(Ley Orgánica 4/2000) De las infracciones en materia de extranjería y su régimen sancionador. Señale la CORRECTA sobre la prescripción de las infracciones.","o":["Las infracciones muy graves prescribirán a los cuatro años.","Las infracciones graves prescribirán a los tres años.","Las infracciones leves prescribirán a los seis meses.","Las infracciones muy graves prescribirán a los dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las infracciones leves prescribirán a los seis meses</mark></span>Según el <span class=\"ref-norma\">art. 56.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-193","p":"Ley Orgánica 4/2000... Prescripción de las infracciones y de las sanciones. Si la sanción impuesta fuera la de expulsión del territorio nacional, la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución, con un máximo de:","o":["Cinco años.","Quince años.","Diez años.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Diez años</mark></span>Según el <span class=\"ref-norma\">art. 56.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Si la sanción impuesta fuera la de expulsión del territorio nacional la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución con un máximo de diez años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-202","p":"Ley Orgánica 4/2000... Las infracciones leves prescribirán a los:","o":["Cinco meses.","Seis meses.","Dos años.","Tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 56.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-204","p":"Ley Orgánica 4/2000... Las sanciones impuestas por infracciones muy graves prescribirán a los:","o":["Diez años.","Cinco años.","Dos años.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 56.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años, las graves a los dos años y las impuestas por infracciones leves al año\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-319","p":"Ley Orgánica 4/2000... Prescripción de las infracciones y de las sanciones. Si la sanción impuesta fuera la de expulsión del territorio nacional, la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución, con un máximo de:","o":["Cinco años.","Quince años.","Diez años.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Diez años</mark></span>Según el <span class=\"ref-norma\">art. 56.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Si la sanción impuesta fuera la de expulsión del territorio nacional la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución con un máximo de diez años\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-325","p":"Ley Orgánica 4/2000... Las infracciones leves prescribirán a los:","o":["Cinco meses.","Seis meses.","Dos años.","Tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 56.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-327","p":"Ley Orgánica 4/2000... Las sanciones impuestas por infracciones muy graves prescribirán a los:","o":["Diez años.","Cinco años.","Dos años.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco años</mark></span>Según el <span class=\"ref-norma\">art. 56.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años, las graves a los dos años y las impuestas por infracciones leves al año\"</span>. (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 27 — Expedición del visado ✱ R6","q":[{"i":"6-39","p":"Ley Orgánica 4/2000. La autoridad competente para resolver inadmitirá a trámite las solicitudes relativas a los procedimientos regulados en esta ley, en los siguientes supuestos: Señale la incorrecta.","o":["Falta de legitimación del solicitante, o insuficiente acreditación de la representación.","Presentación de la solicitud fuera del plazo legalmente establecido.","Cuando se trate de una reiteración de una solicitud ya denegada, siempre que las circunstancias que motivaron la denegación no hayan variado.","Cuando el solicitante tenga prohibida su entrada en Europa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando el solicitante tenga prohibida su entrada en Europa</mark></span>Según el <span class=\"ref-norma\">disposición adicional cuarta de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Cuando el solicitante tenga prohibida su entrada en España\"</span>. La causa de inadmisión es tener prohibida la entrada en España, no en Europa (Verificado con el texto del temario oficial.)"},{"i":"6-95","p":"¿Cuál de las siguientes es una causa de denegación del visado de estancia o de residencia?","o":["Que el solicitante no haya sido debidamente identificado.","Que no se cumpla con los requisitos documentales.","Que exista prohibición de entrada en España.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 33 · Entrada y Permanencia de Extranjeros en España</span>. El Artículo 33 de la Ley Orgánica 4/2000 (causas de denegación del visado) incluye, entre otras, que el solicitante figure como inidentificable (a), que no se acrediten los requisitos (b) o que exista una prohibición de entrada (c)."},{"i":"6-143","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. El visado se solicitará y expedirá _________ salvo en los supuestos excepcionales que se contemplen reglamentariamente y en los supuestos en los que el Estado español, de acuerdo con la normativa comunitaria sobre la materia, haya acordado su representación con otro Estado miembro de la Unión Europea en materia de visados de tránsito o estancia.","o":["En el mismo acto de la solicitud.","En cumplimiento del Convenio de aplicación del Acuerdo de Schengen.","En las Misiones Diplomáticas y Oficinas Consulares de España.","En dependencias del Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En las Misiones Diplomáticas y Oficinas Consulares de España</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El visado se solicitará y expedirá en las Misiones Diplomáticas y Oficinas Consulares de España, salvo en los supuestos excepcionales que se contemplen reglamentariamente o en los supuestos en los que el Estado español, de acuerdo con la normativa comunitaria sobre la materia, haya acordado su representación con otro Estado miembro de la Unión Europea en materia de visados de tránsito o estancia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-148","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. Señale la INCORRECTA:","o":["El ejercicio de la potestad de otorgamiento o denegación de visados se sujetará a los compromisos internacionales vigentes en la materia y se orientará al cumplimiento de los fines de la política exterior del Reino de España y de otras políticas públicas españolas o de la Unión Europea, como la política de inmigración, la política económica y la de seguridad ciudadana8.","El visado se solicitará y expedirá en las Misiones Diplomáticas y Oficinas Consulares de España, salvo en los supuestos excepcionales que se contemplen reglamentariamente o en los supuestos en los que el Estado español, de acuerdo con la normativa comunitaria sobre la materia, haya acordado su representación con otro Estado miembro de la Unión Europea en materia de visados de tránsito o estancia.","La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios.","Para supuestos excepcionales podrán fijarse por vía reglamentaria otros criterios a los que haya de someterse el otorgamiento y denegación de visados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios</mark></span>Según el <span class=\"ref-norma\">art. 27.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia o de tránsito\"</span>. Se corrige B, que también venía alterada («cedido») (Verificado con el texto del temario oficial.)"},{"i":"6-156","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. Señale la INCORRECTA:","o":["El ejercicio de la potestad de otorgamiento o denegación de visados se sujetará a los compromisos internacionales vigentes en la materia y se orientará al cumplimiento de los fines de la política exterior del Reino de España y de otras políticas públicas españolas o de la Unión Europea, como la política de inmigración, la política económica y la de seguridad ciudadana5.","El visado se solicitará y expedirá en las Misiones Diplomáticas y Oficinas Consulares de España, salvo en los supuestos excepcionales que se contemplen reglamentariamente o en los supuestos en los que el Estado español, de acuerdo con la normativa comunitaria sobre la materia, haya acordado su representación con otro Estado miembro de la Unión Europea en materia de visados de tránsito o estancia.","La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios.","Para supuestos excepcionales podrán fijarse por vía reglamentaria otros criterios a los que haya de someterse el otorgamiento y denegación de visados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios</mark></span>Según el <span class=\"ref-norma\">art. 27.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia o de tránsito\"</span>. Se corrige B, que también venía alterada («cedido») (Verificado con el texto del temario oficial.)"},{"i":"6-199","p":"Ley Orgánica 4/2000... ¿Cómo se determinarán las condiciones y requisitos para hacer posible la participación de trabajadores extranjeros en sociedades anónimas laborales y sociedades cooperativas?","o":["Mediante ley.","Mediante real decreto.","Mediante orden ministerial.","Reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span>Según el <span class=\"ref-norma\">art. 36.8 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Reglamentariamente se determinarán las condiciones y requisitos para hacer posible la participación de trabajadores extranjeros en sociedades anónimas laborales y sociedades cooperativas\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-206","p":"Ley Orgánica 4/2000... La concesión del visado:","o":["Habilitará al extranjero para presentarse en un puesto fronterizo español y solicitar su salida.","Habilitará al extranjero, una vez se haya efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido, sin perjuicio de la obligatoriedad de obtener, en su caso, la tarjeta de identidad de extranjero.","A y B son correctas.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Habilitará al extranjero, una vez se haya efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido, sin perjuicio de la obligatoriedad de obtener, en su caso, la tarjeta de identidad de extranjero</mark></span>Según el <span class=\"ref-norma\">art. 27.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Habilitará al extranjero, una vez se ha efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido\"</span>. La A habla de solicitar la «salida»; es la entrada (Verificado con el texto del temario oficial.)"},{"i":"6-236","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Expedición del visado. La denegación de visado deberá ser motivada cuando se trate:","o":["de visados de residencia para reagrupación familiar.","de visados para el trabajo por cuenta ajena.","en el caso de visados de estancia o de tránsito.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 27.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia o de tránsito\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-284","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. Señale la INCORRECTA:","o":["El ejercicio de la potestad de otorgamiento o denegación de visados se sujetará a los compromisos internacionales vigentes en la materia y se orientará al cumplimiento de los fines de la política exterior del Reino de España y de otras políticas públicas españolas o de la Unión Europea, como la política de inmigración, la política económica y la de seguridad ciudadana5.","El visado se solicitará y expedirá en las Misiones Diplomáticas y Oficinas Consulares de España, salvo en los supuestos excepcionales que se contemplen reglamentariamente o en los supuestos en los que el Estado español, de acuerdo con la normativa comunitaria sobre la materia, haya acordado su representación con otro Estado miembro de la Unión Europea en materia de visados de tránsito o estancia.","La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios.","Para supuestos excepcionales podrán fijarse por vía reglamentaria otros criterios a los que haya de someterse el otorgamiento y denegación de visados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia, de residencia o de estudios</mark></span>Según el <span class=\"ref-norma\">art. 27.6 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La denegación de visado deberá ser motivada cuando se trate de visados de residencia para reagrupación familiar o para el trabajo por cuenta ajena, así como en el caso de visados de estancia o de tránsito\"</span>. Se corrige B, que también venía alterada («cedido») (Verificado con el texto del temario oficial.)"},{"i":"6-322","p":"Ley Orgánica 4/2000... ¿Cómo se determinarán las condiciones y requisitos para hacer posible la participación de trabajadores extranjeros en sociedades anónimas laborales y sociedades cooperativas?","o":["Mediante ley.","Mediante real decreto.","Mediante orden ministerial.","Reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span>Según el <span class=\"ref-norma\">art. 36.8 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Reglamentariamente se determinarán las condiciones y requisitos para hacer posible la participación de trabajadores extranjeros en sociedades anónimas laborales y sociedades cooperativas\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-329","p":"Ley Orgánica 4/2000... La concesión del visado:","o":["Habilitará al extranjero para presentarse en un puesto fronterizo español y solicitar su salida.","Habilitará al extranjero, una vez se haya efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido, sin perjuicio de la obligatoriedad de obtener, en su caso, la tarjeta de identidad de extranjero.","A y B son correctas.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Habilitará al extranjero, una vez se haya efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido, sin perjuicio de la obligatoriedad de obtener, en su caso, la tarjeta de identidad de extranjero</mark></span>Según el <span class=\"ref-norma\">art. 27.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Habilitará al extranjero, una vez se ha efectuado la entrada en territorio español, a permanecer en España en la situación para la que hubiese sido expedido\"</span>. La A habla de solicitar la «salida»; es la entrada (Verificado con el texto del temario oficial.)"},{"i":"6-352","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. La concesión del visado:","o":["Habilitará al extranjero para presentarse en un puesto fronterizo español y solicitar su entrada.","Garantiza al extranjero la entrada en territorio español en todo caso.","Habilitará al extranjero para residir en España durante el plazo de vigencia del visado, conforme al procedimiento que reglamentariamente se establezca.","Exime al extranjero de la obligación de obtener la tarjeta de identidad de extranjero."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Habilitará al extranjero para presentarse en un puesto fronterizo español y solicitar su entrada</mark></span>El <span class=\"ref-norma\">art. 27.2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Habilitará al extranjero para presentarse en un puesto fronterizo español y solicitar su entrada.\"</span>"},{"i":"6-412","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. Los visados serán de una de las clases siguientes, entre otras:","o":["Visado de tránsito, de turismo, de residencia, de residencia y trabajo y de reagrupación, conforme al procedimiento que reglamentariamente se establezca.","Visado de tránsito, de estancia, de residencia, de residencia y trabajo de temporada y de estudios.","Visado de estancia, de residencia, de residencia y trabajo de temporada y de refugio.","Visado de tránsito, de estancia, de trabajo por cuenta propia y de estudios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Visado de tránsito, de estancia, de residencia, de residencia y trabajo de temporada y de estudios</mark></span>El <span class=\"ref-norma\">art. 25 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Los visados a que se refiere el apartado anterior serán de una de las clases siguientes: a) Visado de tránsito, que habilita a transitar por la zona de tránsito internacional de un aeropuerto español o a atravesar el territorio español.\"</span>"},{"i":"6-ia-1011","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la documentación. Cuando se haya concedido a un extranjero una autorización para permanecer en España por un periodo no superior a seis meses, en relación con la tarjeta de identidad de extranjero:","o":["no podrá obtenerse la tarjeta en ningún caso mientras dure la autorización.","deberá solicitarse la tarjeta en el plazo de un mes desde la concesión.","reglamentariamente se desarrollarán los supuestos en que se podrá obtener dicha tarjeta.","la tarjeta se expedirá de oficio por la Oficina de Extranjeros de la provincia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reglamentariamente se desarrollarán los supuestos en que se podrá obtener dicha tarjeta</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Reglamentariamente se desarrollarán los supuestos en que se podrá obtener dicha tarjeta de identidad cuando se haya concedido una autorización para permanecer en España por un periodo no superior a seis meses\"</span>. La obligación de solicitar la tarjeta en un mes es para autorizaciones superiores a seis meses; para las de hasta seis meses se remite al reglamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1014","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Participación pública. Los extranjeros residentes, empadronados en un municipio, tienen todos los derechos establecidos por tal concepto en la legislación de bases de régimen local:","o":["pudiendo participar en las votaciones municipales en igualdad de condiciones que los españoles.","debiendo ser oídos preceptivamente en los asuntos que afecten a su situación administrativa.","pudiendo ser oídos únicamente cuando sean residentes de larga duración y lo solicite el Ayuntamiento.","pudiendo ser oídos en los asuntos que les afecten de acuerdo con lo que disponga la normativa de aplicación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">pudiendo ser oídos en los asuntos que les afecten de acuerdo con lo que disponga la normativa de aplicación</mark></span>El <span class=\"ref-norma\">art. 6.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros residentes, empadronados en un municipio, tienen todos los derechos establecidos por tal concepto en la legislación de bases de régimen local, pudiendo ser oídos en los asuntos que les afecten de acuerdo con lo que disponga la normativa de aplicación\"</span>. «Pudiendo» ser oídos, no «debiendo»; y sin exigir residencia de larga duración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1033","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la reagrupación familiar en circunstancias especiales. La forma y la cuantía de los medios económicos considerados suficientes para que los familiares reagrupados puedan obtener una autorización independiente:","o":["se determinarán reglamentariamente.","se fijarán anualmente por orden ministerial.","serán las que establezca cada Comunidad Autónoma.","equivaldrán al salario mínimo interprofesional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se determinarán reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 19.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Reglamentariamente se determinará la forma y la cuantía de los medios económicos considerados suficientes para que los familiares reagrupados puedan obtener una autorización independiente\"</span>. La Ley remite al reglamento la forma y la cuantía. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1037","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la asistencia jurídica gratuita. Cuando el extranjero tuviera derecho a la asistencia jurídica gratuita y se encontrase fuera de España, la solicitud de la misma y, en su caso, la manifestación de la voluntad de recurrir, podrán realizarse ante:","o":["la misión diplomática u oficina consular correspondiente.","el Colegio de Abogados del lugar de la última residencia.","la Delegación del Gobierno que dictó la resolución.","el órgano judicial competente por vía telemática."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la misión diplomática u oficina consular correspondiente</mark></span>El <span class=\"ref-norma\">art. 22.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"cuando el extranjero tuviera derecho a la asistencia jurídica gratuita y se encontrase fuera de España, la solicitud de la misma y, en su caso, la manifestación de la voluntad de recurrir, podrán realizarse ante la misión diplomática u oficina consular correspondiente\"</span>. Desde el extranjero se hace ante la misión diplomática u oficina consular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1045","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Tipos de visado. El visado de tránsito habilita a transitar por la zona de tránsito internacional de un aeropuerto español o a atravesar el territorio español. No será exigible la obtención de dicho visado en casos de tránsito de un extranjero a efectos de repatriación o alejamiento por vía aérea solicitado por:","o":["un Estado miembro de la Unión Europea o por un tercer estado que tenga suscrito con España un acuerdo internacional sobre esta materia.","un Estado miembro de la Unión Europea o por el Alto Comisionado de las Naciones Unidas para los Refugiados.","cualquier Estado parte en el Convenio de aplicación del Acuerdo de Schengen, sin necesidad de acuerdo internacional específico con España.","el país de origen del extranjero, previa comunicación al Ministerio de Asuntos Exteriores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un Estado miembro de la Unión Europea o por un tercer estado que tenga suscrito con España un acuerdo internacional sobre esta materia</mark></span>El <span class=\"ref-norma\">art. 25 bis.2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"No será exigible la obtención de dicho visado en casos de tránsito de un extranjero a efectos de repatriación o alejamiento por vía aérea solicitado por un Estado miembro de la Unión Europea o por un tercer estado que tenga suscrito con España un acuerdo internacional sobre esta materia\"</span>. La exención se da si lo solicita un Estado miembro de la UE o un tercer Estado con acuerdo con España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1050","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. El ejercicio de la potestad de otorgamiento o denegación de visados se sujetará a los compromisos internacionales vigentes en la materia y se orientará al cumplimiento de los fines de la política exterior del Reino de España y de otras políticas públicas españolas o de la Unión Europea, como:","o":["la política de cooperación al desarrollo, la política comercial y la de defensa.","la política de inmigración, la política de empleo y la de vivienda.","la política económica, la política de asilo y la de seguridad nacional.","la política de inmigración, la política económica y la de seguridad ciudadana."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la política de inmigración, la política económica y la de seguridad ciudadana</mark></span>El <span class=\"ref-norma\">art. 27.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"como la política de inmigración, la política económica y la de seguridad ciudadana\"</span>. Se citan la política de inmigración, la económica y la de seguridad ciudadana. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1105","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia temporal. La Administración podrá conceder una autorización de residencia temporal por situación de arraigo, así como por razones humanitarias, de colaboración con la Justicia u otras circunstancias excepcionales que se determinen reglamentariamente. En estos supuestos:","o":["no será exigible el visado.","será exigible el visado de residencia.","no será exigible el pasaporte.","será preceptivo el informe del Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no será exigible el visado</mark></span>El <span class=\"ref-norma\">art. 31.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En estos supuestos no será exigible el visado\"</span>. En las autorizaciones por arraigo y circunstancias excepcionales no se exige visado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1123","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado. Todo extranjero, admitido en calidad de estudiante en otro Estado miembro de la Unión Europea, que solicite cursar parte de sus estudios ya iniciados o completar éstos en España podrá solicitar una autorización de estancia por estudios y obtenerla, si reúne los requisitos reglamentarios para ello:","o":["previa obtención del visado de estudios.","siempre que no supere un curso académico.","no siendo exigible el visado.","previo informe de la universidad de origen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no siendo exigible el visado</mark></span>El <span class=\"ref-norma\">art. 33.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"podrá solicitar una autorización de estancia por estudios y obtenerla, si reúne los requisitos reglamentarios para ello, no siendo exigible el visado\"</span>. En la movilidad intraeuropea de estudiantes no se exige visado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1153","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo. Los extranjeros mayores de dieciséis años precisarán, para ejercer cualquier actividad lucrativa, laboral o profesional, de la correspondiente autorización administrativa previa para residir y trabajar. La autorización de trabajo se concederá conjuntamente con la de residencia, salvo en los supuestos de:","o":["penados extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen reglamentariamente.","trabajadores transfronterizos que, residiendo en la zona limítrofe, desarrollen su actividad en España y regresen diariamente a su lugar de residencia.","menores extranjeros tutelados por la entidad de protección de menores competente.","trabajadores de temporada contratados mediante la gestión colectiva de contrataciones en origen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">penados extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 36.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La autorización de trabajo se concederá conjuntamente con la de residencia, salvo en los supuestos de penados extranjeros que se hallen cumpliendo condenas o en otros supuestos excepcionales que se determinen reglamentariamente\"</span>. La excepción legal expresa es la de los penados extranjeros que cumplen condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1216","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Excepciones a la autorización de trabajo. No será necesaria la obtención de autorización de trabajo para los funcionarios civiles o militares de las Administraciones estatales extranjeras que vengan a España:","o":["para desarrollar cualquier actividad pública, siempre que su estancia no supere los noventa días.","para desarrollar actividades en virtud de acuerdos de cooperación con la Administración española.","como agregados de las misiones diplomáticas, en virtud del principio de reciprocidad.","para desarrollar actividades docentes en universidades españolas públicas o privadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">para desarrollar actividades en virtud de acuerdos de cooperación con la Administración española</mark></span>El <span class=\"ref-norma\">art. 41.1.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Los funcionarios civiles o militares de las Administraciones estatales extranjeras que vengan a España para desarrollar actividades en virtud de acuerdos de cooperación con la Administración española\"</span>. La excepción es para actividades en virtud de acuerdos de cooperación con la Administración española. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1225","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención. Las entidades públicas de protección de menores estarán exentas del pago de las tasas derivadas de las autorizaciones que están obligadas a solicitar para éstos:","o":["en ejercicio de la representación legal que de ellos ostentan.","siempre que el menor carezca de recursos económicos propios.","cuando el menor haya sido declarado en situación de desamparo.","previa solicitud expresa del Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en ejercicio de la representación legal que de ellos ostentan</mark></span>El <span class=\"ref-norma\">art. 47 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las entidades públicas de protección de menores estarán exentas del pago de las tasas derivadas de las autorizaciones que están obligadas a solicitar para éstos en ejercicio de la representación legal que de ellos ostentan\"</span>. La exención va ligada al ejercicio de la representación legal de los menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1332","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros internados. El extranjero sometido a internamiento tiene derecho a que se comunique inmediatamente el ingreso en el centro:","o":["al Ministerio Fiscal y al Juez que autorizó el internamiento, así como a la oficina consular de su país.","a la persona que designe en España y a su abogado, así como a la oficina consular del país del que es nacional.","a sus familiares residentes en España, a su abogado y a las organizaciones de defensa de los inmigrantes.","a la oficina consular de su país, únicamente si el extranjero lo solicita de forma expresa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la persona que designe en España y a su abogado, así como a la oficina consular del país del que es nacional</mark></span>El <span class=\"ref-norma\">art. 62 bis.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) A que se comunique inmediatamente a la persona que designe en España y a su abogado el ingreso en el centro, así como a la oficina consular del país del que es nacional\"</span>. Comunicación inmediata a la persona que designe, a su abogado y a la oficina consular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1413","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Lugares de presentación de las solicitudes y exigencia de comparecencia personal. Cuando el sujeto legitimado se encuentre en territorio extranjero, la presentación de solicitudes de visado y su recogida se realizarán personalmente ante la misión diplomática u oficina consular en cuya demarcación aquél resida. Excepcionalmente, podrá acordarse que la solicitud pueda presentarse por representante debidamente acreditado cuando:","o":["el interesado no resida en la población en que tenga su sede la misión u oficina y se acrediten razones que obstaculicen el desplazamiento.","el interesado sea menor de edad o persona con discapacidad que no pueda comparecer personalmente ante la misión diplomática u oficina consular.","la misión diplomática u oficina consular no disponga de personal suficiente para atender las solicitudes presentadas.","el interesado acredite haber presentado anteriormente otra solicitud de visado ante la misma misión u oficina consular."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el interesado no resida en la población en que tenga su sede la misión u oficina y se acrediten razones que obstaculicen el desplazamiento</mark></span>El <span class=\"ref-norma\">disp. adic. 3.ª.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Excepcionalmente, cuando el interesado no resida en la población en que tenga su sede la misión diplomática u oficina consular y se acrediten razones que obstaculicen el desplazamiento, como la lejanía de la misión u oficina o dificultades de transporte que hagan el viaje especialmente gravoso, podrá acordarse que la solicitud de visado pueda presentarse por representante debidamente acreditado\"</span>. La excepción se basa en no residir en la población sede y en razones que obstaculicen el desplazamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1415","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Lugares de presentación de las solicitudes y exigencia de comparecencia personal. No se requerirá la comparecencia personal:","o":["en los procedimientos de renovación de las autorizaciones de residencia temporal de los residentes legales que acrediten su esfuerzo de integración.","en los procedimientos de reagrupación familiar de los residentes de larga duración en España.","en los procedimientos de contratación colectiva de trabajadores, en los supuestos contemplados en un convenio o acuerdo internacional.","en los procedimientos de solicitud de visado de estudios para cursar estudios superiores en España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en los procedimientos de contratación colectiva de trabajadores, en los supuestos contemplados en un convenio o acuerdo internacional</mark></span>El <span class=\"ref-norma\">disp. adic. 3.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Asimismo, no se requerirá la comparecencia personal en los procedimientos de contratación colectiva de trabajadores, en los supuestos contemplados en un convenio o acuerdo internacional\"</span>. Se exceptúa la contratación colectiva en los supuestos de un convenio o acuerdo internacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1435","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Normativa aplicable a procedimientos en curso. Los procedimientos administrativos en curso a la entrada en vigor de la Ley Orgánica 4/2000 se tramitarán y resolverán:","o":["de acuerdo con lo previsto en la presente Ley, salvo que el interesado solicite la aplicación de la normativa anterior más favorable.","de acuerdo con la normativa vigente en el momento de la iniciación, sin que quepa solicitar la aplicación de la nueva Ley.","de acuerdo con la normativa vigente en el momento de la iniciación, salvo que el interesado solicite la aplicación de la presente Ley.","de acuerdo con la presente Ley en todo caso, conservando validez los trámites ya realizados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de acuerdo con la normativa vigente en el momento de la iniciación, salvo que el interesado solicite la aplicación de la presente Ley</mark></span>El <span class=\"ref-norma\">disp. trans. 3.ª de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los procedimientos administrativos en curso se tramitarán y resolverán de acuerdo con la normativa vigente en el momento de la iniciación, salvo que el interesado solicite la aplicación de la presente Ley\"</span>. En la LO 4/2000 rige la normativa del inicio (la Ley 12/2009 dispone lo contrario: se aplica la nueva salvo que se pida la anterior). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1439","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Código Comunitario de Visados. Las previsiones de la Ley Orgánica 4/2000 en materia de visados de tránsito y estancia se entenderán sin perjuicio de lo establecido en:","o":["el Convenio de aplicación del Acuerdo de Schengen, de 19 de junio de 1990, en materia de visados uniformes.","el Reglamento (CE) 343/2003, del Consejo, de 18 de febrero, sobre determinación del Estado responsable.","el Reglamento (CE) n.º 810/2009, de 13 de julio, por el que se establece un Código Comunitario sobre Visados.","la Directiva 2004/38/CE relativa al derecho de los ciudadanos de la Unión a circular y residir libremente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Reglamento (CE) n.º 810/2009, de 13 de julio, por el que se establece un Código Comunitario sobre Visados</mark></span>El <span class=\"ref-norma\">disp. final 5.ª bis de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las previsiones de la presente Ley en materia de visados de tránsito y estancia se entenderán sin perjuicio de lo establecido en el Reglamento (CE) n.º 810/2009, de 13 de julio, por el que se establece un Código Comunitario sobre Visados\"</span>. El Código Comunitario sobre Visados es el Reglamento (CE) 810/2009. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1534","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Permanencia del solicitante de asilo durante la tramitación de la solicitud. En todo caso, durante la tramitación de la petición de reexamen y del recurso de reposición en frontera, así como en los supuestos en los que se solicite la suspensión del acto recurrido en vía contencioso-administrativa, la persona solicitante de asilo:","o":["será autorizada a entrar provisionalmente en España.","será ingresada en un centro de internamiento de extranjeros.","podrá circular libremente por el territorio nacional.","permanecerá en las dependencias habilitadas a tal efecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">permanecerá en las dependencias habilitadas a tal efecto</mark></span>El <span class=\"ref-norma\">art. 22 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"la persona solicitante de asilo permanecerá en las dependencias habilitadas a tal efecto\"</span>. Permanece en las dependencias habilitadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1536","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Tramitación de urgencia. El Ministerio del Interior acordará la tramitación de urgencia en las solicitudes en que la persona solicitante, sin motivo justificado, presente su solicitud transcurrido el plazo de:","o":["quince días desde la entrada en territorio español.","un mes desde la entrada en territorio español.","tres meses desde la entrada en territorio español.","un mes desde la denegación de la entrada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un mes desde la entrada en territorio español</mark></span>El <span class=\"ref-norma\">art. 25.1.e) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"e) que la persona solicitante, sin motivo justificado, presente su solicitud transcurrido el plazo de un mes previsto en el apartado segundo del artículo 17\"</span>. Fuera del plazo de un mes, sin motivo justificado: tramitación de urgencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1637","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Normativa aplicable a los procedimientos en curso. Los procedimientos administrativos en tramitación a la entrada en vigor de la Ley 12/2009 se instruirán y resolverán:","o":["de acuerdo con lo previsto en ella, salvo que los interesados soliciten expresamente la aplicación de la normativa vigente en el momento de presentación de la solicitud, por considerarlo más favorable.","de acuerdo con la normativa vigente en el momento de presentación de la solicitud, salvo que los interesados soliciten expresamente la aplicación de la nueva Ley por considerarla más favorable a sus intereses.","de acuerdo con lo previsto en ella en todo caso, sin que los interesados puedan optar por la aplicación de la normativa anterior.","de acuerdo con la normativa vigente en el momento de presentación de la solicitud, en todo caso y sin excepción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de acuerdo con lo previsto en ella, salvo que los interesados soliciten expresamente la aplicación de la normativa vigente en el momento de presentación de la solicitud, por considerarlo más favorable</mark></span>El <span class=\"ref-norma\">disp. trans. 1.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los procedimientos administrativos en tramitación a la entrada en vigor de esta Ley se instruirán y resolverán de acuerdo con lo previsto en ella, salvo que los interesados soliciten expresamente la aplicación de la normativa vigente en el momento de presentación de la solicitud, por considerarlo más favorable a sus intereses\"</span>. Regla inversa a la de la LO 4/2000: se aplica la nueva Ley salvo que se pida la anterior por más favorable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 39 — Gestión colectiva de contrataciones en origen ✱","q":[{"i":"6-40","p":"Ley Orgánica 4/2000. Las ofertas de empleo realizadas a través de la gestión colectiva de contrataciones en origen se orientarán preferentemente hacia los países:","o":["Con los que España haya firmado acuerdos sobre regulación de flujos migratorios.","Con los que España haya tenido una relación histórica.","Con los que la U.E. haya firmado acuerdos sobre regulación de flujos migratorios.","Con los que la U.E. haya firmado convenios bilaterales para la circulación de cupos de inmigrantes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con los que España haya firmado acuerdos sobre regulación de flujos migratorios</mark></span>Según el <span class=\"ref-norma\">art. 39.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las ofertas de empleo realizadas a través de este procedimiento se orientarán preferentemente hacia los países con los que España haya firmado acuerdos sobre regulación de flujos migratorios\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-73","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención. No vendrán obligados al pago de las tasas por la concesión de las autorizaciones para trabajar, cuando pretendan realizar una actividad lucrativa:","o":["Los nacionales taiwaneses, filipinos, americanos, ecuatoguineanos y los sefardíes.","Los hijos y nietos de español o española de origen.","Los extranjeros residentes en España.","Los extranjeros, indistintamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los hijos y nietos de español o española de origen</mark></span>Se corrige la opción B, que decía «sean o no de origen»: la Ley exige que sean de ORIGEN. Según el <span class=\"ref-norma\">art. 47 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"...los sefardíes, los hijos y nietos de español o española de origen, y los extranjeros nacidos en España cuando pretendan realizar una actividad lucrativa, laboral o profesional, por cuenta propia.\"</span> (verificado con el texto del temario)."},{"i":"6-369","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto de:","o":["Los hijos o nietos de español por residencia.","Los cónyuges de español, con independencia de su nacionalidad de origen.","Los hijos o nietos de español de origen.","Los ascendientes de español de origen a su cargo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los hijos o nietos de español de origen</mark></span>El <span class=\"ref-norma\">art. 40.1.h) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"h) Los hijos o nietos de español de origen.\"</span>"},{"i":"6-ia-1206","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Gestión colectiva de contrataciones en origen. El Ministerio de Trabajo e Inmigración, teniendo en cuenta la situación nacional de empleo, podrá aprobar una previsión anual de las ocupaciones y, en su caso, de las cifras previstas de empleos que se puedan cubrir a través de la gestión colectiva de contrataciones en origen en un período determinado, a los que sólo tendrán acceso:","o":["aquellos que se hallen en España en situación de estancia.","los nacionales de países con acuerdos de flujos migratorios.","los hijos o nietos de español de origen que residan en el extranjero.","aquellos que no se hallen o residan en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">aquellos que no se hallen o residan en España</mark></span>El <span class=\"ref-norma\">art. 39.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a los que sólo tendrán acceso aquellos que no se hallen o residan en España\"</span>. La gestión colectiva en origen es solo para quienes no se hallen ni residan en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1207","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Gestión colectiva de contrataciones en origen. El Ministerio competente podrá establecer un número de visados para búsqueda de empleo en las condiciones que se determinen, dirigidos a:","o":["trabajadores altamente cualificados y a investigadores de terceros países.","nacionales de países con los que España haya firmado acuerdos de flujos migratorios.","hijos o nietos de español de origen o a determinadas ocupaciones.","extranjeros que hayan sido titulares de autorizaciones de temporada durante dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">hijos o nietos de español de origen o a determinadas ocupaciones</mark></span>El <span class=\"ref-norma\">art. 39.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Asimismo, podrá establecer un número de visados para búsqueda de empleo en las condiciones que se determinen, dirigidos a hijos o nietos de español de origen o a determinadas ocupaciones\"</span>. Los visados para búsqueda de empleo se dirigen a hijos o nietos de español de origen o a determinadas ocupaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 62 bis — Derechos de los extranjeros internados ✱","q":[{"i":"6-41","p":"Ley Orgánica 4/2000. Los centros de internamiento de extranjeros son establecimientos públicos de carácter no penitenciario; el ingreso y estancia en los mismos tendrá:","o":["Únicamente finalidad tutelar, salvaguardando los derechos y libertades reconocidos en el ordenamiento jurídico, sin más limitaciones que las establecidas a su libertad ambulatoria, conforme al contenido y finalidad de la medida judicial de ingreso acordada.","Finalidad preventiva y cautelar, salvaguardando los derechos y libertades reconocidos en el ordenamiento jurídico, sin más limitaciones que las establecidas a su libertad ambulatoria, conforme al contenido y finalidad de la medida judicial de ingreso acordada.","Únicamente finalidad preventiva y cautelar, salvaguardando los derechos y libertades reconocidos en el ordenamiento jurídico, sin más limitaciones que las establecidas a su libertad ambulatoria, conforme al contenido y finalidad de la medida judicial de ingreso acordada.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Únicamente finalidad preventiva y cautelar, salvaguardando los derechos y libertades reconocidos en el ordenamiento jurídico, sin más limitaciones que las establecidas a su libertad ambulatoria, conforme al contenido y finalidad de la medida judicial de ingreso acordada</mark></span>Según el <span class=\"ref-norma\">art. 62 bis.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"el ingreso y estancia en los mismos tendrá únicamente finalidad preventiva y cautelar\"</span>. La literalidad es «únicamente finalidad preventiva y cautelar» (Verificado con el texto del temario oficial.)"},{"i":"6-105","p":"(Ley Orgánica 4/2000) Derecho de extranjeros internados. Los centros de internamiento de extranjeros son:","o":["Establecimientos privados de carácter no penitenciario.","Establecimientos públicos de carácter penitenciario.","Establecimientos públicos de carácter no penitenciario.","Establecimientos privados de carácter penitenciario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Establecimientos públicos de carácter no penitenciario</mark></span>Según el <span class=\"ref-norma\">art. 62 bis.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los centros de internamiento de extranjeros son establecimientos públicos de carácter no penitenciario; el ingreso y estancia en los mismos tendrá únicamente finalidad preventiva y cautelar, salvaguardando los derechos y libertades reconocidos en el ordenamiento jurídico, sin más limitaciones que las establecidas a su libertad ambulatoria, conforme al contenido y finalidad de la medida judicial de ingreso acordada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1104","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia temporal. La autorización inicial de residencia temporal que no comporte autorización de trabajo se concederá a los extranjeros que:","o":["acrediten un seguro de enfermedad y una vivienda adecuada en España.","dispongan de medios suficientes para sí y, en su caso, para los de su familia.","dispongan de medios suficientes para sí, con exclusión de los de su familia.","acrediten una estancia legal previa en España de al menos 90 días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dispongan de medios suficientes para sí y, en su caso, para los de su familia</mark></span>El <span class=\"ref-norma\">art. 31.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La autorización inicial de residencia temporal que no comporte autorización de trabajo se concederá a los extranjeros que dispongan de medios suficientes para sí y, en su caso, para los de su familia\"</span>. La suficiencia de medios incluye, en su caso, a la familia; los criterios se fijan reglamentariamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1331","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros internados. En particular, el extranjero sometido a internamiento tiene los siguientes derechos: Señale la INCORRECTA.","o":["A ser informado de su situación.","A recibir asistencia médica y sanitaria adecuada y ser asistidos por los servicios de asistencia social del centro.","A comunicarse en el horario establecido en el centro con sus familiares, que solo podrá restringirse por resolución del director del centro.","A entrar en contacto con organizaciones no gubernamentales y organismos nacionales, internacionales y no gubernamentales de protección de inmigrantes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A comunicarse en el horario establecido en el centro con sus familiares, que solo podrá restringirse por resolución del director del centro</mark></span>El <span class=\"ref-norma\">art. 62 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"g) A comunicarse en el horario establecido en el centro, con sus familiares, funcionarios consulares de su país u otras personas, que sólo podrán restringirse por resolución judicial\"</span>. Las comunicaciones solo pueden restringirse por resolución JUDICIAL. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1333","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros internados. El extranjero sometido a internamiento tiene derecho a tener en su compañía a sus hijos menores, siempre que:","o":["el Ministerio Fiscal informe favorablemente tal medida y existan en el centro módulos que garanticen la unidad e intimidad familiar.","el director del centro lo autorice y los menores no superen la edad de seis años, en los términos que se establezcan reglamentariamente.","el Juez de Instrucción lo autorice por auto motivado y los servicios de protección de menores informen favorablemente.","lo solicite el otro progenitor y existan en el centro plazas suficientes para la atención de los menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Ministerio Fiscal informe favorablemente tal medida y existan en el centro módulos que garanticen la unidad e intimidad familiar</mark></span>El <span class=\"ref-norma\">art. 62 bis.1.i) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"i) A tener en su compañía a sus hijos menores, siempre que el Ministerio Fiscal informe favorablemente tal medida y existan en el centro módulos que garanticen la unidad e intimidad familiar\"</span>. Informe favorable del Ministerio Fiscal y módulos que garanticen la unidad e intimidad familiar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1334","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros internados. Podrán visitar los centros de internamiento, desarrollándose reglamentariamente las condiciones de las visitas:","o":["los familiares de los internos y los funcionarios consulares de su país, previa autorización del Juez de Instrucción competente para el control.","los miembros de las Cortes Generales y de las Asambleas Legislativas autonómicas, previa comunicación al director.","las organizaciones no gubernamentales que hayan suscrito un convenio de colaboración con el Ministerio del Interior.","las organizaciones constituidas legalmente en España para la defensa de los inmigrantes y los organismos internacionales pertinentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las organizaciones constituidas legalmente en España para la defensa de los inmigrantes y los organismos internacionales pertinentes</mark></span>El <span class=\"ref-norma\">art. 62 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las organizaciones constituidas legalmente en España para la defensa de los inmigrantes y los organismos internacionales pertinentes podrán visitar los centros de internamiento\"</span>. Pueden visitarlos las organizaciones de defensa de inmigrantes y los organismos internacionales pertinentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 10 — Daños graves EX ✱","q":[{"i":"6-42","p":"Ley 12/2009. Constituyen los daños graves que dan lugar a la protección subsidiaria:","o":["La condena a pena de muerte o riesgo de su ejecución material.","Las torturas y los tratos inhumanos o degradantes en el país de origen del solicitante.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 10 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) la condena a pena de muerte o el riesgo de su ejecución material; b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante; c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno\"</span>. Las tres son daños graves (la respuesta estaba mal marcada) (Verificado con el texto del temario oficial.)"},{"i":"6-62","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. De las condiciones para la concesión del derecho a la protección subsidiaria. Constituyen daños graves que dan lugar a la protección subsidiaria prevista en esta Ley: Señale la opción incorrecta.","o":["La condena a pena de muerte o el riesgo de su ejecución material.","La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada sólo en situaciones de conflicto armado internacional.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada sólo en situaciones de conflicto armado internacional</mark></span>Según el <span class=\"ref-norma\">art. 10 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-64","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Daños graves. Constituyen daños graves que dan lugar a la protección subsidiaria prevista en esta Ley: Señale la INCORRECTA.","o":["La condena a pena de muerte o el riesgo de su ejecución material.","La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada solo en situaciones de conflicto internacional.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada solo en situaciones de conflicto internacional</mark></span>Según el <span class=\"ref-norma\">art. 10 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) la condena a pena de muerte o el riesgo de su ejecución material; b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante; c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno\"</span>. El enunciado no pedía la incorrecta y ninguna opción era correcta; la C limita el daño al conflicto internacional (Verificado con el texto del temario oficial.)"},{"i":"6-86","p":"La Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. Las condiciones para la concesión del derecho a la protección subsidiaria. Constituyen los daños graves que dan lugar a la protección subsidiaria prevista en el artículo 4 de esta Ley:","o":["La condena a pena de muerte o el riesgo de su ejecución material.","La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante.","Las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto interno o internacional.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 10 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) la condena a pena de muerte o el riesgo de su ejecución material; b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante; c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-198","p":"Ley 12/2009... Constituyen los daños graves que dan lugar a la protección subsidiaria prevista en esta Ley: señale la INCORRECTA.","o":["La condena a pena de muerte.","El riesgo de la ejecución material de la condena a pena de muerte.","La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante.","Las amenazas contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las amenazas contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno</mark></span>Según el <span class=\"ref-norma\">art. 10 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) la condena a pena de muerte o el riesgo de su ejecución material; b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante; c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno\"</span>. Las amenazas tienen que ser GRAVES; la condena a pena de muerte y su riesgo de ejecución sí son daños graves (la respuesta estaba mal marcada) (Verificado con el texto del temario oficial.)"},{"i":"6-438","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Daños graves. Constituyen daños graves, entre otros:","o":["La tortura y los tratos inhumanos o degradantes en el país de tránsito del solicitante.","Las penas privativas de libertad superiores a diez años en el país de origen.","Las amenazas leves contra el patrimonio del solicitante en situaciones de conflicto.","La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La tortura y los tratos inhumanos o degradantes en el país de origen del solicitante</mark></span>El <span class=\"ref-norma\">art. 10.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante;\"</span>"}]},{"a":"Artículo 42 — Cese del estatuto de refugiado EX ✱","q":[{"i":"6-49","p":"Ley 12/2009. Cese y revocación de la protección internacional. Cesarán en la condición de refugiados quienes, entre otras: señale la INCORRECTA.","o":["Únicamente lo soliciten.","Se hayan acogido de nuevo a la protección del país de su nacionalidad.","No teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados.","Se hayan establecido, de nuevo, voluntariamente, en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Únicamente lo soliciten</mark></span>Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) expresamente así lo soliciten\"</span>. La Ley dice «expresamente así lo soliciten», no «únicamente» (Verificado con el texto del temario oficial.)"},{"i":"6-60","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Cese del Estatuto de Refugiado. Dejarán en la condición de refugiados quienes: Señale la opción incorrecta.","o":["Se hayan acogido de nuevo, voluntariamente, a la protección del país de su nacionalidad.","Teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados.","Hayan adquirido una nueva nacionalidad y disfruten de la protección del país de su nueva nacionalidad.","Se hayan establecido voluntariamente de nuevo en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados</mark></span>Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"h) no teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados\"</span>. Es «NO teniendo nacionalidad» (Verificado con el texto del temario oficial.)"},{"i":"6-89","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Cesarán en la condición de refugiados quienes: Señale la incorrecta.","o":["Se hayan reestablecido, de nuevo, voluntariamente, en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos.","Hayan abandonado el territorio español y fijado su residencia en otro país.","Se hayan acogido de nuevo, voluntariamente, a la protección del país de su nacionalidad.","Teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual</mark></span>La B (abandonar España y fijar la residencia en otro país) SÍ es causa de cese (letra f). La D es la INCORRECTA: la letra h) se refiere a quienes NO tienen nacionalidad. Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Cesarán en la condición de refugiados quienes: [...] f) hayan abandonado el territorio español y fijado su residencia en otro país; g) no puedan continuar negándose a la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados [...] h) no teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual...\"</span> (verificado con el texto del temario)."},{"i":"6-92","p":"Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. Cesarán en la condición de refugiados quienes: Señale la incorrecta.","o":["Expresamente así lo soliciten.","Se hayan establecido de nuevo en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos.","Hayan abandonado el territorio español y fijado su residencia en otro país.","No puedan continuar invocando la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados, el Estado español, basada si cuenta en el cambio de circunstancias con el consentimiento significativo, sin ser de carácter temporal, como para dejar de considerar fundados los temores del refugiado a ser perseguido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No puedan continuar invocando la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados, el Estado español, basada si cuenta en el cambio de circunstancias con el consentimiento significativo, sin ser de carácter temporal, como para dejar de considerar fundados los temores del refugiado a ser perseguido</mark></span>La C SÍ es causa de cese (letra f). La D es la INCORRECTA: el texto dice «continuar NEGÁNDOSE a la protección», no «invocando». Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Cesarán en la condición de refugiados quienes: [...] f) hayan abandonado el territorio español y fijado su residencia en otro país; g) no puedan continuar negándose a la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados [...] h) no teniendo nacionalidad, puedan regresar al país de su anterior residencia habitual...\"</span> (verificado con el texto del temario)."},{"i":"6-93","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cese del estatuto de refugiado. Cesarán en la condición de refugiados quienes: Señale la INCORRECTA.","o":["Expresamente así lo soliciten.","Se hayan establecido de nuevo en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos.","Hayan abandonado el territorio español y fijado su residencia en otro país.","No puedan continuar invocando la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados, el Estado español, basada si cuenta en el cambio de circunstancias con el consentimiento significativo, sin ser de carácter temporal, como para dejar de considerar fundados los temores del refugiado a ser perseguido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No puedan continuar invocando la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados, el Estado español, basada si cuenta en el cambio de circunstancias con el consentimiento significativo, sin ser de carácter temporal, como para dejar de considerar fundados los temores del refugiado a ser perseguido</mark></span>Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"g) no puedan continuar negándose a la protección del país de su nacionalidad por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-106","p":"(Ley 12/2009) Cese del Estatuto de Refugiado. Cesarán en la condición de refugiados quienes: Señale la INCORRECTA.","o":["Habiendo cesado en su calidad.","Habiendo perdido su nacionalidad, la hayan recobrado voluntariamente.","Se hayan establecido, de nuevo, voluntariamente, en el país que habían abandonado, o fuera del cual habían permanecido, por temor a ser perseguidos.","No siendo de nacionalidad, puedan regresar al país de su anterior residencia habitual por haber desaparecido las circunstancias en virtud de las cuales fueron reconocidos como refugiados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Habiendo cesado en su calidad</mark></span>Según el <span class=\"ref-norma\">art. 42.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) habiendo perdido su nacionalidad, la hayan recobrado voluntariamente\"</span>. «Habiendo cesado en su calidad» no es causa de cese (Verificado con el texto del temario oficial.)"},{"i":"6-452","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cese del estatuto de refugiado. Cesarán en la condición de refugiados quienes:","o":["Hayan abandonado el territorio español durante más de seis meses.","Hayan adquirido la nacionalidad de un Estado miembro por naturalización.","Hayan sido condenados por sentencia firme por un delito doloso.","Expresamente así lo soliciten."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Expresamente así lo soliciten</mark></span>El <span class=\"ref-norma\">art. 42.1.a) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"a) expresamente así lo soliciten;\"</span>"},{"i":"6-472","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cese del estatuto de refugiado. Quienes expresamente así lo soliciten:","o":["verán revocado su estatuto por resolución motivada del Ministerio del Interior.","cesarán en la protección subsidiaria, pero conservarán la condición de refugiado.","cesarán en la condición de refugiados.","perderán además, en todo caso, el derecho a seguir residiendo en España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cesarán en la condición de refugiados</mark></span>El <span class=\"ref-norma\">art. 42.1.a) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Cesarán en la condición de refugiados quienes: a) expresamente así lo soliciten\"</span> La solicitud expresa del interesado es causa de cese (no de revocación)."},{"i":"6-ia-1617","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cese del estatuto de refugiado. El cese en la condición de refugiado:","o":["no impedirá la continuación de la residencia en España conforme a la normativa vigente en materia de extranjería e inmigración.","determinará en todo caso la salida obligatoria del territorio español en el plazo de quince días.","conllevará la inmediata tramitación del correspondiente expediente administrativo sancionador para la expulsión del territorio nacional.","impedirá la continuación de la residencia en España salvo que se obtenga la protección subsidiaria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no impedirá la continuación de la residencia en España conforme a la normativa vigente en materia de extranjería e inmigración</mark></span>El <span class=\"ref-norma\">art. 42.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El cese en la condición de refugiado no impedirá la continuación de la residencia en España conforme a la normativa vigente en materia de extranjería e inmigración\"</span>. El cese no impide seguir residiendo conforme a la normativa de extranjería; la tramitación del expediente de expulsión es efecto de la revocación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 8 — Causas de exclusión EXOF ✱","q":[{"i":"6-53","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Quedarán excluidas de la condición de refugiado las personas extranjeras sobre las que existan motivos fundados para considerar que:","o":["Han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad, de los definidos en los instrumentos internacionales que establecen disposiciones relativas a tales delitos.","Son culpables de actos contrarios a las finalidades y a los principios de las Naciones Unidas establecidos en el Preámbulo y en los artículos 1 y 2 de la Carta de las Naciones Unidas.","Las opciones A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las opciones A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 8.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad, de los definidos en los instrumentos internacionales que establecen disposiciones relativas a tales delitos\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-435","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Quedarán excluidas de la condición de refugiados:","o":["Las personas que hayan solicitado protección en un tercer Estado miembro de la Unión Europea, entre otras, en los términos que determine la ley orgánica correspondiente.","Las personas que hayan sido condenadas en su país de origen por delito de terrorismo, entre otras.","Las personas que estén comprendidas en el ámbito de aplicación de la sección D del artículo 1 de la Convención de Ginebra, entre otras.","Las personas que carezcan de documentación identificativa válida, entre otras."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las personas que estén comprendidas en el ámbito de aplicación de la sección D del artículo 1 de la Convención de Ginebra, entre otras</mark></span>El <span class=\"ref-norma\">art. 8.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"1. Quedarán excluidas de la condición de refugiados: a) las personas que estén comprendidas en el ámbito de aplicación de la sección D del artículo 1 de la Convención de Ginebra\"</span>"},{"i":"6-436","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Quedarán excluidas de la condición de refugiados las personas a quienes las autoridades competentes del país donde hayan fijado su residencia les hayan reconocido:","o":["Los derechos de residencia de larga duración propios de los nacionales de terceros Estados.","Los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos.","Los derechos políticos y de sufragio de los nacionales de tal país.","Los derechos y obligaciones inherentes a la nacionalidad, con exclusión de los equivalentes a ellos, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos</mark></span>El <span class=\"ref-norma\">art. 8.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) las personas a quienes las autoridades competentes del país donde hayan fijado su residencia les hayan reconocido los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos.\"</span>"},{"i":"6-437","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. También quedarán excluidas las personas extranjeras sobre las que existan motivos fundados para considerar que:","o":["Han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad, de los definidos en los instrumentos internacionales.","Han cometido en su país de origen cualquier delito sancionado con pena privativa de libertad, conforme al procedimiento que reglamentariamente se establezca.","Han incumplido las obligaciones de comparecencia ante las autoridades españolas.","Han presentado la solicitud fuera del plazo de un mes desde su entrada en España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad, de los definidos en los instrumentos internacionales</mark></span>El <span class=\"ref-norma\">art. 8.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"2. También quedarán excluidas las personas extranjeras sobre las que existan motivos fundados para considerar que: a) han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad, de los definidos en los instrumentos internacionales que establecen disposiciones relativas a tales delitos;\"</span>"},{"i":"6-ia-1302","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. No obstante lo anterior, el juez podrá autorizar, a instancias del interesado y previa audiencia del Ministerio Fiscal, la salida del extranjero del territorio español:","o":["en la forma que determine la autoridad gubernativa competente.","siempre que haya cumplido la mitad de la pena impuesta.","previa prestación de fianza suficiente para responder del proceso.","en la forma que determina la Ley de Enjuiciamiento Criminal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en la forma que determina la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 57.7.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) No obstante lo señalado en el párrafo a) anterior, el juez podrá autorizar, a instancias del interesado y previa audiencia del Ministerio Fiscal, la salida del extranjero del territorio español en la forma que determina la Ley de Enjuiciamiento Criminal\"</span>. La salida se autoriza en la forma que determina la Ley de Enjuiciamiento Criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1502","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Quedarán excluidas de la condición de refugiados las personas a quienes las autoridades competentes del país donde hayan fijado su residencia les hayan reconocido:","o":["una autorización de residencia temporal por razones humanitarias, siempre que hubiera sido renovada en al menos una ocasión.","la condición de residente de larga duración, con independencia de los derechos que dicha condición les atribuya en ese país.","el derecho a trabajar y a acceder a los servicios sociales básicos en las mismas condiciones que a sus nacionales.","los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos</mark></span>El <span class=\"ref-norma\">art. 8.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) las personas a quienes las autoridades competentes del país donde hayan fijado su residencia les hayan reconocido los derechos y obligaciones que son inherentes a la posesión de la nacionalidad de tal país, o derechos y obligaciones equivalentes a ellos\"</span>. Se excluye a quien tiene reconocidos en el país de residencia los derechos y obligaciones inherentes a la nacionalidad o equivalentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1503","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Quedarán excluidas de la condición de refugiado las personas que hayan cometido fuera del país de refugio, antes de ser admitidas como refugiadas, un delito grave, entendiéndose por tal los que lo sean conforme al Código Penal español y que afecten a la vida, la libertad, la indemnidad o la libertad sexual, la integridad de las personas o el patrimonio, siempre que:","o":["hubieran sido castigados con pena de prisión superior a cinco años por sentencia firme dictada en el país de origen.","hubieran sido cometidos con ánimo de lucro, así como en los casos de terrorismo y de delincuencia organizada transnacional.","fuesen realizados con fuerza en las cosas, o violencia o intimidación en las personas, así como en los casos de la delincuencia organizada.","fuesen realizados con violencia o intimidación en las personas, con exclusión de los delitos contra el patrimonio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">fuesen realizados con fuerza en las cosas, o violencia o intimidación en las personas, así como en los casos de la delincuencia organizada</mark></span>El <span class=\"ref-norma\">art. 8.2.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"siempre que fuesen realizados con fuerza en las cosas, o violencia o intimidación en las personas, así como en los casos de la delincuencia organizada\"</span>. Exige fuerza en las cosas o violencia o intimidación en las personas, o delincuencia organizada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1504","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Las causas de exclusión por delitos contra la paz, de guerra o contra la humanidad, delitos graves y actos contrarios a los fines de las Naciones Unidas se aplicarán también a las personas que:","o":["hayan sido condenadas por cualquier delito doloso en su país de origen o de residencia.","inciten a la comisión de los delitos o actos mencionados, o bien participen en su comisión.","pertenezcan a organizaciones calificadas como terroristas por la Unión Europea.","conozcan la comisión de tales delitos y no los hayan denunciado ante las autoridades."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">inciten a la comisión de los delitos o actos mencionados, o bien participen en su comisión</mark></span>El <span class=\"ref-norma\">art. 8.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El apartado segundo se aplicará a las personas que inciten a la comisión de los delitos o actos mencionados en él, o bien participen en su comisión\"</span>. Se extienden a quienes inciten a su comisión o participen en ella. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 30 — Derechos sociales generales","q":[{"i":"6-56","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Condiciones de acogida de los solicitantes de protección internacional. Se proporcionará a las personas solicitantes de protección internacional:","o":["Siempre que carezcan de recursos económicos, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad, sin perjuicio, en tanto que extranjeros, de lo establecido en la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social, y en su normativa de desarrollo.","Siempre que carezcan de recursos económicos, los servicios sanitarios y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad, sin perjuicio, en tanto que extranjeros, de lo establecido en la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social, y en su normativa de desarrollo.","Aunque dispongan de recursos económicos suficientes, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas.","Siempre que carezcan de recursos sociales, los servicios sanitarios y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad, sin perjuicio, en tanto que extranjeros, de lo establecido en la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social, y en su normativa de desarrollo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Siempre que carezcan de recursos económicos, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad, sin perjuicio, en tanto que extranjeros, de lo establecido en la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social, y en su normativa de desarrollo</mark></span>Según el <span class=\"ref-norma\">art. 30.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Se proporcionará a las personas solicitantes de protección internacional, siempre que carezcan de recursos económicos, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad, sin perjuicio, en tanto que extranjeros, de lo establecido en la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social, y en su normativa de desarrollo\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-456","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal. Para la renovación de las autorizaciones de residencia temporal, se valorará en su caso:","o":["El incumplimiento de las obligaciones del extranjero en materia de empadronamiento municipal.","La asistencia del extranjero a cursos de formación profesional durante el período de residencia, salvo que el órgano competente acuerde otra cosa de forma motivada.","El pago de las tasas correspondientes en el plazo de tres meses desde su devengo.","El incumplimiento de las obligaciones del extranjero en materia tributaria y de seguridad social."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El incumplimiento de las obligaciones del extranjero en materia tributaria y de seguridad social</mark></span>El <span class=\"ref-norma\">art. 31.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"7. Para la renovación de las autorizaciones de residencia temporal, se valorará en su caso:\"</span>"},{"i":"6-ia-1051","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expedición del visado. Si la denegación del visado se debe a que el solicitante está incluido en la lista de personas no admisibles prevista en el Convenio de aplicación del Acuerdo de Schengen de 14 de junio de 1990:","o":["no será necesario motivar la denegación en ningún caso.","se le comunicará la causa solo si se trata de visados de residencia para reagrupación familiar.","se le comunicará así de conformidad con las normas establecidas por dicho Convenio.","la resolución no expresará los recursos que procedan contra ella."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se le comunicará así de conformidad con las normas establecidas por dicho Convenio</mark></span>El <span class=\"ref-norma\">art. 27.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Si la denegación se debe a que el solicitante del visado está incluido en la lista de personas no admisibles prevista en el Convenio de aplicación del Acuerdo de Schengen de 14 de junio de 1990, se le comunicará así de conformidad con las normas establecidas por dicho Convenio\"</span>. Se le comunica conforme al Convenio Schengen; la resolución sigue expresando los recursos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1107","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia temporal. Para la renovación de las autorizaciones de residencia temporal, se valorará en su caso los antecedentes penales, considerando:","o":["la cancelación de los antecedentes y la gravedad del delito cometido en España o en el país de origen.","la existencia de indultos y la duración de la pena privativa de libertad efectivamente cumplida.","la existencia de indultos o las situaciones de remisión condicional de la pena o la suspensión de la pena privativa de libertad.","únicamente los antecedentes por delitos dolosos castigados con pena privativa de libertad superior a un año, cometidos en España o en el extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la existencia de indultos o las situaciones de remisión condicional de la pena o la suspensión de la pena privativa de libertad</mark></span>El <span class=\"ref-norma\">art. 31.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Los antecedentes penales, considerando la existencia de indultos o las situaciones de remisión condicional de la pena o la suspensión de la pena privativa de libertad\"</span>. Se consideran los indultos, la remisión condicional y la suspensión de la pena privativa de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1222","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Hecho imponible. Por la prestación de servicios de tramitación de visados por parte de proveedores de servicios externos:","o":["se exigirá la tasa de visado incrementada en un diez por ciento por cada solicitud tramitada.","no podrá exigirse cantidad alguna al solicitante del visado.","se aplicará la exención prevista para los visados de tránsito.","se podrán establecer precios públicos, de conformidad con la normativa aplicable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se podrán establecer precios públicos, de conformidad con la normativa aplicable</mark></span>El <span class=\"ref-norma\">art. 44.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se podrán establecer precios públicos por la prestación de servicios de tramitación de visados por parte de proveedores de servicios externos, de conformidad con la normativa aplicable\"</span>. Para proveedores externos se pueden establecer precios públicos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1330","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. El Juez competente para el control de la estancia en los Centros de Internamiento conocerá de las peticiones y quejas que planteen los internos en cuanto afecten a sus derechos fundamentales:","o":["en primera instancia, con recurso de apelación.","previo informe del director del centro.","previa reclamación ante el Ministerio del Interior.","sin ulterior recurso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sin ulterior recurso</mark></span>El <span class=\"ref-norma\">art. 62.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Este Juez conocerá, sin ulterior recurso, de las peticiones y quejas que planteen los internos en cuanto afecten a sus derechos fundamentales\"</span>. Conoce sin ulterior recurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1341","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento preferente. El procedimiento preferente será aplicable cuando, tratándose de estancia irregular, se diera alguna de las siguientes circunstancias: Señale la INCORRECTA.","o":["que el extranjero carezca de medios económicos suficientes para su manutención.","riesgo de incomparecencia.","que el extranjero evitara o dificultase la expulsión, sin perjuicio de las actuaciones en ejercicio de sus derechos.","que el extranjero representase un riesgo para el orden público, la seguridad pública o la seguridad nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que el extranjero carezca de medios económicos suficientes para su manutención</mark></span>El <span class=\"ref-norma\">art. 63.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) riesgo de incomparecencia. b) el extranjero evitara o dificultase la expulsión, sin perjuicio de las actuaciones en ejercicio de sus derechos. c) el extranjero representase un riesgo para el orden público, la seguridad pública o la seguridad nacional\"</span>. La carencia de medios económicos no es una de las circunstancias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1427","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen especial de Ceuta y Melilla. Los extranjeros que sean detectados en la línea fronteriza de la demarcación territorial de Ceuta o Melilla mientras intentan superar los elementos de contención fronterizos para cruzar irregularmente la frontera:","o":["serán objeto de devolución sin necesidad de expediente de expulsión, previa identificación y comunicación al Juez de Instrucción del lugar en que se produzca.","podrán ser rechazados, salvo que manifiesten su voluntad de solicitar protección internacional en el mismo lugar del rechazo.","podrán ser rechazados a fin de impedir su entrada ilegal en España, respetando la normativa internacional de derechos humanos y de protección internacional.","serán conducidos a las dependencias policiales para la incoación del correspondiente expediente de expulsión preferente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrán ser rechazados a fin de impedir su entrada ilegal en España, respetando la normativa internacional de derechos humanos y de protección internacional</mark></span>El <span class=\"ref-norma\">disp. adic. 10.ª de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"podrán ser rechazados a fin de impedir su entrada ilegal en España\"</span>. Pueden ser rechazados, respetando la normativa de derechos humanos y protección internacional; las solicitudes se formalizan en los pasos fronterizos habilitados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1430","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas. Las ciudades y comunidades autónomas deberán remitir a la persona titular de la Presidencia de la Conferencia Sectorial de Infancia y Adolescencia certificación del número máximo de personas menores de edad extranjeras no acompañadas atendidas por su sistema de protección en el año anterior:","o":["antes del 31 de enero de cada año.","antes del 31 de marzo de cada año.","antes del 15 de febrero de cada año.","antes del 15 de enero de cada año."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">antes del 15 de enero de cada año</mark></span>El <span class=\"ref-norma\">disp. adic. 11.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"antes del 15 de enero de cada año certificación del titular de la Consejería competente del número máximo de personas menores de edad extranjeras no acompañadas atendidas\"</span>. Antes del 15 de enero; el 31 de marzo de 2025 era la fecha de los datos iniciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1553","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reducción o retirada de las condiciones de acogida. Podrán reducirse o retirarse los servicios de acogida cuando por acción u omisión se vulneren los derechos de otros residentes o del personal encargado de los centros donde estén acogidos o:","o":["se dificulte gravemente la convivencia en ellos, de conformidad con lo establecido en las normas internas de los mismos.","se dificulte de cualquier modo la convivencia en ellos, aunque no esté previsto en las normas internas de funcionamiento de los centros.","se cometa cualquier infracción leve de las previstas en la legislación de extranjería.","se incumpla el horario de entrada y salida de los centros en más de tres ocasiones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se dificulte gravemente la convivencia en ellos, de conformidad con lo establecido en las normas internas de los mismos</mark></span>El <span class=\"ref-norma\">art. 33.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) cuando por acción u omisión se vulneren los derechos de otros residentes o del personal encargado de los centros donde estén acogidos o se dificulte gravemente la convivencia en ellos, de conformidad con lo establecido en las normas internas de los mismos\"</span>. Debe dificultarse GRAVEMENTE la convivencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1614","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reagrupación familiar. En el supuesto de reagrupación familiar de las personas refugiadas o beneficiarias de protección subsidiaria:","o":["se exigirá a los reagrupantes acreditar vivienda adecuada y medios económicos suficientes conforme a la normativa de extranjería.","se exigirá a los reagrupados los requisitos de la normativa de extranjería, pero no a los reagrupantes.","se exigirán los requisitos de extranjería salvo el de haber obtenido la renovación de la autorización inicial.","no se exigirá a los reagrupantes ni a los reagrupados los requisitos establecidos en la normativa vigente de extranjería e inmigración."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no se exigirá a los reagrupantes ni a los reagrupados los requisitos establecidos en la normativa vigente de extranjería e inmigración</mark></span>El <span class=\"ref-norma\">art. 41.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"no se exigirá a los refugiados o beneficiarios de la protección subsidiaria, ni tampoco a los beneficiarios de la reagrupación familiar, los requisitos establecidos en la normativa vigente de extranjería e inmigración\"</span>. No se exigen los requisitos de extranjería a ninguno de ellos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1627","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Régimen general de protección. Por razones humanitarias distintas de las señaladas en el estatuto de protección subsidiaria:","o":["se concederá en todo caso el estatuto de protección subsidiaria por extensión a la persona solicitante, previo informe de la Comisión Interministerial.","se podrá conceder el derecho de asilo, previo informe favorable de la Comisión Interministerial.","se podrá autorizar la permanencia de la persona solicitante en España en los términos previstos por la normativa de extranjería.","se suspenderá la tramitación de la solicitud hasta que desaparezcan dichas razones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se podrá autorizar la permanencia de la persona solicitante en España en los términos previstos por la normativa de extranjería</mark></span>El <span class=\"ref-norma\">art. 46.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Por razones humanitarias distintas de las señaladas en el estatuto de protección subsidiaria, se podrá autorizar la permanencia de la persona solicitante de protección internacional en España en los términos previstos por la normativa vigente en materia de extranjería e inmigración\"</span>. Se puede autorizar la permanencia conforme a la normativa de extranjería. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Derechos de los extranjeros e interpretación de las normas ✱","q":[{"i":"6-57","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Normas relativas a los derechos fundamentales de los extranjeros serán interpretadas, sin que pueda alegarse la profesión de creencias religiosas o convicciones ideológicas o culturales de signo diverso para justificar la realización de actos o conductas contrarios a las mismas, de conformidad con:","o":["La Declaración Universal de Derechos Humanos.","Los tratados y acuerdos internacionales sobre las mismas materias vigentes en España.","La Carta de Naciones Unidas.","Las opciones A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 3.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las normas relativas a los derechos fundamentales de los extranjeros serán interpretadas de conformidad con la Declaración Universal de Derechos Humanos y con los tratados y acuerdos internacionales sobre las mismas materias vigentes en España\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-338","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros e interpretación. Las normas relativas a los derechos fundamentales de los extranjeros serán interpretadas de conformidad con:","o":["La Constitución y con la jurisprudencia del Tribunal de Justicia de la Unión Europea únicamente.","La Convención de Ginebra y con los tratados internacionales ratificados por la Unión Europea.","La Declaración Universal de Derechos Humanos y con los tratados y acuerdos internacionales sobre las mismas materias vigentes en España.","La Declaración Universal de Derechos Humanos, con exclusión de los tratados bilaterales suscritos por España, sin perjuicio de lo que establezcan los tratados internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Declaración Universal de Derechos Humanos y con los tratados y acuerdos internacionales sobre las mismas materias vigentes en España</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Las normas relativas a los derechos fundamentales de los extranjeros serán interpretadas de conformidad con la Declaración Universal de Derechos Humanos y con los tratados y acuerdos internacionales sobre las mismas materias vigentes en España\"</span>"},{"i":"6-ia-1010","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros e interpretación de las normas. Los extranjeros gozarán en España de los derechos y libertades reconocidos en el Título I de la Constitución en los términos establecidos en:","o":["la Declaración Universal de Derechos Humanos y en los convenios de la Unión Europea ratificados por España.","esta Ley y en su Reglamento, con exclusión de los Tratados no ratificados.","los Tratados internacionales y en la normativa de la Unión Europea exclusivamente.","los Tratados internacionales, en esta Ley y en las que regulen el ejercicio de cada uno de ellos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Tratados internacionales, en esta Ley y en las que regulen el ejercicio de cada uno de ellos</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros gozarán en España de los derechos y libertades reconocidos en el Título I de la Constitución en los términos establecidos en los Tratados internacionales, en esta Ley y en las que regulen el ejercicio de cada uno de ellos\"</span>. La Declaración Universal sirve para INTERPRETAR las normas sobre derechos fundamentales, no para fijar los términos de su disfrute. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — La condición de refugiado ✱","q":[{"i":"6-58","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Disposiciones generales. La condición de refugiado se reconoce a toda persona que, se encuentra fuera del país de su nacionalidad y no puede o no quiere acogerse a la protección de tal país debido a fundados temores de ser perseguida por motivos de: Señale la opción incorrecta.","o":["Raza o religión.","Nacionalidad u opiniones políticas.","Pertenencia a determinado grupo social o étnico.","Género u orientación sexual."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Pertenencia a determinado grupo social o étnico</mark></span>Según el <span class=\"ref-norma\">art. 3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual\"</span>. Se corrige B («convicciones políticas» → opiniones políticas); el grupo «étnico» no figura (Verificado con el texto del temario oficial.)"},{"i":"6-121","p":"(Ley 12/2009) Señale la opción INCORRECTA sobre las causas de persecución para el reconocimiento de la condición de refugiado.","o":["Raza o religión.","Nacionalidad u opiniones políticas.","Pertenencia a determinado grupo social, étnico o cultural.","Pertenencia a determinado grupo de género u orientación sexual."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Pertenencia a determinado grupo social, étnico o cultural</mark></span>Según el <span class=\"ref-norma\">art. 3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual\"</span>. El grupo «étnico o cultural» no figura como motivo autónomo (Verificado con el texto del temario oficial.)"},{"i":"6-426","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. La condición de refugiado. La condición de refugiado se reconoce a toda persona que, debido a fundados temores de ser perseguida por determinados motivos, se encuentra fuera del país de su nacionalidad. Entre esos motivos figuran:","o":["Raza, religión, nacionalidad, opiniones políticas, situación económica y pertenencia a determinado grupo social, sin perjuicio de lo que establezcan los tratados internacionales.","Raza, religión, nacionalidad y opiniones políticas, con exclusión de las razones de género.","Raza, religión, opiniones políticas, pertenencia a determinado grupo social y lugar de nacimiento.","Raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La condición de refugiado se reconoce a toda persona que, debido a fundados temores de ser perseguida por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual, se encuentra fuera del país de su nacionalidad\"</span>"},{"i":"6-ia-1444","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. La condición de refugiado. La condición de refugiado se reconoce también al apátrida que, careciendo de nacionalidad y hallándose fuera del país donde antes tuviera su residencia habitual, por los mismos motivos:","o":["no puede obtener la nacionalidad del país de su residencia habitual.","no puede o, a causa de dichos temores, no quiere regresar a él.","no ha podido obtener documentación de ningún Estado de forma continuada.","no puede regresar a él, aunque quiera hacerlo, por causas ajenas a su voluntad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no puede o, a causa de dichos temores, no quiere regresar a él</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"o al apátrida que, careciendo de nacionalidad y hallándose fuera del país donde antes tuviera su residencia habitual, por los mismos motivos no puede o, a causa de dichos temores, no quiere regresar a él\"</span>. Para el apátrida, la referencia es el país de su anterior residencia habitual: no puede o no quiere regresar a él. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47 — Exención EXOF ✱","q":[{"i":"6-63","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. De las tasas por autorizaciones administrativas y por tramitación de las solicitudes de visado. No vendrán obligados al pago de las tasas por la concesión de las autorizaciones para trabajar cuando pretendan realizar una actividad lucrativa, laboral o profesional, por cuenta propia los nacionales: Señale la opción incorrecta.","o":["Iberoamericanos.","Andorranos.","Marroquíes.","Ecuatoguineanos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Marroquíes</mark></span>Se cambia la opción D («Saharauis», que tampoco está exenta y daba dos respuestas incorrectas) por «Ecuatoguineanos», que sí lo está. Según el <span class=\"ref-norma\">art. 47 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"No vendrán obligados al pago de las tasas por la concesión de las autorizaciones para trabajar los nacionales iberoamericanos, filipinos, andorranos, ecuatoguineanos, los sefardíes, los hijos y nietos de español o española de origen, y los extranjeros nacidos en España cuando pretendan realizar una actividad lucrativa, laboral o profesional, por cuenta propia.\"</span> (verificado con el texto del temario)."},{"i":"6-77","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención. En aplicación de la normativa comunitaria sobre la materia, quedarán exentos del pago de la tasa relativa a visados de tránsito o estancia; señale la INCORRECTA:","o":["Los niños menores de seis años.","Los investigadores nacionales de terceros países que se desplacen con fines de investigación científica en los términos establecidos por la Recomendación 2005/761/CE, del Parlamento y del Consejo.","Los representantes de organizaciones sin ánimo de lucro que no son mayores de 25 años y viajan para participar en seminarios, conferencias o acontecimientos deportivos o educativos, organizados por organizaciones sin ánimo de lucro.","Los nacionales filipinos, americanos y los sefardíes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los nacionales filipinos, americanos y los sefardíes</mark></span>Según el <span class=\"ref-norma\">art. 47 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"quedarán exentos del pago de la tasa relativa a visados de tránsito o estancia, los niños menores de seis años\"</span>. Filipinos y sefardíes están exentos de la tasa de autorización para trabajar por cuenta propia, no de la de visados (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1226","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención. Las solicitudes de visado presentadas por nacionales de terceros países beneficiarios de derecho comunitario en materia de libre circulación y residencia:","o":["abonarán la tasa reducida en un cincuenta por ciento.","estarán exentas solo si se trata de visados de tránsito.","abonarán las tasas por el principio de reciprocidad.","estarán exentas del pago de las tasas de tramitación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">estarán exentas del pago de las tasas de tramitación</mark></span>El <span class=\"ref-norma\">art. 47 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las solicitudes de visado presentadas por nacionales de terceros países beneficiarios de derecho comunitario en materia de libre circulación y residencia estarán exentas del pago de las tasas de tramitación\"</span>. Estos visados están exentos del pago de las tasas de tramitación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 — Intervención en la tramitación de protección internacional ✱ R27","q":[{"i":"6-66","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Intervención del Alto Comisionado de Naciones Unidas para los Refugiados (ACNUR). Señale la opción incorrecta en esta materia:","o":["El representante de ACNUR en España será convocado a las sesiones de la Comisión Nacional de Asilo y Refugio.","Será informado inmediatamente de la presentación de las solicitudes en frontera y podrá entrevistarse, si lo desea, con los solicitantes.","La presentación de las solicitudes de protección internacional se comunicará a ACNUR, quien podrá informarse de la situación de los expedientes, estar presente en las audiencias a la persona solicitante y presentar informes para su inclusión en el expediente.","En los casos en que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión a trámite, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable, se dará un plazo de diez días al ACNUR para que, en su caso, informe."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El representante de ACNUR en España será convocado a las sesiones de la Comisión Nacional de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 35.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El representante en España del ACNUR será convocado a las sesiones de la Comisión Interministerial de Asilo y Refugio\"</span>. Es la Comisión INTERMINISTERIAL, no «Nacional» (se corrigen B, C y D, que venían alteradas) (Verificado con el texto del temario oficial.)"},{"i":"6-103","p":"Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. Intervención en la tramitación de protección internacional. ¿Quién será convocado a las sesiones de la Comisión Interministerial de Asilo y Refugio?","o":["El representante en España de Cruz Roja.","El representante en España de la OMS.","El representante en España del ACNUR.","El representante en España del SEREM."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El representante en España del ACNUR</mark></span>Según el <span class=\"ref-norma\">art. 35.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El representante en España del ACNUR será convocado a las sesiones de la Comisión Interministerial de Asilo y Refugio\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-135","p":"(Ley 12/2009) ¿Cuál es el plazo de intervención de la ACNUR en la Tramitación de Protección Internacional en el procedimiento de urgencia?","o":["Diez días.","Veinte días.","Quince días.","No tiene plazo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>Según el <span class=\"ref-norma\">art. 35.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión a trámite del artículo 20, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de diez días al ACNUR para que, en su caso, informe\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-154","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de _________ al ACNUR para que, en su caso, informe.","o":["Diez días.","Doce días.","Quince días.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>Según el <span class=\"ref-norma\">art. 35.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión a trámite del artículo 20, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de diez días al ACNUR para que, en su caso, informe\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-227","p":"Ley 12/2009... En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de __________ al ACNUR para que, en su caso, informe.","o":["Diez días.","Doce días.","Quince días.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>Son DIEZ días, no doce. Según el <span class=\"ref-norma\">art. 35.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión a trámite del artículo 20, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de diez días al ACNUR para que, en su caso, informe.\"</span> (verificado con el texto del temario)."},{"i":"6-279","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de _________ al ACNUR para que, en su caso, informe.","o":["Diez días.","Doce días.","Quince días.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>Según el <span class=\"ref-norma\">art. 35.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En los casos que se tramiten las solicitudes mediante el procedimiento de urgencia, y en los casos de admisión a trámite del artículo 20, si la propuesta de resolución de la Oficina de Asilo y Refugio fuese desfavorable se dará un plazo de diez días al ACNUR para que, en su caso, informe\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1550","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Acogida de los solicitantes de protección internacional. La falta de constitución y acreditación de la garantía en la acción concertada podrá dar lugar a la pérdida del derecho al pago de forma definitiva cuando, habiéndose realizado requerimiento previo para que se acredite, éste no fuera atendido en el plazo de:","o":["10 días.","30 días.","1 mes.","15 días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">15 días</mark></span>El <span class=\"ref-norma\">art. 31.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"éste no fuera atendido en el plazo de 15 días\"</span>. Quince días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1555","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Intervención en la tramitación de protección internacional. Con carácter previo a dictarse las resoluciones de inadmisión, denegación o ampliación de plazo sobre las solicitudes presentadas en puestos fronterizos:","o":["se recabará informe de la CIAR.","se oirá al Ministerio Fiscal.","se dará audiencia al ACNUR.","se informará al Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se dará audiencia al ACNUR</mark></span>El <span class=\"ref-norma\">art. 35.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Con carácter previo a dictarse las resoluciones que sobre estas solicitudes prevén los apartados primero, segundo y tercero del artículo 21 de la presente Ley, se dará audiencia al ACNUR\"</span>. Se da audiencia al ACNUR. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 6 — Participación pública ✱ R2","q":[{"i":"6-72","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Participación Pública. Señale la CORRECTA:","o":["Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley.","Los Ayuntamientos no podrán reconocer ni padronar a los extranjeros que no tengan domicilio habitual en el municipio y mantener actualizada la información relativa a los mismos.","Los poderes públicos facilitarán el ejercicio del derecho de sufragio de los extranjeros en los procesos electorales (elecciones de España).","Los extranjeros residentes, empadronados o no, en el municipio, tienen todos los derechos establecidos por ley concursal en la legislación de bases de régimen local, pudiendo no ser oídos en los asuntos que les afecten de acuerdo con lo que disponga la normativa de aplicación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-161","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Los extranjeros residentes en España podrán ser titulares del derecho de sufragio en:","o":["Las elecciones nacionales.","Las elecciones autonómicas.","Las elecciones municipales.","Las elecciones provinciales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las elecciones municipales</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-164","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Participación Pública. Los extranjeros residentes en España podrán:","o":["Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos por el Gobierno, en los tratados internacionales, en su caso, y en la Ley.","Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos por el Gobierno y en los tratados internacionales y en la Ley.","Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-181","p":"Ley Orgánica 4/2000... Participación Pública. Señale la CORRECTA.","o":["Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales.","Los Ayuntamientos no podrán incorporar el padrón a los extranjeros que tengan su domicilio habitual en el municipio.","Los poderes públicos facilitarán el ejercicio del derecho de sufragio de los extranjeros en los procesos electorales democráticos de España.","Todos son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-213","p":"Ley Orgánica 4/2000... Los extranjeros residentes en España podrán ser titulares del derecho de sufragio en:","o":["Las elecciones nacionales.","Las elecciones autonómicas.","Las elecciones municipales.","Las elecciones provinciales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las elecciones municipales</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-225","p":"Ley Orgánica 4/2000... Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: Señale la opción INCORRECTA.","o":["Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española.","Los extranjeros residentes en España.","El cónyuge o hijo de extranjero residente en España con una autorización renovada.","Los titulares de una autorización previa de trabajo que pretendan su renovación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los extranjeros residentes en España</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"f) Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española. g) Los extranjeros nacidos y residentes en España\"</span>. Es «nacidos y residentes» (Verificado con el texto del temario oficial.)"},{"i":"6-291","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Los extranjeros residentes en España podrán ser titulares del derecho de sufragio en:","o":["Las elecciones nacionales.","Las elecciones autonómicas.","Las elecciones municipales.","Las elecciones provinciales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las elecciones municipales</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-294","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Participación Pública. Los extranjeros residentes en España podrán:","o":["Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos por el Gobierno, en los tratados internacionales, en su caso, y en la Ley.","Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos por el Gobierno y en los tratados internacionales y en la Ley.","Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-309","p":"Ley Orgánica 4/2000... Participación Pública. Señale la CORRECTA.","o":["Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales.","Los Ayuntamientos no podrán incorporar el padrón a los extranjeros que tengan su domicilio habitual en el municipio.","Los poderes públicos facilitarán el ejercicio del derecho de sufragio de los extranjeros en los procesos electorales democráticos de España.","Todos son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales</mark></span>Según el <span class=\"ref-norma\">art. 6.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros residentes en España podrán ser titulares del derecho de sufragio, en las elecciones municipales, en los términos establecidos en la Constitución, en los tratados internacionales, en su caso, y en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-340","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Participación pública. Los poderes públicos facilitarán el ejercicio del derecho de sufragio de los extranjeros:","o":["En los procesos electorales democráticos del país de origen.","En las elecciones municipales y autonómicas del Estado de residencia.","En las elecciones al Parlamento Europeo cuando sean nacionales de la Unión.","En todos los procesos electorales celebrados en España, previa inscripción en el padrón."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En los procesos electorales democráticos del país de origen</mark></span>El <span class=\"ref-norma\">art. 6.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"4. Los poderes públicos facilitarán el ejercicio del derecho de sufragio de los extranjeros en los procesos electorales democráticos del país de origen.\"</span>"}]},{"a":"Artículo 38 — Solicitudes de protección internacional en Embajadas y Consulados","q":[{"i":"6-75","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes de protección internacional en embajadas y consulados. Con el fin de atender casos que se presenten fuera del territorio nacional siempre y cuando el solicitante no sea nacional del país en que se encuentre la Representación diplomática y corra peligro su integridad física:","o":["Los Embajadores de España podrán promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley.","Las Embajadas Internacionales podrán promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento administrativo.","Las Embajadas Europeas podrán promover el traslado del o de los solicitantes de asilo a España o a otro miembro para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley.","El Ejecutivo podrá promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Embajadores de España podrán promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley</mark></span>Según el <span class=\"ref-norma\">art. 38 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"los Embajadores de España podrán promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley\"</span>. Son los Embajadores de España (Verificado con el texto del temario oficial.)"},{"i":"6-129","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes de protección internacional en Embajadas y Consulados. Con el fin de atender casos que se presenten fuera del territorio nacional, siempre y cuando el solicitante no sea nacional del país en que se encuentre la Representación diplomática y corra peligro su integridad física, podrán promover el traslado del o de los solicitantes de asilo a España:","o":["Los Embajadores de España.","Los Cónsules honorarios de España.","El Ministro de Asuntos Exteriores.","La Oficina de Asilo y Refugio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Embajadores de España</mark></span>Según el <span class=\"ref-norma\">art. 38 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"los Embajadores de España podrán promover el traslado del o de los solicitantes de asilo a España para hacer posible la presentación de la solicitud conforme al procedimiento previsto en esta Ley\"</span>. El enunciado estaba incompleto; se reformula con el texto literal (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1607","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Solicitudes de protección internacional en Embajadas y Consulados. El Reglamento de desarrollo de la Ley 12/2009 determinará expresamente, en relación con las solicitudes presentadas fuera del territorio nacional:","o":["los países en los que las Embajadas y Consulados podrán recibir solicitudes de protección internacional y el número máximo de traslados anuales.","las condiciones de acceso a las Embajadas y Consulados y el plazo para resolver las solicitudes presentadas en el extranjero.","las condiciones de acceso a las Embajadas y Consulados de los solicitantes, así como el procedimiento para evaluar las necesidades de traslado a España.","el procedimiento de concesión de visados humanitarios por las misiones diplomáticas, previo informe del ACNUR."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las condiciones de acceso a las Embajadas y Consulados de los solicitantes, así como el procedimiento para evaluar las necesidades de traslado a España</mark></span>El <span class=\"ref-norma\">art. 38 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El Reglamento de desarrollo de esta Ley determinará expresamente las condiciones de acceso a las Embajadas y Consulados de los solicitantes, así como el procedimiento para evaluar las necesidades de traslado a España de los mismos\"</span>. Condiciones de acceso y procedimiento para evaluar las necesidades de traslado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Derecho a la libertad de circulación ✱","q":[{"i":"6-76","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la libre circulación. Podrán establecerse medidas limitativas específicas ......................................... excepcionalmente por razones de seguridad pública, de forma individualizada, motivada y en proporción a las circunstancias que concurran en cada caso, por resolución del Ministro del Interior, adoptada de acuerdo con las garantías jurídicas del procedimiento sancionador previsto en la Ley.","o":["Cuando se acuerden en la declaración de estado de alarma, excepción o de sitio, en los términos previstos en la Constitución.","Sólo cuando se acuerden en la declaración de estado de alarma o excepción, en los términos previstos en la Constitución.","Sólo cuando se acuerden en la declaración de estado de alarma o de sitio, en los términos previstos en la Constitución.","Cuando se acuerden en la declaración de estado de excepción o de sitio, en los términos previstos en la Constitución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se acuerden en la declaración de estado de excepción o de sitio, en los términos previstos en la Constitución</mark></span>Según el <span class=\"ref-norma\">art. 5.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"No obstante, podrán establecerse medidas limitativas específicas cuando se acuerden en la declaración de estado de excepción o de sitio, en los términos previstos en la Constitución, y, excepcionalmente por razones de seguridad pública, de forma individualizada, motivada y en proporción a las circunstancias que concurran en cada caso, por resolución del Ministro del Interior, adoptada de acuerdo con las garantías jurídicas del procedimiento sancionador previsto en la Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1012","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la libertad de circulación. Los extranjeros que se hallen en España de acuerdo con lo establecido en la Ley tendrán derecho a circular libremente por el territorio español y a elegir su residencia sin más limitaciones que las establecidas con carácter general por los tratados y las leyes, o las acordadas por la autoridad judicial, con carácter cautelar o en un proceso penal o de extradición en el que el extranjero tenga la condición de:","o":["imputado o condenado, o como consecuencia de resolución administrativa firme.","imputado, víctima o testigo, o como consecuencia de sentencia firme.","imputado o perjudicado, siempre que lo acuerde el Ministerio Fiscal.","acusado o testigo protegido, o como consecuencia de orden de expulsión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">imputado, víctima o testigo, o como consecuencia de sentencia firme</mark></span>El <span class=\"ref-norma\">art. 5.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"en un proceso penal o de extradición en el que el extranjero tenga la condición de imputado, víctima o testigo, o como consecuencia de sentencia firme\"</span>. La ley enumera imputado, víctima o testigo, o sentencia firme. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1624","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Completado el expediente de cese o revocación, será remitido por la Oficina de Asilo y Refugio a la Comisión Interministerial de Asilo y Refugio, que:","o":["resolverá directamente sobre el cese o la revocación, previo informe del ACNUR, sin ulterior recurso en vía administrativa ni posibilidad de reposición.","ordenará el archivo si no concurren causas suficientes o, si procede el cese o la revocación, elevará la propuesta de resolución al Ministro del Interior.","emitirá informe preceptivo y lo devolverá a la Oficina de Asilo y Refugio para que resuelva en el plazo de un mes.","elevará en todo caso la propuesta al Consejo de Ministros, que resolverá sobre el cese o la revocación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ordenará el archivo si no concurren causas suficientes o, si procede el cese o la revocación, elevará la propuesta de resolución al Ministro del Interior</mark></span>El <span class=\"ref-norma\">art. 45.4 y 45.5 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Si ésta entendiese que no concurren causas suficientes para proceder a la declaración de cese o revocación, ordenará el archivo del expediente\"</span>. La CIAR archiva o eleva propuesta al Ministro del Interior, que resuelve. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 43 — Cese de la protección subsidiaria ✱","q":[{"i":"6-78","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Del cese y la revocación de la protección internacional. La protección subsidiaria cesará cuando; señale la INCORRECTA:","o":["Se solicite expresamente por la persona beneficiaria.","La persona beneficiaria haya abandonado el territorio español y fijado su residencia en otro país.","Las circunstancias que condujeron a su concesión dejen de existir o cambien de tal forma que dicha protección ya no sea necesaria.","Se hayan acogido de nuevo, voluntariamente, a la protección del país de su nacionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se hayan acogido de nuevo, voluntariamente, a la protección del país de su nacionalidad</mark></span>Según el <span class=\"ref-norma\">art. 43.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) la persona beneficiaria haya abandonado el territorio español y fijado su residencia en otro país\"</span>. Acogerse de nuevo a la protección del país de su nacionalidad es causa de cese del estatuto de REFUGIADO (Verificado con el texto del temario oficial.)"},{"i":"6-123","p":"(Ley 12/2009) Señale cuándo cesa la protección subsidiaria.","o":["Se solicite expresamente por la persona beneficiaria.","La persona beneficiaria haya abandonado el territorio español y fijado su residencia en otro país.","Las circunstancias que condujeron a su concesión dejen de existir o cambien de tal forma que dicha protección ya no sea necesaria.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 43.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"a) se solicite expresamente por la persona beneficiaria; b) la persona beneficiaria haya abandonado el territorio español y fijado su residencia en otro país; c) las circunstancias que condujeron a su concesión dejen de existir o cambien de tal forma que dicha protección ya no sea necesaria\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1618","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cese de la protección subsidiaria. La protección subsidiaria cesará cuando las circunstancias que condujeron a su concesión dejen de existir o cambien de tal forma que dicha protección ya no sea necesaria. A estos efectos, el Estado español tendrá en cuenta si el cambio de circunstancias:","o":["ha sido declarado por el ACNUR mediante informe razonado sobre la situación general del país de origen.","se ha mantenido durante un plazo mínimo de un año desde la concesión de la protección subsidiaria.","es de carácter temporal o permanente, siempre que reduzca de forma apreciable el riesgo de sufrir daños graves en el país de origen o de residencia habitual.","es lo suficientemente significativo, sin ser de carácter temporal, como para que la persona ya no corra un riesgo real de sufrir daños graves."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">es lo suficientemente significativo, sin ser de carácter temporal, como para que la persona ya no corra un riesgo real de sufrir daños graves</mark></span>El <span class=\"ref-norma\">art. 43.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"El Estado español tendrá en cuenta si el cambio de circunstancias es lo suficientemente significativo, sin ser de carácter temporal, como para que la persona con derecho a protección subsidiaria ya no corra un riesgo real de sufrir daños graves\"</span>. Cambio suficientemente significativo y no temporal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 45 — Procedimientos para el cese y la revocación ✱","q":[{"i":"6-79","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Señale la INCORRECTA:","o":["Los ceses y revocaciones conllevarán el cese en el disfrute de todos los derechos inherentes a la condición de refugiado o persona beneficiaria de protección subsidiaria.","Las resoluciones previstas para el cese y revocación serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior.","Las resoluciones previstas para el cese y revocación serán susceptibles de recurso contencioso-administrativo.","Las resoluciones previstas para el cese y revocación serán susceptibles de recurso de alzada ante el Ministro del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones previstas para el cese y revocación serán susceptibles de recurso de alzada ante el Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 45.8 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en este Título pondrán fin a la vía administrativa y serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior y de recurso contencioso-administrativo\"</span>. No cabe recurso de alzada (Verificado con el texto del temario oficial.)"},{"i":"6-101","p":"En los supuestos de cese y revocación del estatuto de refugiado o de la protección subsidiaria, la persona afectada disfrutará, además de las previstas en el artículo 17, de las siguientes garantías: Señale la Incorrecta.","o":["Que sea informada por escrito de que se está reconsiderando su derecho de asilo o de protección subsidiaria, así como de los motivos de dicha reconsideración.","Que se le sea otorgado el plazo de seis meses para la formulación de alegaciones.","Que la autoridad competente pueda obtener información precisa y actualizada de diversas fuentes, como por ejemplo, cuando proceda, del Alto Comisionado de las Naciones Unidas para los Refugiados (ACNUR), sobre la situación general existente en los países de origen de las personas afectadas.","Que cuando se recopile información sobre el caso concreto con objeto de reconsiderar el estatuto de refugiado, dicha información no se obtenga de los responsables de la persecución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que se le sea otorgado el plazo de seis meses para la formulación de alegaciones</mark></span>Según el <span class=\"ref-norma\">art. 45.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) que le sea otorgado trámite de audiencia para la formulación de alegaciones\"</span>. No hay plazo de seis meses para alegaciones (se corrigen C y D, que venían alteradas) (Verificado con el texto del temario oficial.)"},{"i":"6-159","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. El plazo para la notificación de las resoluciones recaídas en estos procedimientos será de _________ a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación. Concluido dicho plazo, y habida cuenta de las suspensiones o ampliaciones que fuesen aplicables, se tendrá por caducado el expediente, procediéndose de oficio a su archivo.","o":["Dos meses.","Seis meses.","Tres meses.","Un mes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 45.7 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El plazo para la notificación de las resoluciones recaídas en estos procedimientos será de seis meses a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación\"</span>. Se corrige el enunciado («acuerdo de incoación del procedimiento de cese o revocación») (Verificado con el texto del temario oficial.)"},{"i":"6-251","p":"(Ley 12/2009) Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Procedimientos para el cese y la revocación. El plazo para resolver y notificar estos procedimientos será de ___________ a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación.","o":["Seis meses.","Diez meses.","Tres meses.","Quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 45.7 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El plazo para la notificación de las resoluciones recaídas en estos procedimientos será de seis meses a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-287","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. El plazo para la notificación de las resoluciones recaídas en estos procedimientos será de _________ a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación. Concluido dicho plazo, y habida cuenta de las suspensiones o ampliaciones que fuesen aplicables, se tendrá por caducado el expediente, procediéndose de oficio a su archivo.","o":["Dos meses.","Seis meses.","Tres meses.","Un mes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 45.7 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El plazo para la notificación de las resoluciones recaídas en estos procedimientos será de seis meses a partir de la presentación de la solicitud por la persona interesada o de la notificación del acuerdo de incoación del procedimiento de cese o revocación\"</span>. Se corrige el enunciado («acuerdo de incoación del procedimiento de cese o revocación») (Verificado con el texto del temario oficial.)"},{"i":"6-453","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. En los procedimientos para el cese y la revocación se garantizará, cuando se recopile información sobre el caso concreto con objeto de reconsiderar el estatuto de refugiado:","o":["Que dicha información se obtenga preferentemente de las autoridades del país de origen del refugiado, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","Que la persona interesada sea informada con carácter previo de todas las fuentes consultadas.","Que dicha información no se obtenga de los responsables de la persecución de modo tal que dé lugar a que sean informados directamente de que la persona interesada es un refugiado cuyo estatuto está siendo reconsiderado.","Que dicha información se recopile exclusivamente a través de la Oficina del ACNUR en España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Que dicha información no se obtenga de los responsables de la persecución de modo tal que dé lugar a que sean informados directamente de que la persona interesada es un refugiado cuyo estatuto está siendo reconsiderado</mark></span>El <span class=\"ref-norma\">art. 45.2.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) que cuando se recopile información sobre el caso concreto con objeto de reconsiderar el estatuto de refugiado, dicha información no se obtenga de los responsables de la persecución de modo tal que dé lugar a que dichos responsables sean informados directamente de que la persona interesada es un refugiado cuyo estatuto está siendo reconsiderado\"</span>"},{"i":"6-ia-1625","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Los ceses y revocaciones de la protección internacional conllevarán:","o":["el cese en el disfrute de todos los derechos inherentes a la condición de refugiado o persona beneficiaria de protección subsidiaria.","el cese en el disfrute de los derechos inherentes a la condición de refugiado, salvo el de residencia, que se mantendrá en todo caso.","la expulsión inmediata del territorio nacional sin necesidad de tramitar un nuevo expediente administrativo sancionador.","la prohibición de entrada en territorio español durante cinco años desde la notificación de la resolución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el cese en el disfrute de todos los derechos inherentes a la condición de refugiado o persona beneficiaria de protección subsidiaria</mark></span>El <span class=\"ref-norma\">art. 45.6 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los ceses y revocaciones conllevarán el cese en el disfrute de todos los derechos inherentes a la condición de refugiado o persona beneficiaria de protección subsidiaria\"</span>. Se pierden todos los derechos inherentes al estatuto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Derecho a la educación ✱ R3","q":[{"i":"6-80","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la educación. Los extranjeros residentes mayores de dieciocho años tienen el derecho a:","o":["Al acceso a los demás estudios postobligatorios.","A la obtención de las titulaciones correspondientes.","A acceder al sistema público de becas en las mismas condiciones que los españoles.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"los extranjeros residentes mayores de dieciocho años tienen el derecho a acceder a las demás etapas educativas posobligatorias, a la obtención de las titulaciones correspondientes, y al sistema público de becas en las mismas condiciones que los españoles\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-127","p":"(Ley Orgánica 4/2000) Derecho a la educación. Señale la CORRECTA.","o":["Los extranjeros mayores de dieciocho años también tienen derecho a la enseñanza postobligatoria.","Este derecho incluye la obtención de la titulación académica correspondiente, pero no el acceso al sistema público de becas y ayudas en las mismas condiciones que los españoles.","Si el menor alcanza la edad de dieciocho años en el transcurso del curso escolar, conservará ese derecho hasta su finalización.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si el menor alcanza la edad de dieciocho años en el transcurso del curso escolar, conservará ese derecho hasta su finalización</mark></span>Según el <span class=\"ref-norma\">art. 9.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En caso de alcanzar la edad de dieciocho años en el transcurso del curso escolar, conservarán ese derecho hasta su finalización\"</span>. La B era también literal; se reformula como falsa (Verificado con el texto del temario oficial.)"},{"i":"6-183","p":"Ley Orgánica 4/2000... Derecho a la educación. Los extranjeros tienen el derecho y el deber a la educación, que incluye el acceso a una enseñanza básica, gratuita y obligatoria:","o":["Los menores de veintiocho años.","Los menores de catorce años.","Los menores de dieciocho años.","Los menores de dieciséis años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los menores de dieciséis años</mark></span>Los menores de dieciocho tienen derecho a la enseñanza POSOBLIGATORIA, no a la básica obligatoria. Según el <span class=\"ref-norma\">art. 9.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros menores de dieciséis años tienen el derecho y el deber a la educación, que incluye el acceso a una enseñanza básica, gratuita y obligatoria.\"</span> (verificado con el texto del temario)."},{"i":"6-311","p":"Ley Orgánica 4/2000... Derecho a la educación. Los extranjeros tienen el derecho y el deber a la educación, que incluye el acceso a una enseñanza básica, gratuita y obligatoria:","o":["Los menores de veintiocho años.","Los menores de catorce años.","Los menores de dieciocho años.","Los menores de dieciséis años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los menores de dieciséis años</mark></span>Los menores de dieciocho tienen derecho a la enseñanza POSOBLIGATORIA, no a la básica obligatoria. Según el <span class=\"ref-norma\">art. 9.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros menores de dieciséis años tienen el derecho y el deber a la educación, que incluye el acceso a una enseñanza básica, gratuita y obligatoria.\"</span> (verificado con el texto del temario)."},{"i":"6-344","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la educación. Los poderes públicos promoverán que los extranjeros puedan recibir:","o":["Enseñanzas para su mejor integración social.","Enseñanzas de su lengua y cultura de origen en los centros públicos.","Formación profesional gratuita durante el primer año de residencia.","Enseñanzas del idioma oficial, con carácter obligatorio y gratuito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Enseñanzas para su mejor integración social</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Los poderes públicos promoverán que los extranjeros puedan recibir enseñanzas para su mejor integración social.\"</span>"},{"i":"6-ia-1016","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la educación. Los extranjeros residentes que tengan en España menores a su cargo en edad de escolarización obligatoria deberán acreditar dicha escolarización, en las solicitudes de renovación de su autorización o en su solicitud de residencia de larga duración, mediante informe emitido por:","o":["el centro educativo en el que esté matriculado el menor.","las autoridades autonómicas competentes.","los servicios sociales del Ayuntamiento de residencia.","la Alta Inspección de Educación del Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las autoridades autonómicas competentes</mark></span>El <span class=\"ref-norma\">art. 9.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"deberán acreditar dicha escolarización, mediante informe emitido por las autoridades autonómicas competentes\"</span>. El informe lo emiten las autoridades autonómicas competentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 19 — Efectos de la reagrupación familiar en circunstancias especiales ✱","q":[{"i":"6-83","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Entrada y permanencia de extranjeros en España. Efectos de la reagrupación familiar en circunstancias especiales; señale la INCORRECTA:","o":["El cónyuge reagrupado podrá obtener una autorización de residencia independiente cuando disponga de medios económicos suficientes para cubrir sus propias necesidades.","El cónyuge reagrupado podrá obtener una autorización de residencia independiente sin el requisito exclusivo de alcanzar la mayoría de edad.","En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen.","La autorización de residencia por reagrupación familiar, de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral, habilitará para trabajar sin necesidad de ningún otro trámite administrativo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El cónyuge reagrupado podrá obtener una autorización de residencia independiente sin el requisito exclusivo de alcanzar la mayoría de edad</mark></span>Según el <span class=\"ref-norma\">art. 19.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El cónyuge reagrupado podrá obtener una autorización de residencia independiente cuando disponga de medios económicos suficientes para cubrir sus propias necesidades\"</span>. La «mayoría de edad» es requisito de los hijos reagrupados, no del cónyuge (Verificado con el texto del temario oficial.)"},{"i":"6-91","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la reagrupación familiar en circunstancias especiales. Señale la Incorrecta.","o":["La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral, habilita para trabajar cumpliendo con los trámites administrativos que se establezcan reglamentariamente.","El cónyuge reagrupado podrá obtener una autorización de residencia independiente cuando disponga de medios económicos suficientes para cubrir sus propias necesidades.","Los hijos reagrupados podrán obtener una autorización de residencia independiente cuando alcancen la mayoría de edad y dispongan de medios económicos suficientes para cubrir sus propias necesidades.","En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral, habilita para trabajar cumpliendo con los trámites administrativos que se establezcan reglamentariamente</mark></span>Según el <span class=\"ref-norma\">art. 19.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral, habilitará para trabajar sin necesidad de ningún otro trámite administrativo\"</span>. Sin necesidad de ningún otro trámite administrativo (Verificado con el texto del temario oficial.)"},{"i":"6-110","p":"(Ley Orgánica 4/2000) Efectos de la reagrupación familiar en circunstancias especiales. La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral:","o":["Habilitará para trabajar tras la anterior introducción en el sistema de seguridad social.","Habilitará para trabajar sin necesidad de ningún otro trámite judicial.","Habilitará para trabajar sin necesidad de ningún otro trámite administrativo.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Habilitará para trabajar sin necesidad de ningún otro trámite administrativo</mark></span>Según el <span class=\"ref-norma\">art. 19.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral, habilitará para trabajar sin necesidad de ningún otro trámite administrativo\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-118","p":"(Ley Orgánica 4/2000) Efectos de la reagrupación familiar en circunstancias especiales. Señale la CORRECTA.","o":["El cónyuge reagrupado podrá obtener una autorización de residencia independiente aunque no disponga de medios económicos suficientes para cubrir sus propias necesidades.","No obstante, si la Ley determinara la cuantía de los medios económicos suficientes o condiciones suficientes para que el familiar reagrupado pudiera obtener una autorización independiente.","En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen.","Los hijos reagrupados podrán obtener una autorización de residencia independiente cuando alcancen la mayoría de edad, si los padres o los tutores lo autorizan, y dispongan de medios económicos suficientes para cubrir sus propias necesidades."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen</mark></span>Según el <span class=\"ref-norma\">art. 19.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-191","p":"Ley Orgánica 4/2000... Efectos de la reagrupación familiar en circunstancias especiales. Señale la INCORRECTA:","o":["La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral habilitará para trabajar sin necesidad de ningún otro trámite administrativo.","El cónyuge reagrupado podrá obtener una autorización de residencia independiente cuando disponga de medios económicos suficientes para cubrir sus propias necesidades.","En caso de que la cónyuge reagrupada fuera víctima de violencia de género, sin necesidad de que se haya cumplido el requisito anterior, podrá obtener la autorización de residencia y trabajo independiente, desde el momento en que se hubiera dictado a su favor una orden de protección o, en su defecto, informe del Ministerio Fiscal que indique la existencia de indicios de violencia de género.","En caso de muerte del reagrupante, los familiares reagrupados no podrán obtener una autorización de residencia independiente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En caso de muerte del reagrupante, los familiares reagrupados no podrán obtener una autorización de residencia independiente</mark></span>Según el <span class=\"ref-norma\">art. 19.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-317","p":"Ley Orgánica 4/2000... Efectos de la reagrupación familiar en circunstancias especiales. Señale la INCORRECTA:","o":["La autorización de residencia por reagrupación familiar de la que sean titulares el cónyuge e hijos reagrupados cuando alcancen la edad laboral habilitará para trabajar sin necesidad de ningún otro trámite administrativo.","El cónyuge reagrupado podrá obtener una autorización de residencia independiente cuando disponga de medios económicos suficientes para cubrir sus propias necesidades.","En caso de que la cónyuge reagrupada fuera víctima de violencia de género, sin necesidad de que se haya cumplido el requisito anterior, podrá obtener la autorización de residencia y trabajo independiente, desde el momento en que se hubiera dictado a su favor una orden de protección o, en su defecto, informe del Ministerio Fiscal que indique la existencia de indicios de violencia de género.","En caso de muerte del reagrupante, los familiares reagrupados no podrán obtener una autorización de residencia independiente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En caso de muerte del reagrupante, los familiares reagrupados no podrán obtener una autorización de residencia independiente</mark></span>Según el <span class=\"ref-norma\">art. 19.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-349","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la reagrupación familiar. Los hijos reagrupados podrán obtener una autorización de residencia independiente cuando alcancen la mayoría de edad y:","o":["Hayan residido en España al menos cinco años de forma continuada.","Acrediten un contrato de trabajo por cuenta ajena de duración superior a un año.","Dispongan de vivienda adecuada y de informe positivo de la Comunidad Autónoma.","Dispongan de medios económicos suficientes para cubrir sus propias necesidades."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Dispongan de medios económicos suficientes para cubrir sus propias necesidades</mark></span>El <span class=\"ref-norma\">art. 19.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Los hijos reagrupados podrán obtener una autorización de residencia independiente cuando alcancen la mayoría de edad y dispongan de medios económicos suficientes para cubrir sus propias necesidades.\"</span>"},{"i":"6-454","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Menores no acompañados. Los menores no acompañados solicitantes de protección internacional serán remitidos a los servicios competentes en materia de protección de menores y el hecho se pondrá en conocimiento:","o":["Del Defensor del Pueblo.","Del Ministerio Fiscal.","De la Oficina de Asilo y Refugio.","Del Consejo de Ministros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 48.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"1. Los menores no acompañados solicitantes de protección internacional serán remitidos a los servicios competentes en materia de protección de menores y el hecho se pondrá en conocimiento del Ministerio Fiscal.\"</span>"}]},{"a":"Artículo 42 — Régimen especial de los trabajadores de temporada EX ✱","q":[{"i":"6-84","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen especial de los trabajadores de temporada. Para conceder las autorizaciones de residencia y trabajo deberá garantizarse que los trabajadores temporeros serán alojados en condiciones de:","o":["Dignidad e higiene adecuadas.","Habitabilidad adecuadas.","Seguridad e higiene adecuadas.","Ventilación e iluminación adecuadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dignidad e higiene adecuadas</mark></span>Según el <span class=\"ref-norma\">art. 42.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"deberá garantizarse que los trabajadores temporeros serán alojados en condiciones de dignidad e higiene adecuadas\"</span>. Es «dignidad e higiene», no «seguridad e higiene» (la respuesta estaba mal marcada) (Verificado con el texto del temario oficial.)"},{"i":"6-226","p":"Ley Orgánica 4/2000... Régimen especial de los trabajadores de temporada. Señale la CORRECTA.","o":["Las Administraciones públicas promoverán la asistencia de los servicios sociales adecuados.","El Gobierno regulará reglamentariamente la autorización de residencia y trabajo para los trabajadores extranjeros en actividades de temporada o campaña que les permita la entrada y salida del territorio nacional, así como la documentación de su situación, de acuerdo con las características de las citadas campañas y la información que le suministren las Comunidades Autónomas donde se promuevan.","Las Comunidades Autónomas, los Ayuntamientos y los agentes sociales promoverán los circuitos que permitan la concatenación de los trabajadores de temporada, en colaboración con la Administración General del Estado.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 42.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Comunidades Autónomas, los Ayuntamientos y los agentes sociales promoverán los circuitos que permitan la concatenación de los trabajadores de temporada, en colaboración con la Administración General del Estado\"</span>. Se corrigen B y C, que venían alteradas («promulgan», «Comisiones», «contratación») (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1219","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen especial de los trabajadores de temporada. Promoverán los circuitos que permitan la concatenación de los trabajadores de temporada, en colaboración con la Administración General del Estado:","o":["Las Comunidades Autónomas, los Servicios Públicos de Empleo y las organizaciones sindicales.","Los Ayuntamientos y las organizaciones no gubernamentales.","Las Comunidades Autónomas, los Ayuntamientos y los agentes sociales.","La Comisión Laboral Tripartita y las Comunidades Autónomas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Comunidades Autónomas, los Ayuntamientos y los agentes sociales</mark></span>El <span class=\"ref-norma\">art. 42.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las Comunidades Autónomas, los Ayuntamientos y los agentes sociales promoverán los circuitos que permitan la concatenación de los trabajadores de temporada, en colaboración con la Administración General del Estado\"</span>. Son las Comunidades Autónomas, los Ayuntamientos y los agentes sociales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"General / Entrada y Permanencia de Extranjeros en España","q":[{"i":"6-85","p":"Extensión familiar del derecho de asilo o de la protección subsidiaria. El restablecimiento de la unidad familiar de las personas refugiadas y beneficiarias de protección subsidiaria podrá garantizarse mediante la concesión, respectivamente, del derecho de asilo o de la protección subsidiaria por extensión familiar, en los siguientes supuestos: Señale la INCORRECTA.","o":["Los ascendientes en primer grado que acreditasen la dependencia y sus descendientes en primer grado que fueran menores de edad, quedando exceptuado el derecho a la extensión familiar en los supuestos de distinta nacionalidad.","El cónyuge o persona ligada por análoga relación de afectividad y convivencia, con excepción única en los supuestos de divorcio, guarda o el impedimento de la solicitud, quedando exceptuado el derecho a la extensión familiar a la persona que ha sufrido o temido fundados intereses de sufrir persecución o discriminación por violencia de género o por parte de su cónyuge o conviviente.","Las relaciones familiares de los ascendientes y descendientes deberán establecerse mediante las pruebas científicas que sean necesarias, en los casos donde no pueda determinarse sin dudas esa relación de parentesco.","Otro adulto que sea responsable del beneficiario de protección internacional, de acuerdo con la legislación española vigente, cuando dicho beneficiario sea menor no casado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El cónyuge o persona ligada por análoga relación de afectividad y convivencia, con excepción única en los supuestos de divorcio, guarda o el impedimento de la solicitud, quedando exceptuado el derecho a la extensión familiar a la persona que ha sufrido o temido fundados intereses de sufrir persecución o discriminación por violencia de género o por parte de su cónyuge o conviviente</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) El cónyuge o persona ligada por análoga relación de afectividad y convivencia, salvo los supuestos de divorcio, separación legal, separación de hecho, distinta nacionalidad o concesión del estatuto de refugiado por razón de género\"</span>. Se corrige A, que también venía alterada (Verificado con el texto del temario oficial.)"},{"i":"6-98","p":"Situación de residencia temporal. La residencia temporal es la situación que autoriza a permanecer en España por un periodo superior a ______ inferior a cinco años. Las autorizaciones de duración inferior a cinco años podrán renovarse, a petición del interesado, atendiendo a las circunstancias que motivaron su concesión. La duración de las autorizaciones iniciales de residencia temporal y de las renovaciones se establecerá reglamentariamente.","o":["30 días","60 días","90 días","Todos son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">90 días</mark></span>Según el <span class=\"ref-norma\">art. 31.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La residencia temporal es la situación que autoriza a permanecer en España por un período superior a 90 días e inferior a cinco años\"</span>. (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 14 — Derecho a la Seguridad Social y a los servicios sociales R4","q":[{"i":"6-87","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la libertad de circulación. Señale la INCORRECTA.","o":["Podrán establecerse medidas limitativas específicas en cuanto al derecho de libertad de circulación de los extranjeros que se hallen en España, cuando así aconsejen la declaración de estado de alarma, excepción o de sitio...","Los extranjeros tienen el derecho de reunión en las mismas condiciones que los españoles.","Todos los extranjeros tienen el derecho de asociación en las mismas condiciones que los españoles.","Los extranjeros podrán ejercer el derecho a la huelga en las mismas condiciones que los españoles."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrán establecerse medidas limitativas específicas en cuanto al derecho de libertad de circulación de los extranjeros que se hallen en España, cuando así aconsejen la declaración de estado de alarma, excepción o de sitio..</mark></span>Según el <span class=\"ref-norma\">art. 5.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"podrán establecerse medidas limitativas específicas cuando se acuerden en la declaración de estado de excepción o de sitio\"</span>. El estado de alarma no figura (se sustituye D, que no estaba en el temario) (Verificado con el texto del temario oficial.)"},{"i":"6-130","p":"(Ley Orgánica 4/2000) Criterio interpretativo general de la Ley Orgánica 4/2000.","o":["Según la Declaración Universal de Derechos Humanos.","Según los tratados y convenios internacionales sobre las mismas materias vigentes en España.","En condiciones de igualdad con los españoles.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En condiciones de igualdad con los españoles</mark></span>Según el <span class=\"ref-norma\">art. 3.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Como criterio interpretativo general, se entenderá que los extranjeros ejercitan los derechos que les reconoce esta Ley en condiciones de igualdad con los españoles\"</span>. La Declaración Universal y los tratados sirven para interpretar las normas sobre derechos FUNDAMENTALES; el «criterio interpretativo general» es la igualdad con los españoles (Verificado con el texto del temario oficial.)"},{"i":"6-175","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la Seguridad Social y a los servicios sociales. Señale la INCORRECTA.","o":["Los extranjeros residentes tienen derecho a acceder a las prestaciones y servicios de la Seguridad Social en las mismas condiciones que los españoles.","Los extranjeros residentes tienen derecho a los servicios y a las prestaciones sociales, tanto a los generales o básicos como a los específicos, en las mismas condiciones que los españoles.","En cualquier caso, los extranjeros con discapacidad, menores de dieciocho años, que tengan su domicilio habitual en España, tendrán derecho a recibir el tratamiento, servicios y cuidados especiales que exija su estado físico o psíquico.","Los extranjeros que se encuentren en España tienen derecho a la asistencia sanitaria pública de forma gratuita."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los extranjeros que se encuentren en España tienen derecho a la asistencia sanitaria pública de forma gratuita</mark></span>Según el <span class=\"ref-norma\">art. 12 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros tienen derecho a la asistencia sanitaria en los términos previstos en la legislación vigente en materia sanitaria\"</span>. Se corrige C («menores de dieciocho años») (Verificado con el texto del temario oficial.)"},{"i":"6-304","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la Seguridad Social y a los servicios sociales. Señale la INCORRECTA.","o":["Los extranjeros residentes tienen derecho a acceder a las prestaciones y servicios de la Seguridad Social en las mismas condiciones que los españoles.","Los extranjeros residentes tienen derecho a los servicios y a las prestaciones sociales, tanto a los generales o básicos como a los específicos, en las mismas condiciones que los españoles.","En cualquier caso, los extranjeros con discapacidad, menores de dieciocho años, que tengan su domicilio habitual en España, tendrán derecho a recibir el tratamiento, servicios y cuidados especiales que exija su estado físico o psíquico.","Los extranjeros que se encuentren en España tienen derecho a la asistencia sanitaria pública de forma gratuita."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los extranjeros que se encuentren en España tienen derecho a la asistencia sanitaria pública de forma gratuita</mark></span>Según el <span class=\"ref-norma\">art. 12 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros tienen derecho a la asistencia sanitaria en los términos previstos en la legislación vigente en materia sanitaria\"</span>. Se corrige C («menores de dieciocho años») (Verificado con el texto del temario oficial.)"},{"i":"6-341","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Libertades de reunión y manifestación. Los extranjeros tienen el derecho de reunión:","o":["En las condiciones que establezca el Gobierno mediante real decreto.","Solo en lugares cerrados y con autorización de la autoridad gubernativa.","Siempre que se encuentren en situación de residencia temporal o de larga duración.","En las mismas condiciones que los españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Los extranjeros tienen el derecho de reunión en las mismas condiciones que los españoles.\"</span>"},{"i":"6-342","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Libertad de asociación. Todos los extranjeros tienen el derecho de asociación:","o":["En las condiciones que fije su normativa nacional de origen.","Solo los extranjeros residentes, con exclusión de los que se hallen en situación de estancia.","En las mismas condiciones que los españoles.","En las condiciones que determine la Delegación del Gobierno de cada provincia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 8 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Todos los extranjeros tienen el derecho de asociación en las mismas condiciones que los españoles.\"</span>"},{"i":"6-343","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la educación. Los extranjeros residentes mayores de dieciocho años tienen el derecho a acceder a las demás etapas educativas posobligatorias, a la obtención de las titulaciones correspondientes, y al sistema público de becas:","o":["Con las limitaciones que establezca cada Comunidad Autónoma.","En las mismas condiciones que los españoles.","Siempre que acrediten dos años de residencia legal continuada.","En las condiciones que fije el Ministerio de Educación para los no comunitarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, los extranjeros residentes mayores de dieciocho años tienen el derecho a acceder a las demás etapas educativas posobligatorias, a la obtención de las titulaciones correspondientes, y al sistema público de becas en las mismas condiciones que los españoles.\"</span>"},{"i":"6-346","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Seguridad Social y servicios sociales. Los extranjeros residentes tienen derecho a acceder a las prestaciones y servicios de la Seguridad Social:","o":["Una vez transcurridos seis meses desde su inscripción en el padrón.","En las condiciones que establezcan los convenios bilaterales de cada país.","En las mismas condiciones que los españoles.","Con carácter subsidiario respecto de las prestaciones de su Estado de origen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 14.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Los extranjeros residentes tienen derecho a acceder a las prestaciones y servicios de la Seguridad Social en las mismas condiciones que los españoles.\"</span>"},{"i":"6-463","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Inadmisión a trámite. La autoridad competente para resolver inadmitirá a trámite las solicitudes relativas a los procedimientos regulados en la ley, en los siguientes supuestos, entre otros:","o":["Cuando el solicitante tenga prohibida su entrada en España.","Cuando el solicitante haya sido sancionado por una infracción leve en los últimos doce meses.","Cuando el solicitante resida en otra provincia distinta a la del órgano competente para resolver.","Cuando el solicitante no acredite medios económicos suficientes para su sostenimiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando el solicitante tenga prohibida su entrada en España</mark></span>El <span class=\"ref-norma\">disp. adic. 4.ª.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. La autoridad competente para resolver inadmitirá a trámite las solicitudes relativas a los procedimientos regulados en esta ley, en los siguientes supuestos:\"</span>"},{"i":"6-ia-1018","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos y libertades de los extranjeros. En materia de trabajo, sindicación, huelga y asistencia sanitaria, señale la INCORRECTA:","o":["Los extranjeros tienen derecho a sindicarse libremente o a afiliarse a una organización profesional, en las mismas condiciones que los trabajadores españoles.","Los extranjeros tienen derecho a la asistencia sanitaria en los términos previstos en la legislación vigente en materia sanitaria.","Los extranjeros residentes que reúnan los requisitos legales tienen derecho a ejercer una actividad remunerada por cuenta propia o ajena.","Los extranjeros podrán ejercer el derecho a la huelga únicamente cuando sean residentes y cuenten con autorización de trabajo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los extranjeros podrán ejercer el derecho a la huelga únicamente cuando sean residentes y cuenten con autorización de trabajo</mark></span>El <span class=\"ref-norma\">arts. 10 a 12 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros podrán ejercer el derecho a la huelga en las mismas condiciones que los españoles\"</span>. El derecho de huelga se reconoce a los extranjeros en las mismas condiciones que a los españoles, sin exigir residencia ni autorización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1020","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la Seguridad Social y a los servicios sociales. Los extranjeros, cualquiera que sea su situación administrativa, tienen derecho a:","o":["las prestaciones y servicios de la Seguridad Social.","los servicios y prestaciones sociales básicas.","los servicios y prestaciones sociales generales y específicas.","las prestaciones sociales en las mismas condiciones que los españoles."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los servicios y prestaciones sociales básicas</mark></span>El <span class=\"ref-norma\">art. 14.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros, cualquiera que sea su situación administrativa, tienen derecho a los servicios y prestaciones sociales básicas\"</span>. Las prestaciones de Seguridad Social y los servicios generales y específicos se reconocen a los residentes; a todos, solo las básicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1021","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la Seguridad Social y a los servicios sociales. En cualquier caso, los extranjeros con discapacidad, menores de dieciocho años, que tengan su domicilio habitual en España, tendrán derecho a recibir:","o":["el tratamiento, servicios y cuidados especiales que exija su estado físico o psíquico.","las prestaciones económicas no contributivas en las mismas condiciones que los españoles.","la asistencia sanitaria gratuita y una prestación por hijo a cargo.","los servicios sociales básicos, siempre que sean residentes legales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el tratamiento, servicios y cuidados especiales que exija su estado físico o psíquico</mark></span>El <span class=\"ref-norma\">art. 14.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En cualquier caso, los extranjeros con discapacidad, menores de dieciocho años, que tengan su domicilio habitual en España, tendrán derecho a recibir el tratamiento, servicios y cuidados especiales que exija su estado físico o psíquico\"</span>. El derecho es al tratamiento, servicios y cuidados especiales que exija su estado; basta el domicilio habitual en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1036","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la asistencia jurídica gratuita. Los extranjeros que se hallen en España tienen derecho a la asistencia jurídica gratuita en los procesos en los que sean parte:","o":["en el orden contencioso-administrativo, siempre que sean residentes legales en España y acrediten insuficiencia de recursos.","cualquiera que sea la jurisdicción en la que se sigan, en las mismas condiciones que los ciudadanos españoles.","en el orden penal y en el contencioso-administrativo, cuando carezcan de recursos.","cualquiera que sea la jurisdicción, siempre que acrediten la residencia legal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cualquiera que sea la jurisdicción en la que se sigan, en las mismas condiciones que los ciudadanos españoles</mark></span>El <span class=\"ref-norma\">art. 22.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los extranjeros que se hallen en España tienen derecho a la asistencia jurídica gratuita en los procesos en los que sean parte, cualquiera que sea la jurisdicción en la que se sigan, en las mismas condiciones que los ciudadanos españoles\"</span>. Basta con «hallarse en España»; no se exige residencia legal y se aplica en cualquier jurisdicción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1220","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Trabajadores transfronterizos y prestación transnacional de servicios. Los trabajadores extranjeros que, residiendo en la zona limítrofe, desarrollen su actividad en España y regresen a su lugar de residencia diariamente deberán obtener la correspondiente autorización administrativa, siéndoles de aplicación en cuanto a los derechos de seguridad social:","o":["lo establecido en los convenios bilaterales con su país de residencia, en todo caso.","lo establecido para los extranjeros residentes, en las mismas condiciones que los españoles.","únicamente las prestaciones derivadas de accidente de trabajo y enfermedad profesional.","lo establecido para los trabajadores de temporada en actividades de campaña."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">lo establecido para los extranjeros residentes, en las mismas condiciones que los españoles</mark></span>El <span class=\"ref-norma\">art. 43.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"siéndoles de aplicación en cuanto a los derechos de seguridad social lo establecido en el artículo 14.1 de esta Ley\"</span>. Se remite al derecho de los residentes a la Seguridad Social en las mismas condiciones que los españoles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 59 bis — Víctimas de la trata de seres humanos ✱","q":[{"i":"6-88","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. El periodo de restablecimiento y reflexión tendrá una duración de:","o":["Al menos 90 días.","Al menos 10 días.","Máximo 30 días.","Al menos 60 días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al menos 90 días</mark></span>Se corrige la opción A (decía «Máximo 90 días»): la Ley fija un MÍNIMO de noventa días. Según el <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Dicho período de restablecimiento y reflexión tendrá una duración de, al menos, noventa días, y deberá ser suficiente para que la víctima pueda decidir si desea cooperar con las autoridades...\"</span> (verificado con el texto del temario)."},{"i":"6-111","p":"(Ley Orgánica 4/2000) Víctimas de la Trata de Seres Humanos. ¿Cuál es el periodo que tendrá una duración de, al menos, noventa días, y deberá ser suficiente para que la víctima pueda decidir si desea cooperar con las autoridades en la investigación del delito y, en su caso, en el procedimiento penal?","o":["Periodo de deliberación.","Periodo de restablecimiento y reflexión.","Periodo de recuperación y reflexión.","Periodo de rehabilitación y auxilio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Periodo de restablecimiento y reflexión</mark></span>Según el <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Dicho período de restablecimiento y reflexión tendrá una duración de, al menos, noventa días, y deberá ser suficiente para que la víctima pueda decidir si desea cooperar con las autoridades en la investigación del delito y, en su caso, en el procedimiento penal\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-174","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Víctima de trata de seres humanos. El periodo de restablecimiento y reflexión tendrá una duración de, al menos:","o":["30 días.","60 días.","90 días.","120 días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">90 días</mark></span>Según el <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Dicho período de restablecimiento y reflexión tendrá una duración de, al menos, noventa días\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-221","p":"Ley Orgánica 4/2000... Víctima de trata de seres humanos. El período de restablecimiento y reflexión tendrá una duración de, al menos:","o":["30 días.","60 días.","90 días.","120 días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">90 días</mark></span>Según el <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Dicho período de restablecimiento y reflexión tendrá una duración de, al menos, noventa días\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-245","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Víctimas de trata de seres humanos. ¿En qué supuestos podrá denegarse o ser revocado el período de restablecimiento y reflexión?","o":["Por motivos de salud pública.","Cuando se tenga conocimiento de que la condición de víctima se ha invocado de forma debida.","Por motivos de orden público.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por motivos de orden público</mark></span>Según el <span class=\"ref-norma\">art. 59 bis.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El periodo de restablecimiento y reflexión podrá denegarse o ser revocado por motivos de orden público o cuando se tenga conocimiento de que la condición de víctima se ha invocado de forma indebida\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-285","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Víctima de trata de seres humanos. El periodo de restablecimiento y reflexión tendrá una duración de, al menos:","o":["30 días.","60 días.","90 días.","120 días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">90 días</mark></span>Según el <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Dicho período de restablecimiento y reflexión tendrá una duración de, al menos, noventa días\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1315","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. Las autoridades competentes adoptarán las medidas necesarias para la identificación de las víctimas de la trata de personas conforme a lo previsto en:","o":["el Protocolo de las Naciones Unidas para prevenir, reprimir y sancionar la trata de personas, de 15 de noviembre de 2000.","la Directiva del Parlamento Europeo y del Consejo relativa a la prevención y lucha contra la trata de seres humanos.","el Convenio del Consejo de Europa sobre la lucha contra la trata de seres humanos, de 16 de mayo de 2005.","el Convenio de aplicación del Acuerdo de Schengen, de 19 de junio de 1990, en materia de cooperación policial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Convenio del Consejo de Europa sobre la lucha contra la trata de seres humanos, de 16 de mayo de 2005</mark></span>El <span class=\"ref-norma\">art. 59 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Las autoridades competentes adoptarán las medidas necesarias para la identificación de las víctimas de la trata de personas conforme a lo previsto en el artículo 10 del Convenio del Consejo de Europa sobre la lucha contra la trata de seres humanos, de 16 de mayo de 2005\"</span>. La referencia es el Convenio del Consejo de Europa de 16 de mayo de 2005. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1316","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. Tanto durante la fase de identificación de las víctimas de trata, como durante el período de restablecimiento y reflexión:","o":["se incoará el expediente sancionador por estancia irregular, pero no podrá ejecutarse la expulsión hasta que finalice el período de reflexión y se evalúe la situación personal de la víctima.","no se incoará un expediente sancionador por estancia irregular y se suspenderá el que se le hubiere incoado o, en su caso, la ejecución de la expulsión o devolución.","se suspenderá el expediente sancionador ya incoado, pero podrá ejecutarse la devolución si la víctima pretendía entrar ilegalmente.","no se incoará expediente sancionador, salvo que la víctima rechace expresamente cooperar con las autoridades en la investigación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no se incoará un expediente sancionador por estancia irregular y se suspenderá el que se le hubiere incoado o, en su caso, la ejecución de la expulsión o devolución</mark></span>El <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Tanto durante la fase de identificación de las víctimas, como durante el período de restablecimiento y reflexión, no se incoará un expediente sancionador por infracción del artículo 53.1.a) y se suspenderá el expediente administrativo sancionador que se le hubiere incoado o, en su caso, la ejecución de la expulsión o devolución eventualmente acordadas\"</span>. No se incoa expediente por estancia irregular y se suspende el incoado o la ejecución de la expulsión o devolución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1317","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. Durante el período de restablecimiento y reflexión:","o":["se le autorizará la estancia temporal y las administraciones competentes velarán por la subsistencia y, de resultar necesario, la seguridad y protección de la víctima.","se le concederá una autorización de residencia y trabajo por circunstancias excepcionales con validez de un año, renovable mientras coopere con las autoridades en la investigación.","se le autorizará la residencia temporal, sin perjuicio de que la víctima deba presentarse periódicamente ante las autoridades competentes.","se le autorizará la estancia temporal, siempre que la víctima haya manifestado previamente su voluntad de cooperar con las autoridades."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se le autorizará la estancia temporal y las administraciones competentes velarán por la subsistencia y, de resultar necesario, la seguridad y protección de la víctima</mark></span>El <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Asimismo, durante el período de restablecimiento y reflexión, se le autorizará la estancia temporal y las administraciones competentes velarán por la subsistencia y, de resultar necesario, la seguridad y protección de la víctima\"</span>. Se autoriza la estancia temporal y se vela por su subsistencia y, si es necesario, seguridad y protección. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1318","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. Finalizado el período de reflexión de la víctima de trata:","o":["la víctima deberá abandonar el territorio nacional si no ha manifestado su voluntad de cooperar con las autoridades en la investigación penal.","el Ministerio Fiscal emitirá un informe sobre la cooperación prestada por la víctima a efectos de la concesión de la autorización de residencia de larga duración en España.","se reanudará automáticamente el expediente sancionador por estancia irregular que se le hubiera incoado con anterioridad.","las administraciones públicas competentes realizarán una evaluación de la situación personal de la víctima a efectos de determinar una posible ampliación del citado período."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las administraciones públicas competentes realizarán una evaluación de la situación personal de la víctima a efectos de determinar una posible ampliación del citado período</mark></span>El <span class=\"ref-norma\">art. 59 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Finalizado el período de reflexión las administraciones públicas competentes realizarán una evaluación de la situación personal de la víctima a efectos de determinar una posible ampliación del citado período\"</span>. Se evalúa su situación personal para una posible ampliación del período. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1319","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Víctimas de la trata de seres humanos. El periodo de restablecimiento y reflexión podrá denegarse o ser revocado por motivos de orden público o cuando se tenga conocimiento de que la condición de víctima se ha invocado de forma indebida. La denegación o revocación:","o":["no requerirán motivación y solo podrán ser recurridas ante la jurisdicción contencioso-administrativa en el plazo de dos meses.","deberán estar motivadas y no serán susceptibles de recurso alguno en vía administrativa ni jurisdiccional.","deberán estar motivadas y podrán ser recurridas según lo establecido en la legislación general de procedimiento administrativo.","deberán ser autorizadas por el Juez de Instrucción, previa audiencia de la víctima y del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deberán estar motivadas y podrán ser recurridas según lo establecido en la legislación general de procedimiento administrativo</mark></span>El <span class=\"ref-norma\">art. 59 bis.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La denegación o revocación deberán estar motivadas y podrán ser recurridas según lo establecido en la Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común\"</span>. Deben ser motivadas y son recurribles conforme a la legislación de procedimiento administrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 23 — Actos discriminatorios ✱","q":[{"i":"6-94","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Actos discriminatorios. En cualquier caso, constituyen actos de discriminación, entre otros: Señale la INCORRECTA.","o":["Todos los que impongan condiciones más gravosas que a los españoles, o que impliquen resistencia a facilitar a un extranjero bienes o servicios ofrecidos al público, sólo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad.","Todos los que impidan, a través de acciones u omisiones, el ejercicio de una actividad económica emprendida legítimamente por un extranjero residente legalmente en España, sólo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad.","Los efectuados por la autoridad o funcionario público o personal encargado de un servicio público, en el ejercicio de sus funciones, por acción u omisión, realicen cualquier acto discriminatorio prohibido por la ley contra un extranjero solo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad.","Todos los que impongan legalmente condiciones más gravosas que a los españoles o que impidan o limiten el acceso al trabajo, la vivienda, a la educación, a la formación profesional, a los servicios sociales y prestaciones asistenciales, así como a cualquier otro derecho reconocido en la presente Ley Orgánica, al extranjero que se encuentre legalmente en España, solo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos los que impongan legalmente condiciones más gravosas que a los españoles o que impidan o limiten el acceso al trabajo, la vivienda, a la educación, a la formación profesional, a los servicios sociales y prestaciones asistenciales, así como a cualquier otro derecho reconocido en la presente Ley Orgánica, al extranjero que se encuentre legalmente en España, solo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad</mark></span>Según el <span class=\"ref-norma\">art. 23.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"c) Todos los que impongan ilegítimamente condiciones más gravosas que a los españoles o restrinjan o limiten el acceso al trabajo\"</span>. Es «ilegítimamente» y al extranjero que se encuentre «regularmente» en España (se corrigen A y B, que venían alteradas) (Verificado con el texto del temario oficial.)"},{"i":"6-268","p":"(Ley Orgánica 4/2000) ¿Qué tipo de discriminación constituye todo tratamiento derivado de la adopción de criterios que perjudiquen injustificadamente a los trabajadores por su condición de extranjeros o por pertenecer a una determinada raza, religión, etnia o nacionalidad?","o":["Indirecta.","Directa.","Directa o indirecta.","No constituye discriminación ninguna."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Indirecta</mark></span>Según el <span class=\"ref-norma\">art. 23.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"e) Constituye discriminación indirecta todo tratamiento derivado de la adopción de criterios que perjudiquen a los trabajadores por su condición de extranjeros o por pertenecer a una determinada raza, religión, etnia o nacionalidad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1038","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Actos discriminatorios. Representa discriminación todo acto que, directa o indirectamente, conlleve una distinción, exclusión, restricción o preferencia contra un extranjero basada en:","o":["la raza, el sexo, la ascendencia o el origen nacional, las opiniones políticas y la lengua.","la raza, el color, la nacionalidad, la situación administrativa y las convicciones ideológicas.","el origen nacional o étnico, la orientación sexual, la edad y las prácticas religiosas.","la raza, el color, la ascendencia o el origen nacional o étnico, las convicciones y prácticas religiosas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la raza, el color, la ascendencia o el origen nacional o étnico, las convicciones y prácticas religiosas</mark></span>El <span class=\"ref-norma\">art. 23.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"contra un extranjero basada en la raza, el color, la ascendencia o el origen nacional o étnico, las convicciones y prácticas religiosas\"</span>. Los motivos son raza, color, ascendencia u origen nacional o étnico y convicciones y prácticas religiosas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1039","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Actos discriminatorios. El acto discriminatorio es el que tenga como fin o efecto destruir o limitar el reconocimiento o el ejercicio, en condiciones de igualdad, de los derechos humanos y de las libertades fundamentales en el campo:","o":["laboral, sanitario, educativo o de vivienda.","civil, político, laboral o religioso.","político, económico, social o cultural.","económico, social, cultural o deportivo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">político, económico, social o cultural</mark></span>El <span class=\"ref-norma\">art. 23.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"y que tenga como fin o efecto destruir o limitar el reconocimiento o el ejercicio, en condiciones de igualdad, de los derechos humanos y de las libertades fundamentales en el campo político, económico, social o cultural\"</span>. Los cuatro campos son político, económico, social o cultural. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1040","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Actos discriminatorios. En cualquier caso, constituyen actos de discriminación todos los que impongan condiciones más gravosas que a los españoles, o que impliquen __________, sólo por su condición de tal o por pertenecer a una determinada raza, religión, etnia o nacionalidad.","o":["la denegación a un extranjero del acceso a la vivienda de protección oficial","resistencia a facilitar a un extranjero bienes o servicios ofrecidos al público","la negativa a contratar a un extranjero con autorización de residencia y trabajo","la exclusión de un extranjero de los servicios sociales básicos municipales"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">resistencia a facilitar a un extranjero bienes o servicios ofrecidos al público</mark></span>El <span class=\"ref-norma\">art. 23.2.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Todos los que impongan condiciones más gravosas que a los españoles, o que impliquen resistencia a facilitar a un extranjero bienes o servicios ofrecidos al público\"</span>. La letra b) se refiere a la resistencia a facilitar bienes o servicios ofrecidos al público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1041","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Actos discriminatorios. Constituyen actos de discriminación los efectuados por la autoridad o funcionario público o personal encargado de un servicio público, que en el ejercicio de sus funciones:","o":["por acción u omisión, realice cualquier acto discriminatorio prohibido por la ley contra un extranjero sólo por su condición de tal.","por acción, y no por omisión, realice cualquier acto discriminatorio prohibido por la ley contra un extranjero residente.","de forma reiterada, realice actos discriminatorios contra un extranjero que se encuentre regularmente en España.","por acción u omisión, deniegue una autorización a un extranjero sin la debida motivación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por acción u omisión, realice cualquier acto discriminatorio prohibido por la ley contra un extranjero sólo por su condición de tal</mark></span>El <span class=\"ref-norma\">art. 23.2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"que en el ejercicio de sus funciones, por acción u omisión, realice cualquier acto discriminatorio prohibido por la ley contra un extranjero sólo por su condición de tal\"</span>. Basta un solo acto, por acción u omisión, contra cualquier extranjero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 17 — Familiares reagrupables ✱ R12","q":[{"i":"6-99","p":"Familiares reagrupables. Señale la Incorrecta.","o":["Los extranjeros que hubieran adquirido la residencia en virtud de una previa reagrupación podrían, a su vez, ejercer el derecho de reagrupación de sus propios familiares, siempre que cuenten con una autorización de residencia y trabajo, obtenida independientemente de la autorización del reagrupante, y acrediten reunir los requisitos previstos en esta Ley Orgánica.","Cuando se trate de ascendientes reagrupados, éstos sólo podrán ejercer, a su vez, el derecho de reagrupación familiar tras haber obtenido la condición de residentes de larga duración y acreditado solvencia económica.","La persona que mantenga con el extranjero residente una relación de afectividad análoga a la conyugal se equiparará al cónyuge a todos los efectos previstos en este capítulo, siempre que dicha relación esté debidamente acreditada y reúna los requisitos necesarios para producir efectos en España.","Mediante Ley podrá regularse en condiciones justas el ejercicio del derecho de reagrupación así como para acreditar, a tales efectos, la relación de afectividad análoga a la conyugal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Mediante Ley podrá regularse en condiciones justas el ejercicio del derecho de reagrupación así como para acreditar, a tales efectos, la relación de afectividad análoga a la conyugal</mark></span>Según el <span class=\"ref-norma\">art. 17.5 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Reglamentariamente, se desarrollarán las condiciones para el ejercicio del derecho de reagrupación así como para acreditar, a estos efectos, la relación de afectividad análoga a la conyugal\"</span>. Es reglamentariamente, no «mediante Ley» (se corrige C: «mantenga», no «contraiga») (Verificado con el texto del temario oficial.)"},{"i":"6-208","p":"Ley Orgánica 4/2000... El extranjero residente tiene derecho a reagrupar con él en España a los siguientes familiares: señale la INCORRECTA.","o":["Al cónyuge del reagrupante, siempre que no se encuentre separado de hecho o de derecho, y que el matrimonio no se haya celebrado en fraude de ley.","Los hijos del residente y del cónyuge, incluidos los adoptados.","Los menores de dieciocho años y los mayores de esa edad que no sean objetivamente capaces de proveer a sus propias necesidades, debido a un estado de salud, cuando el residente extranjero sea su representante legal y el acto jurídico del que surjan las facultades representativas no sea contrario a los principios del ordenamiento español.","Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean menores de sesenta y cinco años y existan razones que justifiquen la necesidad de autorizar su residencia en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean menores de sesenta y cinco años y existan razones que justifiquen la necesidad de autorizar su residencia en España</mark></span>Según el <span class=\"ref-norma\">art. 17.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"d) Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean mayores de sesenta y cinco años\"</span>. Mayores (no menores) de sesenta y cinco años (Verificado con el texto del temario oficial.)"},{"i":"6-331","p":"Ley Orgánica 4/2000... El extranjero residente tiene derecho a reagrupar con él en España a los siguientes familiares: señale la INCORRECTA.","o":["Al cónyuge del reagrupante, siempre que no se encuentre separado de hecho o de derecho, y que el matrimonio no se haya celebrado en fraude de ley.","Los hijos del residente y del cónyuge, incluidos los adoptados.","Los menores de dieciocho años y los mayores de esa edad que no sean objetivamente capaces de proveer a sus propias necesidades, debido a un estado de salud, cuando el residente extranjero sea su representante legal y el acto jurídico del que surjan las facultades representativas no sea contrario a los principios del ordenamiento español.","Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean menores de sesenta y cinco años y existan razones que justifiquen la necesidad de autorizar su residencia en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean menores de sesenta y cinco años y existan razones que justifiquen la necesidad de autorizar su residencia en España</mark></span>Según el <span class=\"ref-norma\">art. 17.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"d) Los ascendientes en primer grado del reagrupante y de su cónyuge cuando estén a su cargo, sean mayores de sesenta y cinco años\"</span>. Mayores (no menores) de sesenta y cinco años (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1024","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Familiares reagrupables. El extranjero residente tiene derecho a reagrupar con él en España al cónyuge, siempre que no se encuentre separado de hecho o de derecho, y que el matrimonio no se haya celebrado en fraude de ley. En ningún caso podrá reagruparse:","o":["al cónyuge con el que se haya contraído matrimonio en los dos años anteriores a la solicitud.","a más de un cónyuge aunque la ley personal del extranjero admita esta modalidad matrimonial.","al cónyuge menor de dieciocho años, aunque la ley personal del extranjero lo permita.","al cónyuge de distinta nacionalidad que la del reagrupante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a más de un cónyuge aunque la ley personal del extranjero admita esta modalidad matrimonial</mark></span>El <span class=\"ref-norma\">art. 17.1.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En ningún caso podrá reagruparse a más de un cónyuge aunque la ley personal del extranjero admita esta modalidad matrimonial\"</span>. La prohibición absoluta («en ningún caso») es la de reagrupar a más de un cónyuge. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1025","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Familiares reagrupables. Pueden reagruparse los hijos del residente y del cónyuge, incluidos los adoptados, siempre que sean menores de dieciocho años o personas con discapacidad que no sean objetivamente capaces de proveer a sus propias necesidades debido a su estado de salud. Cuando se trate de hijos de uno solo de los cónyuges se requerirá, además:","o":["que éste ejerza en solitario la patria potestad o que se le haya otorgado la custodia y estén efectivamente a su cargo.","que el otro progenitor preste su consentimiento expreso ante la autoridad consular española.","que éste ejerza la patria potestad compartida con el otro progenitor y el menor haya convivido con él durante al menos un año.","que se acredite la dependencia económica y la convivencia previa en el país de origen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que éste ejerza en solitario la patria potestad o que se le haya otorgado la custodia y estén efectivamente a su cargo</mark></span>El <span class=\"ref-norma\">art. 17.1.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Cuando se trate de hijos de uno solo de los cónyuges se requerirá, además, que éste ejerza en solitario la patria potestad o que se le haya otorgado la custodia y estén efectivamente a su cargo\"</span>. Se exige patria potestad en solitario o custodia, y que estén efectivamente a su cargo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1026","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Familiares reagrupables. Los ascendientes en primer grado del reagrupante y de su cónyuge son reagrupables cuando estén a su cargo, sean mayores de sesenta y cinco años y existan razones que justifiquen la necesidad de autorizar su residencia en España. Excepcionalmente, podrá reagruparse al ascendiente menor de sesenta y cinco años:","o":["cuando el reagrupante sea residente de larga duración y acredite solvencia económica suficiente.","cuando el ascendiente padezca una discapacidad que le impida proveer a sus propias necesidades.","cuando lo autorice la Delegación del Gobierno previo informe del Ministerio Fiscal.","cuando concurran razones de carácter humanitario, si se cumplen las demás condiciones previstas en esta Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuando concurran razones de carácter humanitario, si se cumplen las demás condiciones previstas en esta Ley</mark></span>El <span class=\"ref-norma\">art. 17.1.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Excepcionalmente, cuando concurran razones de carácter humanitario, podrá reagruparse al ascendiente menor de sesenta y cinco años si se cumplen las demás condiciones previstas en esta Ley\"</span>. La excepción por edad solo procede por razones de carácter humanitario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1027","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Familiares reagrupables. La persona que mantenga con el extranjero residente una relación de afectividad análoga a la conyugal se equiparará al cónyuge a todos los efectos. En todo caso:","o":["la relación deberá haberse inscrito en un registro público extranjero con al menos dos años de antelación a la solicitud.","podrá reagruparse a más de una persona si la ley personal del extranjero lo admite.","las situaciones de matrimonio y de análoga relación de afectividad se considerarán incompatibles entre sí.","la relación solo producirá efectos si ambos convivientes tienen la misma nacionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las situaciones de matrimonio y de análoga relación de afectividad se considerarán incompatibles entre sí</mark></span>El <span class=\"ref-norma\">art. 17.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, las situaciones de matrimonio y de análoga relación de afectividad se considerarán incompatibles entre sí\"</span>. Matrimonio y relación análoga son incompatibles; tampoco cabe reagrupar a más de una pareja. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — La protección subsidiaria ✱","q":[{"i":"6-102","p":"Ley 12/2009, reguladora del derecho de asilo y de la protección subsidiaria. ¿Qué derecho es dispensado a las personas de otros países y a los apátridas que, sin reunir los requisitos para obtener el asilo o ser reconocidas como refugiados, pero respecto de las cuales se den motivos fundados para creer que si regresasen a su país de origen en el caso de los nacionales, se enfrentarían a un riesgo real recogido en esta Ley?","o":["Condición de refugiado.","Derecho de Asilo.","Protección Internacional.","Protección Subsidiaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Protección Subsidiaria</mark></span>Según el <span class=\"ref-norma\">art. 4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El derecho a la protección subsidiaria es el dispensado a las personas de otros países y a los apátridas que, sin reunir los requisitos para obtener el asilo o ser reconocidas como refugiadas, pero respecto de las cuales se den motivos fundados para creer que si regresasen a su país de origen en el caso de los nacionales o, al de su anterior residencia habitual en el caso de los apátridas, se enfrentarían a un riesgo real de sufrir alguno de los daños graves previstos en el artículo 10 de esta Ley, y que no pueden o, a causa de dicho riesgo, no quieren, acogerse a la protección del país de que se trate, siempre que no concurra alguno de los supuestos mencionados en los artículos 11 y 12 de esta Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-124","p":"(Ley 12/2009) La protección subsidiaria se concederá cuando existan motivos fundados para creer que si el solicitante regresase a su país se enfrentaría a un riesgo real de sufrir:","o":["Daños leves.","Daños muy graves.","Daños graves.","Daños mayores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Daños graves</mark></span>Según el <span class=\"ref-norma\">art. 4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"El derecho a la protección subsidiaria es el dispensado a las personas de otros países y a los apátridas que, sin reunir los requisitos para obtener el asilo o ser reconocidas como refugiadas, pero respecto de las cuales se den motivos fundados para creer que si regresasen a su país de origen en el caso de los nacionales o, al de su anterior residencia habitual en el caso de los apátridas, se enfrentarían a un riesgo real de sufrir alguno de los daños graves previstos en el artículo 10 de esta Ley, y que no pueden o, a causa de dicho riesgo, no quieren, acogerse a la protección del país de que se trate, siempre que no concurra alguno de los supuestos mencionados en los artículos 11 y 12 de esta Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1612","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Extensión familiar del derecho de asilo o de la protección subsidiaria. En ningún caso se concederá protección internacional por extensión familiar a las personas:","o":["que no acrediten la dependencia económica respecto de la persona refugiada en el país de origen.","incursas en los supuestos de exclusión o denegación previstos en la Ley para el asilo y la protección subsidiaria.","que tengan distinta nacionalidad que la persona refugiada o beneficiaria de protección subsidiaria, en todo caso.","que hayan presentado previamente una solicitud independiente de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">incursas en los supuestos de exclusión o denegación previstos en la Ley para el asilo y la protección subsidiaria</mark></span>El <span class=\"ref-norma\">art. 40.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En ningún caso se concederá protección internacional por extensión familiar a las personas incursas en los supuestos previstos en los apartados 2 y 3 del artículo 8 y en los artículos 9, 11 y 12 de la presente ley\"</span>. Se excluye a quienes incurran en causas de exclusión o denegación (la distinta nacionalidad excluye solo ciertos supuestos de la letra a y b). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1638","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Normativa aplicable a las personas autorizadas a residir en España por razones humanitarias. Las personas que hubieran obtenido una autorización para permanecer en España por razones humanitarias conforme a la anterior Ley de asilo de 1984 y su Reglamento:","o":["obtendrán automáticamente el estatuto de refugiado previsto en la Ley 12/2009.","perderán dicha autorización a la entrada en vigor de la Ley 12/2009.","deberán solicitar una autorización de residencia por circunstancias excepcionales en el plazo de seis meses.","podrán beneficiarse del derecho a la protección subsidiaria previsto en la Ley 12/2009."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrán beneficiarse del derecho a la protección subsidiaria previsto en la Ley 12/2009</mark></span>El <span class=\"ref-norma\">disp. trans. 2.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"podrán beneficiarse del derecho a la protección subsidiaria previsto en esta Ley\"</span>. Pueden beneficiarse de la protección subsidiaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 48 — Menores no acompañados R28","q":[{"i":"6-104","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Menores no acompañados. Señale la INCORRECTA:","o":["En los supuestos en los que la minoría de edad no pueda ser establecida con seguridad, se pondrá el hecho en conocimiento inmediato del Ministerio Fiscal, que dispondrá lo necesario para la determinación de la edad del presunto menor.","La negativa a someterse al reconocimiento médico para determinar la edad impedirá que se dicte resolución sobre la solicitud de protección internacional.","Determinada la edad, si se tratase de una persona menor de edad, el Ministerio Fiscal la pondrá a disposición de los servicios competentes de protección de menores.","Los menores no acompañados solicitantes de protección internacional serán remitidos a los servicios competentes en materia de protección de menores y el hecho se pondrá en conocimiento del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La negativa a someterse al reconocimiento médico para determinar la edad impedirá que se dicte resolución sobre la solicitud de protección internacional</mark></span>Según el <span class=\"ref-norma\">art. 48.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La negativa a someterse a tal reconocimiento médico no impedirá que se dicte resolución sobre la solicitud de protección internacional\"</span>. Se corrigen A y D, que venían alteradas (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1629","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Menores no acompañados. En los supuestos en los que la minoría de edad del solicitante de protección internacional no pueda ser establecida con seguridad, colaborarán en la determinación de la edad las instituciones sanitarias oportunas que realizarán las pruebas científicas necesarias:","o":["con carácter prioritario y urgente.","con carácter prioritario.","en el plazo de setenta y dos horas.","previa autorización judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con carácter prioritario y urgente</mark></span>El <span class=\"ref-norma\">art. 48.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"para lo que colaborarán las instituciones sanitarias oportunas que, con carácter prioritario y urgente, realizarán las pruebas científicas necesarias\"</span>. En la Ley 12/2009, «con carácter prioritario y urgente» (en la LO 4/2000, solo «prioritario»). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1630","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Menores no acompañados. De forma inmediata se adoptarán medidas para asegurar que el representante de la persona menor de edad, nombrado de acuerdo con la legislación vigente en materia de protección de menores:","o":["sea designado por el ACNUR entre las organizaciones especializadas en la atención de menores solicitantes de asilo, previa audiencia del Ministerio Fiscal.","preste su consentimiento para la realización de las pruebas de determinación de la edad del menor.","acompañe al menor en el traslado a la comunidad autónoma en la que haya de ser ubicado.","actúe en nombre del menor de edad no acompañado y le asista con respecto al examen de la solicitud de protección internacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">actúe en nombre del menor de edad no acompañado y le asista con respecto al examen de la solicitud de protección internacional</mark></span>El <span class=\"ref-norma\">art. 48.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"De forma inmediata se adoptarán medidas para asegurar que el representante de la persona menor de edad, nombrado de acuerdo con la legislación vigente en materia de protección de menores, actúe en nombre del menor de edad no acompañado y le asista con respecto al examen de la solicitud de protección internacional\"</span>. El representante actúa en nombre del menor y le asiste en el examen de la solicitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 26 — Prohibición de entrada en España ✱","q":[{"i":"6-108","p":"(Ley Orgánica 4/2000) Prohibición de entrada en España. No podrán entrar en España, ni obtener un visado a tal fin:","o":["De manera permanente, los extranjeros expulsados del país.","Aquellos que tengan prohibida la entrada por alguna causa legalmente establecida.","A y B son correctas.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Aquellos que tengan prohibida la entrada por alguna causa legalmente establecida</mark></span>La A es falsa: los expulsados no pueden entrar «mientras dure la prohibición de entrada», no «de manera permanente». Por eso no es «A y B». Según el <span class=\"ref-norma\">art. 26.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"No podrán entrar en España, ni obtener un visado a tal fin, los extranjeros que hayan sido expulsados, mientras dure la prohibición de entrada, así como aquellos que la tengan prohibida por otra causa legalmente establecida o en virtud de convenios internacionales en los que sea parte España.\"</span> (verificado con el texto del temario)."},{"i":"6-233","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. A los extranjeros que no cumplan los requisitos establecidos para la entrada, les será denegada mediante resolución motivada, con información sobre: señale la INCORRECTA.","o":["Los recursos que puedan interponer.","De los plazos para presentar los recursos y la autoridad ante quien deben formalizarlo.","De su derecho a la asistencia letrada, que será de forma obligatoria, de oficio.","De su derecho a intérprete."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De su derecho a la asistencia letrada, que será de forma obligatoria, de oficio</mark></span>Según el <span class=\"ref-norma\">art. 26.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"y de su derecho a la asistencia letrada, que podrá ser de oficio, y de intérprete\"</span>. La asistencia letrada «podrá ser» de oficio; no es obligatoriamente de oficio (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1048","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Prohibición de entrada en España. A los extranjeros que no cumplan los requisitos establecidos para la entrada, les será denegada mediante resolución motivada, con información, entre otros extremos, de su derecho a la asistencia letrada, que podrá ser de oficio, y de intérprete, que comenzará:","o":["en el momento de la notificación de la resolución de denegación de entrada.","en el momento mismo de efectuarse el control en el puesto fronterizo.","una vez que el extranjero sea ingresado en las dependencias habilitadas.","desde que el extranjero manifieste su voluntad de recurrir la denegación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en el momento mismo de efectuarse el control en el puesto fronterizo</mark></span>El <span class=\"ref-norma\">art. 26.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"y de su derecho a la asistencia letrada, que podrá ser de oficio, y de intérprete, que comenzará en el momento mismo de efectuarse el control en el puesto fronterizo\"</span>. La asistencia comienza en el momento mismo del control en el puesto fronterizo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 16 — Derecho a solicitar protección internacional","q":[{"i":"6-112","p":"(Ley 12/2009) De la presentación de la solicitud. Señala la INCORRECTA sobre el derecho a solicitar protección internacional.","o":["La presentación de la solicitud conllevará la valoración de las circunstancias determinantes del reconocimiento de la condición de refugiado, así como de la concesión de la protección subsidiaria.","Toda información relativa al procedimiento, incluida la relativa a la presentación de la solicitud, tendrá carácter público.","Las personas nacionales no comunitarias y los apátridas presentes en territorio español tienen derecho a solicitar protección internacional en España.","La asistencia jurídica será preceptiva cuando las solicitudes se formalicen de acuerdo al procedimiento señalado en el artículo 21 de la presente Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Toda información relativa al procedimiento, incluida la relativa a la presentación de la solicitud, tendrá carácter público</mark></span>Según el <span class=\"ref-norma\">art. 16.4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter confidencial\"</span>. Es confidencial, no pública (se corrige A) (Verificado con el texto del temario oficial.)"},{"i":"6-128","p":"(Ley 12/2009) Presentación de la solicitud. Señale la INCORRECTA.","o":["Las personas nacionales no comunitarias que se hallen presentes en territorio español tienen derecho a solicitar protección internacional en España.","La presentación de la solicitud conllevará la valoración de las circunstancias determinantes del reconocimiento de la condición de refugiado, así como de la concesión de la protección subsidiaria.","Los solicitantes tendrán derecho a asistencia sanitaria y a asistencia jurídica gratuita, que se extenderá a la formalización de la solicitud y a toda la tramitación del procedimiento.","Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter público."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter público</mark></span>Según el <span class=\"ref-norma\">art. 16.4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter confidencial\"</span>. Se corrigen B y C, que venían alteradas (Verificado con el texto del temario oficial.)"},{"i":"6-142","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Derecho a solicitar protección internacional. Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter:","o":["Discrecional.","Confidencial.","Reservado.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Confidencial</mark></span>Según el <span class=\"ref-norma\">art. 16.4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter confidencial\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-278","p":"Ley 12/2009, de 30 de octubre, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Derecho a solicitar protección internacional. Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter:","o":["Discrecional.","Confidencial.","Reservado.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Confidencial</mark></span>Según el <span class=\"ref-norma\">art. 16.4 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter confidencial\"</span>. (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 17 — Presentación de la solicitud ✱","q":[{"i":"6-132","p":"(Ley 12/2009) Reglas procedimentales para el reconocimiento de la protección integral (Señale la CORRECTA).","o":["La Administración adoptará las medidas necesarias para que, cuando sean precisas, el solicitante preste un juramento de decir verdad.","Las personas encargadas de efectuar la entrevista deberán informar al solicitante sobre las consecuencias del uso de intérpretes y las ayudas.","En los términos que se establezcan reglamentariamente, se planteará la posibilidad de una nueva audiencia personal sobre su solicitud de asilo.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En los términos que se establezcan reglamentariamente, se planteará la posibilidad de una nueva audiencia personal sobre su solicitud de asilo</mark></span>Según el <span class=\"ref-norma\">art. 17.8 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"En los términos que se establezcan reglamentariamente, se planteará la posibilidad de una nueva audiencia personal sobre su solicitud de asilo\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-182","p":"Ley 12/2009... En el momento de efectuar la solicitud, la persona extranjera será informada, en una lengua que pueda comprender, acerca de: señale la INCORRECTA.","o":["El procedimiento que debe seguirse.","La posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas reconocidas de protección internacional.","Las posibles consecuencias del incumplimiento de sus obligaciones o de su falta de colaboración con las autoridades.","Los derechos y prestaciones sociales a los que tiene acceso en su condición de solicitante de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas reconocidas de protección internacional</mark></span>Según el <span class=\"ref-norma\">art. 17.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) la posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas necesitadas de protección internacional\"</span>. Son las personas «necesitadas» de protección; A tampoco figuraba y se sustituye por el procedimiento que debe seguirse (Verificado con el texto del temario oficial.)"},{"i":"6-310","p":"Ley 12/2009... En el momento de efectuar la solicitud, la persona extranjera será informada, en una lengua que pueda comprender, acerca de: señale la INCORRECTA.","o":["El procedimiento que debe seguirse.","La posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas reconocidas de protección internacional.","Las posibles consecuencias del incumplimiento de sus obligaciones o de su falta de colaboración con las autoridades.","Los derechos y prestaciones sociales a los que tiene acceso en su condición de solicitante de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas reconocidas de protección internacional</mark></span>Según el <span class=\"ref-norma\">art. 17.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) la posibilidad de contactar con el Alto Comisionado de las Naciones Unidas para los Refugiados y con las Organizaciones no Gubernamentales legalmente reconocidas entre cuyos objetivos figure el asesoramiento y ayuda a las personas necesitadas de protección internacional\"</span>. Son las personas «necesitadas» de protección (Verificado con el texto del temario oficial.)"},{"i":"6-442","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. La comparecencia para formalizar la solicitud deberá realizarse sin demora y en todo caso en el plazo máximo de:","o":["Quince días desde la entrada en el territorio español o desde la notificación de la inadmisión, sin perjuicio de lo que establezcan los tratados internacionales.","Dos meses desde la entrada en el territorio español, sin posibilidad de excepciones.","Un mes desde la entrada en el territorio español o desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves.","Un mes desde la expedición del documento acreditativo de la solicitud."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un mes desde la entrada en el territorio español o desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves</mark></span>El <span class=\"ref-norma\">art. 17.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"2. La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de un mes desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves.\"</span>"},{"i":"6-443","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. Cuando sea preciso, en la entrevista se prestará un tratamiento diferenciado por razón del sexo de la persona solicitante o demás circunstancias previstas en el artículo 46, y de este trámite:","o":["Se informará de oficio a la Oficina del ACNUR en España.","Se dejará debida constancia en el expediente administrativo.","Se dará traslado al Ministerio Fiscal en el plazo de tres días.","Se levantará acta firmada por el intérprete y por el solicitante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se dejará debida constancia en el expediente administrativo</mark></span>El <span class=\"ref-norma\">art. 17.5 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"5. La Administración adoptará las medidas necesarias para que, cuando sea preciso, en la entrevista se preste un tratamiento diferenciado por razón del sexo de la persona solicitante o demás circunstancias previstas en el artículo 46 de esta Ley. De este trámite se dejará debida constancia en el expediente administrativo.\"</span>"},{"i":"6-444","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. Las personas encargadas de efectuar la entrevista informarán a los solicitantes sobre cómo efectuar la solicitud, y:","o":["Les ayudarán a cumplimentarla, facilitándoles la información básica en relación con aquélla.","Les asignarán un abogado de oficio para la formalización de la solicitud, en los términos que determine la ley orgánica correspondiente.","Les entregarán copia íntegra del expediente de su solicitud.","Les remitirán a la Oficina de Asilo y Refugio para que la cumplimenten."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Les ayudarán a cumplimentarla, facilitándoles la información básica en relación con aquélla</mark></span>El <span class=\"ref-norma\">art. 17.6 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"6. Las personas encargadas de efectuar la entrevista informarán a los solicitantes sobre cómo efectuar la solicitud, y les ayudarán a cumplimentarla, facilitándoles la información básica en relación con aquélla.\"</span>"},{"i":"6-ia-1513","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. La solicitud de protección internacional deberá efectuarse mediante comparecencia personal de los interesados o, en caso de imposibilidad física o legal, mediante persona que lo represente. En este último caso:","o":["el solicitante deberá ratificar la petición una vez desaparezca el impedimento.","el representante deberá acreditar su condición mediante poder notarial.","la solicitud se tramitará por el procedimiento de urgencia en todo caso.","el solicitante deberá comparecer en el plazo de un mes desde la solicitud."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el solicitante deberá ratificar la petición una vez desaparezca el impedimento</mark></span>El <span class=\"ref-norma\">art. 17.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"En este último caso, el solicitante deberá ratificar la petición una vez desaparezca el impedimento\"</span>. Debe ratificarse la petición cuando desaparezca el impedimento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1514","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. La entrada ilegal en territorio español:","o":["será sancionada en todo caso, sin perjuicio de que pueda concederse posteriormente la protección internacional a la persona que la haya realizado.","no podrá ser sancionada cuando la persona presente su solicitud en el plazo máximo de un mes desde su entrada.","determinará la tramitación de la solicitud por el procedimiento en frontera previsto en la Ley.","no podrá ser sancionada cuando haya sido realizada por persona que reúna los requisitos para ser beneficiaria de la protección internacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrá ser sancionada cuando haya sido realizada por persona que reúna los requisitos para ser beneficiaria de la protección internacional</mark></span>El <span class=\"ref-norma\">art. 17.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"A estos efectos, la entrada ilegal en territorio español no podrá ser sancionada cuando haya sido realizada por persona que reúna los requisitos para ser beneficiaria de la protección internacional prevista en esta Ley\"</span>. No se sanciona si quien entra reúne los requisitos para ser beneficiario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1515","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. La solicitud de protección internacional se formalizará mediante entrevista personal que se realizará siempre individualmente. De forma excepcional:","o":["podrá prescindirse de la entrevista personal cuando la solicitud se presente en un puesto fronterizo y se tramite por el procedimiento de urgencia, previa conformidad del ACNUR.","podrá realizarse la entrevista de forma colectiva cuando se trate de solicitantes de la misma nacionalidad y procedencia.","podrá requerirse la presencia de otros miembros de la familia de los solicitantes, si ello se considerase imprescindible para la adecuada formalización de la solicitud.","podrá realizarse la entrevista por medios telemáticos, previa conformidad del solicitante y del ACNUR."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá requerirse la presencia de otros miembros de la familia de los solicitantes, si ello se considerase imprescindible para la adecuada formalización de la solicitud</mark></span>El <span class=\"ref-norma\">art. 17.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"De forma excepcional, podrá requerirse la presencia de otros miembros de la familia de los solicitantes, si ello se considerase imprescindible para la adecuada formalización de la solicitud\"</span>. La excepción es la presencia de otros familiares si es imprescindible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1517","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. Cuando razones de seguridad lo aconsejen:","o":["se podrá registrar a la persona solicitante y sus pertenencias, siempre y cuando se garantice el pleno respeto a su dignidad e integridad.","se podrá denegar la solicitud por razones fundadas de peligro para la seguridad de España, sin necesidad de entrevista.","se podrá acordar el internamiento de la persona solicitante en un centro de internamiento, previa autorización judicial.","se podrá registrar a la persona solicitante y sus pertenencias, previa autorización del Juez de Instrucción competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se podrá registrar a la persona solicitante y sus pertenencias, siempre y cuando se garantice el pleno respeto a su dignidad e integridad</mark></span>El <span class=\"ref-norma\">art. 17.7 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Cuando razones de seguridad lo aconsejen, se podrá registrar a la persona solicitante y sus pertenencias, siempre y cuando se garantice el pleno respeto a su dignidad e integridad\"</span>. Cabe el registro con pleno respeto a su dignidad e integridad, sin autorización judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 59 — Colaboración contra redes organizadas","q":[{"i":"6-138","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. El extranjero que se encuentre irregularmente en España y sea _________ de un acto de tráfico ilícito de seres humanos, inmigración ilegal, explotación laboral o de tráfico ilícito de mano de obra o de explotación en la prostitución abusando de su situación de necesidad, podrá quedar exento de responsabilidad administrativa y no será expulsado si denuncia a los autores o cooperadores de dicho tráfico, o coopera y colabora con las autoridades competentes, proporcionando datos esenciales o testificando, en su caso, en el proceso correspondiente contra aquellos autores.","o":["Perjudicado.","Víctima.","Testigo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 59.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El extranjero que se encuentre irregularmente en España y sea víctima, perjudicado o testigo de un acto de tráfico ilícito de seres humanos, inmigración ilegal, explotación laboral o de tráfico ilícito de mano de obra o de explotación en la prostitución abusando de su situación de necesidad, podrá quedar exento de responsabilidad administrativa y no será expulsado\"</span>. Puede ser víctima, perjudicado o testigo: las tres son correctas (Verificado con el texto del temario oficial.)"},{"i":"6-275","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. El extranjero que se encuentre irregularmente en España y sea _________ de un acto de tráfico ilícito de seres humanos, inmigración ilegal, explotación laboral o de tráfico ilícito de mano de obra o de explotación en la prostitución abusando de su situación de necesidad, podrá quedar exento de responsabilidad administrativa y no será expulsado si denuncia a los autores o cooperadores de dicho tráfico, o coopera y colabora con las autoridades competentes, proporcionando datos esenciales o testificando, en su caso, en el proceso correspondiente contra aquellos autores.","o":["Perjudicado.","Víctima.","Testigo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 59.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El extranjero que se encuentre irregularmente en España y sea víctima, perjudicado o testigo de un acto de tráfico ilícito de seres humanos, inmigración ilegal, explotación laboral o de tráfico ilícito de mano de obra o de explotación en la prostitución abusando de su situación de necesidad, podrá quedar exento de responsabilidad administrativa y no será expulsado\"</span>. Puede ser víctima, perjudicado o testigo: las tres son correctas (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1313","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Colaboración contra redes organizadas. Cuando el Ministerio Fiscal tenga conocimiento de que un extranjero, contra el que se ha dictado una resolución de expulsión, aparezca en un procedimiento penal como víctima, perjudicado o testigo y considere imprescindible su presencia para la práctica de diligencias judiciales:","o":["lo pondrá de manifiesto a la autoridad gubernativa competente para que valore la inejecución de su expulsión.","acordará por sí mismo la suspensión de la ejecución de la expulsión hasta que finalicen las diligencias.","lo pondrá en conocimiento del Juez de Instrucción para que revoque la resolución de expulsión dictada.","solicitará al Ministro del Interior que conceda al extranjero una autorización de residencia de larga duración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">lo pondrá de manifiesto a la autoridad gubernativa competente para que valore la inejecución de su expulsión</mark></span>El <span class=\"ref-norma\">art. 59.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"lo pondrá de manifiesto a la autoridad gubernativa competente para que valore la inejecución de su expulsión\"</span>. El Fiscal lo pone de manifiesto a la autoridad gubernativa, que valora la inejecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 37 — Autorización de residencia y trabajo por cuenta propia ✱ R11","q":[{"i":"6-139","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta propia. La concesión de la autorización inicial de trabajo corresponde a:","o":["Al Extranjero.","Al Gobierno.","A las Comunidades Autónomas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A las Comunidades Autónomas</mark></span>Según el <span class=\"ref-norma\">art. 37.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La concesión de la autorización inicial de trabajo, en necesaria coordinación con la que corresponde al Estado en materia de residencia, corresponderá a las Comunidades Autónomas de acuerdo con las competencias asumidas en los correspondientes Estatutos.\"</span> (verificado con el texto del temario)."},{"i":"6-165","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta propia. Señala la CORRECTA:","o":["La autorización inicial se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a cualquier sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, la Comunidad Autónoma, y a un sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, y a cualquier sector de actividad.","La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad</mark></span>Según el <span class=\"ref-norma\">art. 37.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-215","p":"Ley Orgánica 4/2000... Autorización de residencia y trabajo por cuenta propia. Señale la CORRECTA.","o":["La autorización inicial se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a cualquier sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, la Comunidad Autónoma, y a un sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, y a cualquier sector de actividad.","La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad</mark></span>Según el <span class=\"ref-norma\">art. 37.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-254","p":"(Ley Orgánica 4/2000) Autorización de residencia y trabajo por cuenta propia. Señala la INCORRECTA:","o":["La duración de la autorización inicial de residencia y trabajo por cuenta propia se determinará reglamentariamente.","La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad.","La concesión de la autorización inicial de trabajo, sin necesidad de coordinación con la CCAA donde se vaya a ejercer la actividad, podrá realizarse por la Administración General del Estado.","Para la realización de actividades económicas por cuenta propia habrá de acreditar el cumplimiento de los requisitos exigidos por la legislación vigente para la apertura y funcionamiento de la actividad proyectada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La concesión de la autorización inicial de trabajo, sin necesidad de coordinación con la CCAA donde se vaya a ejercer la actividad, podrá realizarse por la Administración General del Estado</mark></span>Según el <span class=\"ref-norma\">art. 37.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La concesión de la autorización inicial de trabajo, en necesaria coordinación con la que corresponde al Estado en materia de residencia, corresponderá a las Comunidades Autónomas\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-295","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta propia. Señala la CORRECTA:","o":["La autorización inicial se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a cualquier sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, la Comunidad Autónoma, y a un sector de actividad.","La autorización inicial se limitará a un ámbito geográfico no superior al de una provincia, y a cualquier sector de actividad.","La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad</mark></span>Según el <span class=\"ref-norma\">art. 37.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La autorización inicial de residencia y trabajo por cuenta propia se limitará a un ámbito geográfico no superior al de una Comunidad Autónoma, y a un sector de actividad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1106","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia temporal. La autorización inicial de residencia temporal y trabajo:","o":["autorizará únicamente a realizar actividades lucrativas por cuenta ajena.","autorizará a realizar actividades lucrativas por cuenta propia, previa colegiación.","autorizará a realizar actividades no lucrativas y de voluntariado.","autorizará a realizar actividades lucrativas por cuenta propia y/o ajena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">autorizará a realizar actividades lucrativas por cuenta propia y/o ajena</mark></span>El <span class=\"ref-norma\">art. 31.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La autorización inicial de residencia temporal y trabajo, que autorizará a realizar actividades lucrativas por cuenta propia y/o ajena\"</span>. Habilita para actividades lucrativas por cuenta propia y/o ajena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1157","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta propia. Para la realización de actividades económicas por cuenta propia habrá de acreditarse el cumplimiento de todos los requisitos que la legislación vigente exige a los nacionales para la apertura y funcionamiento de la actividad proyectada, así como los relativos a:","o":["la suficiencia de la inversión y la potencial creación de empleo, entre otros que reglamentariamente se establezcan.","la viabilidad económica del proyecto y la contratación de trabajadores españoles, entre otros que fije la ley.","la titulación académica del solicitante y la inscripción en el registro mercantil, entre otros que se determinen.","la suficiencia de la inversión y la residencia previa en España, entre otros que reglamentariamente se establezcan."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la suficiencia de la inversión y la potencial creación de empleo, entre otros que reglamentariamente se establezcan</mark></span>El <span class=\"ref-norma\">art. 37.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"así como los relativos a la suficiencia de la inversión y la potencial creación de empleo, entre otros que reglamentariamente se establezcan\"</span>. Se exigen la suficiencia de la inversión y la potencial creación de empleo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1218","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen especial de los trabajadores de temporada. El Gobierno regulará reglamentariamente la autorización de residencia y trabajo para los trabajadores extranjeros en actividades de temporada o campaña que les permita la entrada y salida del territorio nacional, así como la documentación de su situación, de acuerdo con las características de las citadas campañas y la información que le suministren:","o":["los Servicios Públicos de Empleo provinciales.","las organizaciones empresariales agrarias.","las Subdelegaciones del Gobierno afectadas.","las Comunidades Autónomas donde se promuevan."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las Comunidades Autónomas donde se promuevan</mark></span>El <span class=\"ref-norma\">art. 42.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"de acuerdo con las características de las citadas campañas y la información que le suministren las Comunidades Autónomas donde se promuevan\"</span>. La información la suministran las Comunidades Autónomas donde se promuevan las campañas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 6 — Actos de persecución ✱","q":[{"i":"6-140","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución definidos en el apartado primero podrán revestir, entre otras, las siguientes formas: Señale la INCORRECTA.","o":["Actos de violencia física o psíquica, incluidos los actos de violencia sexual.","Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria.","Concesión o denegación que cause desproporcionadas o discriminatorias.","Denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Concesión o denegación que cause desproporcionadas o discriminatorias</mark></span>Según el <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) procesamientos o penas que sean desproporcionados o discriminatorios; d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-153","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución definidos en el apartado primero podrán revestir, entre otras, las siguientes formas: Señale la INCORRECTA.","o":["Actos de violencia física o psíquica, incluidos los actos de violencia sexual.","Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria.","Concesión o denegación que cause desproporcionadas o discriminatorias.","Denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Concesión o denegación que cause desproporcionadas o discriminatorias</mark></span>Según el <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) procesamientos o penas que sean desproporcionados o discriminatorios; d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-188","p":"Ley 12/2009... Actos de persecución. Los actos de persecución definidos en el apartado primero podrán revestir, entre otras, las siguientes formas: señale la INCORRECTA.","o":["Actos de violencia física o psíquica, incluidos los actos de violencia sexual.","Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria.","Concesión o denegación que cause desproporcionadas o discriminatorias.","Denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Concesión o denegación que cause desproporcionadas o discriminatorias</mark></span>La antigua opción C («procesamientos o penas desproporcionados o discriminatorios») es literal de la letra c), así que no había ninguna incorrecta; se sustituye por la opción intrusa de las preguntas gemelas. Según el <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Los actos de persecución definidos en el apartado primero podrán revestir, entre otras, las siguientes formas: [...] c) procesamientos o penas que sean desproporcionados o discriminatorios; d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias...\"</span> (verificado con el texto del temario)."},{"i":"6-276","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución definidos en el apartado primero podrán revestir, entre otras, las siguientes formas: Señale la INCORRECTA.","o":["Actos de violencia física o psíquica, incluidos los actos de violencia sexual.","Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria.","Concesión o denegación que cause desproporcionadas o discriminatorias.","Denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Concesión o denegación que cause desproporcionadas o discriminatorias</mark></span>Según el <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"c) procesamientos o penas que sean desproporcionados o discriminatorios; d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-427","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución podrán revestir, entre otras, las siguientes formas:","o":["Actos de violencia física, con exclusión de los actos de violencia psíquica.","Medidas fiscales discriminatorias aplicadas de forma generalizada.","Actos de violencia física o psíquica, incluidos los actos de violencia sexual.","Restricciones a la libertad de circulación por razones de seguridad nacional, en los términos que determine la ley orgánica correspondiente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Actos de violencia física o psíquica, incluidos los actos de violencia sexual</mark></span>El <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"a) actos de violencia física o psíquica, incluidos los actos de violencia sexual;\"</span>"},{"i":"6-428","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución podrán revestir la forma de:","o":["Medidas legislativas y administrativas que se apliquen de manera proporcionada y no discriminatoria, salvo que el órgano competente acuerde otra cosa de forma motivada.","Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria.","Medidas policiales y judiciales adoptadas conforme a la legislación del país de origen.","Medidas administrativas de carácter sancionador que se apliquen con carácter general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria</mark></span>El <span class=\"ref-norma\">art. 6.2.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria;\"</span>"},{"i":"6-429","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución podrán revestir la forma de denegación de tutela judicial:","o":["De la que se deriven penas desproporcionadas o discriminatorias.","De la que se derive la imposibilidad de acceder a la asistencia jurídica gratuita.","De la que se deriven penas privativas de libertad de más de diez años.","En el marco de procesos seguidos ante tribunales militares."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De la que se deriven penas desproporcionadas o discriminatorias</mark></span>El <span class=\"ref-norma\">art. 6.2.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias;\"</span>"},{"i":"6-430","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución podrán revestir la forma de:","o":["Actos de naturaleza sexual que afecten únicamente a menores de edad.","Actos de violencia de género cometidos en el ámbito familiar y privado.","Actos de naturaleza sexual cometidos exclusivamente por agentes estatales.","Actos de naturaleza sexual que afecten a adultos o a niños."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Actos de naturaleza sexual que afecten a adultos o a niños</mark></span>El <span class=\"ref-norma\">art. 6.2.f) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"f) actos de naturaleza sexual que afecten a adultos o a niños.\"</span>"},{"i":"6-ia-1446","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos en que se basen los fundados temores a ser objeto de persecución deberán ser suficientemente graves por su naturaleza o carácter reiterado como para constituir una violación grave de los derechos fundamentales, o bien:","o":["ser una medida única de especial gravedad adoptada por agentes estatales contra una persona por motivos de raza, religión, nacionalidad u opiniones políticas.","ser una acumulación de varias medidas leves, aunque no afecten a la persona de manera similar a una violación grave.","haber sido declarados como persecución por una resolución del Alto Comisionado de las Naciones Unidas para los Refugiados.","ser una acumulación lo suficientemente grave de varias medidas, incluidas las violaciones de derechos humanos, como para afectar a una persona de manera similar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ser una acumulación lo suficientemente grave de varias medidas, incluidas las violaciones de derechos humanos, como para afectar a una persona de manera similar</mark></span>El <span class=\"ref-norma\">art. 6.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) ser una acumulación lo suficientemente grave de varias medidas, incluidas las violaciones de derechos humanos, como para afectar a una persona de manera similar a la mencionada en la letra a)\"</span>. La alternativa es la acumulación suficientemente grave de varias medidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1448","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Actos de persecución. Los actos de persecución podrán revestir, entre otras, las siguientes formas: Señale la INCORRECTA.","o":["actos de violencia física o psíquica, incluidos los actos de violencia sexual;","denegación de la nacionalidad del Estado de residencia por razones administrativas;","procesamientos o penas por la negativa a prestar servicio militar en un conflicto en el que el cumplimiento de dicho servicio conllevaría delitos comprendidos en las cláusulas de exclusión;","actos de naturaleza sexual que afecten a adultos o a niños."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">denegación de la nacionalidad del Estado de residencia por razones administrativas;</mark></span>El <span class=\"ref-norma\">art. 6.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"f) actos de naturaleza sexual que afecten a adultos o a niños\"</span>. La denegación de la nacionalidad por razones administrativas no figura entre las formas de persecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 36 — Efectos de la concesión del derecho de asilo o de protección subsidiaria ✱","q":[{"i":"6-144","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la resolución. La concesión del derecho de asilo o de la protección subsidiaria implicará el reconocimiento de los derechos establecidos en la Convención de Ginebra sobre el Estatuto de los Refugiados, en la normativa vigente en materia de extranjería e inmigración, así como en la normativa de la Unión Europea, y, en todo caso, señale la INCORRECTA:","o":["La protección contra la devolución en los términos establecidos en los tratados internacionales firmados por España.","El acceso a la información sobre los derechos y obligaciones relacionados con el contenido de la protección internacional concedida, en una lengua que le sea comprensible a la persona beneficiaria de dicha protección.","La expedición de documentos de identidad y viaje a quienes les sea reconocida la condición de refugiado, o cuando sea necesaria, para quienes se beneficien de la protección subsidiaria.","El acceso a los servicios privados de empleo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El acceso a los servicios privados de empleo</mark></span>Según el <span class=\"ref-norma\">art. 36.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"e) el acceso a los servicios públicos de empleo\"</span>. Son los servicios PÚBLICOS de empleo (Verificado con el texto del temario oficial.)"},{"i":"6-169","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. De los efectos de la resolución. La concesión del derecho de asilo o de la protección subsidiaria implicará el reconocimiento de los derechos establecidos en la Convención de Ginebra sobre el Estatuto de los Refugiados, en la normativa vigente en materia de extranjería e inmigración, así como en la normativa de la Unión Europea, y, en todo caso, señale la INCORRECTA:","o":["La protección contra la devolución en los términos establecidos en los tratados internacionales firmados por España.","El acceso a la información sobre los derechos y obligaciones relacionados con el contenido de la protección internacional concedida, en una lengua que le sea comprensible a la persona beneficiaria de dicha protección.","La expedición de documentos de identidad y viaje a quienes les sea reconocida la condición de refugiado, o cuando sea necesaria, para quienes se beneficien de la protección subsidiaria.","El acceso a los servicios privados de empleo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El acceso a los servicios privados de empleo</mark></span>Según el <span class=\"ref-norma\">art. 36.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"e) el acceso a los servicios públicos de empleo\"</span>. Son los servicios PÚBLICOS de empleo (Verificado con el texto del temario oficial.)"},{"i":"6-299","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. De los efectos de la resolución. La concesión del derecho de asilo o de la protección subsidiaria implicará el reconocimiento de los derechos establecidos en la Convención de Ginebra sobre el Estatuto de los Refugiados, en la normativa vigente en materia de extranjería e inmigración, así como en la normativa de la Unión Europea, y, en todo caso, señale la INCORRECTA:","o":["La protección contra la devolución en los términos establecidos en los tratados internacionales firmados por España.","El acceso a la información sobre los derechos y obligaciones relacionados con el contenido de la protección internacional concedida, en una lengua que le sea comprensible a la persona beneficiaria de dicha protección.","La expedición de documentos de identidad y viaje a quienes les sea reconocida la condición de refugiado, o cuando sea necesaria, para quienes se beneficien de la protección subsidiaria.","El acceso a los servicios privados de empleo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El acceso a los servicios privados de empleo</mark></span>Según el <span class=\"ref-norma\">art. 36.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"e) el acceso a los servicios públicos de empleo\"</span>. Son los servicios PÚBLICOS de empleo (Verificado con el texto del temario oficial.)"},{"i":"6-447","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo. La concesión del derecho de asilo o de la protección subsidiaria implicará, entre otros efectos:","o":["La autorización de residencia temporal por un año, prorrogable en los términos de la Ley Orgánica 4/2000, conforme al procedimiento que reglamentariamente se establezca.","La autorización de residencia y trabajo permanente, en los términos que establece la Ley Orgánica 4/2000.","La autorización de residencia de larga duración tras cinco años de residencia continuada.","La autorización de trabajo por cuenta ajena sujeta a la situación nacional de empleo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La autorización de residencia y trabajo permanente, en los términos que establece la Ley Orgánica 4/2000</mark></span>El <span class=\"ref-norma\">art. 36.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) la autorización de residencia y trabajo permanente, en los términos que establece la Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social;\"</span>"},{"i":"6-448","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo. La concesión del derecho de asilo o de la protección subsidiaria implicará, entre otros efectos:","o":["El acceso a los servicios públicos de empleo.","El acceso preferente a la vivienda de protección oficial.","La exención del pago de tasas administrativas durante tres años.","El acceso a la función pública en las mismas condiciones que los españoles."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El acceso a los servicios públicos de empleo</mark></span>El <span class=\"ref-norma\">art. 36.1.e) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"e) el acceso a los servicios públicos de empleo;\"</span>"},{"i":"6-449","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo. La concesión del derecho de asilo o de la protección subsidiaria implicará, entre otros efectos:","o":["El acceso a los programas de reasentamiento en un tercer Estado.","El acceso a la nacionalidad española por residencia en un plazo reducido.","El acceso a las prestaciones no contributivas desde el primer día de residencia, sin perjuicio de lo que establezcan los tratados internacionales.","El acceso a los programas de integración con carácter general o específico que se establezcan."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El acceso a los programas de integración con carácter general o específico que se establezcan</mark></span>El <span class=\"ref-norma\">art. 36.1.i) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"i) el acceso a los programas de integración con carácter general o específico que se establezcan;\"</span>"},{"i":"6-450","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo. La concesión del derecho de asilo o de la protección subsidiaria implicará, entre otros efectos:","o":["El acceso a los programas de reagrupación familiar con carácter prioritario.","El acceso a los programas de ayuda al retorno forzoso que puedan establecerse, en los términos que determine la ley orgánica correspondiente.","El acceso a los programas de ayuda al retorno voluntario que puedan establecerse.","El acceso a los programas de movilidad laboral dentro de la Unión Europea."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El acceso a los programas de ayuda al retorno voluntario que puedan establecerse</mark></span>El <span class=\"ref-norma\">art. 36.1.j) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"j) el acceso a los programas de ayuda al retorno voluntario que puedan establecerse;\"</span>"},{"i":"6-ia-1601","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo o de protección subsidiaria. La concesión del derecho de asilo o de la protección subsidiaria implicará, en todo caso, la expedición de documentos de identidad y viaje:","o":["a quienes les sea reconocida la condición de refugiado, y, cuando sea necesario, para quienes se beneficien de la protección subsidiaria.","a quienes se beneficien de la protección subsidiaria y, cuando sea necesario, a quienes les sea reconocida la condición de refugiado.","tanto a refugiados como a beneficiarios de protección subsidiaria, en todo caso y en las mismas condiciones.","únicamente a quienes les sea reconocida la condición de refugiado, con exclusión en todo caso de los beneficiarios de protección subsidiaria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a quienes les sea reconocida la condición de refugiado, y, cuando sea necesario, para quienes se beneficien de la protección subsidiaria</mark></span>El <span class=\"ref-norma\">art. 36.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) la expedición de documentos de identidad y viaje a quienes les sea reconocida la condición de refugiado, y, cuando sea necesario, para quienes se beneficien de la protección subsidiaria\"</span>. Al refugiado siempre; al beneficiario de protección subsidiaria, cuando sea necesario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1603","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la concesión del derecho de asilo o de protección subsidiaria. La concesión del derecho de asilo o de la protección subsidiaria implicará, en todo caso: Señale la INCORRECTA.","o":["la libertad de circulación;","el acceso a los programas de ayuda al retorno voluntario que puedan establecerse;","la exención de la obligación de obtener la tarjeta de identidad de extranjero;","el mantenimiento de la unidad familiar en los términos previstos en la Ley y acceso a los programas de apoyo que a tal efecto puedan establecerse."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la exención de la obligación de obtener la tarjeta de identidad de extranjero;</mark></span>El <span class=\"ref-norma\">art. 36.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"h) la libertad de circulación; i) el acceso a los programas de integración con carácter general o específico que se establezcan; j) el acceso a los programas de ayuda al retorno voluntario que puedan establecerse\"</span>. La exención de la tarjeta de identidad de extranjero no figura entre los efectos de la concesión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 — Enumeración de las situaciones ✱ R8","q":[{"i":"6-146","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Enumeración de las situaciones. Los extranjeros podrán encontrarse en España en las situaciones de:","o":["Estancia o permanencia.","Permanencia y residencia.","Estancia o residencia.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Estancia o residencia</mark></span>Según el <span class=\"ref-norma\">art. 29.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros podrán encontrarse en España en las situaciones de estancia o residencia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-282","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Enumeración de las situaciones. Los extranjeros podrán encontrarse en España en las situaciones de:","o":["Estancia o permanencia.","Permanencia y residencia.","Estancia o residencia.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Estancia o residencia</mark></span>Según el <span class=\"ref-norma\">art. 29.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros podrán encontrarse en España en las situaciones de estancia o residencia\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-355","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situaciones de los extranjeros. Las diferentes situaciones de los extranjeros en España podrán acreditarse mediante:","o":["Certificado de empadronamiento o tarjeta de identidad de extranjero, según corresponda, salvo que el órgano competente acuerde otra cosa de forma motivada.","Pasaporte o documento de viaje que acredite su identidad, visado o tarjeta de identidad de extranjero, según corresponda.","Pasaporte o documento de viaje, con exclusión del visado, según corresponda.","Visado o certificado de la Delegación del Gobierno, según corresponda."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Pasaporte o documento de viaje que acredite su identidad, visado o tarjeta de identidad de extranjero, según corresponda</mark></span>El <span class=\"ref-norma\">art. 29.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Las diferentes situaciones de los extranjeros en España podrán acreditarse mediante pasaporte o documento de viaje que acredite su identidad, visado o tarjeta de identidad de extranjero, según corresponda.\"</span>"}]},{"a":"Disposición adicional novena — Autorizaciones autonómicas de trabajo en origen","q":[{"i":"6-149","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La integración de los inmigrantes. Las Administraciones Públicas incorporarán el objetivo de la integración entre inmigrantes y sociedad receptora, con carácter transversal a todas las políticas y servicios públicos, promoviendo la participación: señale la INCORRECTA.","o":["Ejecutiva.","Económica y social.","Cultural.","Política."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ejecutiva</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"promoviendo la participación económica, social, cultural y política de las personas inmigrantes\"</span>. La participación «ejecutiva» no figura (Verificado con el texto del temario oficial.)"},{"i":"6-288","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. La integración de los inmigrantes. Las Administraciones Públicas incorporarán el objetivo de la integración entre inmigrantes y sociedad receptora, con carácter transversal a todas las políticas y servicios públicos, promoviendo la participación: señale la INCORRECTA.","o":["Ejecutiva.","Económica y social.","Cultural.","Política."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ejecutiva</mark></span>Según el <span class=\"ref-norma\">art. 2 ter.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"promoviendo la participación económica, social, cultural y política de las personas inmigrantes\"</span>. La participación «ejecutiva» no figura (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 30 — Situación de estancia EXOF EX ✱","q":[{"i":"6-152","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de estancia. En los supuestos de entrada con visado:","o":["Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses.","Por un período superior a 90 días e inferior a seis años.","Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, por un período de igual duración, en un período de seis meses.","Cuando la duración de éste sea inferior a dos meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses</mark></span>Según el <span class=\"ref-norma\">art. 30.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada con visado, cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-160","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de Estancia. En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de:","o":["Tres meses.","Seis meses.","Dos meses.","Un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses</mark></span>Según el <span class=\"ref-norma\">art. 30.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de tres meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-166","p":"Ley Orgánica 4/2000 sobre derechos y libertades de los extranjeros en España y su integración social. Situación de Estancia. Se entenderá por estancia:","o":["La permanencia en territorio español por un período de tiempo no superior a 90 días.","La permanencia en territorio español por un período de tiempo no superior a seis meses.","La permanencia en territorio español por un período de tiempo no superior a cinco años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La permanencia en territorio español por un período de tiempo no superior a 90 días</mark></span>Según el <span class=\"ref-norma\">art. 30.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto en el artículo 33 para la admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-196","p":"Ley Orgánica 4/2000... Situación de estancia. En los supuestos de entrada con visado:","o":["Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses.","Por un período superior a 90 días e inferior a seis años.","Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, por un período de igual duración, en un período de seis meses.","Cuando la duración de éste sea inferior a dos meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses</mark></span>Según el <span class=\"ref-norma\">art. 30.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada con visado, cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-212","p":"Ley Orgánica 4/2000... En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de:","o":["Tres meses.","Seis meses.","Dos meses.","Un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses</mark></span>Según el <span class=\"ref-norma\">art. 30.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de tres meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-216","p":"Ley Orgánica 4/2000... Situación de Estancia. Se entenderá por estancia:","o":["La permanencia en territorio español por un período de tiempo no superior a 90 días.","La permanencia en territorio español por un período de tiempo no superior a seis meses.","La permanencia en territorio español por un período de tiempo no superior a cinco años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La permanencia en territorio español por un período de tiempo no superior a 90 días</mark></span>Según el <span class=\"ref-norma\">art. 30.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto en el artículo 33 para la admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-234","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. La estancia es la permanencia en territorio español por un período de tiempo:","o":["Inferior a 180 días.","Inferior a 90 días.","No superior a 90 días.","No superior a 6 meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No superior a 90 días</mark></span>Según el <span class=\"ref-norma\">art. 30.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto en el artículo 33 para la admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-235","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. El plazo máximo de resolución y notificación de los procedimientos de concesión o denegación de permisos y visados regulados en esta Ley, salvo excepciones concretas, es de:","o":["Un mes.","Tres meses.","Seis meses.","Quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tres meses</mark></span>Según el <span class=\"ref-norma\">disposición adicional primera de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las solicitudes de prórroga de la autorización de residencia, la renovación de la autorización de trabajo, así como las solicitudes de autorización de residencia de larga duración que se formulen por los interesados a tenor de lo dispuesto en la presente Ley Orgánica se resolverán y notificarán en el plazo máximo de tres meses contados a partir del día siguiente al de la fecha en que hayan tenido entrada en el registro del órgano competente para tramitarlas\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-249","p":"(Ley Orgánica 4/2000) Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un período superior a ___________ obtendrán la tarjeta de identidad de extranjero.","o":["Dieciséis meses.","Seis meses.","Diez meses.","Ocho meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 4.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un período superior a seis meses, obtendrán la tarjeta de identidad de extranjero\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-272","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de estancia. En los supuestos de entrada con visado:","o":["Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses.","Por un período superior a 90 días e inferior a seis años.","Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, por un período de igual duración, en un período de seis meses.","Cuando la duración de éste sea inferior a dos meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses</mark></span>Según el <span class=\"ref-norma\">art. 30.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada con visado, cuando la duración de éste sea inferior a tres meses, se podrá prorrogar la estancia, que en ningún caso podrá ser superior a tres meses, en un período de seis meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-290","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de Estancia. En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de:","o":["Tres meses.","Seis meses.","Dos meses.","Un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses</mark></span>Según el <span class=\"ref-norma\">art. 30.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de tres meses\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-296","p":"Ley Orgánica 4/2000 sobre derechos y libertades de los extranjeros en España y su integración social. Situación de Estancia. Se entenderá por estancia:","o":["La permanencia en territorio español por un período de tiempo no superior a 90 días.","La permanencia en territorio español por un período de tiempo no superior a seis meses.","La permanencia en territorio español por un período de tiempo no superior a cinco años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La permanencia en territorio español por un período de tiempo no superior a 90 días</mark></span>Según el <span class=\"ref-norma\">art. 30.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto en el artículo 33 para la admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-356","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de estancia. Transcurrido el tiempo de estancia, para permanecer en España será preciso obtener:","o":["Una prórroga de estancia o una autorización de residencia.","Una autorización de residencia, sin posibilidad de prórroga de estancia.","Una prórroga de estancia o un visado de larga duración.","Una autorización de residencia temporal exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Una prórroga de estancia o una autorización de residencia</mark></span>El <span class=\"ref-norma\">art. 30.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Transcurrido dicho tiempo, para permanecer en España será preciso obtener o una prórroga de estancia o una autorización de residencia.\"</span>"},{"i":"6-423","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Inadmisión de visados de tránsito o estancia. En los procedimientos relativos a solicitudes de visado de tránsito o estancia, se inadmitirá a trámite la solicitud presentada fuera del plazo de:","o":["Los seis meses anteriores al comienzo del viaje.","Los quince días anteriores al comienzo del viaje.","Los tres meses anteriores al comienzo del viaje.","Los tres meses posteriores al comienzo del viaje."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los tres meses anteriores al comienzo del viaje</mark></span>El <span class=\"ref-norma\">disp. adic. 4.ª.2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Presentación de la solicitud fuera del plazo de los tres meses anteriores al comienzo del viaje.\"</span>"},{"i":"6-ia-1101","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de estancia. Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto para la admisión a efectos de:","o":["estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado.","estudios, investigación, prácticas laborales o trabajos de temporada.","turismo, negocios, estudios o tratamiento médico acreditado.","estudios, formación profesional, empleo en prácticas o voluntariado remunerado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado</mark></span>El <span class=\"ref-norma\">art. 30.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Estancia es la permanencia en territorio español por un período de tiempo no superior a 90 días, sin perjuicio de lo dispuesto en el artículo 33 para la admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado\"</span>. La salvedad se refiere al régimen de estudios, intercambio de alumnos, prácticas NO laborales y voluntariado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1102","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de estancia y de residencia. Sobre las situaciones de estancia y residencia, señale la INCORRECTA:","o":["Transcurrido el tiempo de estancia, para permanecer en España será preciso obtener o una prórroga de estancia o una autorización de residencia.","Son residentes los extranjeros que se encuentren en España y sean titulares de una autorización para residir.","Los residentes podrán encontrarse en la situación de residencia temporal o de residencia de larga duración.","En los supuestos de entrada sin visado, la estancia podrá autorizarse más allá de tres meses en todo caso, a petición del interesado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En los supuestos de entrada sin visado, la estancia podrá autorizarse más allá de tres meses en todo caso, a petición del interesado</mark></span>El <span class=\"ref-norma\">arts. 30 y 30 bis de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En los supuestos de entrada sin visado, cuando concurran circunstancias excepcionales que lo justifiquen, podrá autorizarse la estancia de un extranjero en el territorio español más allá de tres meses\"</span>. Sin visado, la estancia más allá de tres meses solo se autoriza cuando concurran circunstancias excepcionales que lo justifiquen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 — Agentes de protección R24","q":[{"i":"6-155","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de protección. Podrán proporcionar protección: Señale la INCORRECTA.","o":["El Estado.","Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución.","Los partidos, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio.","Las organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución</mark></span>Según el <span class=\"ref-norma\">art. 14.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio\"</span>. Los «agentes no estatales» son agentes de persecución, no de protección (Verificado con el texto del temario oficial.)"},{"i":"6-195","p":"Ley 12/2009... Agentes de protección. Podrán proporcionar protección: Señale la INCORRECTA.","o":["El Estado.","Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución.","Los partidos, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio.","Las organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución</mark></span>Según el <span class=\"ref-norma\">art. 14.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio\"</span>. Los «agentes no estatales» son agentes de persecución, no de protección (Verificado con el texto del temario oficial.)"},{"i":"6-280","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de protección. Podrán proporcionar protección: Señale la INCORRECTA.","o":["El Estado.","Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución.","Los partidos, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio.","Las organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidos los organismos internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución</mark></span>Según el <span class=\"ref-norma\">art. 14.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio\"</span>. Los «agentes no estatales» son agentes de persecución, no de protección (Verificado con el texto del temario oficial.)"},{"i":"6-441","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de protección. Podrán proporcionar protección:","o":["El Estado y las organizaciones no gubernamentales con presencia en el territorio.","Los partidos políticos y los agentes no estatales con capacidad de protección efectiva.","El Estado, con exclusión de las organizaciones internacionales que controlen parte de su territorio, conforme al procedimiento que reglamentariamente se establezca.","El Estado, o los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Estado, o los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio</mark></span>El <span class=\"ref-norma\">art. 14.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"1. Podrán proporcionar protección: a) el Estado, o b) los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el Estado o una parte considerable de su territorio.\"</span>"},{"i":"6-465","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de persecución o causantes de daños graves. Los agentes de persecución o causantes de daños graves podrán ser:","o":["Los partidos políticos con representación en las Cortes Generales del Estado.","Las organizaciones internacionales con presencia en el territorio del Estado.","Los partidos u organizaciones que controlen el Estado o una parte considerable de su territorio.","Los partidos u organizaciones que controlen una pequeña parte del territorio del Estado, en los términos que determine la ley orgánica correspondiente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los partidos u organizaciones que controlen el Estado o una parte considerable de su territorio</mark></span>El <span class=\"ref-norma\">art. 13.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) los partidos u organizaciones que controlen el Estado o una parte considerable de su territorio;\"</span>"},{"i":"6-ia-1508","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de protección. En general, se entenderá que existe protección cuando los agentes de protección adopten medidas razonables y efectivas para impedir la persecución o el padecimiento de daños graves, tales como el establecimiento de un sistema jurídico eficaz para la investigación, el procesamiento y la sanción de acciones constitutivas de persecución o de daños graves:","o":["aunque el solicitante no tenga acceso efectivo a dicha protección.","y siempre que el solicitante tenga acceso efectivo a dicha protección.","y siempre que así lo haya reconocido el ACNUR en su informe.","y siempre que el Estado haya ratificado los convenios internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">y siempre que el solicitante tenga acceso efectivo a dicha protección</mark></span>El <span class=\"ref-norma\">art. 14.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"y siempre que el solicitante tenga acceso efectivo a dicha protección\"</span>. Se requiere que el solicitante tenga acceso efectivo a la protección. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1509","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de protección. Al efecto de valorar si una organización internacional controla un Estado o una parte considerable de su territorio y proporciona protección, se tendrá en cuenta la orientación que pueda desprenderse de:","o":["los actos pertinentes de las instituciones de la Unión Europea o de organizaciones internacionales relevantes.","los informes del Ministerio de Asuntos Exteriores y de las representaciones diplomáticas españolas.","las resoluciones del Consejo de Seguridad de las Naciones Unidas exclusivamente.","la jurisprudencia del Tribunal Europeo de Derechos Humanos y del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los actos pertinentes de las instituciones de la Unión Europea o de organizaciones internacionales relevantes</mark></span>El <span class=\"ref-norma\">art. 14.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Se tendrá en cuenta la orientación que pueda desprenderse de los actos pertinentes de las instituciones de la Unión Europea o de organizaciones internacionales relevantes\"</span>. Se atiende a los actos de las instituciones de la UE o de organizaciones internacionales relevantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 62 quinquies — Medidas de seguridad ✱","q":[{"i":"6-158","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas de Seguridad. El juez, _________ y siempre que la medida acordada fuere separación preventiva del agresor, deberá si está vigente, acordar su mantenimiento o revocación.","o":["Cuando lo estimare oportuno.","En el plazo máximo de 30 días.","En el plazo más breve posible.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo más breve posible</mark></span>Según el <span class=\"ref-norma\">art. 62 quinquies.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El juez, en el plazo más breve posible y siempre que la medida acordada fuere separación preventiva del agresor, deberá si está vigente, acordar su mantenimiento o revocación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-187","p":"Ley Orgánica 4/2000... Medidas de seguridad en Centros de Internamientos. La utilización de medios de contención será previamente autorizada por:","o":["El responsable de las Fuerzas y Cuerpos de Seguridad con competencia territorial.","El juez de vigilancia penitenciaria.","El Juez de instrucción.","El director del centro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El director del centro</mark></span>Según el <span class=\"ref-norma\">art. 62 quinquies.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La utilización de medios de contención será previamente autorizada por el director del centro, salvo que razones de urgencia no lo permitan, en cuyo caso se pondrá en su conocimiento inmediatamente\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-286","p":"Ley Orgánica 4/2000... Medidas de Seguridad. El Juez, ________________ y siempre que la medida acordada fuere separación preventiva del agresor, deberá si está vigente, acordar su mantenimiento o revocación.","o":["Cuando lo estimare oportuno.","En el plazo máximo de 30 días.","En el plazo más breve posible.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo más breve posible</mark></span>Según el <span class=\"ref-norma\">art. 62 quinquies.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El juez, en el plazo más breve posible y siempre que la medida acordada fuere separación preventiva del agresor, deberá si está vigente, acordar su mantenimiento o revocación\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-314","p":"Ley Orgánica 4/2000... Medidas de seguridad en Centros de Internamientos. La utilización de medios de contención será previamente autorizada por:","o":["El responsable de las Fuerzas y Cuerpos de Seguridad con competencia territorial.","El juez de vigilancia penitenciaria.","El Juez de instrucción.","El director del centro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El director del centro</mark></span>Según el <span class=\"ref-norma\">art. 62 quinquies.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"La utilización de medios de contención será previamente autorizada por el director del centro, salvo que razones de urgencia no lo permitan, en cuyo caso se pondrá en su conocimiento inmediatamente\"</span>. (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 30 bis — Situación de residencia","q":[{"i":"6-163","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Los residentes podrán encontrarse en situación de:","o":["Residencia temporal o de residencia de larga duración.","Estancia temporal o de residencia de larga duración.","Estancia temporal o de estancia de larga duración.","Residencia temporal o de estancia de larga duración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Residencia temporal o de residencia de larga duración</mark></span>Según el <span class=\"ref-norma\">art. 30 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los residentes podrán encontrarse en la situación de residencia temporal o de residencia de larga duración\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-293","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Los residentes podrán encontrarse en situación de:","o":["Residencia temporal o de residencia de larga duración.","Estancia temporal o de residencia de larga duración.","Estancia temporal o de estancia de larga duración.","Residencia temporal o de estancia de larga duración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Residencia temporal o de residencia de larga duración</mark></span>Según el <span class=\"ref-norma\">art. 30 bis.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los residentes podrán encontrarse en la situación de residencia temporal o de residencia de larga duración\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1103","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Situación de residencia. Son residentes los extranjeros que se encuentren en España y:","o":["estén inscritos en el Padrón Municipal de Habitantes.","permanezcan en territorio español más de 90 días.","sean titulares de una autorización para residir.","sean titulares de una tarjeta de identidad de extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sean titulares de una autorización para residir</mark></span>El <span class=\"ref-norma\">art. 30 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Son residentes los extranjeros que se encuentren en España y sean titulares de una autorización para residir\"</span>. La condición de residente depende de ser titular de una autorización para residir, no del padrón ni del tiempo de permanencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 — Recursos ✱ R26","q":[{"i":"6-168","p":"Ley 12/2009 reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Señale la INCORRECTA:","o":["Las resoluciones sobre el cese y la revocación pondrán fin a la vía administrativa.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso contencioso-administrativo.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 45.8 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en este Título pondrán fin a la vía administrativa y serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior y de recurso contencioso-administrativo\"</span>. No cabe recurso de alzada (Verificado con el texto del temario oficial.)"},{"i":"6-214","p":"Ley 12/2009... Procedimientos para el cese y la revocación. Señale la INCORRECTA:","o":["Las resoluciones sobre el cese y la revocación pondrán fin a la vía administrativa.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso contencioso-administrativo.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 45.8 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en este Título pondrán fin a la vía administrativa y serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior y de recurso contencioso-administrativo\"</span>. No cabe recurso de alzada (Verificado con el texto del temario oficial.)"},{"i":"6-224","p":"Ley 12/2009... En materia de recursos, señale la CORRECTA:","o":["Las resoluciones previstas en esta Ley pondrán fin a la vía administrativa (salvo si se presentó la petición de reexamen del art. 21.4) y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa.","Cuando se interponga el recurso de reposición y se solicite la suspensión del acto recurrido.","La persona a quien se haya denegado la solicitud podrá solicitar su reexamen cuando aparezcan nuevos elementos probatorios.","En el caso de que se haya paralizado el período de reexamen, se entenderá que la resolución que resulte de dicha paralización pone fin a la vía administrativa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las resoluciones previstas en esta Ley pondrán fin a la vía administrativa (salvo si se presentó la petición de reexamen del art. 21.4) y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa</mark></span>Se corrige la opción A, que decía «en todo caso»: si hay petición de reexamen, pone fin a la vía administrativa la resolución del reexamen. Según el <span class=\"ref-norma\">art. 29.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en la presente Ley pondrán fin a la vía administrativa, salvo en el caso de que se haya presentado la petición de reexamen prevista en el apartado cuarto del artículo 21, en que se entenderá que pone fin a la vía administrativa la resolución que decida dicha petición, y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa.\"</span> (verificado con el texto del temario)."},{"i":"6-298","p":"Ley 12/2009 reguladora del derecho de asilo y de la protección subsidiaria. Procedimientos para el cese y la revocación. Señale la INCORRECTA:","o":["Las resoluciones sobre el cese y la revocación pondrán fin a la vía administrativa.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso contencioso-administrativo.","Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones sobre el cese y la revocación serán susceptibles de recurso de alzada ante el Ministro del Interior</mark></span>Según el <span class=\"ref-norma\">art. 45.8 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en este Título pondrán fin a la vía administrativa y serán susceptibles de recurso de reposición con carácter potestativo ante el Ministro del Interior y de recurso contencioso-administrativo\"</span>. No cabe recurso de alzada (Verificado con el texto del temario oficial.)"},{"i":"6-335","p":"Ley 12/2009... En materia de recursos, señale la CORRECTA:","o":["Las resoluciones previstas en esta Ley pondrán fin a la vía administrativa (salvo si se presentó la petición de reexamen del art. 21.4) y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa.","Cuando se interponga el recurso de reposición y se solicite la suspensión del acto recurrido.","La persona a quien se haya denegado la solicitud podrá solicitar su reexamen cuando aparezcan nuevos elementos probatorios.","En el caso de que se haya paralizado el período de reexamen, se entenderá que la resolución que resulte de dicha paralización pone fin a la vía administrativa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las resoluciones previstas en esta Ley pondrán fin a la vía administrativa (salvo si se presentó la petición de reexamen del art. 21.4) y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa</mark></span>Se corrige la opción A, que decía «en todo caso»: si hay petición de reexamen, pone fin a la vía administrativa la resolución del reexamen. Según el <span class=\"ref-norma\">art. 29.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Las resoluciones previstas en la presente Ley pondrán fin a la vía administrativa, salvo en el caso de que se haya presentado la petición de reexamen prevista en el apartado cuarto del artículo 21, en que se entenderá que pone fin a la vía administrativa la resolución que decida dicha petición, y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa.\"</span> (verificado con el texto del temario)."},{"i":"6-445","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Recursos. Las resoluciones previstas en la Ley pondrán fin a la vía administrativa y serán susceptibles de:","o":["Recurso de alzada obligatorio y de recurso ante la jurisdicción contencioso-administrativa, salvo que el órgano competente acuerde otra cosa de forma motivada.","Recurso de reposición con carácter obligatorio y de recurso ante el Tribunal Supremo.","Recurso extraordinario de revisión y de recurso ante la Audiencia Nacional exclusivamente.","Recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa</mark></span>El <span class=\"ref-norma\">art. 29.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"1. Las resoluciones previstas en la presente Ley pondrán fin a la vía administrativa, salvo en el caso de que se haya presentado la petición de reexamen prevista en el apartado cuarto del artículo 21, en que se entenderá que pone fin a la vía administrativa la resolución que decida dicha petición, y serán susceptibles de recurso de reposición con carácter potestativo y de recurso ante la jurisdicción contencioso-administrativa.\"</span>"},{"i":"6-ia-1543","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Recursos. Cuando se interponga un recurso contencioso-administrativo contra una resolución en materia de protección internacional y se solicite la suspensión del acto recurrido, dicha solicitud:","o":["producirá la suspensión automática del acto recurrido hasta que recaiga sentencia firme en el proceso.","deberá resolverse por el Juez de Instrucción del lugar en que se encuentre la persona solicitante.","tendrá la consideración de especial urgencia contemplada en la Ley Reguladora de la Jurisdicción Contencioso-Administrativa.","no impedirá la ejecución inmediata de la resolución recurrida, salvo que la persona solicitante sea menor de edad o persona vulnerable."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tendrá la consideración de especial urgencia contemplada en la Ley Reguladora de la Jurisdicción Contencioso-Administrativa</mark></span>El <span class=\"ref-norma\">art. 29.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"dicha solicitud tendrá la consideración de especial urgencia contemplada en el artículo 135 de la Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa\"</span>. Se tramita como especial urgencia en la jurisdicción contencioso-administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1544","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Recursos. La persona a quien le haya sido denegada la solicitud de protección internacional podrá solicitar su revisión:","o":["en el plazo de un mes desde la notificación, mediante petición de reexamen ante el Ministro del Interior.","cuando aparezcan nuevos elementos probatorios, conforme a la legislación de procedimiento administrativo.","cuando lo solicite el ACNUR mediante informe razonado, en el plazo de seis meses desde la denegación.","en cualquier momento, siempre que haya cambiado la situación general de su país de origen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando aparezcan nuevos elementos probatorios, conforme a la legislación de procedimiento administrativo</mark></span>El <span class=\"ref-norma\">art. 29.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La persona a quien le haya sido denegada la solicitud podrá solicitar su revisión cuando aparezcan nuevos elementos probatorios\"</span>. La revisión procede cuando aparezcan nuevos elementos probatorios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 40 — Supuestos específicos de exención de la situación nacional de empleo ✱","q":[{"i":"6-173","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: Señale la opción INCORRECTA.","o":["Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española.","Los extranjeros nacidos y residentes en España.","Los titulares de una autorización previa de trabajo que pretendan su renovación.","Los titulares de una autorización de estancia por estudios que pretendan su renovación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los titulares de una autorización de estancia por estudios que pretendan su renovación</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Los titulares de una autorización previa de trabajo que pretendan su renovación\"</span>. Había tres opciones falsas; se corrigen con el texto literal (Verificado con el texto del temario oficial.)"},{"i":"6-201","p":"Ley Orgánica 4/2000... No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: señale la INCORRECTA.","o":["Los titulares de una autorización previa de trabajo que pretendan su renovación.","Los trabajadores necesarios para el montaje por renovación de una instalación o equipos productivos.","Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante cuatro años naturales, y hayan retornado a su país.","Los extranjeros que hayan renunciado a su autorización de residencia y trabajo en virtud de un programa de retorno voluntario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante cuatro años naturales, y hayan retornado a su país</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"k) Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante dos años naturales, y hayan retornado a su país\"</span>. Son dos años naturales, no cuatro (Verificado con el texto del temario oficial.)"},{"i":"6-303","p":"Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social. Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: Señale la opción INCORRECTA.","o":["Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española.","Los extranjeros nacidos y residentes en España.","Los titulares de una autorización previa de trabajo que pretendan su renovación.","Los titulares de una autorización de estancia por estudios que pretendan su renovación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los titulares de una autorización de estancia por estudios que pretendan su renovación</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Los titulares de una autorización previa de trabajo que pretendan su renovación\"</span>. Había tres opciones falsas; se corrigen con el texto literal (Verificado con el texto del temario oficial.)"},{"i":"6-324","p":"Ley Orgánica 4/2000... No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: señale la INCORRECTA.","o":["Los titulares de una autorización previa de trabajo que pretendan su renovación.","Los trabajadores necesarios para el montaje por renovación de una instalación o equipos productivos.","Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante cuatro años naturales, y hayan retornado a su país.","Los extranjeros que hayan renunciado a su autorización de residencia y trabajo en virtud de un programa de retorno voluntario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante cuatro años naturales, y hayan retornado a su país</mark></span>Según el <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"k) Los extranjeros que hayan sido titulares de autorizaciones de trabajo para actividades de temporada, durante dos años naturales, y hayan retornado a su país\"</span>. Son dos años naturales, no cuatro (Verificado con el texto del temario oficial.)"},{"i":"6-368","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto de los que hubieran gozado de la condición de refugiados, durante:","o":["Los dos años siguientes a la cesación de la aplicación de la Convención de Ginebra.","Los seis meses siguientes a la denegación de la protección internacional.","El año siguiente a la concesión de la protección subsidiaria.","El año siguiente a la cesación de la aplicación de la Convención de Ginebra."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El año siguiente a la cesación de la aplicación de la Convención de Ginebra</mark></span>El <span class=\"ref-norma\">art. 40.1.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Los que hubieran gozado de la condición de refugiados, durante el año siguiente a la cesación de la aplicación de la Convención de Ginebra\"</span>"},{"i":"6-370","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto de los menores extranjeros en edad laboral con autorización de residencia que sean tutelados por la entidad de protección de menores competente, para aquellas actividades que, a criterio de la mencionada entidad:","o":["Favorezcan su formación profesional, y una vez cumplidos los dieciséis años de edad.","Favorezcan su integración social, y una vez acreditada la imposibilidad de retorno con su familia o al país de origen.","Faciliten su emancipación económica, previo informe favorable del Ministerio Fiscal.","Favorezcan su integración social, con independencia de la posibilidad de retorno al país de origen, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Favorezcan su integración social, y una vez acreditada la imposibilidad de retorno con su familia o al país de origen</mark></span>El <span class=\"ref-norma\">art. 40.1.i) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"i) Los menores extranjeros en edad laboral con autorización de residencia que sean tutelados por la entidad de protección de menores competente, para aquellas actividades que, a criterio de la mencionada entidad, favorezcan su integración social, y una vez acreditada la imposibilidad de retorno con su familia o al país de origen.\"</span>"},{"i":"6-371","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto de los extranjeros que hayan renunciado a su autorización de residencia y trabajo:","o":["En virtud de un programa de retorno voluntario.","Para trasladarse a otro Estado miembro de la Unión Europea.","Por haber obtenido la nacionalidad de otro Estado.","Para cursar estudios en el extranjero durante más de un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En virtud de un programa de retorno voluntario</mark></span>El <span class=\"ref-norma\">art. 40.1.l) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"l) Los extranjeros que hayan renunciado a su autorización de residencia y trabajo en virtud de un programa de retorno voluntario.\"</span>"},{"i":"6-ia-1210","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo cuando el contrato de trabajo vaya dirigido a: Señale la INCORRECTA.","o":["Los trabajadores necesarios para el montaje por renovación de una instalación o equipos productivos.","Los que hubieran sido reconocidos como apátridas y los que hubieran perdido la condición de apátridas el año siguiente a la terminación de dicho estatuto.","Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española.","Los que hubieran sido reconocidos como apátridas, durante los cinco años siguientes a dicho reconocimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los que hubieran sido reconocidos como apátridas, durante los cinco años siguientes a dicho reconocimiento</mark></span>El <span class=\"ref-norma\">art. 40.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Los que hubieran sido reconocidos como apátridas y los que hubieran perdido la condición de apátridas el año siguiente a la terminación de dicho estatuto\"</span>. La Ley no limita a cinco años el supuesto de los apátridas; para quienes perdieron la condición, es el año siguiente a la terminación del estatuto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1211","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Supuestos específicos de exención de la situación nacional de empleo. No se tendrá en cuenta la situación nacional de empleo respecto del hijo de ciudadanos de otros Estados miembros de la Unión Europea y de otros Estados parte en el Espacio Económico Europeo, siempre que estos últimos lleven:","o":["como mínimo, dos años residiendo legalmente en España y el hijo sea menor de veintiún años.","como mínimo, seis meses residiendo legalmente en España y el hijo conviva con ellos.","como mínimo, un año residiendo legalmente en España y al hijo no le sea de aplicación el régimen comunitario.","como mínimo, un año residiendo legalmente en España, aunque al hijo le sea de aplicación el régimen comunitario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">como mínimo, un año residiendo legalmente en España y al hijo no le sea de aplicación el régimen comunitario</mark></span>El <span class=\"ref-norma\">art. 40.1.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"siempre que estos últimos lleven, como mínimo, un año residiendo legalmente en España y al hijo no le sea de aplicación el régimen comunitario\"</span>. Un año de residencia legal de los padres y que al hijo no le sea aplicable el régimen comunitario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 — Derecho a la asistencia jurídica gratuita","q":[{"i":"6-180","p":"Ley Orgánica 4/2000... Derecho a la asistencia y a la tutela judicial efectiva. Señale la CORRECTA:","o":["Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos penales pero no administrativos que puedan llevar a su denegación de entrada, devolución o expulsión.","Los extranjeros que se hallen en España tienen derecho a asistencia letrada únicamente en los procedimientos judiciales que puedan llevar a su denegación de entrada, devolución o expulsión.","Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional</mark></span>Según el <span class=\"ref-norma\">art. 22.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional\"</span>. Se reescriben B y C con el texto literal (Verificado con el texto del temario oficial.)"},{"i":"6-308","p":"Ley Orgánica 4/2000... Derecho a la asistencia y a la tutela judicial efectiva. Señale la CORRECTA:","o":["Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos penales pero no administrativos que puedan llevar a su denegación de entrada, devolución o expulsión.","Los extranjeros que se hallen en España tienen derecho a asistencia letrada únicamente en los procedimientos judiciales que puedan llevar a su denegación de entrada, devolución o expulsión.","Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional</mark></span>Según el <span class=\"ref-norma\">art. 22.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros que se hallen en España tienen derecho a asistencia letrada en los procedimientos administrativos que puedan llevar a su denegación de entrada, devolución, o expulsión del territorio español y en todos los procedimientos en materia de protección internacional\"</span>. Se reescriben B y C con el texto literal (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 35 — Menores no acompañados ✱ R9 R10","q":[{"i":"6-190","p":"Ley Orgánica 4/2000... Menores no acompañados. ¿Quién podrán establecer acuerdos con los países de origen dirigidos a procurar que la atención e integración social de los menores se realice en su entorno de procedencia?","o":["El Ministro de Asuntos Exteriores.","El Ministro del Interior.","Las Comunidades Autónomas.","El Consejo de Ministros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Comunidades Autónomas</mark></span>Al Gobierno le corresponde promover los Acuerdos de colaboración del art. 35.1 (prevención, protección y retorno). Según el <span class=\"ref-norma\">art. 35.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Comunidades Autónomas podrán establecer acuerdos con los países de origen dirigidos a procurar que la atención e integración social de los menores se realice en su entorno de procedencia.\"</span> (verificado con el texto del temario)."},{"i":"6-263","p":"(Ley Orgánica 4/2000) Menores NO acompañados: señala la INCORRECTA.","o":["Las Comunidades Autónomas podrán establecer acuerdos con los países de origen dirigidos a procurar la atención e integración social y el retorno de los menores no acompañados.","En los supuestos en que los Cuerpos y Fuerzas de Seguridad del Estado localicen a un extranjero indocumentado cuya minoría de edad no pueda ser establecida con seguridad, se pondrá el hecho en conocimiento inmediato del Ministerio Fiscal, que dispondrá la determinación de su edad.","Determinada la edad, si se tratase de un menor, el Ministerio Fiscal lo pondrá a disposición de los servicios competentes de protección de menores de la Comunidad Autónoma en la que se halle.","El Gobierno promoverá el establecimiento de Acuerdos de colaboración con los países de origen que contemplen, integradamente, la prevención de la inmigración irregular, la protección y el retorno3."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Comunidades Autónomas podrán establecer acuerdos con los países de origen dirigidos a procurar la atención e integración social y el retorno de los menores no acompañados</mark></span>Según el <span class=\"ref-norma\">art. 35.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Comunidades Autónomas podrán establecer acuerdos con los países de origen dirigidos a procurar que la atención e integración social de los menores se realice en su entorno de procedencia\"</span>. El «retorno» lo contemplan los Acuerdos del Gobierno; se corrigen B y C (es el Ministerio Fiscal quien los pone a disposición) (Verificado con el texto del temario oficial.)"},{"i":"6-316","p":"Ley Orgánica 4/2000... Menores no acompañados. ¿Quién podrán establecer acuerdos con los países de origen dirigidos a procurar que la atención e integración social de los menores se realice en su entorno de procedencia?","o":["El Ministro de Asuntos Exteriores.","El Ministro del Interior.","Las Comunidades Autónomas.","El Consejo de Ministros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Comunidades Autónomas</mark></span>Al Gobierno le corresponde promover los Acuerdos de colaboración del art. 35.1 (prevención, protección y retorno). Según el <span class=\"ref-norma\">art. 35.2 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Las Comunidades Autónomas podrán establecer acuerdos con los países de origen dirigidos a procurar que la atención e integración social de los menores se realice en su entorno de procedencia.\"</span> (verificado con el texto del temario)."},{"i":"6-364","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. Promoverá el establecimiento de Acuerdos de colaboración con los países de origen que contemplen, integradamente, la prevención de la inmigración irregular, la protección y el retorno de los menores no acompañados:","o":["El Gobierno.","Las Comunidades Autónomas.","El Ministerio de Asuntos Exteriores.","La Entidad de protección de menores competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Gobierno</mark></span>El <span class=\"ref-norma\">art. 35.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. El Gobierno promoverá el establecimiento de Acuerdos de colaboración con los países de origen que contemplen, integradamente, la prevención de la inmigración irregular, la protección y el retorno de los menores no acompañados.\"</span>"},{"i":"6-365","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. A los mayores de dieciséis y menores de dieciocho años se les reconocerá capacidad para actuar en el procedimiento de repatriación, pudiendo intervenir:","o":["Únicamente a través del representante designado por la entidad de protección.","Personalmente, con la asistencia obligatoria del Ministerio Fiscal.","A través del defensor judicial que nombre el juez en todo caso.","Personalmente o a través del representante que designen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Personalmente o a través del representante que designen</mark></span>El <span class=\"ref-norma\">art. 35.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"6. A los mayores de dieciséis y menores de dieciocho años se les reconocerá capacidad para actuar en el procedimiento de repatriación previsto en este artículo, así como en el orden jurisdiccional contencioso administrativo por el mismo objeto, pudiendo intervenir personalmente o a través del representante que designen.\"</span>"},{"i":"6-ia-1127","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. En los supuestos en que los Cuerpos y Fuerzas de Seguridad del Estado localicen a un extranjero indocumentado cuya minoría de edad no pueda ser establecida con seguridad, el Ministerio Fiscal dispondrá la determinación de su edad, para lo que colaborarán las instituciones sanitarias oportunas que:","o":["en el plazo máximo de setenta y dos horas, realizarán las pruebas.","previa autorización judicial, realizarán las pruebas radiológicas.","con carácter prioritario, realizarán las pruebas necesarias.","con carácter urgente y previo consentimiento del menor, realizarán las pruebas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con carácter prioritario, realizarán las pruebas necesarias</mark></span>El <span class=\"ref-norma\">art. 35.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"para lo que colaborarán las instituciones sanitarias oportunas que, con carácter prioritario, realizarán las pruebas necesarias\"</span>. La LO 4/2000 dice «con carácter prioritario» (la Ley 12/2009 añade «y urgente» para los solicitantes de asilo). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1128","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. Cuando los Cuerpos y Fuerzas de Seguridad del Estado localicen a un extranjero indocumentado cuya minoría de edad no pueda ser establecida con seguridad, se le dará la atención inmediata que precise:","o":["por los propios Cuerpos y Fuerzas de Seguridad del Estado, hasta que el Ministerio Fiscal determine su edad.","por los servicios competentes de protección de menores, de acuerdo con la legislación de protección jurídica del menor.","por las instituciones sanitarias, de acuerdo con la normativa reguladora de la asistencia sanitaria.","por la Delegación del Gobierno, en coordinación con los servicios sociales de la Comunidad Autónoma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por los servicios competentes de protección de menores, de acuerdo con la legislación de protección jurídica del menor</mark></span>El <span class=\"ref-norma\">art. 35.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se le dará, por los servicios competentes de protección de menores, la atención inmediata que precise, de acuerdo con lo establecido en la legislación de protección jurídica del menor\"</span>. La atención inmediata la prestan los servicios competentes de protección de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1129","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. La Administración del Estado solicitará informe sobre las circunstancias familiares del menor a la representación diplomática del país de origen:","o":["con carácter previo a la decisión relativa a la iniciación de un procedimiento sobre su repatriación.","una vez acordada la repatriación, para asegurar su reagrupación familiar en el país de origen.","con carácter previo a la puesta a disposición del menor ante los servicios de protección.","en el plazo de un mes desde que el menor fuera puesto a disposición del Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con carácter previo a la decisión relativa a la iniciación de un procedimiento sobre su repatriación</mark></span>El <span class=\"ref-norma\">art. 35.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La Administración del Estado solicitará informe sobre las circunstancias familiares del menor a la representación diplomática del país de origen con carácter previo a la decisión relativa a la iniciación de un procedimiento sobre su repatriación\"</span>. El informe se pide ANTES de decidir si se inicia el procedimiento de repatriación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1130","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. De acuerdo con el principio de interés superior del menor, la repatriación al país de origen se efectuará:","o":["únicamente mediante reagrupación familiar, previa conformidad expresa del menor si tuviera suficiente juicio y previo informe favorable de los servicios de protección de menores del país de origen.","bien mediante reagrupación familiar, bien mediante la entrega del menor a la representación diplomática de su país de origen.","mediante la puesta a disposición del menor ante las autoridades de frontera de su país, en todo caso.","bien mediante reagrupación familiar, bien mediante la puesta a disposición del menor ante los servicios de protección de menores, si se dieran las condiciones adecuadas para su tutela."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">bien mediante reagrupación familiar, bien mediante la puesta a disposición del menor ante los servicios de protección de menores, si se dieran las condiciones adecuadas para su tutela</mark></span>El <span class=\"ref-norma\">art. 35.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la repatriación al país de origen se efectuará bien mediante reagrupación familiar, bien mediante la puesta a disposición del menor ante los servicios de protección de menores, si se dieran las condiciones adecuadas para su tutela por parte de los mismos\"</span>. Son las dos vías: reagrupación familiar o servicios de protección de menores del país de origen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1131","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. Cuando se trate de menores de dieciséis años, con juicio suficiente, que hubieran manifestado una voluntad contraria a la de quien ostenta su tutela o representación en el procedimiento de repatriación:","o":["se archivará el procedimiento de repatriación y se otorgará una autorización de residencia.","prevalecerá la voluntad de quien ostenta la tutela, previa audiencia del Ministerio Fiscal.","se suspenderá el curso del procedimiento, hasta el nombramiento del defensor judicial que les represente.","podrán intervenir personalmente en el procedimiento, asistidos por el Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se suspenderá el curso del procedimiento, hasta el nombramiento del defensor judicial que les represente</mark></span>El <span class=\"ref-norma\">art. 35.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Cuando se trate de menores de dieciséis años, con juicio suficiente, que hubieran manifestado una voluntad contraria a la de quien ostenta su tutela o representación, se suspenderá el curso del procedimiento, hasta el nombramiento del defensor judicial que les represente\"</span>. Se suspende hasta que se nombre defensor judicial; la intervención personal es para los mayores de dieciséis. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1132","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. Una vez que haya quedado acreditada la imposibilidad de retorno con su familia o al país de origen, se otorgará al menor tutelado una autorización de residencia, cuyos efectos:","o":["comenzarán desde la fecha de la resolución por la que se otorgue la autorización de residencia, sin efectos retroactivos en ningún caso.","se retrotraerán al momento en que el menor hubiere sido puesto a disposición de los servicios de protección de menores.","se retrotraerán al momento de la entrada del menor en territorio español, si constara.","comenzarán cuando el menor alcance la edad de dieciséis años, si hubiera cumplido el período de tutela."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se retrotraerán al momento en que el menor hubiere sido puesto a disposición de los servicios de protección de menores</mark></span>El <span class=\"ref-norma\">art. 35.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se otorgará al menor una autorización de residencia, cuyos efectos se retrotraerán al momento en que el menor hubiere sido puesto a disposición de los servicios de protección de menores\"</span>. Los efectos se retrotraen a la puesta a disposición de los servicios de protección de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1135","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Menores no acompañados. La Administración General del Estado y las Comunidades Autónomas podrán establecer convenios con organizaciones no gubernamentales, fundaciones y entidades dedicadas a la protección de menores, con el fin de atribuirles la tutela ordinaria de los menores extranjeros no acompañados. Estará legitimada para promover la constitución de la tutela:","o":["la entidad que vaya a asumir la tutela del menor, adjuntando el convenio correspondiente.","el Ministerio Fiscal del lugar donde resida el menor.","la Comunidad Autónoma bajo cuya custodia se encuentre el menor.","la Administración General del Estado en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Comunidad Autónoma bajo cuya custodia se encuentre el menor</mark></span>El <span class=\"ref-norma\">art. 35.11 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Estará legitimada para promover la constitución de la tutela la Comunidad Autónoma bajo cuya custodia se encuentre el menor\"</span>. Promueve la tutela la Comunidad Autónoma que tenga la custodia, dirigiéndose al juzgado del lugar en que vaya a residir el menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 63 — Procedimiento preferente EX ✱","q":[{"i":"6-230","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Procedimiento de expulsión preferente: señale la INCORRECTA.","o":["Durante la tramitación del procedimiento preferente, así como en la fase de ejecución de la expulsión que hubiera recaído, podrán adoptarse medidas cautelares y el internamiento.","En casos excepcionales, se llevará a cabo el derecho del extranjero a la asistencia letrada, que se le proporcionará de oficio, y a ser asistido por intérprete, si no comprende o no habla castellano.","Iniciado el expediente, se dará traslado al interesado del acuerdo de incoación debidamente motivado y por escrito, para que alegue lo que considere adecuado, en el plazo de cuarenta y ocho horas, advirtiéndole de las consecuencias de no hacerlo así.","La ejecución de la orden de expulsión por el procedimiento preferente se efectuará de forma inmediata."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En casos excepcionales, se llevará a cabo el derecho del extranjero a la asistencia letrada, que se le proporcionará de oficio, y a ser asistido por intérprete, si no comprende o no habla castellano</mark></span>Según el <span class=\"ref-norma\">art. 63.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Se garantizará el derecho del extranjero a asistencia letrada, que se le proporcionará de oficio, en su caso, y a ser asistido por intérprete\"</span>. Se garantiza siempre, no solo «en casos excepcionales» (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1342","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento preferente. En los supuestos en que, por estancia irregular, se tramite el procedimiento preferente por concurrir riesgo de incomparecencia, evitación de la expulsión o riesgo para el orden público o la seguridad:","o":["se concederá un período de salida voluntaria de siete días.","el internamiento no podrá exceder de treinta días.","se suspenderá la expulsión si existe arraigo familiar.","no cabrá la concesión del período de salida voluntaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no cabrá la concesión del período de salida voluntaria</mark></span>El <span class=\"ref-norma\">art. 63.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En estos supuestos no cabrá la concesión del período de salida voluntaria\"</span>. En el preferente no cabe período de salida voluntaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1343","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento preferente. En el supuesto de estancia irregular o trabajo sin autorización, cuando el extranjero acredite haber solicitado con anterioridad autorización de residencia temporal por arraigo o circunstancias excepcionales, el órgano encargado de tramitar la expulsión:","o":["archivará el expediente de expulsión y concederá de oficio la autorización de residencia temporal solicitada por el extranjero.","continuará el expediente de expulsión, sin perjuicio de que la autorización pueda concederse con posterioridad a la ejecución.","suspenderá la misma hasta la resolución de la solicitud, procediendo a la continuación del expediente en caso de denegación.","suspenderá la ejecución de la expulsión durante un plazo máximo de tres meses para que se resuelva la solicitud."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">suspenderá la misma hasta la resolución de la solicitud, procediendo a la continuación del expediente en caso de denegación</mark></span>El <span class=\"ref-norma\">art. 63.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"el órgano encargado de tramitar la expulsión suspenderá la misma hasta la resolución de la solicitud, procediendo a la continuación del expediente en caso de denegación\"</span>. Se suspende hasta que se resuelva la solicitud; si se deniega, continúa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 33 — Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas EXOF ✱","q":[{"i":"6-238","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado. Señale la INCORRECTA:","o":["La autorización se prorrogará con el límite de un año en cada prórroga...","La vigencia de la autorización coincidirá con la duración del curso para el que esté matriculado...","Los extranjeros admitidos con fines de estudio, prácticas no laborales o voluntariado no podrán ser autorizados para ejercer una actividad retribuida por cuenta propia o ajena.","La realización de trabajo en una familia para compensar la estancia y mantenimiento en la misma... se regulará de acuerdo con lo dispuesto en los acuerdos internacionales sobre colocación \"au pair\"."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los extranjeros admitidos con fines de estudio, prácticas no laborales o voluntariado no podrán ser autorizados para ejercer una actividad retribuida por cuenta propia o ajena</mark></span>Según el <span class=\"ref-norma\">art. 33.4 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Los extranjeros admitidos con fines de estudio, prácticas no laborales o voluntariado podrán ser autorizados para ejercer una actividad retribuida por cuenta propia o ajena\"</span>. SÍ podrán ser autorizados (Verificado con el texto del temario oficial.)"},{"i":"6-362","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de estancia por estudios. Podrá autorizarse la estancia a los extranjeros que pretendan en España, entre otras actividades:","o":["Realizar actividades de investigación remuneradas con carácter permanente.","Realizar actividades de formación, con exclusión de las prácticas no laborales, en los términos que determine la ley orgánica correspondiente.","Realizar actividades de investigación o formación, sin perjuicio del régimen especial de los investigadores.","Realizar trabajos de temporada vinculados a un programa de estudios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Realizar actividades de investigación o formación, sin perjuicio del régimen especial de los investigadores</mark></span>El <span class=\"ref-norma\">art. 33.1.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Realizar actividades de investigación o formación, sin perjuicio del régimen especial de los investigadores.\"</span>"},{"i":"6-363","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de estancia por estudios. Se someten al régimen de estancia previsto en este artículo los extranjeros que cursen en España estudios de formación sanitaria especializada, salvo que:","o":["Hayan obtenido la titulación en un Estado miembro de la Unión Europea.","Ya contaran con una autorización de residencia previamente al inicio de los mismos, en cuyo caso podrán continuar en dicha situación.","Presten servicios retribuidos en el sistema nacional de salud.","Cuenten con una oferta de trabajo al finalizar la formación especializada, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ya contaran con una autorización de residencia previamente al inicio de los mismos, en cuyo caso podrán continuar en dicha situación</mark></span>El <span class=\"ref-norma\">art. 33.8 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"8. Se someten al régimen de estancia previsto en este artículo los extranjeros que cursen en España estudios de formación sanitaria especializada de acuerdo con la Ley 44/2003, de 11 de noviembre, de profesiones sanitarias, salvo que ya contaran con una autorización de residencia previamente al inicio de los mismos, en cuyo caso podrán continuar en dicha situación.\"</span>"},{"i":"6-ia-1120","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado. Podrá ser autorizado, en régimen de estancia, el extranjero que tenga como fin único o principal realizar una de las siguientes actividades de carácter no laboral: Señale la INCORRECTA.","o":["Participar en programas de intercambio de alumnos en cualesquiera centros docentes o científicos, públicos o privados, oficialmente reconocidos.","Realizar trabajos de temporada vinculados a la formación.","Cursar o ampliar estudios.","Realizar servicios de voluntariado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Realizar trabajos de temporada vinculados a la formación</mark></span>El <span class=\"ref-norma\">art. 33.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) Participar en programas de intercambio de alumnos en cualesquiera centros docentes o científicos, públicos o privados, oficialmente reconocidos\"</span>. Los trabajos de temporada son actividad laboral; el régimen de estancia por estudios es para actividades no laborales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1121","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado. En el caso de los estudios superiores, en los supuestos en los que el solicitante vaya a estudiar más de un curso académico, la vigencia de la autorización coincidirá con:","o":["la duración oficial de los estudios en las condiciones que reglamentariamente se determinen.","la duración del primer curso, prorrogable con el límite de un año en cada prórroga.","un máximo de cuatro años, salvo estudios de doctorado debidamente acreditados.","la duración del curso académico para el que esté matriculado en cada momento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la duración oficial de los estudios en las condiciones que reglamentariamente se determinen</mark></span>El <span class=\"ref-norma\">art. 33.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En el caso de los estudios superiores, en los supuestos en los que el solicitante vaya a estudiar más de un curso académico, la vigencia de la autorización coincidirá con la duración oficial de los estudios en las condiciones que reglamentariamente se determinen\"</span>. Para estudios superiores de varios cursos, la vigencia coincide con la duración oficial de los estudios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1122","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Régimen de admisión a efectos de estudios, intercambio de alumnos, prácticas no laborales o servicios de voluntariado. La realización de trabajo en una familia para compensar la estancia y mantenimiento en la misma, mientras se mejoran los conocimientos lingüísticos o profesionales, se regulará de acuerdo con lo dispuesto en:","o":["la normativa laboral sobre el servicio del hogar familiar.","el régimen general de autorización de residencia y trabajo.","los convenios de acogida firmados con organismos educativos.","los acuerdos internacionales sobre colocación «au pair»."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los acuerdos internacionales sobre colocación «au pair»</mark></span>El <span class=\"ref-norma\">art. 33.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se regulará de acuerdo con lo dispuesto en los acuerdos internacionales sobre colocación «au pair»\"</span>. El trabajo en familia para compensar la estancia es la colocación «au pair», regida por acuerdos internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 62 ter — Deberes de los extranjeros internados","q":[{"i":"6-239","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Centros de internamiento de extranjeros. El extranjero sometido a internamiento estará obligado: señale la INCORRECTA.","o":["A permanecer en el centro a disposición del Ministro de Interior que hubiere autorizado su ingreso.","A mantener una actividad cívica correcta y de respeto con los funcionarios y empleados del centro, con los visitantes y con los otros extranjeros internados...","A conservar el buen estado de las instalaciones materiales, mobiliario y demás efectos del centro...","A observar las normas por las que se rige el centro y cumplir las instrucciones generales impartidas por la dirección..."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A permanecer en el centro a disposición del Ministro de Interior que hubiere autorizado su ingreso</mark></span>Según el <span class=\"ref-norma\">art. 62 ter de la LO 4/2000</span>: <span class=\"ref-concepto\">\"a) A permanecer en el centro a disposición del Juez de Instrucción que hubiere autorizado su ingreso\"</span>. Es a disposición del Juez de Instrucción, no del Ministro del Interior (Verificado con el texto del temario oficial.)"}]},{"a":"Artículo 9 — Causas de denegación EX R23","q":[{"i":"6-255","p":"(Ley 12/2009) Ley 12/2009... Causa de denegación. En todo caso, la protección subsidiaria se denegará a:","o":["Las personas que, habiendo sido objeto de una condena firme por delito grave constituyan una amenaza para la comunidad.","Las personas que constituyan, por razones fundadas, un peligro para la seguridad de Europa.","A las personas a las que se les haya expedido una autorización individualizada para entrar en territorio español por razones humanitarias.","A las personas a las que se les haya expedido una autorización específica para cruzar la frontera de manera controlada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las personas que, habiendo sido objeto de una condena firme por delito grave constituyan una amenaza para la comunidad</mark></span>Según el <span class=\"ref-norma\">art. 12 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"b) las personas que, habiendo sido objeto de una condena firme por delito grave constituyan una amenaza para la comunidad\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1505","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de denegación. En todo caso, el derecho de asilo se denegará a: Señale la INCORRECTA.","o":["las personas que hayan entrado ilegalmente en territorio español sin presentar su solicitud en el plazo de un mes.","las personas que constituyan, por razones fundadas, un peligro para la seguridad de España.","las personas que, habiendo sido objeto de una condena firme por delito grave, constituyan una amenaza para la comunidad.","las personas que constituyan, por razones fundadas, un peligro para la seguridad de España, aunque no hayan sido condenadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las personas que hayan entrado ilegalmente en territorio español sin presentar su solicitud en el plazo de un mes</mark></span>El <span class=\"ref-norma\">art. 9 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"a) las personas que constituyan, por razones fundadas, un peligro para la seguridad de España; b) las personas que, habiendo sido objeto de una condena firme por delito grave constituyan una amenaza para la comunidad\"</span>. La presentación fuera de plazo da lugar a la tramitación de urgencia, no a la denegación; además, la entrada ilegal no se sanciona si se reúnen los requisitos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 28 — Notificación ✱","q":[{"i":"6-257","p":"(Ley 12/2009) Ley 12/2009... De la tramitación de las solicitudes. Notificación. A efectos de comunicaciones y notificaciones, se tendrá en cuenta el último domicilio o residencia que conste en el expediente. Cuando no prospere este procedimiento de notificación, el trámite se realizará a través. Señala la INCORRECTA:","o":["Del Portal del Ciudadano, del portal electrónico de la Oficina de Asilo y Refugio.","De los tablones de anuncios, accesibles al público, de la Comisaría de Policía correspondiente.","De los tablones de anuncios, accesibles al público, de las Oficinas de Extranjeros de la Comunidad Autónoma.","En todo caso, de los tablones de anuncios accesibles al público de la Oficina de Asilo y Refugio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De los tablones de anuncios, accesibles al público, de las Oficinas de Extranjeros de la Comunidad Autónoma</mark></span>Según el <span class=\"ref-norma\">art. 28 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"de la Comisaría de Policía correspondiente o de la Oficina de Extranjeros de la provincia en que conste el último lugar de residencia de la persona solicitante\"</span>. Es la Oficina de Extranjeros de la PROVINCIA (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1542","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Notificación. A efectos de comunicaciones y notificaciones en el procedimiento de protección internacional, se tendrá en cuenta:","o":["el domicilio que figure en el Padrón Municipal de Habitantes.","el domicilio de la entidad que preste la acogida.","el domicilio que designe el abogado del solicitante.","el último domicilio o residencia que conste en el expediente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el último domicilio o residencia que conste en el expediente</mark></span>El <span class=\"ref-norma\">art. 28 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"A efectos de comunicaciones y notificaciones, se tendrá en cuenta el último domicilio o residencia que conste en el expediente\"</span>. El último domicilio o residencia que conste en el expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 53 — Infracciones graves EXOF ✱","q":[{"i":"6-259","p":"(Ley Orgánica 4/2000) La sanción por la comisión de una infracción grave puede consistir en multa de 501 a 10.000 euros. ¿Cuál de las siguientes infracciones graves puede ser sancionada además con la expulsión?","o":["La omisión o el retraso en la comunicación a las autoridades españolas de los cambios de nacionalidad o de domicilio.","Encontrarse irregularmente en territorio español por no haber obtenido o no haber renovado la residencia.","El retraso de más de tres meses en la solicitud de renovación de las autorizaciones una vez hayan caducado.","La falta de comunicación de la entrada en territorio español, en los términos establecidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Encontrarse irregularmente en territorio español por no haber obtenido o no haber renovado la residencia</mark></span>Según el <span class=\"ref-norma\">art. 57.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Cuando los infractores sean extranjeros y realicen conductas de las tipificadas como muy graves, o conductas graves de las previstas en los apartados a), b), c), d) y f) del artículo 53.1 de esta Ley Orgánica, podrá aplicarse, en atención al principio de proporcionalidad, en lugar de la sanción de multa, la expulsión del territorio español\"</span>. La B corresponde a la infracción grave de encontrarse irregularmente en España (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1013","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la libertad de circulación. Las medidas limitativas de la libertad de circulación adoptadas por razones de seguridad pública, cuya duración no excederá del tiempo imprescindible y proporcional a la persistencia de las circunstancias que justificaron su adopción, podrán consistir en:","o":["la presentación periódica ante las autoridades competentes y en el alejamiento de fronteras o núcleos de población concretados singularmente.","la residencia obligatoria en determinado lugar y en la retirada del pasaporte o documento acreditativo de su nacionalidad, previa entrega del resguardo acreditativo.","la presentación diaria ante las autoridades competentes y en el internamiento preventivo en un centro de internamiento.","el alejamiento de fronteras y en la prohibición de salida del territorio nacional acordada por el Ministro del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la presentación periódica ante las autoridades competentes y en el alejamiento de fronteras o núcleos de población concretados singularmente</mark></span>El <span class=\"ref-norma\">art. 5.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"podrán consistir en la presentación periódica ante las autoridades competentes y en el alejamiento de fronteras o núcleos de población concretados singularmente\"</span>. La residencia obligatoria y la retirada del pasaporte son medidas CAUTELARES del procedimiento sancionador, no medidas limitativas de la circulación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1232","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones leves. Encontrarse trabajando en una ocupación, sector de actividad, o ámbito geográfico no contemplado por la autorización de residencia y trabajo de la que se es titular constituye una infracción:","o":["grave.","leve.","muy grave.","grave si es reincidente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">leve</mark></span>El <span class=\"ref-norma\">art. 52.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Encontrarse trabajando en una ocupación, sector de actividad, o ámbito geográfico no contemplado por la autorización de residencia y trabajo de la que se es titular\"</span>. Es leve; trabajar sin autorización alguna y sin residencia válida es grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1306","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Efectos de la expulsión y devolución. La autoridad competente no impondrá la prohibición de entrada, en las circunstancias que se determinen reglamentariamente, cuando el extranjero hubiera abandonado el territorio nacional durante la tramitación de un expediente administrativo sancionador por:","o":["cualquier infracción grave de las tipificadas en la Ley Orgánica.","estancia irregular o por incumplir las medidas de seguridad pública.","participación en actividades contrarias al orden público.","estancia irregular o por trabajar sin autorización ni residencia válida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">estancia irregular o por trabajar sin autorización ni residencia válida</mark></span>El <span class=\"ref-norma\">art. 58.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la autoridad competente no impondrá la prohibición de entrada cuando el extranjero hubiera abandonado el territorio nacional durante la tramitación de un expediente administrativo sancionador por alguno de los supuestos contemplados en las letras a) y b) del artículo 53.1 de esta Ley Orgánica\"</span>. Se refiere a los supuestos de las letras a) (estancia irregular) y b) (trabajo sin autorización ni residencia) del art. 53.1. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1416","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Inadmisión a trámite de solicitudes. La autoridad competente para resolver inadmitirá a trámite las solicitudes relativas a los procedimientos regulados en esta ley, en los siguientes supuestos: Señale la INCORRECTA.","o":["Cuando se trate de solicitudes manifiestamente carentes de fundamento.","Cuando el solicitante haya sido sancionado por una infracción leve en el año anterior.","Cuando dicha solicitud no sea realizada personalmente y dicha circunstancia sea exigida por ley.","Cuando se refieran a extranjeros que se encontrasen en España en situación irregular, salvo que puedan encontrarse en un supuesto de arraigo o circunstancias excepcionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando el solicitante haya sido sancionado por una infracción leve en el año anterior</mark></span>El <span class=\"ref-norma\">disp. adic. 4.ª.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"f) Cuando se trate de solicitudes manifiestamente carentes de fundamento\"</span>. Una sanción leve previa no es causa de inadmisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 72 — Comisión Laboral Tripartita de Inmigración R21","q":[{"i":"6-262","p":"(Ley Orgánica 4/2000) Comisión laboral tripartita de inmigración. ___________ se determinará su composición, forma de designación de sus miembros, competencia y régimen de funcionamiento.","o":["Mediante Orden Ministerial.","Mediante Real Decreto.","Reglamentariamente.","Mediante Ley Orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mediante Orden Ministerial</mark></span>Según el <span class=\"ref-norma\">art. 72.3 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Mediante Orden Ministerial se determinará su composición, forma de designación de sus miembros, competencias y régimen de funcionamiento\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-409","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Comisión Laboral Tripartita de Inmigración. Es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, de la que forman parte las organizaciones sindicales y empresariales más representativas:","o":["La Comisión Laboral Tripartita de Inmigración.","El Foro para la Integración Social de los Inmigrantes.","La Conferencia Sectorial de Inmigración.","El Observatorio Español del Racismo y la Xenofobia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Comisión Laboral Tripartita de Inmigración</mark></span>El <span class=\"ref-norma\">art. 72.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. La Comisión Laboral Tripartita de Inmigración es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, de la que forman parte las organizaciones sindicales y empresariales más representativas.\"</span>"},{"i":"6-ia-1405","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Comisión Laboral Tripartita de Inmigración. La Comisión Laboral Tripartita de Inmigración es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, del que forman parte:","o":["las organizaciones sindicales y empresariales más representativas.","las Comunidades Autónomas y las asociaciones de inmigrantes.","la Administración General del Estado, las CCAA y los Ayuntamientos.","las organizaciones no gubernamentales y los agentes sociales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las organizaciones sindicales y empresariales más representativas</mark></span>El <span class=\"ref-norma\">art. 72.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La Comisión Laboral Tripartita de Inmigración es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, de la que forman parte las organizaciones sindicales y empresariales más representativas\"</span>. Forman parte las organizaciones sindicales y empresariales más representativas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1420","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos. La tramitación de los procedimientos en materia de extranjería se realizará sobre una aplicación informática común cuya implantación y coordinación respecto de los restantes Departamentos implicados corresponderá:","o":["al Ministerio del Interior.","al Ministerio de Trabajo e Inmigración.","al Ministerio de Asuntos Exteriores y de Cooperación.","al Ministerio de Política Territorial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Ministerio de Trabajo e Inmigración</mark></span>El <span class=\"ref-norma\">disp. adic. 5.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"se realizará sobre una aplicación informática común cuya implantación y coordinación respecto de los restantes Departamentos implicados corresponderá al Ministerio de Trabajo e Inmigración\"</span>. La aplicación común la coordina el Ministerio de Trabajo e Inmigración; el Registro central de extranjeros, el de Interior; los visados, Exteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1423","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos. Aunará el conjunto de la información estadística disponible en materia de extranjería, inmigración, protección internacional y nacionalidad, con independencia de la Administración Pública, Departamento ministerial u Organismo responsable de su elaboración:","o":["el Observatorio Español del Racismo y la Xenofobia.","el Instituto Nacional de Estadística.","el Observatorio Permanente de la Inmigración.","el Foro para la Integración Social de los Inmigrantes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Observatorio Permanente de la Inmigración</mark></span>El <span class=\"ref-norma\">disp. adic. 5.ª.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Observatorio Permanente de la Inmigración aunará el conjunto de la información estadística disponible en materia de extranjería, inmigración, protección internacional y nacionalidad\"</span>. Es el Observatorio Permanente de la Inmigración (no el del Racismo y la Xenofobia). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 quinquies — Criterios de aplicación del Plan de respuesta solidaria ante la","q":[{"i":"6-270","p":"Evaluación de las solicitudes. ¿Quién velará por que la información necesaria para la evaluación de las solicitudes de protección no se obtenga de los responsables de la persecución o de los daños graves?","o":["El solicitante.","La Administración General del Estado.","El Ministro del Interior.","El Ministro de asuntos exteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Administración General del Estado</mark></span>Según el <span class=\"ref-norma\">art. 26.1 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"La Administración General del Estado velará por que la información necesaria para la evaluación de las solicitudes de protección no se obtenga de los responsables de la persecución o de los daños graves, de modo tal que dé lugar a que dichos responsables sean informados de que la persona interesada es solicitante de protección internacional cuya solicitud está siendo considerada, ni se ponga en peligro la integridad de la persona interesada y de las personas a su cargo, ni la libertad y la seguridad de sus familiares que aún vivan en el país de origen\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1149","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Criterios de aplicación del Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. En defecto del acuerdo unánime de la Conferencia Sectorial de Infancia y Adolescencia, los criterios de aplicación del Plan de respuesta solidaria serán adoptados:","o":["en el seno de la Conferencia Sectorial de Infancia y Adolescencia en ejercicio de las funciones de coordinación de la Administración General del Estado.","por el Consejo de Ministros mediante real decreto, previo informe de la Conferencia Sectorial de Infancia y Adolescencia y oídas las comunidades y ciudades autónomas afectadas.","por el Ministerio de Juventud e Infancia mediante orden ministerial, oídas las comunidades autónomas afectadas.","por mayoría absoluta del Congreso de los Diputados, previa propuesta elaborada por el Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el seno de la Conferencia Sectorial de Infancia y Adolescencia en ejercicio de las funciones de coordinación de la Administración General del Estado</mark></span>El <span class=\"ref-norma\">art. 35 quinquies.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"los criterios de aplicación del Plan de respuesta solidaria serán adoptados en el seno de la Conferencia Sectorial de Infancia y Adolescencia en ejercicio de las funciones de coordinación de la Administración General del Estado\"</span>. Se adoptan en el seno de la propia Conferencia Sectorial, en ejercicio de funciones de coordinación de la AGE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1150","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Criterios de aplicación del Plan de respuesta solidaria ante la situación de contingencia migratoria extraordinaria. Los criterios de aplicación del Plan de respuesta solidaria, una vez aprobados, serán comunicados a todas las comunidades y ciudades autónomas afectadas:","o":["por el Ministerio de Juventud e Infancia, por conducto de las Delegaciones del Gobierno en las comunidades y ciudades autónomas afectadas, quienes darán traslado a los servicios de su titularidad.","por la Presidencia de la Conferencia Sectorial, mediante su publicación en el Boletín Oficial del Estado.","por el Ministerio Fiscal, por conducto de las Fiscalías de Menores de cada comunidad o ciudad autónoma.","por la Secretaría de la Conferencia Sectorial de Infancia y Adolescencia, por conducto de las personas titulares de las Consejerías competentes en materia de juventud e infancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por la Secretaría de la Conferencia Sectorial de Infancia y Adolescencia, por conducto de las personas titulares de las Consejerías competentes en materia de juventud e infancia</mark></span>El <span class=\"ref-norma\">art. 35 quinquies.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"serán comunicados por la Secretaría de la Conferencia Sectorial de Infancia y Adolescencia a todas las comunidades y ciudades autónomas afectadas por conducto de las personas titulares de la Consejerías competentes en materia de juventud e infancia\"</span>. Los comunica la Secretaría de la Conferencia Sectorial a través de los titulares de las Consejerías competentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Delimitación del ámbito ✱","q":[{"i":"6-336","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Delimitación del ámbito. Se consideran extranjeros, a los efectos de la aplicación de la presente Ley:","o":["Los que carezcan de la nacionalidad española.","Los que carezcan de la nacionalidad de un Estado miembro de la Unión Europea.","Los que no residan habitualmente en territorio español.","Los que carezcan de la nacionalidad española y de autorización de residencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los que carezcan de la nacionalidad española</mark></span>El <span class=\"ref-norma\">art. 1.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Se consideran extranjeros, a los efectos de la aplicación de la presente Ley, a los que carezcan de la nacionalidad española.\"</span>"},{"i":"6-337","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Delimitación del ámbito. Lo dispuesto en la Ley se entenderá, en todo caso, sin perjuicio de lo establecido:","o":["En las leyes orgánicas y en los reglamentos de la Unión Europea en vigor.","En los convenios bilaterales y en los reglamentos de desarrollo de la presente Ley.","En las leyes autonómicas y en los Tratados internacionales ratificados por España.","En leyes especiales y en los Tratados internacionales en los que España sea parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En leyes especiales y en los Tratados internacionales en los que España sea parte</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Lo dispuesto en esta Ley se entenderá, en todo caso, sin perjuicio de lo establecido en leyes especiales y en los Tratados internacionales en los que España sea parte.\"</span>"},{"i":"6-ia-1001","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Delimitación del ámbito. Los nacionales de los Estados miembros de la Unión Europea y aquellos a quienes sea de aplicación el régimen comunitario se regirán por las normas que lo regulan, siéndoles de aplicación la presente Ley __________.","o":["en aquellos aspectos que pudieran ser más favorables","con carácter supletorio en todo lo no previsto por aquellas normas","únicamente en materia de infracciones y régimen sancionador","en aquellos aspectos que no hubieran sido objeto de armonización"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en aquellos aspectos que pudieran ser más favorables</mark></span>El <span class=\"ref-norma\">art. 1.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los nacionales de los Estados miembros de la Unión Europea y aquellos a quienes sea de aplicación el régimen comunitario se regirán por las normas que lo regulan, siéndoles de aplicación la presente Ley en aquellos aspectos que pudieran ser más favorables\"</span>. Por qué fallan las otras: la Ley no se aplica como supletoria general ni solo al régimen sancionador; la cláusula es de favorabilidad («más favorables»). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1501","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Quedarán excluidas de la condición de refugiados las personas comprendidas en la Convención de Ginebra en lo relativo a la protección o asistencia de un órgano u organismo de las Naciones Unidas distinto del ACNUR. Cuando esta protección o asistencia haya cesado por cualquier motivo, sin que la suerte de tales personas se haya solucionado definitivamente:","o":["aquéllas tendrán, «ipso facto», derecho a los beneficios del asilo regulado en la Ley.","aquéllas podrán solicitar la protección subsidiaria, pero no el derecho de asilo.","aquéllas deberán acreditar de nuevo los fundados temores de persecución.","aquéllas quedarán excluidas de la protección internacional durante cinco años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">aquéllas tendrán, «ipso facto», derecho a los beneficios del asilo regulado en la Ley</mark></span>El <span class=\"ref-norma\">art. 8.1.a) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Cuando esta protección o asistencia haya cesado por cualquier motivo, sin que la suerte de tales personas se haya solucionado definitivamente con arreglo a las Resoluciones aprobadas sobre el particular por la Asamblea General de las Naciones Unidas, aquéllas tendrán, «ipso facto», derecho a los beneficios del asilo regulado en la presente Ley\"</span>. Al cesar esa protección sin solución definitiva, tienen «ipso facto» derecho a los beneficios del asilo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la Ley de Extranjería","q":[{"i":"6-339","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derecho a la documentación. Los extranjeros no podrán ser privados de su documentación, salvo en los supuestos y con los requisitos previstos en esta Ley Orgánica y en:","o":["La Ley de Enjuiciamiento Criminal y en la Ley de Seguridad Privada.","La Ley Orgánica sobre Protección de la Seguridad Ciudadana.","La Ley Orgánica de Protección de Datos de Carácter Personal.","La Ley Orgánica reguladora del Derecho de Reunión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Ley Orgánica sobre Protección de la Seguridad Ciudadana</mark></span>El <span class=\"ref-norma\">art. 4.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Los extranjeros no podrán ser privados de su documentación, salvo en los supuestos y con los requisitos previstos en esta Ley Orgánica y en la Ley Orgánica 1/1992, de 21 de febrero, sobre Protección de la Seguridad Ciudadana.\"</span>"},{"i":"6-353","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Salida de España. Las salidas del territorio español podrán realizarse libremente, excepto en los casos previstos:","o":["En el Código Penal y en la Ley de Enjuiciamiento Criminal.","En la presente Ley y en los convenios internacionales suscritos por España.","En el Código Penal y en la Ley Orgánica de Seguridad Ciudadana.","En el Código Penal y en la presente Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el Código Penal y en la presente Ley</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Las salidas del territorio español podrán realizarse libremente, excepto en los casos previstos en el Código Penal y en la presente Ley.\"</span>"},{"i":"6-354","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Salida de España. La salida será obligatoria, entre otros supuestos, en caso de:","o":["Resolución favorable de una solicitud de protección internacional.","Finalización del periodo de estancia por la entrada con visado de turismo, sin perjuicio de lo que establezcan los tratados internacionales, en los términos que determine la ley orgánica correspondiente.","Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario.","Cumplimiento de la pena de multa impuesta por una infracción grave."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario</mark></span>El <span class=\"ref-norma\">art. 28.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Cumplimiento del plazo en el que un trabajador extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de retorno voluntario.\"</span>"},{"i":"6-357","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal. Para autorizar la residencia temporal de un extranjero será preciso que:","o":["Carezca de antecedentes penales en España, con independencia de sus países anteriores de residencia, conforme al procedimiento que reglamentariamente se establezca.","Acredite una residencia previa en España de al menos dos años de forma legal.","Carezca de antecedentes policiales en los últimos cinco años en cualquier país.","Carezca de antecedentes penales en España o en los países anteriores de residencia, por delitos existentes en el ordenamiento español."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Carezca de antecedentes penales en España o en los países anteriores de residencia, por delitos existentes en el ordenamiento español</mark></span>El <span class=\"ref-norma\">art. 31.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"5. Para autorizar la residencia temporal de un extranjero será preciso que carezca de antecedentes penales en España o en los países anteriores de residencia, por delitos existentes en el ordenamiento español\"</span>"},{"i":"6-358","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal. Los extranjeros con autorización de residencia temporal vendrán obligados a poner en conocimiento de las autoridades competentes:","o":["Los cambios de nacionalidad y de domicilio, con exclusión del estado civil.","Los cambios de estado civil, de domicilio y de situación laboral.","Los cambios de nacionalidad, estado civil y domicilio.","Los cambios de nacionalidad, estado civil, domicilio y profesión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los cambios de nacionalidad, estado civil y domicilio</mark></span>El <span class=\"ref-norma\">art. 31.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"6. Los extranjeros con autorización de residencia temporal vendrán obligados a poner en conocimiento de las autoridades competentes los cambios de nacionalidad, estado civil y domicilio.\"</span>"},{"i":"6-359","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia temporal. Para la renovación de las autorizaciones de residencia temporal se valorará especialmente el esfuerzo de integración del extranjero, acreditado mediante:","o":["Un informe positivo de la Delegación del Gobierno sobre su arraigo familiar y laboral.","Un informe positivo de la Comunidad Autónoma que certifique la asistencia a las acciones formativas contempladas en el artículo 2 ter.","Un certificado del Ayuntamiento de residencia sobre su participación en actividades de integración, sin perjuicio de lo que establezcan los tratados internacionales.","Un informe del Ministerio del Interior sobre la ausencia de antecedentes durante la residencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un informe positivo de la Comunidad Autónoma que certifique la asistencia a las acciones formativas contempladas en el artículo 2 ter</mark></span>El <span class=\"ref-norma\">art. 31.7.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"A los efectos de dicha renovación, se valorará especialmente el esfuerzo de integración del extranjero que aconseje su renovación, acreditado mediante un informe positivo de la Comunidad Autónoma que certifique la asistencia a las acciones formativas contempladas en el artículo 2 ter de esta Ley.\"</span>"},{"i":"6-360","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. La extinción de la residencia de larga duración se producirá cuando se produzca la ausencia del territorio de la Unión Europea durante:","o":["12 meses consecutivos.","6 meses consecutivos.","24 meses consecutivos.","12 meses no consecutivos en un período de dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">12 meses consecutivos</mark></span>El <span class=\"ref-norma\">art. 32.5.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) Cuando se produzca la ausencia del territorio de la Unión Europea durante 12 meses consecutivos.\"</span>"},{"i":"6-361","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. La extinción de la residencia de larga duración se producirá, entre otros casos:","o":["Cuando se adquiera la nacionalidad de otro Estado miembro por residencia.","Cuando se obtenga una autorización de residencia temporal por reagrupación.","Cuando se resida más de seis meses en otro Estado miembro.","Cuando se adquiera la residencia de larga duración en otro Estado miembro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se adquiera la residencia de larga duración en otro Estado miembro</mark></span>El <span class=\"ref-norma\">art. 32.5.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Cuando se adquiera la residencia de larga duración en otro Estado miembro.\"</span>"},{"i":"6-367","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. A partir de la primera concesión, las autorizaciones se concederán:","o":["Sin limitación alguna de ámbito geográfico u ocupación.","Con limitación geográfica a la Comunidad Autónoma de la primera concesión.","Con limitación de ocupación al sector de actividad inicial durante tres años.","Sin limitación de ocupación, pero dentro del ámbito de la provincia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sin limitación alguna de ámbito geográfico u ocupación</mark></span>El <span class=\"ref-norma\">art. 38.7 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"7. A partir de la primera concesión, las autorizaciones se concederán sin limitación alguna de ámbito geográfico u ocupación.\"</span>"},{"i":"6-382","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Cuantía de las tasas. Se consideran elementos para determinar la cuantía de las tasas, en la concesión de autorizaciones de residencia, la duración de la autorización, así como su carácter definitivo o temporal, y:","o":["El hecho de que el solicitante tenga o no familiares a su cargo.","El hecho de que se trate de la primera o ulteriores concesiones o sus renovaciones.","El nivel de renta del solicitante en el último ejercicio fiscal.","El hecho de que la solicitud se presente en territorio español o en el consulado, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El hecho de que se trate de la primera o ulteriores concesiones o sus renovaciones</mark></span>El <span class=\"ref-norma\">art. 48.3.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) En la concesión de autorizaciones de residencia, la duración de la autorización, así como su carácter definitivo o temporal, y, dentro de estas últimas, el hecho de que se trate de la primera o ulteriores concesiones o sus renovaciones.\"</span>"},{"i":"6-384","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones leves. Es infracción leve encontrarse trabajando en España sin haber solicitado autorización administrativa para trabajar por cuenta propia, cuando se cuente con:","o":["Autorización de residencia de larga duración.","Visado de estancia de duración inferior a tres meses.","Autorización de residencia temporal y de trabajo por cuenta ajena.","Autorización de residencia temporal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Autorización de residencia temporal</mark></span>El <span class=\"ref-norma\">art. 52.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) Encontrarse trabajando en España sin haber solicitado autorización administrativa para trabajar por cuenta propia, cuando se cuente con autorización de residencia temporal.\"</span>"},{"i":"6-400","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. Entre las medidas cautelares se encuentra la detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de:","o":["48 horas previas a la solicitud de internamiento, en los términos que determine la ley orgánica correspondiente.","24 horas previas a la solicitud de devolución.","72 horas previas a la solicitud de internamiento.","96 horas previas a la solicitud de internamiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">72 horas previas a la solicitud de internamiento</mark></span>El <span class=\"ref-norma\">art. 61.1.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de 72 horas previas a la solicitud de internamiento.\"</span>"},{"i":"6-401","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. Entre las medidas cautelares se encuentra el internamiento preventivo:","o":["Previa autorización de la Delegación del Gobierno en los centros de internamiento.","Previa autorización judicial en los centros de internamiento.","Previa comunicación al Ministerio Fiscal en los centros penitenciarios.","Acordado directamente por el instructor en los centros de internamiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Previa autorización judicial en los centros de internamiento</mark></span>El <span class=\"ref-norma\">art. 61.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Internamiento preventivo, previa autorización judicial en los centros de internamiento.\"</span>"},{"i":"6-402","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. En los expedientes sancionadores por infracciones de transportistas, si éstos infringen la obligación de tomar a cargo al extranjero transportado ilegalmente, podrá acordarse:","o":["La suspensión de sus actividades, la prestación de fianzas, avales, o la inmovilización del medio de transporte utilizado.","La retirada de la licencia de transporte y la prohibición de entrada en el territorio nacional, salvo que el órgano competente acuerde otra cosa de forma motivada.","La clausura del establecimiento y el decomiso del medio de transporte utilizado.","La prestación de fianzas, avales o la devolución inmediata del medio de transporte utilizado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La suspensión de sus actividades, la prestación de fianzas, avales, o la inmovilización del medio de transporte utilizado</mark></span>El <span class=\"ref-norma\">art. 61.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. En los expedientes sancionadores en la comisión de infracciones por transportistas, si éstos infringen la obligación de tomar a cargo al extranjero transportado ilegalmente, podrá acordarse la suspensión de sus actividades, la prestación de fianzas, avales, o la inmovilización del medio de transporte utilizado.\"</span>"},{"i":"6-421","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Plazo máximo de resolución. Las solicitudes de modificación de la limitación territorial o de ocupación de las autorizaciones iniciales de residencia y trabajo se resolverán y notificarán en el plazo máximo de:","o":["Un mes.","Quince días.","Dos meses.","Tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes</mark></span>El <span class=\"ref-norma\">disp. adic. 1.ª.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Las solicitudes de modificación de la limitación territorial o de ocupación de las autorizaciones iniciales de residencia y trabajo se resolverán y notificarán por la administración autonómica o estatal competente en el plazo máximo de un mes.\"</span>"},{"i":"6-455","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Salida de España. La salida será obligatoria en los siguientes supuestos, entre otros:","o":["Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal.","Denegación de la prórroga de estancia solicitada por el extranjero con visado de tránsito, en los términos que determine la ley orgánica correspondiente.","Cumplimiento de la pena de multa impuesta por una infracción leve.","Pérdida de la tarjeta de identidad de extranjero por causas ajenas al titular."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Expulsión del territorio español por orden judicial, en los casos previstos en el Código Penal</mark></span>El <span class=\"ref-norma\">art. 28.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. La salida será obligatoria en los siguientes supuestos:\"</span>"},{"i":"6-457","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de larga duración. La extinción de la residencia de larga duración se producirá en los casos siguientes, entre otros:","o":["Cuando se produzca la ausencia del territorio español durante 6 meses consecutivos, conforme al procedimiento que reglamentariamente se establezca.","Cuando se produzca la ausencia del territorio de la Unión Europea durante 24 meses.","Cuando se produzca la ausencia del territorio de la Unión Europea durante 12 meses consecutivos.","Cuando se adquiera la residencia temporal por reagrupación familiar en otro Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando se produzca la ausencia del territorio de la Unión Europea durante 12 meses consecutivos</mark></span>El <span class=\"ref-norma\">art. 32.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"5. La extinción de la residencia de larga duración se producirá en los casos siguientes:\"</span>"},{"i":"6-458","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Autorización de residencia y trabajo por cuenta ajena. La autorización de residencia y trabajo se renovará a su expiración:","o":["Cuando el extranjero haya cotizado a la Seguridad Social al menos seis meses en el último año, sin perjuicio de lo que establezcan los tratados internacionales.","Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo.","Cuando el extranjero acredite haber abonado la tasa de renovación con carácter previo.","Cuando el extranjero sea beneficiario de una prestación no contributiva por desempleo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo</mark></span>El <span class=\"ref-norma\">art. 38.6.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Cuando por la autoridad competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una prestación contributiva por desempleo.\"</span>"},{"i":"6-460","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Cuantía de las tasas. Se consideran elementos y criterios esenciales de cuantificación de las tasas, que sólo podrán modificarse mediante norma del mismo rango, en la tramitación de la solicitud de visado:","o":["Los gastos de traducción de los documentos, la nacionalidad del solicitante y el motivo del viaje.","La renta del solicitante, la duración de la estancia y el número de miembros de su unidad familiar.","Los gastos administrativos de tramitación y el hecho de que se solicite en un consulado de la Unión Europea, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","Los gastos administrativos de tramitación, la duración de la estancia, el número de entradas autorizadas, el carácter de la residencia y, en su caso, el hecho de que se expida en frontera."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los gastos administrativos de tramitación, la duración de la estancia, el número de entradas autorizadas, el carácter de la residencia y, en su caso, el hecho de que se expida en frontera</mark></span>El <span class=\"ref-norma\">art. 48.3.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) En la tramitación de la solicitud de visado, los gastos administrativos de tramitación, la limitación de los efectos del visado de tránsito aeroportuario, la duración de la estancia, el número de entradas autorizadas, el carácter de la residencia, así como, en su caso, el hecho de que se expida en frontera.\"</span>"},{"i":"6-468","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas cautelares. Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las medidas cautelares previstas en la ley:","o":["el Delegado o Subdelegado del Gobierno de la provincia.","el instructor.","el Juez de instrucción del lugar de la detención.","el Ministerio Fiscal, de oficio o a instancia de parte."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el instructor</mark></span>El <span class=\"ref-norma\">art. 61.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Desde el momento en que se incoe un procedimiento sancionador en el que pueda proponerse la expulsión, el instructor, a fin de asegurar la resolución final que pudiera recaer, podrá adoptar alguna de las siguientes medidas cautelares\"</span> Las medidas cautelares las adopta el instructor."}]},{"a":"Artículo 11 — Libertad de sindicación y huelga ✱","q":[{"i":"6-345","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Libertad de sindicación y huelga. Los extranjeros tienen derecho a sindicarse libremente o a afiliarse a una organización profesional:","o":["Únicamente cuando se hallen en situación de residencia y con autorización de trabajo.","Siempre que su Estado de origen reconozca el mismo derecho a los españoles.","Con la limitación de no poder ocupar cargos directivos en la organización.","En las mismas condiciones que los trabajadores españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En las mismas condiciones que los trabajadores españoles</mark></span>El <span class=\"ref-norma\">art. 11.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Los extranjeros tienen derecho a sindicarse libremente o a afiliarse a una organización profesional, en las mismas condiciones que los trabajadores españoles.\"</span>"}]},{"a":"Artículo 15 — Sujeción de los extranjeros a los mismos impuestos que los españoles ✱","q":[{"i":"6-347","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sujeción a los mismos impuestos. Los extranjeros tienen derecho a transferir sus ingresos y ahorros obtenidos en España a su país, o a cualquier otro:","o":["Sin más limitación que la de declarar la transferencia ante la Agencia Tributaria, en los términos que determine la ley orgánica correspondiente.","Conforme a los procedimientos establecidos en la legislación española y de conformidad con los acuerdos internacionales aplicables.","Previa autorización de la Delegación del Gobierno y por un importe máximo anual.","Conforme a los procedimientos que determine el país de destino de los fondos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Conforme a los procedimientos establecidos en la legislación española y de conformidad con los acuerdos internacionales aplicables</mark></span>El <span class=\"ref-norma\">art. 15.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. Los extranjeros tienen derecho a transferir sus ingresos y ahorros obtenidos en España a su país, o a cualquier otro, conforme a los procedimientos establecidos en la legislación española y de conformidad con los acuerdos internacionales aplicables.\"</span>"},{"i":"6-ia-1022","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sujeción de los extranjeros a los mismos impuestos que los españoles. Sin perjuicio de lo dispuesto en los acuerdos aplicables sobre doble imposición internacional, los extranjeros estarán sujetos:","o":["únicamente a los impuestos que graven las rentas obtenidas en España.","a los impuestos que determine el convenio con su país de origen.","a los mismos impuestos que los españoles, salvo los residentes temporales.","con carácter general, a los mismos impuestos que los españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con carácter general, a los mismos impuestos que los españoles</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Sin perjuicio de lo dispuesto en los acuerdos aplicables sobre doble imposición internacional, los extranjeros estarán sujetos, con carácter general, a los mismos impuestos que los españoles\"</span>. La regla es la sujeción, con carácter general, a los mismos impuestos que los españoles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 45 — Devengo EXOF ✱","q":[{"i":"6-379","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Devengo de las tasas. En los casos de autorización de residencia y trabajo por cuenta ajena a favor de trabajadores de servicio doméstico de carácter parcial o discontinuo, el devengo de la tasa se producirá:","o":["En el momento de afiliación y/o alta del trabajador en la Seguridad Social.","En el momento de la presentación de la solicitud de autorización.","En el momento de la notificación de la resolución favorable al empleador, conforme al procedimiento que reglamentariamente se establezca.","A los treinta días de la concesión de la autorización inicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el momento de afiliación y/o alta del trabajador en la Seguridad Social</mark></span>El <span class=\"ref-norma\">art. 45.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. En los casos de autorización de residencia y trabajo por cuenta ajena a favor de trabajadores de servicio doméstico de carácter parcial o discontinuo, el devengo de la tasa se producirá en el momento de afiliación y/o alta del trabajador en la Seguridad Social.\"</span>"},{"i":"6-380","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Devengo de las tasas. En los casos de renovación de la autorización de residencia y trabajo por cuenta ajena, en ausencia de empleador, y cuando se trate de trabajadores de servicio doméstico de carácter parcial o discontinuo, el devengo de la tasa se producirá:","o":["En el momento de la renovación de la tarjeta de identidad de extranjero.","En el momento de presentación de la solicitud de renovación.","En el momento en que se dicte la resolución de renovación.","En el momento de alta del trabajador en la Seguridad Social."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el momento de alta del trabajador en la Seguridad Social</mark></span>El <span class=\"ref-norma\">art. 45.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. En los casos de renovación de la autorización de residencia y trabajo por cuenta ajena, en ausencia de empleador, y cuando se trate de trabajadores de servicio doméstico de carácter parcial o discontinuo, el devengo de la tasa se producirá en el momento de alta del trabajador en la Seguridad Social.\"</span>"},{"i":"6-ia-1223","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Devengo. Las tasas se devengarán cuando se solicite la autorización, la prórroga, la modificación, la renovación, o el visado. En el caso de las Comunidades Autónomas que tengan traspasadas las competencias en materia de autorización de trabajo:","o":["el rendimiento de las tasas se ingresará en el Tesoro Público.","la tasa se devengará en el momento del alta del trabajador.","les corresponderá el devengo del rendimiento de las tasas.","el devengo se producirá con la concesión de la autorización."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">les corresponderá el devengo del rendimiento de las tasas</mark></span>El <span class=\"ref-norma\">art. 45.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En el caso de las Comunidades Autónomas que tengan traspasadas las competencias en materia de autorización de trabajo, les corresponderá el devengo del rendimiento de las tasas\"</span>. A esas Comunidades Autónomas les corresponde el devengo del rendimiento de las tasas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1229","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Gestión, recaudación y autoliquidación. La gestión y recaudación de las tasas corresponderá a:","o":["los órganos competentes para la concesión de las autorizaciones, modificaciones, renovaciones y prórrogas, la expedición de la documentación y la tramitación de la solicitud de visado.","la Agencia Estatal de Administración Tributaria, en colaboración con los órganos competentes para la concesión de las autorizaciones de residencia y trabajo y con las misiones diplomáticas en el caso de los visados.","las Delegaciones del Gobierno en las Comunidades Autónomas, salvo en los visados, cuya gestión corresponde al Ministerio de Asuntos Exteriores.","las Comunidades Autónomas en todo caso, de acuerdo con las competencias asumidas en sus respectivos Estatutos de Autonomía."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos competentes para la concesión de las autorizaciones, modificaciones, renovaciones y prórrogas, la expedición de la documentación y la tramitación de la solicitud de visado</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La gestión y recaudación de las tasas corresponderá a los órganos competentes para la concesión de las autorizaciones, modificaciones, renovaciones y prórrogas, la expedición de la documentación a que se refiere el artículo 44 y la tramitación de la solicitud de visado\"</span>. Las gestionan y recaudan los propios órganos competentes para conceder o tramitar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 46 — Sujetos pasivos ✱","q":[{"i":"6-381","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sujetos pasivos de las tasas. En las autorizaciones de trabajo por cuenta ajena será sujeto pasivo de la tasa el empleador o empresario, excepto en el supuesto de relaciones laborales en el sector del servicio doméstico de carácter parcial o discontinuo, en que lo será:","o":["El titular del hogar familiar.","El empleador, con derecho a repetir contra el trabajador.","El propio trabajador.","El solicitante del visado en el consulado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El propio trabajador</mark></span>El <span class=\"ref-norma\">art. 46.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Serán sujetos pasivos de las tasas los solicitantes de visado y las personas en cuyo favor se concedan las autorizaciones o se expidan los documentos previstos en el artículo 44, salvo en las autorizaciones de trabajo por cuenta ajena, en cuyo caso será sujeto pasivo el empleador o empresario, excepto en el supuesto de relaciones laborales en el sector del servicio doméstico de carácter parcial o discontinuo, en que lo será el propio trabajador.\"</span>"},{"i":"6-ia-1224","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sujetos pasivos. Será nulo todo pacto por el que el trabajador por cuenta ajena:","o":["renuncie al alta en la Seguridad Social durante la tramitación de la autorización de trabajo.","asuma la obligación de pagar en todo o en parte el importe de las tasas establecidas.","asuma los costes del viaje desde su país de origen hasta el lugar de trabajo en España.","se comprometa a no solicitar la renovación de la autorización durante el primer año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">asuma la obligación de pagar en todo o en parte el importe de las tasas establecidas</mark></span>El <span class=\"ref-norma\">art. 46.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Será nulo todo pacto por el que el trabajador por cuenta ajena asuma la obligación de pagar en todo o en parte el importe de las tasas establecidas\"</span>. La nulidad se refiere al pacto por el que el trabajador asume el pago de las tasas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 52 — Infracciones leves ✱","q":[{"i":"6-383","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones leves. Es infracción leve:","o":["El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado.","El retraso, hasta seis meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado, en los términos que determine la ley orgánica correspondiente.","El retraso, hasta un mes, en la comunicación de los cambios de domicilio a la autoridad competente.","El retraso, hasta tres meses, en la solicitud inicial de la tarjeta de identidad de extranjero."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado</mark></span>El <span class=\"ref-norma\">art. 52.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado.\"</span>"},{"i":"6-385","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones leves. Es infracción leve la contratación de trabajadores cuya autorización no les habilita para trabajar en esa ocupación o ámbito geográfico, incurriéndose:","o":["En una única infracción, con independencia del número de trabajadores ocupados.","En una infracción por cada centro de trabajo en que se produzca la contratación.","En una infracción por cada uno de los trabajadores extranjeros ocupados.","En una infracción por cada mes de duración de la contratación indebida."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En una infracción por cada uno de los trabajadores extranjeros ocupados</mark></span>El <span class=\"ref-norma\">art. 52.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) La contratación de trabajadores cuya autorización no les habilita para trabajar en esa ocupación o ámbito geográfico, incurriéndose en una infracción por cada uno de los trabajadores extranjeros ocupados.\"</span>"},{"i":"6-ia-1233","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones leves. Es infracción leve la ausencia de comunicación a la autoridad pública, por parte de las entidades cuyo objeto se refiera total o parcialmente a la atención de personas menores de edad extranjeras no acompañadas:","o":["de la localización de personas menores de edad extranjeras no acompañadas a fin de que pueda procederse en consecuencia.","de los cambios de domicilio de los menores extranjeros no acompañados que tengan bajo su guarda o tutela.","de la fuga de los menores extranjeros no acompañados de los centros de protección en el plazo de veinticuatro horas.","de la mayoría de edad alcanzada por los menores tutelados que dispongan de autorización de residencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de la localización de personas menores de edad extranjeras no acompañadas a fin de que pueda procederse en consecuencia</mark></span>El <span class=\"ref-norma\">art. 52.f) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"f) La ausencia de comunicación a la autoridad pública por parte de las entidades cuyo objeto se refiera total o parcialmente a la atención de personas menores de edad extranjeras no acompañadas\"</span>. La infracción es no comunicar la localización de menores extranjeros no acompañados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 64 — Ejecución de la expulsión EX ✱","q":[{"i":"6-406","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. Cuando un extranjero sea detenido en territorio español y se constate que contra él se ha dictado una resolución de expulsión por un Estado miembro de la Unión Europea, se procederá a:","o":["Incoar un nuevo expediente de expulsión con carácter preferente.","Solicitar al Estado miembro el reconocimiento de la resolución en el plazo de diez días, en los términos que determine la ley orgánica correspondiente.","Poner al extranjero a disposición del juez para que decida sobre la ejecución.","Ejecutar inmediatamente la resolución, sin necesidad de incoar nuevo expediente de expulsión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ejecutar inmediatamente la resolución, sin necesidad de incoar nuevo expediente de expulsión</mark></span>El <span class=\"ref-norma\">art. 64.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"4. Cuando un extranjero sea detenido en territorio español y se constate que contra él se ha dictado una resolución de expulsión por un Estado miembro de la Unión Europea, se procederá a ejecutar inmediatamente la resolución, sin necesidad de incoar nuevo expediente de expulsión.\"</span>"},{"i":"6-469","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. Tanto en los supuestos de prórroga del plazo de cumplimiento voluntario como de aplazamiento o suspensión de la ejecución de la expulsión, lo que se acreditará __________, se tendrá en cuenta la garantía para el extranjero afectado de determinados extremos.","o":["mediante diligencia extendida en el pasaporte del interesado","en documento debidamente notificado al interesado","en resolución motivada publicada en el boletín oficial","mediante comparecencia personal ante la autoridad gubernativa"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en documento debidamente notificado al interesado</mark></span>El <span class=\"ref-norma\">art. 64.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Tanto en los supuestos de prórroga del plazo de cumplimiento voluntario como de aplazamiento o suspensión de la ejecución de la expulsión, lo que se acreditará en documento debidamente notificado al interesado, se tendrá en cuenta la garantía para el extranjero afectado de\"</span> Se acredita en documento debidamente notificado al interesado."},{"i":"6-ia-1346","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. Expirado el plazo de cumplimiento voluntario sin que el extranjero haya abandonado el territorio nacional, se procederá a su detención y conducción hasta el puesto de salida. Si la expulsión no se pudiera ejecutar en el plazo de setenta y dos horas:","o":["se prorrogará la detención por otras setenta y dos horas, con comunicación al Juez de Instrucción.","deberá ponerse en libertad al extranjero y concederle un nuevo plazo de cumplimiento voluntario.","podrá solicitarse el internamiento, que podrá prorrogarse por otros sesenta días en el mismo expediente.","podrá solicitarse la medida de internamiento, que no podrá exceder del período máximo legalmente establecido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrá solicitarse la medida de internamiento, que no podrá exceder del período máximo legalmente establecido</mark></span>El <span class=\"ref-norma\">art. 64.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Si la expulsión no se pudiera ejecutar en el plazo de setenta y dos horas, podrá solicitarse la medida de internamiento regulada en los artículos anteriores, que no podrá exceder del período establecido en el artículo 62 de esta Ley\"</span>. Se puede pedir el internamiento con el límite máximo legal (60 días). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1348","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. La ejecución de la resolución de expulsión se efectuará, en su caso, a costa del empleador que hubiera sido sancionado por no dar de alta al trabajador o por contratar sin autorización o, en el resto de los supuestos:","o":["a costa de la Administración General del Estado en todo caso.","a costa del extranjero si tuviere medios económicos para ello.","a costa del transportista que lo trasladó a territorio español.","a costa del Estado de origen del extranjero."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a costa del extranjero si tuviere medios económicos para ello</mark></span>El <span class=\"ref-norma\">art. 64.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"o, en el resto de los supuestos, a costa del extranjero si tuviere medios económicos para ello\"</span>. Si no hay empleador sancionado, a costa del extranjero si tiene medios; si no, se comunica al representante diplomático o consular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1349","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. Se suspenderá la ejecución de la resolución de expulsión cuando:","o":["se formalice una petición de protección internacional, hasta que se haya inadmitido a trámite o resuelto.","se interponga recurso contencioso-administrativo contra la resolución de expulsión, hasta que recaiga sentencia firme.","el extranjero acredite haber contraído matrimonio con un residente legal en España.","se presente una solicitud de autorización de residencia de larga duración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se formalice una petición de protección internacional, hasta que se haya inadmitido a trámite o resuelto</mark></span>El <span class=\"ref-norma\">art. 64.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se suspenderá la ejecución de la resolución de expulsión cuando se formalice una petición de protección internacional, hasta que se haya inadmitido a trámite o resuelto\"</span>. La solicitud de protección internacional suspende la ejecución hasta la inadmisión o la resolución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1350","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ejecución de la expulsión. No será precisa la incoación de expediente de expulsión para proceder al traslado, escoltados por funcionarios, de los solicitantes de protección internacional cuya solicitud haya sido inadmitida a trámite al ser responsable otro Estado de su examen, cuando dicho traslado se produzca:","o":["dentro de las setenta y dos horas siguientes a la notificación de la resolución de inadmisión a trámite.","una vez que el Estado responsable haya resuelto expresamente sobre la solicitud de protección internacional.","dentro del mes siguiente a la notificación de la resolución de inadmisión, previa autorización judicial.","dentro de los plazos que el Estado responsable tiene la obligación de proceder al estudio de la solicitud."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dentro de los plazos que el Estado responsable tiene la obligación de proceder al estudio de la solicitud</mark></span>El <span class=\"ref-norma\">art. 64.6.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"cuando dicho traslado se produzca dentro de los plazos que el Estado responsable tiene la obligación de proceder al estudio de la solicitud\"</span>. El traslado debe producirse dentro de los plazos en que el Estado responsable debe estudiar la solicitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 69 — Apoyo al movimiento asociativo de los inmigrantes ✱","q":[{"i":"6-407","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Apoyo al movimiento asociativo. Los poderes públicos impulsarán el fortalecimiento del movimiento asociativo entre los inmigrantes y apoyarán a los sindicatos, organizaciones empresariales y a las organizaciones no gubernamentales que, sin ánimo de lucro, favorezcan su integración social, facilitándoles:","o":["Ayuda económica, únicamente a través de los programas generales de subvenciones.","Locales públicos y asesoramiento jurídico gratuito para el desarrollo de sus actividades.","Ayuda económica, tanto a través de los programas generales como en relación con sus actividades específicas.","Ayuda económica y representación en el Foro para la Integración Social de los Inmigrantes, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ayuda económica, tanto a través de los programas generales como en relación con sus actividades específicas</mark></span>El <span class=\"ref-norma\">art. 69 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Los poderes públicos impulsarán el fortalecimiento del movimiento asociativo entre los inmigrantes y apoyarán a los sindicatos, organizaciones empresariales y a las organizaciones no gubernamentales que, sin ánimo de lucro, favorezcan su integración social, facilitándoles ayuda económica, tanto a través de los programas generales como en relación con sus actividades específicas.\"</span>"}]},{"a":"Artículo 71 — Observatorio Español del Racismo y la Xenofobia ✱","q":[{"i":"6-408","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Observatorio Español del Racismo y la Xenofobia. Se constituirá el Observatorio Español del Racismo y la Xenofobia, con funciones de estudio y análisis, y con capacidad para:","o":["Imponer sanciones por conductas discriminatorias en el ámbito laboral.","Elevar propuestas de actuación, en materia de lucha contra el racismo y la xenofobia.","Informar preceptivamente los proyectos normativos sobre extranjería.","Representar al Estado ante los organismos internacionales en materia de discriminación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Elevar propuestas de actuación, en materia de lucha contra el racismo y la xenofobia</mark></span>El <span class=\"ref-norma\">art. 71 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se constituirá el Observatorio Español del Racismo y la Xenofobia, con funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación, en materia de lucha contra el racismo y la xenofobia.\"</span>"},{"i":"6-ia-1404","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Observatorio Español del Racismo y la Xenofobia. Se constituirá el Observatorio Español del Racismo y la Xenofobia, en materia de lucha contra el racismo y la xenofobia, con:","o":["funciones de inspección y sanción, y con capacidad para incoar expedientes.","funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación.","funciones de consulta, información y asesoramiento en materia de integración.","funciones de coordinación de las Administraciones Públicas en esta materia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación</mark></span>El <span class=\"ref-norma\">art. 71 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se constituirá el Observatorio Español del Racismo y la Xenofobia, con funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación, en materia de lucha contra el racismo y la xenofobia\"</span>. Estudio y análisis y propuestas; la consulta y asesoramiento son del Foro; la coordinación, de la Conferencia Sectorial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 bis — Contingencia migratoria extraordinaria para la protección del interés ✱","q":[{"i":"6-415","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Contingencia migratoria extraordinaria. La Conferencia Sectorial de Infancia y Adolescencia podrá adoptar los requisitos para la declaración de la situación de contingencia migratoria extraordinaria mediante Acuerdo:","o":["Por mayoría absoluta.","Por mayoría de dos tercios.","Por unanimidad.","Por mayoría simple de las Comunidades Autónomas presentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por unanimidad</mark></span>El <span class=\"ref-norma\">art. 35 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. La Conferencia Sectorial de Infancia y Adolescencia podrá adoptar mediante Acuerdo por unanimidad tanto los requisitos para la declaración de la situación de contingencia migratoria extraordinaria\"</span>"},{"i":"6-ia-1136","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Contingencia migratoria extraordinaria para la protección del interés superior de la infancia y la adolescencia migrante no acompañada. La Conferencia Sectorial de Infancia y Adolescencia podrá adoptar los requisitos para la declaración de la situación de contingencia migratoria extraordinaria, el Plan de respuesta y los criterios para su aplicación mediante Acuerdo:","o":["por mayoría absoluta, que podrá adoptarse por separado para cada elemento.","por unanimidad, que debe ser único y recoger el conjunto de estos elementos.","por mayoría de dos tercios, que debe ser único y recoger todos estos elementos.","por unanimidad, que podrá adoptarse por separado para cada uno de los elementos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad, que debe ser único y recoger el conjunto de estos elementos</mark></span>El <span class=\"ref-norma\">art. 35 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La Conferencia Sectorial de Infancia y Adolescencia podrá adoptar mediante Acuerdo por unanimidad\"</span>. El Acuerdo es por unanimidad y, de adoptarse, «debe ser único y recoger el conjunto de estos elementos». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1137","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Contingencia migratoria extraordinaria para la protección del interés superior de la infancia y la adolescencia migrante no acompañada. Los criterios de aplicación del Plan incluirán, en todo caso, los necesarios para determinar en qué supuestos procede que se ordene el traslado de personas menores extranjeras no acompañadas de una comunidad o ciudad autónoma a otra por resolución de:","o":["la persona que presida la Conferencia Sectorial de Infancia y Adolescencia.","el Consejo de Ministros, a propuesta del Ministerio de Juventud e Infancia y oída la Conferencia Sectorial.","la persona titular de la Consejería competente de la comunidad de origen.","el Ministerio Fiscal, previa audiencia de las comunidades afectadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la persona que presida la Conferencia Sectorial de Infancia y Adolescencia</mark></span>El <span class=\"ref-norma\">art. 35 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"determinar en qué supuestos procede que se ordene el traslado de personas menores extranjeras no acompañadas de una comunidad o ciudad autónoma a otra por resolución de la persona que presida la Conferencia Sectorial de Infancia y Adolescencia\"</span>. Lo ordena por resolución quien presida la Conferencia Sectorial, previa comunicación y acreditación de la contingencia por la comunidad afectada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1138","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Contingencia migratoria extraordinaria para la protección del interés superior de la infancia y la adolescencia migrante no acompañada. Se declarará la situación de contingencia migratoria extraordinaria en aquellas comunidades o ciudades autónomas cuyo sistema de protección y tutela de personas menores de edad extranjeras no acompañadas exceda en ocupación __________ su capacidad ordinaria.","o":["dos veces","el doble de","cuatro veces","tres veces"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres veces</mark></span>El <span class=\"ref-norma\">art. 35 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"exceda en ocupación tres veces su capacidad ordinaria\"</span>. El umbral es exceder TRES veces la capacidad ordinaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1139","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Contingencia migratoria extraordinaria para la protección del interés superior de la infancia y la adolescencia migrante no acompañada. La aprobación de la declaración de la situación de contingencia migratoria extraordinaria se realizará en un plazo máximo de:","o":["diez días hábiles desde la comunicación por parte de la comunidad o ciudad autónoma afectada.","cinco días hábiles desde la solicitud de la Conferencia Sectorial de Infancia y Adolescencia.","cinco días naturales desde la comunicación por parte de la comunidad o ciudad autónoma afectada.","quince días naturales desde la constatación de la sobreocupación por el Ministerio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cinco días naturales desde la comunicación por parte de la comunidad o ciudad autónoma afectada</mark></span>El <span class=\"ref-norma\">art. 35 bis.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La aprobación de dicha declaración se realizará en un plazo máximo de cinco días naturales desde la comunicación por parte de la comunidad o ciudad autónoma afectada\"</span>. Cinco días NATURALES desde la comunicación de la comunidad o ciudad autónoma afectada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 ter — Modelo de gestión de contingencias migratorias extraordinarias para la EXOF","q":[{"i":"6-416","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Modelo de gestión de contingencias. En el modelo de gestión de contingencias, un porcentaje se determina atendiendo al esfuerzo en atención a personas menores no acompañadas, valorando, en sentido inverso, el esfuerzo de la comunidad o ciudad autónoma. Ese porcentaje es:","o":["Un 10 por ciento.","Un 6 por ciento.","Un 13 por ciento.","Un 15 por ciento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un 6 por ciento</mark></span>El <span class=\"ref-norma\">art. 35 ter.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Un 6 por ciento atendiendo al esfuerzo en atención a personas menores no acompañadas, valorando, en sentido inverso, el esfuerzo de la comunidad o ciudad autónoma en la atención a niñas, niños y adolescentes acogidos\"</span>"},{"i":"6-ia-1140","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Modelo de gestión de contingencias migratorias extraordinarias para la infancia y la adolescencia migrante no acompañada. En defecto de acuerdo unánime, entre los criterios objetivos para determinar la ubicación de las personas menores de edad extranjeras no acompañadas, el de mayor peso es el de:","o":["un 50 por ciento en razón a la Renta disponible bruta per cápita de los hogares de las comunidades de acogida.","un 50 por ciento de las niñas y niños en razón a la población de las comunidades o ciudades autónomas de acogida.","un 15 por ciento en razón a la población de las comunidades o ciudades autónomas de acogida.","un 50 por ciento en razón inversa a la Tasa de paro según la Encuesta de Población Activa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un 50 por ciento de las niñas y niños en razón a la población de las comunidades o ciudades autónomas de acogida</mark></span>El <span class=\"ref-norma\">art. 35 ter.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Un 50 por ciento de las niñas y niños en razón a la población de las comunidades o ciudades autónomas de acogida según los datos recogidos en la Estadística continua de población\"</span>. Población 50 %; renta 13 %; paro 15 % (inverso); esfuerzo 6 %; plazas 10 %; frontera, insularidad y dispersión 2 % cada uno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1141","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Modelo de gestión de contingencias migratorias extraordinarias para la infancia y la adolescencia migrante no acompañada. Entre los criterios objetivos de ubicación de las personas menores de edad extranjeras no acompañadas figura un __________ en razón inversa a la Tasa de paro según la Encuesta de Población Activa del último cuatrimestre de las comunidades o ciudades autónomas de acogida.","o":["15 por ciento","13 por ciento","10 por ciento","6 por ciento"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">15 por ciento</mark></span>El <span class=\"ref-norma\">art. 35 ter.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) Un 15 por ciento en razón inversa a la Tasa de paro según la Encuesta de Población Activa del último cuatrimestre de las comunidades o ciudades autónomas de acogida\"</span>. Paro: 15 %; la renta disponible es el 13 %, el dimensionamiento de plazas el 10 % y el esfuerzo el 6 %. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la Ley de Asilo","q":[{"i":"6-431","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. Al valorar los motivos de persecución, el concepto de religión comprenderá, en particular, la profesión de:","o":["Creencias teístas y no teístas, con exclusión de las ateas, en cultos formales en público.","Creencias teístas, no teístas y ateas, únicamente cuando se manifiesten en cultos formales en comunidad.","Creencias teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público.","Creencias teístas y ateas, así como la pertenencia a una confesión inscrita en el registro de entidades religiosas, conforme al procedimiento que reglamentariamente se establezca."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Creencias teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público</mark></span>El <span class=\"ref-norma\">art. 7.1.b) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) el concepto de religión comprenderá, en particular, la profesión de creencias teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público\"</span>"},{"i":"6-432","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. El concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular:","o":["La pertenencia a un grupo determinado por su identidad religiosa, étnica o lingüística y su lugar de residencia habitual, sin perjuicio de lo que establezcan los tratados internacionales.","La pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado.","La posesión de la nacionalidad de un Estado distinto al de la residencia y la pertenencia a una minoría nacional.","La pertenencia a un grupo determinado por sus orígenes geográficos comunes, con exclusión de la identidad lingüística."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado</mark></span>El <span class=\"ref-norma\">art. 7.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) el concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular, la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado;\"</span>"},{"i":"6-433","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. El concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos, independientemente de que el solicitante:","o":["Haya o no obrado de acuerdo con tales opiniones, ideas o creencias.","Haya manifestado públicamente tales opiniones ante las autoridades de su país.","Pertenezca o no a un partido político legalmente constituido en su país.","Haya sido o no condenado por la expresión de tales opiniones, ideas o creencias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Haya o no obrado de acuerdo con tales opiniones, ideas o creencias</mark></span>El <span class=\"ref-norma\">art. 7.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) el concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos, independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias;\"</span>"},{"i":"6-434","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. En la valoración acerca de si la persona solicitante tiene fundados temores a ser perseguida será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución, a condición de que:","o":["El solicitante la acredite mediante prueba documental.","El agente de persecución la conozca por sus propios medios.","La autoridad del país de acogida la considere verosímil.","El agente de persecución se la atribuya."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El agente de persecución se la atribuya</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"2. En la valoración acerca de si la persona solicitante tiene fundados temores a ser perseguida será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución, a condición de que el agente de persecución se la atribuya.\"</span>"},{"i":"6-451","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Extensión familiar. La extensión familiar del derecho de asilo o de la protección subsidiaria alcanza a otro adulto que sea responsable del beneficiario de protección internacional, de acuerdo con la legislación española vigente, cuando dicho beneficiario sea:","o":["Un menor, esté o no casado.","Un menor no casado.","Un menor no acompañado.","Un mayor de edad no casado a su cargo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un menor no casado</mark></span>El <span class=\"ref-norma\">art. 40.1.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) Otro adulto que sea responsable del beneficiario de protección internacional, de acuerdo con la legislación española vigente, cuando dicho beneficiario sea un menor no casado.\"</span>"},{"i":"6-464","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Motivos de persecución. Al valorar los motivos de persecución se tendrán en cuenta los siguientes elementos, entre otros:","o":["El concepto de raza comprenderá, en particular, el color y el origen, con exclusión del grupo étnico, sin perjuicio de lo que establezcan los tratados internacionales.","El concepto de religión comprenderá únicamente la profesión de creencias teístas.","El concepto de nacionalidad se limitará a poseer o no la ciudadanía de un Estado.","El concepto de raza comprenderá, en particular, el color, el origen o la pertenencia a un determinado grupo étnico."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El concepto de raza comprenderá, en particular, el color, el origen o la pertenencia a un determinado grupo étnico</mark></span>El <span class=\"ref-norma\">art. 7.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"1. Al valorar los motivos de persecución se tendrán en cuenta los siguientes elementos:\"</span>"},{"i":"6-471","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Tramitación de urgencia. A la tramitación de urgencia le será de aplicación lo dispuesto para el procedimiento ordinario, salvo en materia de plazos, que:","o":["se verán reducidos a la tercera parte.","serán los mismos que en el procedimiento ordinario.","se ampliarán al doble en las solicitudes de frontera.","se verán reducidos a la mitad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se verán reducidos a la mitad</mark></span>El <span class=\"ref-norma\">art. 25.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Será de aplicación al presente procedimiento lo dispuesto en el artículo 24 de la Ley, salvo en materia de plazos que se verán reducidos a la mitad\"</span> Urgencia = plazos del ordinario reducidos a la mitad."}]},{"a":"Artículo 11 — Causas de exclusión EX ✱","q":[{"i":"6-439","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión de la protección subsidiaria. Quedarán excluidas de la protección subsidiaria las personas sobre las que existan motivos fundados para considerar que:","o":["Constituyen un peligro para la seguridad exterior de España, con exclusión del orden público, sin perjuicio de lo que establezcan los tratados internacionales.","Han abandonado voluntariamente su país de origen antes de solicitar protección.","Constituyen un peligro para la seguridad interior o exterior de España o para el orden público.","Han sido condenadas en España por un delito leve en los últimos cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Constituyen un peligro para la seguridad interior o exterior de España o para el orden público</mark></span>El <span class=\"ref-norma\">art. 11.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) constituyen un peligro para la seguridad interior o exterior de España o para el orden público.\"</span>"},{"i":"6-ia-1506","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Causas de exclusión. Además de las causas comunes con la condición de refugiado, quedarán excluidas de la condición de beneficiarias de la protección subsidiaria aquellas personas respecto de las que existan fundados motivos para considerar que:","o":["han residido en un tercer país seguro antes de llegar a España durante más de seis meses.","han abandonado su país de origen por motivos exclusivamente económicos o laborales.","han solicitado previamente protección internacional en otro Estado miembro de la Unión Europea.","constituyen un peligro para la seguridad interior o exterior de España o para el orden público."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">constituyen un peligro para la seguridad interior o exterior de España o para el orden público</mark></span>El <span class=\"ref-norma\">art. 11.1.d) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"d) constituyen un peligro para la seguridad interior o exterior de España o para el orden público\"</span>. La letra d) es propia de la protección subsidiaria: peligro para la seguridad interior o exterior o el orden público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1522","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Efectos de la presentación de la solicitud. Las personas solicitantes de asilo tienen derecho a entrevistarse con un abogado en las dependencias de los puestos fronterizos y centros de internamiento de extranjeros. Reglamentariamente podrán establecerse condiciones para el ejercicio de este derecho derivadas de razones de:","o":["seguridad nacional, salud pública o capacidad de los centros.","urgencia, horario de los centros o disponibilidad de intérpretes.","orden público, salud pública o protección de datos.","seguridad, orden público o de su gestión administrativa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seguridad, orden público o de su gestión administrativa</mark></span>El <span class=\"ref-norma\">art. 19.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"podrán establecerse condiciones para el ejercicio de este derecho derivadas de razones de seguridad, orden público o de su gestión administrativa\"</span>. Razones de seguridad, orden público o gestión administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 13 — Agentes de persecución o causantes de daños graves EX ✱","q":[{"i":"6-440","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de persecución o causantes de daños graves. Podrán ser agentes de persecución o causantes de daños graves los agentes no estatales, cuando los agentes estatales y los partidos u organizaciones que controlen el Estado, incluidas las organizaciones internacionales:","o":["No puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves.","No puedan proporcionar protección efectiva, aunque quieran hacerlo.","No hayan sido informados de la situación de riesgo del solicitante.","No hayan agotado los recursos judiciales internos del país de origen, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves</mark></span>El <span class=\"ref-norma\">art. 13.c) de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidas las organizaciones internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves.\"</span>"},{"i":"6-ia-1507","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de persecución o causantes de daños graves. Los agentes de persecución o causantes de daños graves podrán ser, entre otros, agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidas las organizaciones internacionales:","o":["hayan sido declarados responsables de la persecución por una resolución de las Naciones Unidas.","no controlen una parte considerable del territorio del Estado de origen del solicitante.","no puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves.","no hayan ratificado la Convención sobre el Estatuto de los Refugiados de Ginebra de 1951."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves</mark></span>El <span class=\"ref-norma\">art. 13 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"c) agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidas las organizaciones internacionales, no puedan o no quieran proporcionar protección efectiva contra la persecución o los daños graves\"</span>. Los agentes no estatales lo son cuando el Estado u organizaciones no pueden o no quieren proteger. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 44 — Hecho imponible EX","q":[{"i":"6-467","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Hecho imponible. Constituye el hecho imponible de las tasas, en particular, la tramitación de autorizaciones de trabajo, salvo que se trate de autorizaciones para un período inferior a __________.","o":["tres meses de duración.","noventa días naturales.","un año natural completo.","seis meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 44.2.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La tramitación de autorizaciones de trabajo, salvo que se trate de autorizaciones para un período inferior a seis meses\"</span> Las autorizaciones de trabajo inferiores a seis meses no generan la tasa."},{"i":"6-ia-1221","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Hecho imponible. Constituye el hecho imponible de las tasas, en particular, la tramitación de autorizaciones de trabajo:","o":["salvo que se trate de autorizaciones para un período inferior a seis meses.","salvo que se trate de autorizaciones para trabajadores de temporada.","salvo que se trate de autorizaciones iniciales por cuenta propia.","salvo que se trate de autorizaciones para un período inferior a tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">salvo que se trate de autorizaciones para un período inferior a seis meses</mark></span>El <span class=\"ref-norma\">art. 44.2.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) La tramitación de autorizaciones de trabajo, salvo que se trate de autorizaciones para un período inferior a seis meses\"</span>. Las autorizaciones de trabajo por menos de seis meses no generan la tasa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 24 — Aplicabilidad del procedimiento sumario","q":[{"i":"6-470","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Agentes de persecución o causantes de daños graves. En relación con los agentes de persecución o causantes de daños graves, señale la correcta:","o":["Podrán ser, entre otros, el Estado.","Podrán ser únicamente el Estado y los partidos u organizaciones que lo controlen.","Solo podrán ser agentes no estatales cuando así lo reconozca el país de origen.","Serán exclusivamente los enumerados en la ley, sin que quepa admitir ningún otro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrán ser, entre otros, el Estado</mark></span>El <span class=\"ref-norma\">art. 13 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Los agentes de persecución o causantes de daños graves podrán ser, entre otros: a) el Estado\"</span> La enumeración es abierta («entre otros») y empieza por el Estado."},{"i":"6-ia-1042","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Aplicabilidad del procedimiento sumario. La tutela judicial contra cualquier práctica discriminatoria podrá ser exigida por el procedimiento previsto en la Constitución para la protección de los derechos fundamentales cuando dicha práctica:","o":["proceda de una autoridad o funcionario público en el ejercicio de sus funciones.","afecte a un extranjero residente de larga duración.","haya sido declarada en vía administrativa firme.","comporte vulneración de derechos y libertades fundamentales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comporte vulneración de derechos y libertades fundamentales</mark></span>El <span class=\"ref-norma\">art. 24 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La tutela judicial contra cualquier práctica discriminatoria que comporte vulneración de derechos y libertades fundamentales podrá ser exigida por el procedimiento previsto en el artículo 53.2 de la Constitución\"</span>. El procedimiento sumario procede cuando la práctica discriminatoria vulnera derechos y libertades fundamentales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Disposición adicional undécima — Capacidad ordinaria de los sistemas para la adecuada","q":[{"i":"6-ia-1009","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Integración de los inmigrantes. Los programas de acción bienales acordados en la Conferencia Sectorial de Inmigración serán financiados con cargo a un fondo estatal para la integración de los inmigrantes, que se dotará __________, y que podrá incluir fórmulas de cofinanciación por parte de las Administraciones receptoras de las partidas del fondo.","o":["anualmente","cada dos años","por periodos plurianuales","semestralmente"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anualmente</mark></span>El <span class=\"ref-norma\">art. 2 ter.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Tales programas serán financiados con cargo a un fondo estatal para la integración de los inmigrantes, que se dotará anualmente\"</span>. Los programas son bienales, pero el fondo se dota anualmente: es la trampa entre las dos cifras. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Libertades de reunión y manifestación ✱","q":[{"i":"6-ia-1015","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Libertades de reunión y manifestación. Los promotores de reuniones o manifestaciones en lugares de tránsito público darán comunicación previa a la autoridad competente con la antelación prevista en la Ley Orgánica reguladora del Derecho de Reunión, la cual:","o":["podrá prohibirla cuando los promotores no sean residentes legales en España.","deberá autorizarla expresamente cuando la mayoría de los asistentes sean extranjeros.","no podrá prohibirla o proponer su modificación sino por las causas previstas en dicha Ley.","podrá proponer su modificación por razones de orden público apreciadas libremente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no podrá prohibirla o proponer su modificación sino por las causas previstas en dicha Ley</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"la cual no podrá prohibirla o proponer su modificación sino por las causas previstas en dicha Ley\"</span>. Rige el régimen general de comunicación previa; no hay causas añadidas por la condición de extranjero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 34 — Residencia de apátridas, indocumentados y refugiados ✱","q":[{"i":"6-ia-1124","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de apátridas, indocumentados y refugiados. Reconocerá la condición de apátrida a los extranjeros que manifestando que carecen de nacionalidad reúnen los requisitos previstos en la Convención sobre el Estatuto de Apátridas, hecha en Nueva York el 28 de septiembre de 1954, y les expedirá la documentación prevista en dicha Convención:","o":["El Ministro de Asuntos Exteriores.","El Ministro del Interior.","La Oficina de Asilo y Refugio.","El Consejo de Ministros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministro del Interior</mark></span>El <span class=\"ref-norma\">art. 34.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Ministro del Interior reconocerá la condición de apátrida a los extranjeros que manifestando que carecen de nacionalidad reúnen los requisitos previstos en la Convención sobre el Estatuto de Apátridas, hecha en Nueva York el 28 de septiembre de 1954\"</span>. El reconocimiento de la apatridia corresponde al Ministro del Interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1125","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de apátridas, indocumentados y refugiados. El extranjero que se presente en dependencias del Ministerio del Interior acreditando que no puede ser documentado por las autoridades de ningún país y que desea ser documentado por España podrá obtener un documento identificativo. En todo caso, se denegará la documentación solicitada cuando:","o":["el peticionario tenga prohibida la entrada en España o se haya dictado contra él una orden de expulsión.","el peticionario carezca de medios de vida suficientes para su estancia en España o no acredite domicilio conocido en el país.","el peticionario no acredite una residencia previa en España de al menos un año.","el peticionario haya solicitado previamente protección internacional en otro Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el peticionario tenga prohibida la entrada en España o se haya dictado contra él una orden de expulsión</mark></span>El <span class=\"ref-norma\">art. 34.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"En todo caso, se denegará la documentación solicitada cuando el peticionario esté incurso en alguno de los supuestos del artículo 26, o se haya dictado contra él una orden de expulsión\"</span>. Se deniega si está incurso en una prohibición de entrada o tiene una orden de expulsión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1126","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Residencia de apátridas, indocumentados y refugiados. La resolución favorable sobre la petición de asilo en España supondrá el reconocimiento de la condición de refugiado del solicitante. Dicha condición supondrá:","o":["su derecho a obtener la nacionalidad española tras un año de residencia legal y continuada en España, en los términos de la Convención de Ginebra.","su no devolución ni expulsión, salvo que haya entrado ilegalmente en territorio español.","su residencia en España por un período máximo de cinco años, renovable a petición propia.","su no devolución ni expulsión en los términos de la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su no devolución ni expulsión en los términos de la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951</mark></span>El <span class=\"ref-norma\">art. 34.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Dicha condición supondrá su no devolución ni expulsión en los términos del artículo 33 de la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951\"</span>. La condición de refugiado supone la no devolución ni expulsión en los términos de la Convención de Ginebra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 67 — Coordinación de los órganos de la Administración del Estado ✱","q":[{"i":"6-ia-1356","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de los órganos de la Administración del Estado. Al objeto de conseguir una adecuada coordinación de su actuación administrativa, el Gobierno unificará los servicios existentes, dependientes de diferentes órganos de la Administración del Estado con competencia en inmigración, en:","o":["Delegaciones regionales.","Oficinas provinciales.","Oficinas autonómicas.","Centros comarcales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Oficinas provinciales</mark></span>El <span class=\"ref-norma\">art. 67.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Gobierno unificará en Oficinas provinciales los servicios existentes, dependientes de diferentes órganos de la Administración del Estado con competencia en inmigración, al objeto de conseguir una adecuada coordinación de su actuación administrativa\"</span>. Se unifican en Oficinas provinciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1357","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de los órganos de la Administración del Estado. El Gobierno elaborará planes, programas y directrices sobre la actuación de la Inspección de Trabajo previa al procedimiento sancionador destinados especialmente a comprobar:","o":["el cumplimiento del principio de igualdad y no discriminación de los trabajadores extranjeros y de la normativa en materia de autorización de trabajo.","la afiliación y alta en la Seguridad Social de los trabajadores extranjeros contratados mediante la gestión colectiva en origen y de los trabajadores de temporada.","el cumplimiento de las condiciones de alojamiento de los trabajadores de temporada en las explotaciones agrarias.","la veracidad de los contratos de trabajo presentados en las solicitudes de autorización de residencia y trabajo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el cumplimiento del principio de igualdad y no discriminación de los trabajadores extranjeros y de la normativa en materia de autorización de trabajo</mark></span>El <span class=\"ref-norma\">art. 67.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"destinados especialmente a comprobar el cumplimiento del principio de igualdad y no discriminación de los trabajadores extranjeros, así como el cumplimiento efectivo de la normativa en materia de autorización de trabajo de extranjeros\"</span>. Igualdad y no discriminación, y cumplimiento de la normativa sobre autorización de trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 68 — Coordinación de las Administraciones Públicas ✱","q":[{"i":"6-ia-1358","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de las Administraciones Públicas. Es el órgano a través del cual se asegurará la adecuada coordinación de las actuaciones que desarrollen las Administraciones Públicas en materia de inmigración:","o":["La Comisión Laboral Tripartita de Inmigración.","El Foro para la Integración Social de los Inmigrantes.","El Observatorio Permanente de la Inmigración.","La Conferencia Sectorial de Inmigración."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Conferencia Sectorial de Inmigración</mark></span>El <span class=\"ref-norma\">art. 68.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"La Conferencia Sectorial de Inmigración es el órgano a través del cual se asegurará la adecuada coordinación de las actuaciones que desarrollen las Administraciones Públicas en materia de inmigración\"</span>. La coordinación interadministrativa es de la Conferencia Sectorial de Inmigración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1401","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de las Administraciones Públicas. Con carácter previo a la concesión de autorizaciones por arraigo, emitirán un informe sobre la integración social del extranjero cuyo domicilio habitual se encuentre en su territorio:","o":["las Comunidades Autónomas o, en su caso, los Ayuntamientos.","las Delegaciones o Subdelegaciones del Gobierno de la provincia.","los Servicios Públicos de Empleo de la Comunidad Autónoma.","las Oficinas de Extranjeros o, en su caso, las Comisarías."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las Comunidades Autónomas o, en su caso, los Ayuntamientos</mark></span>El <span class=\"ref-norma\">art. 68.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Con carácter previo a la concesión de autorizaciones por arraigo, las Comunidades Autónomas o, en su caso, los Ayuntamientos, emitirán un informe sobre la integración social del extranjero cuyo domicilio habitual se encuentre en su territorio\"</span>. El informe de integración para el arraigo es de las Comunidades Autónomas o, en su caso, de los Ayuntamientos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1403","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Coordinación de las Administraciones Públicas. Las Comunidades Autónomas que hayan asumido competencias en materia de seguridad ciudadana y orden público mediante la creación de una policía propia podrán aportar, en su caso, en los procedimientos de autorización de residencia o su renovación en los que se prevea la necesidad de informe gubernativo:","o":["un informe vinculante sobre la concesión o denegación de la autorización solicitada.","un informe sobre antecedentes policiales en sustitución del estatal.","un informe sobre afectación al orden público, que se incorporará al expediente.","un informe de integración social, previo a la concesión del arraigo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un informe sobre afectación al orden público, que se incorporará al expediente</mark></span>El <span class=\"ref-norma\">art. 68.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"podrán aportar, en su caso, un informe sobre afectación al orden público en todos los procedimientos de autorización de residencia o su renovación\"</span>. Aportan un informe sobre afectación al orden público, que se incorpora al expediente junto al de las FFCCSE; no es vinculante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1633","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Cooperación con otras Administraciones Públicas. De acuerdo con sus respectivas competencias en los ámbitos sanitario, educativo y social, gestionarán los servicios y programas específicamente destinados a las personas solicitantes de asilo, en coordinación y cooperación con la Administración General del Estado:","o":["Las Comunidades Autónomas.","Los Ayuntamientos.","Las organizaciones no gubernamentales.","Las Delegaciones del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">disp. adic. 4.ª de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Las Comunidades Autónomas, de acuerdo con sus respectivas competencias en los ámbitos sanitario, educativo y social gestionarán los servicios y programas específicamente destinados a las personas solicitantes de asilo\"</span>. Las Comunidades Autónomas, en coordinación con la AGE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 24 — Procedimiento ordinario EX ✱","q":[{"i":"6-ia-1516","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Presentación de la solicitud. En el momento de efectuar la solicitud, la persona extranjera será informada, en una lengua que pueda comprender, acerca de: Señale la INCORRECTA.","o":["el procedimiento que debe seguirse.","los criterios de valoración que aplicará la Comisión Interministerial de Asilo y Refugio.","sus derechos y obligaciones durante la tramitación, en especial en materia de plazos y medios de que dispone para cumplir éstas.","los derechos y prestaciones sociales a los que tiene acceso en su condición de solicitante de protección internacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los criterios de valoración que aplicará la Comisión Interministerial de Asilo y Refugio</mark></span>El <span class=\"ref-norma\">art. 17.3 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"b) sus derechos y obligaciones durante la tramitación, en especial en materia de plazos y medios de que dispone para cumplir éstas\"</span>. Los criterios de valoración de la CIAR no figuran entre los extremos de información. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41 — Reagrupación familiar ✱","q":[{"i":"6-ia-1613","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reagrupación familiar. Las personas refugiadas y beneficiarias de protección subsidiaria podrán optar por reagrupar a los familiares que la Ley enumera, aun cuando ya se encontrasen en España, sin solicitar la extensión del estatuto de que disfruten. Esta reagrupación será siempre aplicable cuando:","o":["los beneficiarios sean de nacionalidad distinta a la persona refugiada o beneficiaria de protección subsidiaria.","los beneficiarios sean menores de edad o personas con discapacidad que estén a cargo de la persona refugiada o beneficiaria.","los beneficiarios no hayan convivido previamente con la persona refugiada en el país de origen.","los beneficiarios se encuentren fuera de España en el momento de la concesión del estatuto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los beneficiarios sean de nacionalidad distinta a la persona refugiada o beneficiaria de protección subsidiaria</mark></span>El <span class=\"ref-norma\">art. 41.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Esta reagrupación será siempre aplicable cuando los beneficiarios sean de nacionalidad distinta a la persona refugiada o beneficiaria de protección subsidiaria\"</span>. Con distinta nacionalidad no cabe la extensión, por eso la reagrupación es siempre aplicable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1616","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Reagrupación familiar. La reagrupación familiar de las personas refugiadas o beneficiarias de protección subsidiaria será ejercitable:","o":["dos veces como máximo, siempre que los reagrupados obtengan autorización de residencia y trabajo.","una sola vez, sin que los reagrupados puedan solicitar reagrupaciones sucesivas de sus familiares.","tantas veces como se acredite la dependencia de los familiares respecto de la persona refugiada.","una sola vez por cada grado de parentesco, sin límite para los descendientes menores de edad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una sola vez, sin que los reagrupados puedan solicitar reagrupaciones sucesivas de sus familiares</mark></span>El <span class=\"ref-norma\">art. 41.4 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"La reagrupación familiar será ejercitable una sola vez, sin que las personas que hubiesen sido reagrupadas y obtenido autorización para residir en España en virtud de lo dispuesto en el apartado anterior puedan solicitar reagrupaciones sucesivas de sus familiares\"</span>. Una sola vez, sin reagrupaciones sucesivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
